INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (4, 'movie', 'اللص والكلاب', 'The Thief and the Dogs', 'اللص والكلاب', 'اللص والكلاب', 1962, 258663, 'movie', '/yqROZKGOVBQKMXMbDYLzjinbFqg.jpg', '/g3DafXmmi5avb1Qve1jRyGte4IP.jpg', 'سعيد مهران لص عتيد اﻹجرام، يتخذ من رؤوف علوان قدوته في الحياة، خاصة بعدما نصحه أن الانسان لابد أن يحصل علي مايريد بأي وسيلة يراها، وأثناء تنفيذه إحدى السرقات، يبلغ صبيه عليش سدره عنه لكي يتزوج من زوجة سعيد بعد سجنه، وبعد خروج سعيد من السجن يقابله رؤوف علوان بتكبر شديد بعد أن صار صحافيًا لامعًا، ويصبح كل من رؤوف ونبوية زوجة سعيد السابقة وعليش سدره صبيه ألد خصومه له ويسعي إلي الانتقام منهم.', 'This film, inspired by Naguib Mahfouz'' The thief and the dogs, tells the story of Mahran, a thief who quickly ascends to be the head of his gang. However, his second in command conspires against Mahran to take his position and his wife. After his prison term, Mahran is thirsty for revenge. But being chased by the police and by his new enemies destines him to a tragic life in hiding.', 6.7, '["جريمة", "دراما", "حركة", "إثارة"]'::jsonb, '[{"name": "شكري سرحان", "character": "سعيد مهران", "profile_path": "/aDtuqqgvwAMkmbjVK4jFhKDaLPr.jpg"}, {"name": "شادية", "character": "نور", "profile_path": "/62arY87I83h7Nh2dYSFLvVNOnfB.jpg"}, {"name": "كمال الشناوي", "character": "رؤوف علوان", "profile_path": "/hT887J0ndDEChmjFiKU1OsSrHk8.jpg"}, {"name": "فاخر فاخر", "character": "الشيخ", "profile_path": "/fY75rNCWbPDWeuedSsomjhiP3Ts.jpg"}, {"name": "نظيم شعراوي", "character": "مدير الامن", "profile_path": "/y60J9E5llZKjniiZw288J4TrSrc.jpg"}, {"name": "عبدالمنعم إسماعيل", "character": "قهوجي", "profile_path": "/pKqrpewdplAglTFHf4YqGHlvCir.jpg"}]'::jsonb, 130) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (6, 'movie', 'العميل صفر', 'Agent Zero', 'العميل صفر', 'العميل صفر', 2023, 1157303, 'movie', '/weiM771BhB6LvvaYUlGUICvmGpD.jpg', '/7Y30ZwKTkFiFXeER9NxIkHYEcin.jpg', 'يحلم صفر، وهو حارس أمن متحف، أن يكون بطلا مثل جيمس بوند، ولكنه يقع في مشاكل ومواقف كوميدية عدة عندما يفشل في أداء عمله بشكل صحيح.', 'Sefr, a museum guard who dreams of being James Bond, looks to emulate his hero – with comic results – when he tries to recover a stolen sculpture.', 4.8, '["حركة", "كوميديا"]'::jsonb, '[{"name": "أكرم حسني", "character": "Sefr Abdellatif Shadad El-Hemam", "profile_path": "/tZGdekospdRJ9XZ25hQ7W6RwB9M.jpg"}, {"name": "بيومي فؤاد", "character": "Abdellatif Shadad EL-Hemam", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "مصطفى غريب", "character": "Nono", "profile_path": "/glzcFTExMpbS6Jnfwtmkv4x2hDR.jpg"}, {"name": "محمد أوتاكا", "character": "Hmamsi", "profile_path": "/XyVpD2tp4x8wGlMjePtg5dhyGZ.jpg"}, {"name": "فاطمة البنوي", "character": "Lili", "profile_path": "/7wnLPaeINawQR3mqFhmST9bQTAi.jpg"}, {"name": "منذر رياحنة", "character": "El-D2a2", "profile_path": "/gFcuGTwyqcGegvm7UGiqmty7kIc.jpg"}]'::jsonb, 112) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (7, 'movie', 'الزواج على الطريقة الحديثة', 'Marriage on the Modern Way', 'الزواج على الطريقة الحديثة', 'الزواج علي الطريقه الحديثه', 1968, 537225, 'movie', '/gw2OYJ23KXoKpNlgLff3StAKcwc.jpg', '/9zXR5QRXp3kw7t8rPGj2gWoyEbR.jpg', 'أحمد ونهى أولاد خالة تربوا وتعلموا معًا حتى وصلوا إلى الجامعة، وبينما هم في رحلة معسكر الجامعة على الشاطيء في الاجازة الصيفية يندلع الحب بينهم. ويقرران الزواج، ولكن الظروف لا تساعدهم على الزواج خاصة مع ظهور عريس مهندس يطلب الزواج من نهى فتقوم بعمل حيل حتى يهرب منها.', 'Noha and Ahmed are in love but face a series of complications before getting married due to their traditional parents', 6.7, '["كوميديا", "دراما"]'::jsonb, '[{"name": "سعاد حسني", "character": "نهى", "profile_path": "/ulWhmq32VFr98H5SoOqbEHa9T34.jpg"}, {"name": "حسن يوسف", "character": "أحمد", "profile_path": "/jPtJpKZxfOH7Cj2AfxdvHpLMYMx.jpg"}, {"name": "سمير غانم", "character": "سمير", "profile_path": "/vSqmd98zrxOAnDFnBGnt4Wihn7B.jpg"}, {"name": "الضيف أحمد", "character": "عتريس", "profile_path": "/mInXtgIPmci2EOJZnU3fP53i3g3.jpg"}, {"name": "جورج سيدهم", "character": "مخيمر", "profile_path": "/6saaUS66LzUs4hiIpmwNrO6wpq.jpg"}, {"name": "محمد رضا", "character": "مرسي بيه الشافعي", "profile_path": "/c45atsICuA4BShxcd8qIGOHp2QU.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (8, 'movie', 'مين فينا الحرامي', 'Who is the Thief Between Us', 'مين فينا الحرامي', 'مين فينا الحرامي', 1984, 514001, 'movie', '/xX1zfClvzRl7UdVGr6PJp4oPjC7.jpg', '/gA7EjPbS1fZIipkC26af0XweU5E.jpg', 'تلتقي الصحفية الشابة الحسناء (سحر) مع (حسين) في لندن ويعودان الى مصر حيث يتعرّف على والدها (عاصم) مدير الشركة التي اختلس منه اخوه التوأم (شريف) مبلغا كبيرا واخفاه في السرير إلى ان يبيع (حسين) أثاث الشقة حتي يتمكن من اخراج اخيه (شريف) من السجن بعض القبض عليه وتدور الاحداث حول رحلة البحث عن السرير المخبئ به الاموال من (شريف).', 'The young journalist, Sahar, meets Hussein in London and they return to Egypt, where he meets her father, Asim, the company manager, from whom his twin brother, Sherif, embezzled a large sum of money. After Sherif gets arrested, Hussein tries to sell everything to help him get out of jail.', 4.5, '["دراما", "كوميديا"]'::jsonb, '[{"name": "عادل إمام", "character": "شريف/ حسين", "profile_path": "/vPEubkxYDRfkSUDoAfJUWQgg4cD.jpg"}, {"name": "شريهان", "character": "سحر", "profile_path": "/lNs6Coz2064WNTsVcwNhylFIfTv.jpg"}, {"name": "صلاح نظمي", "character": "الهلباوي بيه", "profile_path": "/n0jY20G7CvG7nS7aoKGa8Awfxpi.jpg"}, {"name": "فريدة سيف النصر", "character": "غندوره", "profile_path": "/if6OaEDGIf1bX8Uau8v3ocLuqtC.jpg"}, {"name": "منيرفا", "character": "رندة", "profile_path": "/4iwhKsRy4Pf1mbD9JdSjL7kIDnV.jpg"}, {"name": "أحمد بدير", "character": "إسماعيل", "profile_path": "/czumAPB9nIYytuVEELuhnBgqc10.jpg"}]'::jsonb, 110) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (9, 'movie', 'ياباني أصلي', 'From Japan to Egypt', 'ياباني أصلي', 'ياباني اصلي', 2017, 445681, 'movie', '/c0o25aE7Jwk1DQ4SA01zHOTtvVn.jpg', '/AqQHyIGa9WoebeXLdZXBBuK0nOi.jpg', 'تدور احداث فيلم حول (محرم) مندوب شركة سياحية يعيش بمنطقة شعبية، يقع في حب دبلوماسية يابانية تُدعى (ساكورا)، يتزوجا وينجبا طفلين توأم، وفي ظل الظروف المعيشية الصعبة تطلب العودة لليابان، لكنه يرفض؛ فتأخذ الطفلين، وتسافر دون علمه، وبعد مرور 7 سنوات، يتوصلا لاتفاق ينص على مجيء الطفلين لمدة 6 شهور للإقامة معه، لكن بشروط.', 'Muharram falls in love with a Japanese diplomat named Sakura, they get married and have twins.  But she returns to Japan with the kids without his knowledge because of the difficult living conditions. Seven years later, they reach an agreement that the children come for six months to stay with him, but under conditions.', 6.1, '["كوميديا"]'::jsonb, '[{"name": "أحمد عيد", "character": "محرم", "profile_path": "/8mkmyIoo0EAfZ00YbLetFsUCirY.jpg"}, {"name": "ندى موسى", "character": "لبنى", "profile_path": "/lYKQkpiM6XyRUJ2RhBkTxPZvWKc.jpg"}, {"name": "محمد ثروت", "character": "شاهين", "profile_path": "/3uqttDmL1KH7811E3plwINeGtUs.jpg"}, {"name": "هشام إسماعيل", "character": "فرحات الديب المحامى", "profile_path": "/kCXHQWokhgiyGzFAaoNnZSiH7yF.jpg"}, {"name": "إيمان السيد", "character": "بدرية - الأخت", "profile_path": "/3ZBU4Aj2owkabyG3pR2oBUB0sy7.jpg"}, {"name": "Saki Tsukamoto", "character": "ساكورا", "profile_path": "/qtfzhSOhQOpVlSTbC4hylhJA8Z1.jpg"}]'::jsonb, 91) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
