INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (12, 'movie', 'اللي بالي بالك', 'You Know Who', 'اللي بالي بالك', 'اللي بالي بالك', 2003, 42319, 'movie', '/txstnOjizjPhtTeVN8pyY8OU8lZ.jpg', '/aqqh8NT9Ky5DWgS7cAnQO9M8z4E.jpg', 'يحكي الفيلم قصة اللمبي تلك الشخصية التي جسدها محمد سعد في فيلم سينمائي، ويعد هذ الفيلم تكملة للفيلم السابق ويجسد محمد سعد فيه شخصيتين أحدهما لرياض المنفلوطي الضابط الحازم واللمبي الذي سيحل محل رياض بعد وفاته في حادث سيارة ومن هنا تنشأ المفارقات الكوميدية.', 'Ellambi how stole from his uncle and go to prison and then he escaped from prison and during the hunting he makes an accident', 6.5, '["كوميديا", "جريمة", "رومنسية"]'::jsonb, '[{"name": "محمد سعد", "character": "Ellembi / Riyad El-Manfaloti", "profile_path": "/zpIK3GYmqDPumneEDf0aqsqxhV1.jpg"}, {"name": "حسن حسني", "character": "Adham", "profile_path": "/vMG9Carh5bi18v5unk06aYvvKZw.jpg"}, {"name": "نيفين مندور", "character": "فيحاء", "profile_path": "/5TUIfOb1s5d7GkmnWgqWgPtGrZj.jpg"}, {"name": "طارق الأمير", "character": "", "profile_path": "/jj6DaKgiRZWdgpWVerr0IAfrEQY.jpg"}, {"name": "عبلة كامل", "character": "Doctor", "profile_path": "/wVFfL9ZEQx4LZ4AfVvx2K8ab80b.jpg"}, {"name": "سامي العدل", "character": "", "profile_path": "/3a866qPfEYhTa4ragVkg1lYnA5e.jpg"}]'::jsonb, 110) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (13, 'movie', 'الظالم والمظلوم', 'El Zalem Wel Mazloom', 'الظالم والمظلوم', 'الظالم والمظلوم', 1989, 572115, 'movie', '/m3WS5x8BDK8E1WX6c3bkEpptb4h.jpg', '/jDncawOFlWpCDknWjPfDaRWghk1.jpg', 'A young man working in Alexandria marries his beautiful sweetheart, which is desired by a senior official in the Socialist Union uses his influence to get the husband unjustly imprisoned and sentenced to 25 years. And then comes out to avenge those who imprisoned him.', 'A young man working in Alexandria marries his beautiful sweetheart, which is desired by a senior official in the Socialist Union uses his influence to get the husband unjustly imprisoned and sentenced to 25 years. And then comes out to avenge those who imprisoned him.', 7.2, '[]'::jsonb, '[{"name": "نور الشريف", "character": "جابر الونش / مرسي جابر الونش", "profile_path": "/wBFojkh5Tr2JCHWkQ7sfmo2SKgd.jpg"}, {"name": "إلهام شاهين", "character": "بدور", "profile_path": "/hG3IfVj7D51Qm42ML64IR8dW3h8.jpg"}, {"name": "حسن حسني", "character": "إبراهيم النص", "profile_path": "/vMG9Carh5bi18v5unk06aYvvKZw.jpg"}, {"name": "جمال إسماعيل", "character": "القوصى عبدالسلام", "profile_path": "/wNvs1uFFum4cVnVvJzRNBheSZ9G.jpg"}, {"name": "يوسف داوود", "character": "سالم", "profile_path": "/uTz8sNPGcTMzwNaPdkTcsiDsQPo.jpg"}, {"name": "فاروق نجيب", "character": "برقوقه", "profile_path": "/u0bOIwdJaBp0tFAXnG3VEuOvuzQ.jpg"}]'::jsonb, 120) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXC