INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (14, 'movie', 'رغدة متوحشة', 'Savage Raghda', 'رغدة متوحشة', 'رغده متوحشه', 2018, 546922, 'movie', '/7mSAUtjBMdyWYgq8GQSnxmgLFTQ.jpg', '/5lmxzmT4s66TjEJSmJWHMtat027.jpg', 'عندما يعلم إسماعيل وهو شاب يعمل بأحد مراكز التجميل أن مخرج إعلانات يبحث عن وجه جديد، يحول نفسه إلى فتاة ليشارك في تصوير الإعلان.', 'Desperate to support his son, a single father uses his talent with makeup to dress up as a woman to try out for a part in a commercial.', 4.2, '["عائلي", "كوميديا"]'::jsonb, '[{"name": "رامز جلال", "character": "إسماعيل الجارحي (رغدة)", "profile_path": "/AtDCtYZBTswr4OXJVwvZOhrPUbj.jpg"}, {"name": "ريهام حجاج", "character": "رانيا فهمي", "profile_path": "/xCbVOGEiJg7rIjcpY76Q5wyZ5B4.jpg"}, {"name": "بيومي فؤاد", "character": "أدهم العشري", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "محمد ثروت", "character": "جريشة", "profile_path": "/3uqttDmL1KH7811E3plwINeGtUs.jpg"}, {"name": "أحمد فتحي", "character": "سامح", "profile_path": "/mZtqVj2TP0qyrdsRZB8WwYeFKrq.jpg"}, {"name": "إنتصار", "character": "يسرا", "profile_path": "/ljvthYcSu8we0v2CZ1511Dl5LUL.jpg"}]'::jsonb, 90) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (15, 'movie', 'برا المنهج', 'Bara El Manhag', 'برا المنهج', 'برا المنهج', 2021, 892306, 'movie', '/mp6PDqcdVFNxDbODQ9CJeM0lf8A.jpg', '/cAjf1lh5roaig8WzgzgkgtOALIr.jpg', 'يحاول الطفل اليتيم نور، الذي يبلغ من العمر 13 سنة، اكتساب احترام زملائه؛ من خلال دخول منزل مهجور أمام المدرسة، يخاف الأولاد المرور بقربه ليكتشف أن الذي يسكنه رجل عجوز يعيش هناك مختبئاً من العالم. تنشأ صداقة وعلاقة تربوية بين الصبي والرجل العجوز، ما يدفعهما إلى رحلة لاكتشاف الذات.', 'Nour is a 13-year-old orphan living in the countryside in the early 1980s. He is smart, but is also a compulsive liar with vision problems and wears eyeglasses that don''t quite remedy his weakened eyesight. To gain the respect of his fellow classmates, he ventures inside a haunted house right in front of the school, one that all the kids are afraid to enter. Inside, he finds a solitary old man who''s hiding from the world. A friendship and apprenticeship are born between the boy and the old man, initiating a journey of self-discovery that lies at the very heart of this light-hearted drama.', 7.9, '["دراما", "كوميديا"]'::jsonb, '[{"name": "عمر شريف", "character": "", "profile_path": "/iSiOazDKO0tIChVnn79oJJGYTHp.jpg"}, {"name": "ماجد الكدواني", "character": "", "profile_path": "/iBOBl5XrufQr67yqUU7YOUXoY54.jpg"}, {"name": "روبي", "character": "", "profile_path": "/oHnmUfGuJuNdS2QcoZlKUZwfHAi.jpg"}, {"name": "دنيا ماهر", "character": "", "profile_path": "/y4lVAb0EBl5M1sCIeATftZzbi2G.jpg"}, {"name": "أحمد خالد صالح", "character": "", "profile_path": "/oh1ng5yRPv56h6tXza661BMR1G3.jpg"}, {"name": "أحمد أمين", "character": "", "profile_path": "/b22RdCDUrUEmD1g8X1gkHqF9q1U.jpg"}]'::jsonb, 101) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (16, 'movie', 'لخمة راس', 'Lakhmet Ras', 'لخمة راس', 'لخمه راس', 2006, 514018, 'movie', '/joagsrOpT7uBttyMMdUbdUkPXfR.jpg', '/bed9Z86527cJxvPLGx51kCH0V0t.jpg', 'يحلم صابران يلتحق ابنه يوسف بكلية الشرطة ولكن كلية الشرطة لم تقبل يوسف لسمنته الزائدة ، ويقع صابرفي مشكلة كبيرة لانه اقترض مال من اهل الحته فيتظاهر يوسف بانه قبل فى الكليه ويلبس بدلة طالب بكلية الشرطة ويسافر الى والدته , وفى الاوتوبيس تتبدل حقيبته مع حقيبة المجرم نخنوخ التى تحتوى على رأس قتيل ، وتقوم العصابة بإختطاف خطيبة يوسف لاسترجاع الحقيبة.', 'Saber dreams of joining his son Yusuf at the police academy, but the police college did not accept Yusuf for his extra charm. Saberifi is a big problem because he borrowed money from his family. Yusuf pretends to be in college and wears a police uniform and travels to his mother. In his bus, Containing a dead head, and the gang kidnapped Yusuf''s fiancée to retrieve the bag.', 5.9, '["كوميديا", "عائلي"]'::jsonb, '[{"name": "أحمد رزق", "character": "يوسف \"ويكا\" صابر", "profile_path": "/st0gdwDQQ6SuVjdR6YzebQ4rmEg.jpg"}, {"name": "أشرف عبدالباقي", "character": "نخنوخ", "profile_path": "/5Kazsywa6e7bftoQcJEGXCLJHRZ.jpg"}, {"name": "سعد الصغير", "character": "سفينة", "profile_path": "/vkjjqbTRbioT1eoLhc01Pgbl18u.jpg"}, {"name": "سامح حسين", "character": "دبشة", "profile_path": "/9pvQYPlo9V1AGVEci5wu808RipM.jpg"}, {"name": "مها أحمد", "character": "حبيبه", "profile_path": "/6H4A2o0rqK3sdymlREZ6bgQAqzc.jpg"}, {"name": "حسن حسني", "character": "صابر السويفى", "profile_path": "/vMG9Carh5bi18v5unk06aYvvKZw.jpg"}]'::jsonb, 115) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (17, 'movie', 'يا أنا يا خالتي', 'Me or My Aunt', 'يا أنا يا خالتي', 'يا انا يا خالتي', 2005, 406854, 'movie', '/etUDmMO1lobnCG5cqOAu8pJpj5z.jpg', '/vfcbs9a5QjIggCAORRufvjYniR0.jpg', 'تدور القصة حول (تيمور) الطالب بمعهد الموسيقى، والمرتبط عاطفيًا بزميلته (نوال)، ويسعى للزواج منها، لكن والدة نوال تؤمن بالسحر والشعوذة، فيلجأ تيمور إلى وضع قناع إصطناعي ليمثل شخصية الساحرة (الخالة نوسة) حتى يتمكن من نيل رضاها ومباركتها لإرتباطهما، فهل سينجح؟', 'Henedy plays Taimor, a Young man studies music. He loves his colleague and intends to marry her. Her mother, who believes in magic, refuses their marriage.', 6.1, '["كوميديا"]'::jsonb, '[{"name": "محمد هنيدي", "character": "تيمور/ الخالة نوسة", "profile_path": "/duDDRRuYjC3qvabxA4w1e1y7g6R.jpg"}, {"name": "حسن حسني", "character": "ببلاوي", "profile_path": "/vMG9Carh5bi18v5unk06aYvvKZw.jpg"}, {"name": "دنيا سمير غانم", "character": "نوال", "profile_path": "/kNXX9aE5XpW2igRuEzAlbJ0r1yL.jpg"}, {"name": "لطفي لبيب", "character": "بشندي", "profile_path": "/guGZ0Xv4csBj10ipPlQAgf0yq6o.jpg"}, {"name": "علاء مرسي", "character": "عمرو", "profile_path": "/wE5NLHpCy3iJa77wDbZmFKhoHsR.jpg"}, {"name": "نبيل عيسى", "character": "فودة", "profile_path": "/rZTGdfjmDBWs7iw68JvWTulHBl4.jpg"}]'::jsonb, 105) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (18, 'movie', 'الحناكيش', 'The Hustlers', 'الحناكيش', 'الحناكيش', 1986, 418423, 'movie', '/lOBQX004DhWDP7lO1SYuqMXvPnO.jpg', NULL, 'يعود (طاهر) من المنفى ويطلع ولديه (عصام)، و(عمر) على سر دفنه لحقيبة مليئة بالذهب والمجوهرات في حديقة الفيلا التي كان يمتلكها قبل نفيه، ويضع خطة لإستعادتها بأن يوقع (عصام) بالخادمة (عواطف) في حبه، ليتمكن من دخول الفيلا، وتتوالى الأحداث.', 'Tahar returns from exile and informs his sons (Issam) and (Omar) of the secret of his burial for a bag full of gold and jewelry in the garden of the villa that he owned before his exile.', 0.0, '[]'::jsonb, '[{"name": "نبيلة عبيد", "character": "", "profile_path": "/ic5fFHKofWxJsluIqhNQgA1Pp69.jpg"}, {"name": "كمال الشناوي", "character": "", "profile_path": "/hT887J0ndDEChmjFiKU1OsSrHk8.jpg"}, {"name": "فاروق الفيشاوي", "character": "", "profile_path": "/kSatrCW9N69Px33OTRzTwc90XmQ.jpg"}, {"name": "عبدالله مشرف", "character": "", "profile_path": "/agbxF5mqQws2izKEnJz2zvaz4Rw.jpg"}, {"name": "حاتم ذو الفقار", "character": "", "profile_path": "/esbeTATCtBCZ2UiQVU27v8I3CjD.jpg"}, {"name": "عبدالغني ناصر", "character": "", "profile_path": "/u43pO0HlyH21WsebLKru96zHBgT.jpg"}]'::jsonb, 96) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (19, 'movie', 'جواب اعتقال', 'Detention Letter', 'جواب اعتقال', 'جواب اعتقال', 2017, 463905, 'movie', '/3x4AQyeNvzoDMw3DGCMoQMU1Scf.jpg', '/ielOWFvi6J8EXBH6IKh3cqpwQtj.jpg', 'ينضم (خالد الدجوي) إلى صفوف إحدى الجماعات الإرهابية، وعندما يحاول أخيه (أحمد) الانضمام لهذه الجماعة، يرفض (خالد) ذلك، ويحاول منعه، إلا أنه ينضم، وفي أحد الأيام يُقتل (أحمد) على يد عضو بالجماعة، ويجن جنون (خالد) الذي يسعى للانتقام من الجماعة، وهى نفس اللحظة التي يصدر فيها جواب اعتقال ضد (خالد).', 'Khaled, in a terrorist group believing he fights for God, tries stopping his brother Ahmad from joining. After Ahmad joins and dies in a group dispute, Khaled seeks revenge until police arrest him.', 5.2, '["حركة", "جريمة", "إثارة"]'::jsonb, '[{"name": "محمد رمضان", "character": "Khalid Eldegwy", "profile_path": "/2UlMUlVJqW59dvXQ0NOQPPnlPWc.jpg"}, {"name": "دينا الشربيني", "character": "", "profile_path": "/yKIdQwGzMtYN7j75gSQOYQOwVXz.jpg"}, {"name": "أحمد راتب", "character": "", "profile_path": "/nJr6S2q3hdXZlffPRNp9Mldl34U.jpg"}, {"name": "إياد نصار", "character": "", "profile_path": "/1rMMqeDTEWIpEVIEfBYbOTow6kA.jpg"}, {"name": "سيد رجب", "character": "", "profile_path": "/r6zPbQX4Rj4Y1ynk5Ym4kfdYBpq.jpg"}, {"name": "صبري فواز", "character": "", "profile_path": "/6YYhKaE8MlMnFCySd9zmCS9RMQM.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (20, 'movie', 'البدلة', 'The Suit', 'البدلة', 'البدله', 2018, 532108, 'movie', '/qYmdApNCqwDN6Q09NQeJBQPUAFs.jpg', '/oKXLdkWsva7SoXF7KjKwn6weBdM.jpg', 'تدور القصة حول حمادة، ووليد اللذين ولدا في نفس اليوم فاشلين في الحياة، يقرران الذهاب إلى حفلة تنكرية، ويتنكران في زي رجال الشرطة لمقابلة زملائهم القدامى، الأمر الذي يجعل الجميع يعتقد بأنهما شرطيين حقيقيين، وتقع لهما العديد من الأحداث والمشاكل.', 'The events revolve around Akram, who receives an invitation to attend a masquerade party. He decides to wear police uniforms, which causes him to suffer a crisis as a police officer, while looking for a particular file.', 5.9, '["حركة", "كوميديا", "دراما"]'::jsonb, '[{"name": "تامر حسني", "character": "Walid Gamal", "profile_path": "/2YGi3xoFD3EKXUKprTkRXVRHquH.jpg"}, {"name": "أكرم حسني", "character": "Hamadah Ainel-Aql", "profile_path": "/tZGdekospdRJ9XZ25hQ7W6RwB9M.jpg"}, {"name": "ماجد المصري", "character": "Markos", "profile_path": "/hCFDKcAiotPNs5cvlhHXgFS6dX0.jpg"}, {"name": "أمينة خليل", "character": "Rim", "profile_path": "/eHJBpaypMN52VSIF84r5MgvC0Mr.jpg"}, {"name": "Mahmoud El-Bezzawy", "character": "Chief prosecutor", "profile_path": null}, {"name": "دلال عبدالعزيز", "character": "Nagat", "profile_path": "/oIW8HsQaRbb1j81Fi4FghJryuTj.jpg"}]'::jsonb, 97) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (21, 'movie', 'حصل خير', 'It''s Fine', 'حصل خير', 'حصل خير', 2012, 170823, 'movie', '/fZo5j5NHeOZLgBqbFxDQ9DBqX1U.jpg', '/lmSfR2rRwzaBoO5imwqcIkVe5L1.jpg', 'راقصة شعبية (قمر) تسكن عمارة تضم مجموعة من الأسر، وفور وصول الساكنة الجديدة، يتهافت عليها الأزواج ومنهم موظف مصلحة الضرائب فوزي (كريم محمود عبد العزيز)، ومدرس اللغة العربية (محمد رمضان)، والمطرب (سعد الصغير)، وينقلب حال الأسر، فتحاول الزوجات الحفاظ على أزواجهن منها في قالب من الأحداث الكوميدية.', 'Qamar is a belly dancer who moves into building inhabited by several families. When she moves in, she is bombarded by the husbands'' attention. The husbands are Fawzi, a tax authority employee, an Arabic teacher and a singer. Their family lives are disrupted, and their wives attempt to keep their husbands in a comedy setting.', 5.3, '["دراما", "كوميديا", "موسيقى"]'::jsonb, '[{"name": "سعد الصغير", "character": "أش أش", "profile_path": "/vkjjqbTRbioT1eoLhc01Pgbl18u.jpg"}, {"name": "أيتن عامر", "character": "رقة", "profile_path": "/vVANxXVcWOSC6r3O3HTJGR39Zve.jpg"}, {"name": "لطفي لبيب", "character": "أبو الوفا", "profile_path": "/guGZ0Xv4csBj10ipPlQAgf0yq6o.jpg"}, {"name": "كريم محمود عبدالعزيز", "character": "فوزي", "profile_path": "/lIIiYr9DUWFoBIMVwX10gM7XpuV.jpg"}, {"name": "محمد رمضان", "character": "عفيفي", "profile_path": "/2UlMUlVJqW59dvXQ0NOQPPnlPWc.jpg"}, {"name": "Qamar", "character": "قمر", "profile_path": null}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (22, 'movie', 'صايع بحر', 'The Beach Loafer', 'صايع بحر', 'صايع بحر', 2004, 56336, 'movie', '/qScs2RwHuTfNTILX89ssYiiClCr.jpg', '/8CtG6fRb9aA9gjabD5jS0fLfk42.jpg', 'حسن حنتيرة وهيمة وعبده، ثلاث أصدقاء من الإسكندرية يغنون في الأفراح الشعبية، يٌتهم حنتيرة بالتورط في جريمة قتل، ويحاولون إثبات براءته لكي يتمكن من الزواج بخطيبته.', 'Three friends from Alexandria singing in the popular Wedding accuse someone of murder and trying to prove his innocence in order to be able to marry his fiancee.', 4.9, '["كوميديا", "جريمة", "رومنسية"]'::jsonb, '[{"name": "أحمد حلمي", "character": "حنتيرة", "profile_path": "/xVhX7ia3ptI43V65Os90gbfgxAe.jpg"}, {"name": "ياسمين عبدالعزيز", "character": "نعمة", "profile_path": "/6WevW0u4fa47n5NSSps18leaPep.jpg"}, {"name": "محمود عبدالمغني", "character": "عماد", "profile_path": "/78NvDJqQ2X71GDKXDIpH0kqEdvp.jpg"}, {"name": "Riko", "character": "", "profile_path": "/eEyOCZZP3DodUQcAI8NUI7x4gmZ.jpg"}, {"name": "أحمد راتب", "character": "", "profile_path": "/nJr6S2q3hdXZlffPRNp9Mldl34U.jpg"}, {"name": "سعاد نصر", "character": "والدة حنتيرة", "profile_path": "/nT6VHDAuqFDE5WWEzQ5807kDuW0.jpg"}]'::jsonb, 112) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (23, 'movie', 'كراكون في الشارع', 'Karakon On The Street', 'كراكون في الشارع', 'كراكون في الشارع', 1986, 514146, 'movie', '/nnHFW4I27UxBOUllGRxBFIhwYjj.jpg', '/A4iUG9Pij4Vkci1H8AAMUZNcFZE.jpg', 'يقيم المهندس شريف وزوجته سعاد المُدرّسة وابنتهما سارة وابنهما هانى ووالدته بمساكن الإيواء بعد هدم منزلهم، ونظرا للمستوى غير الإنسانى للمعيشة في مساكن الإيواء يلجأون إلى فناء حوش الأسرة ويفاجأون بإقامة أبو دومة فيه فيشب الخلاف بين الطرفين . تأمر النيابة بأن يتقاسموا الحوش. يتمكن شريف من تصميم مسكن متنقل من الأخشاب والإقامة فيه. يتعرّض لمضايقات عديدة وتنجب زوجته ولدا يسميه كراكون، من وحى استدعائه المتكرر للكراكون بتهم كثيرة، كسرقة التيار الكهربائي وإشغال الطريق. يقتنع عدد كبير من الشباب بفكرة المسكن المتنقل بعد إذاعة برنامج تليفزيوني عن تجربة شريف. يشرعون فى إقامة عدد من هذه المساكن بالصحراء، لكن شرطة المرافق تقوم بإزالتها بناء على أمر سلطات المحافظة تتدخل السلطات العيا وتآمر بالإبقاء عليها.', 'Sharif, his wife Su''ad, their daughter Sarah, their son Hany and his mother are all living in the shelters after their house was demolished. Due to the inhumane standard of living in the shelters, they go to live in the courtyard of the family house. Unfortunately they find another person living there. Sharif designs and builds a wooden cabin to live in the street. He is subjected to many harassment.', 6.8, '["كوميديا"]'::jsonb, '[{"name": "عادل إمام", "character": "Sherif Al Masry", "profile_path": "/vPEubkxYDRfkSUDoAfJUWQgg4cD.jpg"}, {"name": "يسرا", "character": "Suad", "profile_path": "/8t6l70q7XT8Mv1hQSFqHqqnVSgX.jpg"}, {"name": "علي الشريف", "character": "Abuo Doma", "profile_path": "/yqbj6gAt8clSeV3P0ymXqx5QN8g.jpg"}, {"name": "نعيمة الصغير", "character": "Sherif Mother", "profile_path": "/s1fVNL6G0eEcUlatHbdtBsdrnwF.jpg"}, {"name": "يوسف داوود", "character": "Shaban", "profile_path": "/uTz8sNPGcTMzwNaPdkTcsiDsQPo.jpg"}, {"name": "رأفت ماهر لبيب", "character": "Hany", "profile_path": "/gYbL8MxyVTcqd3K2W8PryZOxVP8.jpg"}]'::jsonb, 108) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
