INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (25, 'movie', 'حدث فى٢ طلعت حرب', 'Happened on 2 Talaat Harb', 'حدث في ٢ طلعت حرب', 'حدث في 2 طلعت حرب', 2022, 949962, 'movie', '/nEUJO3KSiQnGrFwHqIPV0FsQGa1.jpg', '/WuozhZH28TNX3GVzs1gtSQjzOt.jpg', 'يعيش أربعة أشخاص في الشقة نفسها خلال فترات زمنية مختلفة، ويحمل كل منهم حكاية تعرض في إطار تأثير الحالة السياسية على المجتمع المحيط بهم', 'Four stories take place in a furnished apartment that we follow through the doorman and his family who live on top of the building in a miserable room. In the first story, a doctor tries to treat a figure with a political position. In the second story, Hassan meets in the 1970s with his old friend Nadim, who comes from Lebanon during its Civil War. The third story takes place at the beginning of the new millennium and the takeover of businessmen. As for the fourth story, it takes place before January 2011 when Sami returns under pressure from his family to sell the apartment and the whole building.', 8.5, '["دراما", "رومنسية"]'::jsonb, '[{"name": "سمير صبري", "character": "", "profile_path": "/qNCXv1BxUdkSov7pOQmaFiWxCzX.jpg"}, {"name": "عبير صبري", "character": "", "profile_path": "/sEX1mAUVltS8Lt0Wv0IbaxisYt.jpg"}, {"name": "أحمد وفيق", "character": "", "profile_path": "/fBYFStyMSTDBZH3egH5j7xpCh3H.jpg"}, {"name": "أحمد مجدي", "character": "", "profile_path": "/kcbZnjkdCZaDm8CHZAhHo5PxgNK.jpg"}, {"name": "سهر الصايغ", "character": "", "profile_path": "/AlcaJiTiUyBlzSL7GRq2YzaSfjJ.jpg"}, {"name": "شريف دسوقي", "character": "", "profile_path": "/dT4V6FdpobWJQMFz575t4On5hXl.jpg"}]'::jsonb, 115) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year