INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (27, 'series', 'ظل', 'Shadow', 'ظل', 'ظل', 2022, 196596, 'series', '/jRahxaSiq6S00wZa8EmVfmbSwar.jpg', '/h7xA5R8HDeLMAjbaFeQP8uIqdTm.jpg', 'متجاهلا قيمه الأخلاقية، ينشر محامي باسمه رواية توفي كاتبها، ليكتشف بعد أن يحقق نجاحا شاسعا أن أحداث الرواية حقيقية ويصبح المتهم الأساسي في جريمة قتل.', 'A lawyer ignores his values and publishes a dead man’s book in his own name, only to discover that the murder story is real and become the prime suspect.', 5.2, '["دراما"]'::jsonb, '[{"name": "عبدالمنعم عمايري", "character": "", "profile_path": "/cS8riByO0wTnjIjp5KqMnabbECv.jpg"}, {"name": "جيسي عبدو", "character": "", "profile_path": "/aHmPGthDM7CvrrtsIfvi7YrbFGw.jpg"}, {"name": "كندة حنا", "character": "", "profile_path": "/rzp7bBPWe568VBnwvL32ss6Angf.jpg"}, {"name": "جمال سليمان", "character": "", "profile_path": "/lc7zKY4FrYR652UkIuZTYXqesMG.jpg"}]'::jsonb, 45) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
