INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (31, 'series', 'جوما', 'Juma', 'جوما', 'جوما', 2025, 283744, 'series', '/6EYZBAtPKar7fmPKHQt9gcRnFcW.jpg', '/nleSISgSAQlm28ulmyJndYpSkUu.jpg', 'تتقاطع حياة طبيب نفسي مع العديد من الأشخاص من حوله، لكن تؤدي عقدهم النفسية والماضي السيئ والمشوه لكل منهم إلى حدوث صراعات خفية وأُخرى معلنة، وتدفعهم لارتكاب جرائم بشعة، لتتسبب في خسائر كبيرة للكل.', 'The life of a psychiatrist intersects with many people around him, but their psychological complexes and the bad and distorted past of each of them lead to hidden and overt conflicts, which push them to commit heinous crimes, causing great losses for everyone.', 0.0, '["دراما"]'::jsonb, '[{"name": "ميرفت أمين", "character": "", "profile_path": "/wJnpt9qKrUL3ac0zCpUaYm0t7Zq.jpg"}, {"name": "محمود عبدالمغني", "character": "", "profile_path": "/78NvDJqQ2X71GDKXDIpH0kqEdvp.jpg"}, {"name": "ريم البارودي", "character": "", "profile_path": "/p15h77ySUCXfHouqgzpFg9CuhMO.jpg"}, {"name": "فراس سعيد", "character": "", "profile_path": "/3u4vxTtzgRu6miJbqmNSr6zerPF.jpg"}, {"name": "محمد مهران", "character": "", "profile_path": "/cxeJx7eOnHq8dZf5x4M2UnYfV8O.jpg"}, {"name": "مارتينا عادل", "character": "", "profile_path": "/4rdTOIev0aHQCpbaPIbPBQLvHd8.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (32, 'movie', 'من أجل زيكو', 'For Zeko', 'من أجل زيكو', 'من اجل زيكو', 2022, 911622, 'movie', '/okcbyzM7bNakeUUVAJCWYYcc1id.jpg', '/gWkw4bAbqKBeocnDOLu53TIQOvP.jpg', 'عندما تتسنى الفرصة لزيكو أن يشارك في مسابقة أذكى طفل في مصر، ينطلق مع عائلته في رحلة على الطريق، ولكن سرعان ما يتعرضون لتحديات عديدة تصعب عليهم الوصول.', 'The story follows a simple family whose young son, Zeko, wins the opportunity to participate in a contest for Egypt''s smartest child. As they set out to attend the contest, many paradoxes happen to them during the two-day trip', 6.7, '["كوميديا", "دراما"]'::jsonb, '[{"name": "كريم محمود عبدالعزيز", "character": "فتحي", "profile_path": "/lIIiYr9DUWFoBIMVwX10gM7XpuV.jpg"}, {"name": "منة شلبي", "character": "صفاء", "profile_path": "/oxX093z8VFpDUTDTR0T0WFaMIos.jpg"}, {"name": "محمود حافظ", "character": "عصام", "profile_path": "/j3rqnfwdNttoKOoVUphD7APd9cy.jpg"}, {"name": "محمد محمود", "character": "الجد خميس", "profile_path": "/9UIBmYQDSX8N0XZjOdRD5PpQMtl.jpg"}, {"name": "Youssef Salah", "character": "زيكو", "profile_path": "/5lOrX1cqZUSIFXRXcifE41nsSgO.jpg"}, {"name": "عمرو عبدالجليل", "character": "قاطع طريق", "profile_path": "/5H6iU6KXLvfLPzjPIm3DMkOGtf0.jpg"}]'::jsonb, 92) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
