INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (35, 'movie', 'ثانية واحدة', 'One Second', 'ثانية واحدة', 'ثانيه واحده', 2021, 827818, 'movie', '/lGVkh5Ur6TZKTgj36hFkyTZdZLo.jpg', '/875z76chnTDCh9kUZdIYCEqmjdu.jpg', 'تدور أحداث الفيلم في إطار رومانسي كوميدي، حيث يتعرف شاب على فتاة ويتسبب لها في الكثير من المشاكل، ثم يتعرض لحادث يقلب حياته بشكل كبير.', 'The story follows a young man who gets to know a girl and causes her many problems. But when he''s exposed to an accident, his life takes a drastic turn.', 5.5, '["كوميديا", "رومنسية", "دراما", "تاريخ"]'::jsonb, '[{"name": "دينا الشربيني", "character": "دينا الشامي", "profile_path": "/yKIdQwGzMtYN7j75gSQOYQOwVXz.jpg"}, {"name": "مصطفى خاطر", "character": "آدم عثمان / قدري", "profile_path": "/pj5b1XP1iM8BaCKb6QOdZpAD8xW.jpg"}, {"name": "بيومي فؤاد", "character": "البواب", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "سوسن بدر", "character": "سكينة - والدة دينا", "profile_path": "/yHgnipZ0bDUjjdf1Pu9S7bEhcun.jpg"}, {"name": "شريف دسوقي", "character": "محمود الشامي - والد دينا", "profile_path": "/dT4V6FdpobWJQMFz575t4On5hXl.jpg"}, {"name": "فتحي عبدالوهاب", "character": "عماد عبدالسلام", "profile_path": "/kYIlzvwURNRxrQED5OtkqYCUN8Z.jpg"}]'::jsonb, 88) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (36, 'movie', 'مش رايحين في داهية', 'We''re Not Heading Into Trouble', 'مش رايحين في داهية', 'مش رايحين في داهيه', 2017, 1037728, 'movie', '/pOdGG9smkAnQmeSxaqKs7CR6x30.jpg', '/c6ihsVVaf0qrleJk9tfrDNIMxwA.jpg', 'يعيش مجموعة من الشباب حياة فخمة وخالية من الهموم إلى أن يقوم واحد منهم بتمني أمنية سرعان ما تنقلب عليه وعلى رفاقه.', 'A group of careless, aimless youth can only live their lives recklessly. They spend their time at nightclubs with women, until an incident forces them to change the way they think. But what is this incident and how will it change the course of their lives?', 0.0, '["كوميديا", "دراما"]'::jsonb, '[{"name": "بشرى", "character": "", "profile_path": "/q5tSanaqYG1ko6dR3PMWaFtN6tL.jpg"}, {"name": "ريم مصطفى", "character": "", "profile_path": "/vCl2SFZ5bOCYEMI1hr9iPdRreQ0.jpg"}, {"name": "مي سليم", "character": "", "profile_path": "/38MDrZq8iPLKbUbDYtp92ezhZas.jpg"}, {"name": "أحمد صلاح حسني", "character": "", "profile_path": "/gGR1ZmdJmRdhBXJkQG90yVPQWZ4.jpg"}, {"name": "نبيل عيسى", "character": "", "profile_path": "/rZTGdfjmDBWs7iw68JvWTulHBl4.jpg"}, {"name": "عمر السعيد", "character": "", "profile_path": "/2vdiKlu2b4njPvoDz967ycBdQA4.jpg"}]'::jsonb, 82) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
