INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (38, 'movie', 'امرأة في الطريق', 'امرأة في الطريق', 'امرأة في الطريق', 'في الطريق', 1958, 330855, 'movie', '/w6EDHrMvbfsnFZGWsT3fdB6S09g.jpg', '/2jYWtk48cETCpZSHLm05hOYP8js.jpg', 'المعلم فرج لديه ولدان من زوجتين مختلفتين ولكنه يحب واحد عن الأخر بسبب ما فعلته أمه فيه، تقع حادثة للأب ويعتقد الأب أن صابر هو من فعلها ليفقد الأب على أثرها البصر ورغم أن صابر بريء من فعلته إلا أن الأب يصر على أنه هو من فعلها، ومع ذللك يحاول صابر الاستمرار في عمله حتى يساعد والده.', 'المعلم فرج لديه ولدان من زوجتين مختلفتين ولكنه يحب واحد عن الأخر بسبب ما فعلته أمه فيه، تقع حادثة للأب ويعتقد الأب أن صابر هو من فعلها ليفقد الأب على أثرها البصر ورغم أن صابر بريء من فعلته إلا أن الأب يصر على أنه هو من فعلها، ومع ذللك يحاول صابر الاستمرار في عمله حتى يساعد والده.', 6.5, '["دراما"]'::jsonb, '[{"name": "رشدي أباظة", "character": "صابر فرج الصعيدى", "profile_path": "/julfbz4ZSohGcXmldmAbMVNV7kD.jpg"}, {"name": "هدى سلطان", "character": "لواحظ", "profile_path": "/uGSvgQIO6xHIGJI5YuwpuBMQ5uF.jpg"}, {"name": "شكري سرحان", "character": "حسنين فرج الصعيدي", "profile_path": "/aDtuqqgvwAMkmbjVK4jFhKDaLPr.jpg"}, {"name": "زكي رستم", "character": "المعلم فرج الصعيدى", "profile_path": "/6E4bPZW5yLDBcJ3BzSP4jSnniYU.jpg"}, {"name": "عبدالغني قمر", "character": "الحاج امين عبد الصبور", "profile_path": "/7w9JefNQqdML24ZvEkj2XftaPH9.jpg"}]'::jsonb, 115) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast