INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (39, 'movie', 'حرب كرموز', 'Karmouz War', 'حرب كرموز', 'حرب كرموز', 2018, 521784, 'movie', '/utBRzHlnl0yJaaLvNnPdZHJpz0m.jpg', '/oWZgN0tvqDdL7QE2lDoXixPwnE4.jpg', 'خلال فترة اﻷربعينات، تتعرض فتاة للاغتصاب على يد مجموعة من الجنود اﻹنجليز، فيثأر لها ثلاث شباب مصريين، يموت أحدهم، ويحتجز الجندي الانجليزي الحي في قسم شرطة كرموز الذي يرأسه الجنرال يوسف المصري، ويطالب الجنرال آدمز بتسليمه إليه، لكن يوسف يرفض، ويحرك الجنرال جنود لمحاصرة قسم الشرطة.', 'Alexandria, Egypt, 1940. Three young Egyptians come to the aid of a woman being attacked by three British soldiers. One of them is arrested and thrown in jail. When the military surrounds the police station and begins an all-out assault, it''s up to one man, Gen. Youssef al-Masri, to defend his prison and protect his people.', 5.9, '["حركة", "حرب", "دراما"]'::jsonb, '[{"name": "أمير كرارة", "character": "البكباشي يوسف المصري", "profile_path": "/cfdecL9iTJfhFN2UNNLRVQPr5e.jpg"}, {"name": "غادة عبدالرازق", "character": "زوبة - فتاة البغاء", "profile_path": "/57KpAr5jKo8updReZSqig12LycM.jpg"}, {"name": "محمود حميدة", "character": "بكباشي معزول عزت الوحش", "profile_path": "/8uSJfakEstaPOBqCtn1oIzJm7VZ.jpg"}, {"name": "مصطفى خاطر", "character": "عصفورة - اللص", "profile_path": "/pj5b1XP1iM8BaCKb6QOdZpAD8xW.jpg"}, {"name": "بيومي فؤاد", "character": "رياض الشندويلي - عضو مجلس النواب", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "Fouad Sharaf ElDein", "character": "الجنرال آدم فرانك", "profile_path": "/qJwC6pjSuXEz4bHpoML4CfaXr7x.jpg"}]'::jsonb, 115) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (40, 'series', 'صبايا', 'Sabaya', 'صبايا', 'صبايا', 2009, 93636, 'tv', '/5I3DU11Z5nelQMO1FUkN6dReaVK.jpg', NULL, 'صبايا هو مسلسل كوميدي سوري يحكي مسلسل صبايا قصة خمس فتيات يعشن في منزل واحد وما يتخلل ذلك من أحداث ومغامرات متفرقة نتعرف فيها على العديد من الشخصيات التي تحتك بالفتيات ضمن إطار اجتماعي كوميدي خفيف ليشكل هذا العمل عبر ثلاثين حلقة نموذجاً لعدة شرائح اجتماعية وتفاعلها مع بعضها البعض وما يرافق ذلك من مواقف تأتي انعكاساً حقيقياً للحياة الواقعية.', 'Five different girls live together. Each day they face challenges, sadness, and happiness together. They love each other and they''re basically a family.', 3.0, '["كوميديا", "دراما"]'::jsonb, '[{"name": "Deema Bayyaa", "character": "Nour", "profile_path": "/8QT143znnwKUnVGIZx92YnyGaEb.jpg"}, {"name": "Jenny Esber", "character": "Media", "profile_path": "/tTFIGzYF0PoNMZ5ydiOwBMHIdQi.jpg"}, {"name": "نسرين طافش", "character": "Layla", "profile_path": "/bFCRd1JKIYdgUzY5u58wyQEwLTE.jpg"}, {"name": "ديمة الجندي", "character": "Lobna", "profile_path": "/6r3xEgnBkQMzXUMB7Gatz04sKdJ.jpg"}, {"name": "كندة حنا", "character": "Samiha", "profile_path": "/rzp7bBPWe568VBnwvL32ss6Angf.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
