INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (42, 'series', 'صيف بارد', 'A Cold Summer', 'صيف بارد', 'صيف بارد', 2018, 279540, 'series', '/c5niYzUKGNMlOnkxMhSf0NQJ0Vy.jpg', NULL, 'في إطار درامي، تعيش ياسمين مع عائلتها وتتولى إدارة شركة والدها عقب وفاته، وتغار منها ليلى، متطلعة لثرائها الفاحش، فتنتحل شخصيتها وتتعرف على خالد للزج بياسمين في علاقة عابرة، ولكن تتحول الأمور لصالح ياسمين، في الوقت ذاته تتعرف جود على بدر وتنشأ بينهما قصة حب.', '', 0.0, '["دراما"]'::jsonb, '[{"name": "أحمد السعيد", "character": "", "profile_path": "/ozCxhUrXpEytHsac70xttjb26Q9.jpg"}, {"name": "ريم حمدان", "character": "", "profile_path": null}, {"name": "نيرمين محسن", "character": "", "profile_path": "/jcFSVOrfNfrnbWr65g7yvZ33Jn.jpg"}, {"name": "Marim Hussain", "character": "", "profile_path": "/epr2aOORDNrico7tpNhrJHt40jc.jpg"}, {"name": "شيلاء سبت", "character": "", "profile_path": "/lXAiTlFta6SnmIEznDJRgrPbDKc.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (43, 'movie', 'خير و بركة', 'Khair And Baraka', 'خير و بركة', 'خير وبركه', 2017, 543248, 'movie', '/gaFlG2WTtEBQDIeoLrUSrgjKl4E.jpg', '/nzNOTazfTgNhwOW0B6YN8BmuE2l.jpg', 'تدور أحداث الفيلم في إطار كوميدي يتناول قصة شقيقين يحاولان البحث عن فرصة عمل، وخلال رحلة البحث يواجهان العديد من المواقف الكوميدية عندما يعملان في مهن لا يعرفان عنها شيئًا.', 'Two brothers who are looking for a job, find themselves in many comedic situations during their search journey and when they work in professions they know nothing about.', 5.5, '["كوميديا"]'::jsonb, '[{"name": "علي الربيع", "character": "خير", "profile_path": "/uJHx2Gsa46WMGXFWZEIivKGHZnH.jpg"}, {"name": "دلال عبدالعزيز", "character": "فرحانه - الأم", "profile_path": "/oIW8HsQaRbb1j81Fi4FghJryuTj.jpg"}, {"name": "محمد عبد الرحمن", "character": "بركة", "profile_path": "/cmvZyoAQ5a6YrMJ5HRNbK6N5nUU.jpg"}, {"name": "تارا عماد", "character": "نازك شوقى سفينه", "profile_path": "/oNS3ui8NT6VWPIDERi2igvN82Tf.jpg"}, {"name": "بيومي فؤاد", "character": "جميل", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "مي سليم", "character": "زيزيت", "profile_path": "/38MDrZq8iPLKbUbDYtp92ezhZas.jpg"}]'::jsonb, 110) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
