INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (45, 'series', 'سدف', 'Sedef', 'سدف', 'سدف', 2025, 285156, 'series', '/n2HY1veB2O7HR31KI6TiR3t44ID.jpg', '/mB93vfHM2w81nTbwMyD2SyYNT1J.jpg', 'Set in 1970s kuwait following a series of kidnappings, where the only trace left is a polaroid photograph of the victim left in the crime scene. A family drama following Fayez his wife Amani and their daughter Sarah, Fayez is a struggling actor, who is given a chance to become a star, as their lives seems to be on the right track their daughter is kidnapped. It becomes a game of cat and mouse, everyone becomes a suspect, even Fayez himself', 'Set in 1970s kuwait following a series of kidnappings, where the only trace left is a polaroid photograph of the victim left in the crime scene. A family drama following Fayez his wife Amani and their daughter Sarah, Fayez is a struggling actor, who is given a chance to become a star, as their lives seems to be on the right track their daughter is kidnapped. It becomes a game of cat and mouse, everyone becomes a suspect, even Fayez himself', 0.0, '[]'::jsonb, '[{"name": "بثينة الرئيسي", "character": "أماني", "profile_path": "/8sT0FCn1lEFVFQ5RIOCnyOGTTOu.jpg"}, {"name": "أحمد إيراج", "character": "فهد", "profile_path": "/yeVmETvIVYkmInhw8HlihLhI1o7.jpg"}, {"name": "حسين المهدي", "character": "فايز", "profile_path": "/SoCeLXz27ABeFBWQi1Nr9gqvfY.jpg"}, {"name": "عبدالله بهمن", "character": "شاهين", "profile_path": "/8V16AwEEtOymTJwF9jaQxthpH5v.jpg"}, {"name": "خالد العجيرب", "character": "عدنان", "profile_path": "/oNFrcgpt7XIgCCQsnJMMZe5KoV5.jpg"}, {"name": "غدير السبتي", "character": "تهاني", "profile_path": "/vpmfOwlo4l43dZT5sXs9GWtN8ef.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (46, 'series', 'السبع', 'Al Sabea', 'السبع', 'السبع', 2025, 284424, 'series', '/vVsvR3IJOJhlJ8Y45ayeOyiMJRF.jpg', '/4jvORHJUqZKuA3hFTqHW0qzpYB3.jpg', 'في إطار خيالي، يتناول العمل حياة الغجر، ويسلط الضوء على الصراعات بين عائلتين بسبب المال والنفوذ، حيث يقع حادث مأساوي يؤثر على الجميع، يجعل الانتقام السبيل الوحيد لتغيير مجرى الأمور.', 'Abu Jaber’s family struggles in poverty, while Aziz’s family lives in luxury but without an heir. When Abu Jaber is unable to repay his debts, Fidda is forced to make a difficult choice: give up her newborn… or her body.', 0.0, '["خيال علمي وفانتازيا", "دراما", "غموض"]'::jsonb, '[{"name": "باسم ياخور", "character": "", "profile_path": "/bGH42YnqKpvcoNi4Q9ENoZtSs2I.jpg"}, {"name": "أمل عرفة", "character": "", "profile_path": "/cfd1sNg49Q663CQTB5XvhfgUGka.jpg"}, {"name": "حلا رجب", "character": "مطيعة", "profile_path": "/mE5MtAIkTQLdscr840tOS2GrzF0.jpg"}, {"name": "Jafra Younes", "character": "", "profile_path": null}, {"name": "أمل بوشوشة", "character": "", "profile_path": "/18fG8jYW1hFGa4hwVKeJB0fPMio.jpg"}, {"name": "عبدالمنعم عمايري", "character": "", "profile_path": "/cS8riByO0wTnjIjp5KqMnabbECv.jpg"}]'::jsonb, 40) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (47, 'movie', 'حفلة نقانق', 'Sausage Party', 'Sausage Party', 'حفله', 2016, 223702, 'movie', '/vNgdPJQ5CI60oEiiHLKRNrsDhMy.jpg', '/hsb8nNBt3emvWqBs7Xv5IKlz6Im.jpg', 'فيلم رسومي في إطار كوميدي مشوق، تدور أحداثه حول واحدة من النقانق التي يُحيّرها تفكيرها حول مسألة وجودها وكيف وُجدَت، فتشرع في البحث عن الإجابة لتكتشف حقيقة وجودها.', 'فيلم رسومي في إطار كوميدي مشوق، تدور أحداثه حول واحدة من النقانق التي يُحيّرها تفكيرها حول مسألة وجودها وكيف وُجدَت، فتشرع في البحث عن الإجابة لتكتشف حقيقة وجودها.', 5.8, '["مغامرة", "رسوم متحركة", "كوميديا", "فانتازيا"]'::jsonb, '[{"name": "سيث روغن", "character": "Frank / Sergeant Pepper / Peanut Butter (voice)", "profile_path": "/nYl9bvQzaPQLzlf0wf75clLN6Hi.jpg"}, {"name": "كريستين ويج", "character": "Brenda (voice)", "profile_path": "/6U6UGztBwk7c4lg8n5BS5QOByot.jpg"}, {"name": "جونا هيل", "character": "Carl (voice)", "profile_path": "/cymlWttB83MsAGR2EkTgANtjeRH.jpg"}, {"name": "بيل هادر", "character": "Firewater / Tequila / El Guaco (voice)", "profile_path": "/qyT50vQ9PQIEctE1IxDTEsBKstU.jpg"}, {"name": "مايكل سيرا", "character": "Barry (voice)", "profile_path": "/qjhNKsw0OLyZQgK4srhelBafcCf.jpg"}]'::jsonb, 89) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (48, 'series', 'حريم طارق', 'Hareem Tariq', 'حريم طارق', 'حريم طارق', 2022, 196052, 'series', '/A4pdIDeuXKGJJpJQdSaQyv5DpN7.jpg', '/cnNYWqe5v6tx6ADuGNFOYkH0ebm.jpg', 'في إطار كوميدي، يتناول المسلسل قصة طارق الذي تكتشف زوجته ريما خيانته لها، وزواجه من المذيعة ميسة، وتحاول كلا منهما دفع طارق لطلاق الأخرى، حتى يكتشفان زواجه من أخريات.', 'When Tariq''s wife, Rima, discovers his infidelity and his marriage to the broadcaster Maisa, both women try to push Tariq to divorce the other, until they discover his marriage to other women.', 0.0, '["كوميديا"]'::jsonb, '[{"name": "غريس قبيلي", "character": "", "profile_path": null}, {"name": "كابتن ريما", "character": "ريما", "profile_path": "/bwz2mCa5JyYG0TfjCZchEeu0l7y.jpg"}, {"name": "رنا الشافعي", "character": "", "profile_path": "/lMMabCG0f3InIZXCfzoE6nXy0zn.jpg"}, {"name": "منصور الفيلي", "character": "", "profile_path": null}, {"name": "طارق العلي", "character": "طارق", "profile_path": "/4L2aQVOR6UOcobM4UqClvW1cwFD.jpg"}, {"name": "خالد العجيرب", "character": "بدر", "profile_path": "/oNFrcgpt7XIgCCQsnJMMZe5KoV5.jpg"}]'::jsonb, 25) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
