INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (54, 'movie', 'أسوار القمر', 'The Walls of the Moon', 'أسوار القمر', 'اسوار القمر', 2015, 321761, 'movie', '/kuO3FxaqDjkduoKvIaoTkm3eq8U.jpg', '/bAM9VtXOiIxOzuURARLJqPOrvTn.jpg', 'تستفيق (زينة) من إغماءة تعرضت لها لتجد نفسها فاقدة للبصر، ولا تتذكر أي شيء، لينتهي بها الأمر بصحبة (أحمد) على مركبه، والذي يدخل في مطاردة محمومة مع (رشيد)، وبعد جلوسها وحيدة في إحدى غرف المركب، تحاول أن تسترجع كل ما حدث معها من خلال تسجيلاتها، بما في ذلك تفاصيل مثلث الحب الذي كانت هي نفسها أحد أضلاعه.', 'Zeina wakes up from a faint to find herself blind and unable to remember anything. She ends up with Ahmed on his boat, who enters into a frantic chase with Rashid. After sitting alone in one of the boat''s rooms, she tries to recall everything that happened to her through its recordings, including the details of the love triangle in which she herself was one of the sides.', 5.6, '["رومنسية", "دراما"]'::jsonb, '[{"name": "منى زكي", "character": "زينة", "profile_path": "/qXImbMkrqYpWg2jEerb1RDPr3hN.jpg"}, {"name": "عمرو سعد", "character": "رشيد", "profile_path": "/ii5oJije7WOfqBwyxAt4YettAnj.jpg"}, {"name": "آسر ياسين", "character": "أحمد", "profile_path": "/olUkZr3b6wcKCiU7Kmdoxd9CZiw.jpg"}, {"name": "سلوى محمد علي", "character": "والدة زينة", "profile_path": "/mIgBQ3gZeP4EX83zlN8f8ISs6Co.jpg"}, {"name": "محمد شاهين", "character": "", "profile_path": "/yvtb7nS52zr26MJIg6IVDkxzNKF.jpg"}, {"name": "تامر ضيائي", "character": "", "profile_path": "/dmLGgLyYiQHK2Yq6LNp0CG8XtBW.jpg"}]'::jsonb, 101) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (55, 'movie', 'لف ودوران', 'Flimflam', 'لف ودوران', 'لف ودوران', 2016, 415813, 'movie', '/ypSuDI9EFtZl2nk5CYyAST03IlM.jpg', '/98gSw6r2XP9E3kiRF2ZkF0xl1xh.jpg', 'مرشد سياحي يستغل عرضا تقدمه الشركة لقضاء شهر العسل في شرم الشيخ في سبيل مقابلة فتاة إيطالية، لكنه يفاجأ بوجود فتاة في الفيلا تدعي أنها العروس المقدم لها العرض.', 'A tour guide named "Noor" travels to Sharm el-Sheikh with his family to take the advantage of an offer provided by a company to spend a honeymoon in order to meet an Italian girl named "Perla".  He finds there a girl named "Layla " staying in the same villa .  By the time Noor''s family allied with "Layla " to discourage him from developing a relationship with "Perla".', 5.3, '["كوميديا", "عائلي", "دراما"]'::jsonb, '[{"name": "أحمد حلمي", "character": "نور قباني", "profile_path": "/xVhX7ia3ptI43V65Os90gbfgxAe.jpg"}, {"name": "دنيا سمير غانم", "character": "ليلة البعطوطي", "profile_path": "/kNXX9aE5XpW2igRuEzAlbJ0r1yL.jpg"}, {"name": "صابرين", "character": "ناهد", "profile_path": "/x9BU8T80Z6se9PnE5q32HPJimhy.jpg"}, {"name": "بيومي فؤاد", "character": "حمادة نجم", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "Gamila Awad", "character": "جومانا", "profile_path": "/qFFikLZSuEdl6yfNUyeZYB99XLJ.jpg"}, {"name": "ياسر الطوبجي", "character": "هاني - زميل نور", "profile_path": "/ibfMXbe2vGjJvdqcSh9NJLZ4wxf.jpg"}]'::jsonb, 90) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (56, 'series', 'دنيا تانية', 'Another World', 'دنيا تانية', 'دنيا تانيه', 2022, 196031, 'series', '/H66rQ35Bw1LzRxbSnoFAApbg26.jpg', '/heymh6RdBwNvticuBUhluRbeCvf.jpg', 'دنيا سالم مديرة لإحدى المدارس الدولية، ومتزوجة من "بدر"، ولديها اثنين من الابناء تتعرض "دنيا" لصدمة بعد غرق ابنها في حمام السباحة، وفقدان ابنها الثاني النطق بسبب صدمة وفاة أخيه، فتتهم زوجها بالإهمال وتسعى لخلعه', 'In a dramatic drama, a school principal named Donia Salem is shocked after her son drowns in the swimming pool, and her second son loses his speech due to the shock of his brother''s death. She accuses her husband Badr of neglect and seeks to depose him.', 0.0, '["دراما"]'::jsonb, '[{"name": "ليلى علوي", "character": "", "profile_path": "/vX4NzKS2l0SR9z40hfXylXUxRoN.jpg"}, {"name": "وفاء صادق", "character": "", "profile_path": "/bqkQOwNK6WpJN94GBykv0OAjv4I.jpg"}, {"name": "أشرف زكي", "character": "", "profile_path": "/AgYzxSLdHj1dEaFKih8UUzATxOZ.jpg"}, {"name": "مجدي كامل", "character": "", "profile_path": "/y149S0WfKcbYrIqekzw6qo3JWTH.jpg"}, {"name": "مي سليم", "character": "", "profile_path": "/38MDrZq8iPLKbUbDYtp92ezhZas.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (57, 'series', 'قلوب من ماء', 'Hearts of Water', 'قلوب من ماء', 'قلوب من ماء', 2024, 248718, 'series', '/vrhqU848CZcQyzdzsZw2gwi9662.jpg', '/yYdMzGoOOCoPGaBK5ixgi1bnACK.jpg', 'تدور الأحداث حول مجموعة من الشبان والشابات والعائلات التي جاءت واستقرت في دولة الإمارات العربية المتحدة، أملًا في البحث عن السعادة، والهروب من الماضي الموجع والحاضر الصعب إلى المستقبل الأكثر اطمئنانًا واستقرارًا.', 'The series follows a group of young men, women and families who came and settled in the United Arab Emirates, hoping to search for happiness and escape from the painful past and difficult present to a more reassuring and stable future.', 0.0, '[]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (58, 'series', 'ملكة في المنفى', 'Queen in Exile', 'ملكة في المنفى', 'ملكه في المنفي', 2010, 263154, 'series', '/hs5Koz4TW6xnSS9O4zmymSsLqGj.jpg', NULL, 'تدور احداث العمل حول حياة الملكة نازلي بداية من زواجها من الملك فؤاد واختيار البريطانيين له ليحكم مصر، وكيف استخدمها كواجهة حضارية أثناء رحلته التاريخية إلي أوروبا عام 1972، وبعد إنجاب الملك فاروق للأميرة فريال تشعر الملكة نازلي بالقلق على ابنها والعرش وتتوالى الأحداث.', 'Queen in Exile follows a deposed royal forced to rebuild her life after political betrayal drives her from her homeland. As she navigates foreign courts, hidden enemies, and the weight of her past, she confronts loyalty, identity, and the personal cost of power lost and dignity reclaimed.', 0.0, '["دراما"]'::jsonb, '[{"name": "نادية الجندي", "character": "", "profile_path": "/az5y9WqFd2FRJ2nAmzHH3KWVCWc.jpg"}, {"name": "كمال أبو رية", "character": "", "profile_path": "/1EktBy2LmZjKaldAjBObiISq4D8.jpg"}, {"name": "عايدة عبدالعزيز", "character": "", "profile_path": "/5ykpxdEIt14ML2Fq3yzbFpQTzxG.jpg"}, {"name": "ليلى طاهر", "character": "", "profile_path": "/5fod7Cs6hlquA0LwJwf3se8qtJk.jpg"}, {"name": "شريف سلامة", "character": "", "profile_path": "/1KK2HlLD8m7B0qhOb7OJmvUzGCl.jpg"}, {"name": "محمود قابيل", "character": "", "profile_path": "/wst97l3WhAW0s1BTvS3SaFhBXpH.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_