INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (59, 'program', 'الكندوش الجزء الثاني', NULL, NULL, 'الكندوش الجزء الثاني', NULL, NULL, NULL, NULL, NULL, 'برنامج تلفزيوني يُعرض على القنوات الفضائية.', NULL, NULL, '[]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (60, 'series', 'طارق ونوف', 'Tariq & Nouf', 'طارق ونوف', 'طارق ونوف', 2024, 249198, 'series', '/wdtAeZm7WWN0SsioJ2hATvqIw5v.jpg', NULL, 'في إطار من الدراما الممزوجة بالكوميديا، تقع أحداث المسلسل حول يوميات (طارق) و(نوف)، اللذين يتعرضان للعديد من المواقف والمفارقات اليومية في حياتهما، ويسعان لمواجهتها.', 'In a blend of drama and comedy, the series follows the everyday lives of Tariq and Nouf, who find themselves facing a series of daily situations and unexpected twists as they try to navigate life’s challenges together.', 0.0, '[]'::jsonb, '[{"name": "آيدا القصي", "character": "", "profile_path": "/tzu0GLkebhR7S8Rc6sdmdLXM5x5.jpg"}, {"name": "فايز بن جريس", "character": "", "profile_path": "/mQAbHDxGylni8bUCUJ8NrCiKQbU.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (65, 'movie', 'عفريت مراتي', 'My Wife''s Ghost', 'عفريت مراتي', 'عفريت مراتي', 1968, 713847, 'movie', '/y101vFQjUCvC2AcHts0Vlw7Rhmz.jpg', '/tLa6pnjcg4RVN3liSOfCXaHHwsu.jpg', 'نتيجة انشغال صالح بعمله، تعاني عايدة زوجته من الوحدة، لتنصرف إلى مشاهدة الأفلام وتبدأ بتقمص شخصيات البطلات اللاتي تشاهدهن في الأفلام، مما يوقع زوجها في مشاكل جديدة، ليحاول بمساعدة أصدقائه تخليصها من تلك الحالة.', 'As a result of Saleh''s preoccupation with his work, his wife Aida suffers from loneliness. She turns to watching films and starts impersonating the characters of the heroines she sees in the films, which gets her husband into many troubles and with the help of his friends he tries to make her stop.', 7.8, '["دراما", "رومنسية", "كوميديا"]'::jsonb, '[{"name": "شادية", "character": "Aida", "profile_path": "/62arY87I83h7Nh2dYSFLvVNOnfB.jpg"}, {"name": "صلاح ذو الفقار", "character": "Salah", "profile_path": "/gbH71T5Ko4z2npuyGSx9RNkkGPA.jpg"}, {"name": "عماد حمدي", "character": "Raif", "profile_path": "/9s5AtkshCQReedy7EXg11C8xdyF.jpg"}, {"name": "عادل إمام", "character": "Shafi''i", "profile_path": "/vPEubkxYDRfkSUDoAfJUWQgg4cD.jpg"}, {"name": "حسن حسين", "character": "", "profile_path": "/tXpfntSJHYPJKX6Fy1x55JK34ZG.jpg"}, {"name": "آمال زايد", "character": "Aida''s mother", "profile_path": "/wMJgU7hhHbp1TSxhCozW5sGiFuz.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (66, 'movie', 'ريا وسكينة', 'Rayya and  Sakina', 'ريا وسكينة', 'ريا وسكينه', 1983, 514363, 'movie', '/dihgpkiqMUzBAaId4C5Y0couuiX.jpg', '/df6bstEcGjvg2b91l5yZopRHl9X.jpg', 'فى العشرينات عزوز ممسل مسرحى فاشل وخطيبته فلة تعمل خادمة فى منزل برعى حكمدار البوليس بالاسكندرية وهو المسئول عن القبض على السفاحتين ريا وسكينة تفشل جميع الخطط التى توضع للقبض عليهما بواسطة الضابط فتحى يهدد برعى ريا وسكينة تليفونيا مما يثير الرعب فى قلب زوجته عصمت هانم ترى عصمت هانم عزوز متنكرا فى زى نسائى لمقابلة فلة فتعتقد انهما ريا وسكينة وتعطيهما مصوغاتها يتفق عزوز وفلة على التنكر والسرقة باعتبار انهما السافحتان لكنهما يقعان فى ايدى ريا وسكينة الحقيقيتينيتمكن عزوز من الهرب من منزلهما ليبلغ البوليس ويتم القبض عليهما يحصل عزوز وفلة على المكافاة ويتزوجان.', 'In the 1920s, Azouz is a failed actor and his fiancée Folla works as a maid in the house of the chief of police in Alexandria, who''s responsible for arresting serial killers Raya and Sakina. When all plans to arrest them by officer Fathi fail, Azzouz and Folla disguise themselves as Raya and Sakina.', 7.0, '["كوميديا", "جريمة", "دراما"]'::jsonb, '[{"name": "يونس شلبي", "character": "عزوز / سكينة", "profile_path": "/jLtc7MnYVPHGdIyIhKeVESVdpb7.jpg"}, {"name": "شريهان", "character": "فُلة / ريا", "profile_path": "/lNs6Coz2064WNTsVcwNhylFIfTv.jpg"}, {"name": "حسن عابدين", "character": "رعي - حكمدار الإسكندرية", "profile_path": "/tFxfjJfJdKfe9BwqXRJvT5rqSYY.jpg"}, {"name": "نعيمة وصفي", "character": "عصمت هانم", "profile_path": "/qxOwZIlLHVBUJ080oZBIYGjSKhz.jpg"}, {"name": "سميحة توفيق", "character": "سكينة", "profile_path": "/93vO1rq6tfdRb4SGwTHCMouMcBT.jpg"}, {"name": "نعيمة الصغير", "character": "ريّا", "profile_path": "/s1fVNL6G0eEcUlatHbdtBsdrnwF.jpg"}]'::jsonb, 111) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (67, 'movie', 'قلب أمه', 'Mama''s Boy', 'قلب أمه', 'قلب امه', 2018, 527735, 'movie', '/b04eCPftbA6nhfIwkT8qB0gi4DS.jpg', '/cuDUHErG5RYa31Thc1MQUnLRE9k.jpg', 'تدور الأحداث في إطار كوميدي حول زعيم عصابة يُدعى (مجدي تختوخ) يدخل في مشاجرة يُصاب على إثرها؛ وينُقل إلى المستشفى في حالة خطيرة حيث يحتاج إلى نقل قلب، وفي ذات الوقت تتوفى والدة الشاب (يونس)؛ فيلجأ اﻷطباء إلى نقل قلب والدته إلى (تختوخ) ﻹنقاذ حياته، فيتعامل مع (يونس) بطريقة حنان الأم وخوفها عليه.', 'A comedy about  a gang leader who gets into a fight and  is seriously injured, after which he is transferred to the hospital in a critical condition where he needs a heart transplant. At the same time, the mother of another young man dies and doctors resort to transferring her heart to the  gang leader to save his life, but he starts acting in a motherly way towards the young man.', 5.8, '["كوميديا"]'::jsonb, '[{"name": "هشام ماجد", "character": "يونس عبد الحي", "profile_path": "/p8jemmilRFz892wz4KBPNWuxhAN.jpg"}, {"name": "نور قدري", "character": "عليا", "profile_path": "/mhUfVbHy4YHx72T9ZUD0wCLG4qU.jpg"}, {"name": "شيكو", "character": "مجدي تختوخ", "profile_path": "/gurvnsbru3btbeENF3HANKw2VM8.jpg"}, {"name": "دلال عبدالعزيز", "character": "خلود أحمد السمنودي - أم يونس", "profile_path": "/oIW8HsQaRbb1j81Fi4FghJryuTj.jpg"}, {"name": "محمد أسامة", "character": "عوني", "profile_path": "/khnJ5LVjOjLPuTPNnPzEpCRtPT3.jpg"}, {"name": "محمود الليثي", "character": "المقدم عاطف الشعلة", "profile_path": null}]'::jsonb, 101) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (68, 'movie', '٣٠ يوم في السجن', '30 Days in Prison', '30 يوم في السجن', '30 يوم في السجن', 1966, 320981, 'movie', '/vbAl3Hh1rgHrHjqUZMnQHpwZETc.jpg', '/9xvO7RgSnsAkaO94zDRqozy4bIc.jpg', 'يعمل أمشير (فريد شوقي) فتوة في الكباريه الذي يمتلكه صديقه الثري مدحت الشماشيري (أبو بكر عزت)، ويصدر حكم قضائي على مدحت بالسجن شهرًا بعد أن تسبب في حرق شارب رجل من أثرياء الصعيد يدعى النجعاوي، ويدخل أمشير السجن بدلاً منه ليقضي مدة العقوبة مقابل مبلغ من المال، وفي تلك الأثناء يتودد مدحت لأزهار، وتكتشف خطيبته سهير نزواته لتتوالي الأحداث الكوميدية التي تكشف حقيقة مدحت.', 'Amshir works in a cabaret owned by his wealthy friend Medhat. Medhat is sentenced to a month in prison after he burned the mustache of a wealthy Upper Egyptian man named Al-Najawi. Amshir then goes to prison instead of him in exchange for a sum of money.', 6.8, '["كوميديا", "دراما", "موسيقى"]'::jsonb, '[{"name": "فريد شوقي", "character": "أمشير", "profile_path": "/eGQniixtU1hjF2Fa5rYWlvt3nLk.jpg"}, {"name": "مديحة كامل", "character": "سهير", "profile_path": "/l5HaBDR9knXllZRIAiX1oga8jjy.jpg"}, {"name": "أبو بكر عزت", "character": "مدحت الشماشيري", "profile_path": "/iVUhTgrfVe85iHUG7SUe198JEnT.jpg"}, {"name": "نوال أبو الفتوح", "character": "أزهار", "profile_path": "/gbKlShB9R1LhJhzuuyRfmdRoVe5.jpg"}, {"name": "محمد رضا", "character": "جنجل أبو شفطورة", "profile_path": "/c45atsICuA4BShxcd8qIGOHp2QU.jpg"}, {"name": "ميمي شكيب", "character": "أم سهير", "profile_path": "/mEKnx6cmfBfHagBCBVatHZ9fEeU.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_pat