INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (69, 'movie', 'احترس من الخِط', 'احترس من الخِط', 'احترس من الخِط', 'احترس من الخط', 1984, 401325, 'movie', '/8a2UrPfcJ9HKxVl2fxBCGSdzqgi.jpg', '/ykdc1vx7opYJnOSlnYsphMQ1aQx.jpg', 'تدور قصة الفيلم حول (خصوصي) الشاب البسيط، والذي يعمل بشركة ابنة عمه (نبيلة) ويقع في حبها ولكنها لا تبادله نفس الشعور، لأنها تحب (سامي) مدير الشركة، يكتشف (خصوصي) الاختلاسات التي تحدث في الشركة بواسطة مساعد مدير الشركة المقاول (مسعد) ويشيع نبأ إنتحاره كذبًا ثم يعود في شخصية مزيفة ومرعبة هى (الخُط) ليكشف ألاعيب (مسعد)، لتتصاعد الأحداث في إطار كوميدي.', 'تدور قصة الفيلم حول (خصوصي) الشاب البسيط، والذي يعمل بشركة ابنة عمه (نبيلة) ويقع في حبها ولكنها لا تبادله نفس الشعور، لأنها تحب (سامي) مدير الشركة، يكتشف (خصوصي) الاختلاسات التي تحدث في الشركة بواسطة مساعد مدير الشركة المقاول (مسعد) ويشيع نبأ إنتحاره كذبًا ثم يعود في شخصية مزيفة ومرعبة هى (الخُط) ليكشف ألاعيب (مسعد)، لتتصاعد الأحداث في إطار كوميدي.', 6.3, '["كوميديا", "دراما"]'::jsonb, '[{"name": "عادل إمام", "character": "خصوصي/ الخط خليفة الخط", "profile_path": "/vPEubkxYDRfkSUDoAfJUWQgg4cD.jpg"}, {"name": "لبلبة", "character": "نبيلة", "profile_path": "/aS0lRbuphlsd0T2RlaVXn0QAhWr.jpg"}, {"name": "سمير صبري", "character": "سامي", "profile_path": "/qNCXv1BxUdkSov7pOQmaFiWxCzX.jpg"}, {"name": "أسامة عباس", "character": "العقيد رشاد", "profile_path": "/ow1gKSNAsMefRVJqVcG2kNdpBVT.jpg"}, {"name": "عبدالله فرغلي", "character": "المقاول", "profile_path": "/gM8eNT5xncTTOk6lN8I86Hh4nOJ.jpg"}]'::jsonb, 96) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_pa