INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (70, 'program', 'حبيبي نائماً', NULL, NULL, 'حبيبي نائما', NULL, NULL, NULL, NULL, NULL, 'برنامج تلفزيوني يُعرض على القنوات الفضائية.', NULL, NULL, '[]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (71, 'movie', 'محمد حسين', 'Mohamed Hussein', 'محمد حسين', 'محمد حسين', 2019, 620635, 'movie', '/fjeKROek3rdpfdqaZZkZoHSgZyf.jpg', '/eZhfJ09aWXZIoMDZfjXzkTtxzRQ.jpg', 'يعود الرسام العالمي شريف كمال (سمير صبري) إلى وطنه (مصر) بعد 37 عامًا ليُقرر أن يرسم رسمته الأخيرة تكريمًا للوطن، ولكن تأبى لوجين ابنة زوجته (فريال يوسف) أن يحدث ذلك فتدبر خطة للانتقام منه، ويجن جنون لوجين بعدما تعلم أن أخر لوحة رسمها (شريف) قبل مقتله كانت على ظهر محمد حسين (السائق)، فتساومه لكي تحصل على الرسمة بأي طريقة كانت، ولكن محمد حسين له رأي أخر.', 'Mohamed Hussein, a chauffeur at a 5-star hotel, is accused by the police of murdering a famous painter who had just arrived from Paris and was staying at the hotel where he works, since he was the last person to come in contact with him. Before his death, the painter sketches a grand painting on Mohamed''s back which draws the attention of a mob who are now after his "back-painting".', 5.6, '["كوميديا"]'::jsonb, '[{"name": "محمد سعد", "character": "محمد حسين", "profile_path": "/zpIK3GYmqDPumneEDf0aqsqxhV1.jpg"}, {"name": "مي سليم", "character": "إيمان منصور", "profile_path": "/38MDrZq8iPLKbUbDYtp92ezhZas.jpg"}, {"name": "سمير صبري", "character": "شريف كمال", "profile_path": "/qNCXv1BxUdkSov7pOQmaFiWxCzX.jpg"}, {"name": "فريال يوسف", "character": "لوجين", "profile_path": "/wiDxuLAhwjpY5osNxBp6wWfL0RH.jpg"}, {"name": "نبيل عيسى", "character": "حاتم", "profile_path": "/rZTGdfjmDBWs7iw68JvWTulHBl4.jpg"}, {"name": "Dina Mohsen", "character": "منى", "profile_path": "/5d6WvClOPREq164sIYJlyaCbVIv.jpg"}]'::jsonb, 96) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year