INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (72, 'movie', 'بلبل أفندي', 'Bolbol Afandy', 'بلبل أفندي', 'بلبل افندي', 1948, 619032, 'movie', '/uFlmdRNrCKYRa0sXIwGHcjN2nAW.jpg', NULL, '(Sabah) is an arrogant actress, arrogant and married to the old man lover (Hassan Fayek) and lives with them his daughter Wafa (Samiha Tawfiq) engaged to the young man Munir (Kamal Hussein) and treated as a wife or mother, betraying her husband with her lover Abdullatif Abdal (Istfan Rusti) Aziz Bey, and he fought to blackmail her with the help of his wife, the employment of Znobh Alexandrian (Isaf Abdel Maqsoud).', '(Sabah) is an arrogant actress, arrogant and married to the old man lover (Hassan Fayek) and lives with them his daughter Wafa (Samiha Tawfiq) engaged to the young man Munir (Kamal Hussein) and treated as a wife or mother, betraying her husband with her lover Abdullatif Abdal (Istfan Rusti) Aziz Bey, and he fought to blackmail her with the help of his wife, the employment of Znobh Alexandrian (Isaf Abdel Maqsoud).', 6.5, '[]'::jsonb, '[{"name": "فريد الأطرش", "character": "", "profile_path": "/3M2dhjmPucvJyLwwT2GEct5Ukr1.jpg"}, {"name": "صباح", "character": "", "profile_path": "/99KbGfDOKrSOBqHY27fMXKv1VMA.jpg"}, {"name": "إسماعيل يس", "character": "", "profile_path": "/rMq2iI5br3Qy1zrNYc0XsTzNQKa.jpg"}, {"name": "حسن فايق", "character": "", "profile_path": "/9tUSkaTQHN695k6jOL30Vpbczbn.jpg"}]'::jsonb, 133) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (73, 'movie', 'إنهم يسرقون الأرانب', 'They''re Stealing Millions', 'إنهم يسرقون الأرانب', 'انهم يسرقون الارانب', 1983, 757609, 'movie', '/6jJxGlkxgEOGMGYKJbCAtm2hXzl.jpg', '/ljZLInXP9NMyz2CSkkEo7zOFtmQ.jpg', 'Two friends are thrown in jail for charges of sorcery, and they meet inside a famous businessman named Ali. The two friends get closer to Ali and discover that he has a map with a detailed plan to rob a bank.  They rob the bank, and prepare to carry out their next job once their sentence is over.', 'Two friends are thrown in jail for charges of sorcery, and they meet inside a famous businessman named Ali. The two friends get closer to Ali and discover that he has a map with a detailed plan to rob a bank.  They rob the bank, and prepare to carry out their next job once their sentence is over.', 0.0, '["كوميديا"]'::jsonb, '[{"name": "يحيى الفخراني", "character": "", "profile_path": "/lzQT2AX0yDTe63eYMjFuTIUGf4X.jpg"}, {"name": "سمير غانم", "character": "", "profile_path": "/vSqmd98zrxOAnDFnBGnt4Wihn7B.jpg"}, {"name": "لبلبة", "character": "", "profile_path": "/aS0lRbuphlsd0T2RlaVXn0QAhWr.jpg"}, {"name": "جميل راتب", "character": "", "profile_path": "/9ZNYtVH3LAq5UtGVnyPZvoKqlSp.jpg"}, {"name": "نظيم شعراوي", "character": "", "profile_path": "/y60J9E5llZKjniiZw288J4TrSrc.jpg"}, {"name": "مجدي إمام", "character": "", "profile_path": "/owBlpbgqo18aH6l5oAgZHuXhMew.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, ra