INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (74, 'movie', 'توم وجيمي', 'Tom W Jemmy', 'توم وجيمي', 'توم وجيمي', 2013, 446508, 'movie', '/pEik1o2w2D3Zlh0udWSX2zyhWTL.jpg', '/bFTPE626ZG1fJuX2wWHAYr2kSam.jpg', 'يرصد الفيلم حياة رجلٍ معاقٍ ذهنيًا، حيث إن عقله لا يتعدى عقل طفلٍ في السابعة من عمره ،بالرغم من أن جسده يبدو للجميع أنه ناضج ولكن من يقترب منه يكتشف عكس ذلك تمامًا، تتعقد الأحداث كثيرًا ذهابًا وإيابًا في جوٍ لا يخلو من الكوميديا والمرح، لينكشف لنا كثيرٌ من الجوانب الإنسانية لهذا الرجل ولكل من حوله.', 'The story of a grown man who is developmentally disabled. Despite having the physical appearance of an adult, his mental capacity is that of a 7-year-old child. As he goes through various situations, his admirable characteristics shine right through, as do the characteristics of those around him.', 3.9, '["كوميديا"]'::jsonb, '[{"name": "هاني رمزي", "character": "Tom", "profile_path": "/r0RMbUmnBuRbwLLFat60eBFq4B4.jpg"}, {"name": "حسن حسني", "character": "Jimmy", "profile_path": "/vMG9Carh5bi18v5unk06aYvvKZw.jpg"}, {"name": "Tatiana", "character": "Dina", "profile_path": null}, {"name": "جمال إسماعيل", "character": "Tom''s Grandpa", "profile_path": "/wNvs1uFFum4cVnVvJzRNBheSZ9G.jpg"}, {"name": "سامي مغاوري", "character": "Nadim", "profile_path": "/675TmIEoWDqpHYF5BCe0moimtXr.jpg"}, {"name": "غسان مطر", "character": "Taher Al Banna", "profile_path": "/rfUoK2bSpuhZfCKUKMHdXx1bf9M.jpg"}]'::jsonb, 88) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (75, 'movie', 'أعز الولد', 'Apple of my Eyes', 'أعز الولد', 'اعز الولد', 2021, 802243, 'movie', '/j3K9ouT6MB7imylv7GQ7UVQHBhM.jpg', '/msb7H6hWEKRRyimCBYfCuWqzf7P.jpg', 'عندما يُختطف خمسة أطفال وهم في طريقهم إلى المدرسة، يلجأ الأهالي إلى الشرطة، في حين تقرّر جدّاتهم تولّي زمام الأمور بأنفسهنّ.', 'When five kids are abducted on their way to school, the parents turn to the police, but their grandmothers decide to their matters into their own hands.', 5.7, '["دراما", "كوميديا"]'::jsonb, '[{"name": "دلال عبدالعزيز", "character": "", "profile_path": "/oIW8HsQaRbb1j81Fi4FghJryuTj.jpg"}, {"name": "ميرفت أمين", "character": "", "profile_path": "/wJnpt9qKrUL3ac0zCpUaYm0t7Zq.jpg"}, {"name": "شيرين", "character": "", "profile_path": "/cWrLR7cg9ldnoGo0pDtPfD0em59.jpg"}, {"name": "إنعام سالوسة", "character": "", "profile_path": "/bbvYQgJBUXDOUkkoZ609kgFD9wD.jpg"}, {"name": "ريهام عبدالغفور", "character": "", "profile_path": "/nLYYmE7KYZT4yVgr4dnoCRlFdfZ.jpg"}, {"name": "أمينة خليل", "character": "", "profile_path": "/eHJBpaypMN52VSIF84r5MgvC0Mr.jpg"}]'::jsonb, 92) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (76, 'movie', 'إسماعيل يس في الطيران', 'Ismail Yassine in the Air Force', 'إسماعيل يس في الطيران', 'اسماعيل يس في الطيران', 1959, 407340, 'movie', '/fHDSmgBC636fl3lWY8F0VppBfEk.jpg', '/lkT6drYK18XVzdUptdYXKQnKRCh.jpg', 'تدور أحداث الفيلم حول شخصين توأم، واحد يعمل في السينما والأخر يعمل في الطيران ولكن الأخ الذي يعمل في السينما يقع في حب راقصة ولكنها لا تشعر به لانها تأمل أن تتزوج من طيار، ولذلك يحاول الأخ انتحال شخصية أخيه الطيار لكي يفوز بقلب هذه الراقصة.', 'Ismail El Ghandoor works as a stuntman and a small time actor in movies. He falls in love with a young belly dancer, Soheir who dreams of being the wife of a pilot. Ismail dresses up in his brother Hussein’s clothes as a pilot in the force while his brother is away on his honeymoon. When Hussein returns the truth is revealed, and each of them goes back to his real job. Will Soheir accept the real Ismail or will she continue to pursue her dream of marrying a pilot?', 7.0, '["كوميديا", "رومنسية"]'::jsonb, '[{"name": "إسماعيل يس", "character": "Ismail Al-Ghandour / Hussein Al-Ghandour", "profile_path": "/rMq2iI5br3Qy1zrNYc0XsTzNQKa.jpg"}, {"name": "أحمد رمزي", "character": "", "profile_path": "/qeuyXQVUdJsuWwsSEUYDWW22nVz.jpg"}, {"name": "عبدالمنعم إبراهيم", "character": "Abd Almonem", "profile_path": "/Ae0DVAvlWuyT02B9yflrC7R34MM.jpg"}, {"name": "زهرة العلا", "character": "", "profile_path": "/mb3nrkoYuKVfQsrkkoCe4nYhjxa.jpg"}, {"name": "محمود المليجي", "character": "", "profile_path": "/3WWkVGMG4KfWhn2XwPJYdUOasX7.jpg"}, {"name": "نجوى فؤاد", "character": "Suheir Mahmoud", "profile_path": "/8bE1pliDb7SmAiHm3AEMu79u25s.jpg"}]'::jsonb, 95) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (77, 'movie', 'صراع الزوجات', 'Clash of wives', 'صراع الزوجات', 'صراع الزوجات', 1992, 638142, 'movie', '/s50QRg6JK9O4zJTiULULz7guSAA.jpg', NULL, 'Life seems impossible between the wealthy and successful businessman Said and his wife Souad, despite having their only daughter Dounia, and decides to separate. At the same time, Souad continues to search for a new source of livelihood.', 'Life seems impossible between the wealthy and successful businessman Said and his wife Souad, despite having their only daughter Dounia, and decides to separate. At the same time, Souad continues to search for a new source of livelihood.', 0.0, '["دراما"]'::jsonb, '[{"name": "محمود حميدة", "character": "", "profile_path": "/8uSJfakEstaPOBqCtn1oIzJm7VZ.jpg"}, {"name": "دلال عبدالعزيز", "character": "", "profile_path": "/oIW8HsQaRbb1j81Fi4FghJryuTj.jpg"}, {"name": "نهلة سلامة", "character": "", "profile_path": "/Ag19EJroMpRVypIlRHbKb1SgVK7.jpg"}, {"name": "أمل إبراهيم", "character": "", "profile_path": "/uCVmfo6ZRfQhU7OMckTg3fvFm54.jpg"}, {"name": "دنيا عبدالعزيز", "character": "", "profile_path": "/hcLzRO5NSovqURnDJpv9U8t1lZI.jpg"}, {"name": "حجاج عبدالعظيم", "character": "", "profile_path": "/7jCaw613wGCWGvTSJp0YDeSwVmI.jpg"}]'::jsonb, 98) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (78, 'movie', 'الحرامي والعبيط', 'The Thief and the Fool', 'الحرامي والعبيط', 'الحرامي والعبيط', 2013, 265002, 'movie', '/yLyCNE1IxXJKLE1i2XF5vJCfhYV.jpg', '/yJHnfIstxmguFtoVvRbRVCLxBSe.jpg', 'دراما إنسانية ترصد الكثير من القضايا الاجتماعية من خلال حياة رجلين فتحي (خالد صالح)، وصلاح روسي (خالد الصاوي). يفقد فتحي عقله بسبب ظروف الحياة القاسية والظلم الذي يطعنه من كل صوب. أما صلاح روسي رجلٌ لئيم يفقد عينه في إحدى المشاجرات. يتعرف فتحي على صلاح روسي وتنشأ بينهما علاقةُ صداقةٍ قويةٍ، ولكن هناك مؤامرة تحاك من وراء ظهر فتحي من قبل صلاح روسي بمعاونة صديقته الممرضة (روبي) من أجل سرقة عين فتحي . فهل سينجح الحرامي في سرقة عين العبيط؟ وإلي أين ستتجه الأحداث؟.', 'A foolish man down on his luck is befriended by another man who lost his eye in a brawl. Little does he know that his new, one-eyed friend is scheming to steal his eye and has enlisted the help of his nurse friend (Ruby), who works in an organ-trading hospital.', 5.7, '["دراما", "كوميديا"]'::jsonb, '[{"name": "خالد الصاوي", "character": "Salah", "profile_path": "/t4Z5PVsbFgN6RsN1bksjDwZlkhc.jpg"}, {"name": "خالد صالح", "character": "Fathy", "profile_path": "/704KztEDhJn437IwVeJI0PNPQ9M.jpg"}, {"name": "روبي", "character": "Nahed", "profile_path": "/oHnmUfGuJuNdS2QcoZlKUZwfHAi.jpg"}, {"name": "سيد رجب", "character": "Nahed''s Uncle", "profile_path": "/r6zPbQX4Rj4Y1ynk5Ym4kfdYBpq.jpg"}, {"name": "عايدة عبدالعزيز", "character": "Salah''s Mother", "profile_path": "/5ykpxdEIt14ML2Fq3yzbFpQTzxG.jpg"}, {"name": "ضياء الميرغني", "character": "", "profile_path": "/5Ddo3UpnTLhDuDU4KMzhchc6zbk.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (79, 'movie', 'عفريت ترانزيت', 'Ghost in Transit', 'عفريت ترانزيت', 'عفريت ترانزيت', 2020, 798558, 'movie', '/chZTuQPmz0b9k88A9LbW6z9qzC5.jpg', '/cNXHkC1dFN8aUiboNaZIj4KG30o.jpg', 'بائع مخدرات يتعرض للعديد من المشاكل واتهامه في جريمة قتل، الأمر الذي يدفعه لمحاولة البحث عن براءته والسير في طريق التوبة', 'The story follows a drug dealer who is exposed to many problems after he becomes accused of murder, which drives him to try to prove his innocence and repent.', 4.2, '["كوميديا"]'::jsonb, '[{"name": "بيومي فؤاد", "character": "بيرم - بوما", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "أسماء أبو اليزيد", "character": "مروة جمال", "profile_path": "/qM9mfKLafVZQoPSi9BlqZjDLYCK.jpg"}, {"name": "محمد ثروت", "character": "زوزا جمال", "profile_path": "/3uqttDmL1KH7811E3plwINeGtUs.jpg"}, {"name": "أحمد فتحي", "character": "عارف", "profile_path": "/mZtqVj2TP0qyrdsRZB8WwYeFKrq.jpg"}, {"name": "محمود حافظ", "character": "شبكه", "profile_path": "/j3rqnfwdNttoKOoVUphD7APd9cy.jpg"}, {"name": "محمود الليثي", "character": "عادل - دووله", "profile_path": null}]'::jsonb, 85) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
