INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (90, 'movie', 'المطارد', 'The Pursued', 'المطارد', 'المطارد', 1985, 421347, 'movie', '/ogV2mm5NfdN45trXSlSFivoU6ts.jpg', '/euQJkrG0XQ01Cvc6Ubt3cjFKzm8.jpg', 'في الحكاية الرابعة من (ملحمة الحرافيش)، يقرر سماحة الناجي حفيد عاشور الناجي أن يتزوج من مهلبية، لكن المشكلة أن هناك من يطمع في الزواج منها، وهو القللي فتوة الحي، وعندما يحاول سماحة ومهلبية الهرب من الحي، يقتل رجال القللي مهلبية وتلفق التهمة لسماحة، فيهرب نحو الصعيد.', 'In the fourth story of the epic of Harafish, Samaha Al-Nagy grandson of Ashour al-Nagy decides to marry Mahlabia. But Al-Qalali the bully of the neighborhood wants to marry her. When Samaha and Mahlabia try to escape, the men of Al-Qalali kill Mahlabia and frame Samaha, who flees to Upper Egypt.', 0.0, '["جريمة", "دراما"]'::jsonb, '[{"name": "نور الشريف", "character": "Samaha el nagy سماحة الناجي", "profile_path": "/wBFojkh5Tr2JCHWkQ7sfmo2SKgd.jpg"}, {"name": "سهير رمزي", "character": "Mahasen محاسن", "profile_path": "/plGZWAL3zTqDiNmTEHkXRASLSN5.jpg"}, {"name": "أبو بكر عزت", "character": "Helmy The Informer حلمي المخبر", "profile_path": "/iVUhTgrfVe85iHUG7SUe198JEnT.jpg"}, {"name": "تحية كاريوكا", "character": "Nazeera نظيرة والدة محاسن", "profile_path": "/5dMBqXfNzEH2LHsKDb68jFbbAFS.jpg"}, {"name": "مجدي وهبة", "character": "El fullaly الفُللي", "profile_path": "/1rXlxmAOhhVxSEgWnAPvNpl1IFO.jpg"}, {"name": "أحمد عقل", "character": "El fullaly’s partner إبن الفنجرية (مساعد الفللي)", "profile_path": "/qmiZB7kUiocqGOh0IlczQUWnv43.jpg"}]'::jsonb, 120) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.pos