INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (93, 'movie', 'ياسمين', 'Yasmine', 'ياسمين', 'ياسمين', 1950, 334430, 'movie', '/kx4CU0jY2dqoAKLtJufZ7SCB0wf.jpg', NULL, 'Yasmine is the daughter of a wealthy man who was not interested in females, so he left her at the door of an orphanage. She grows up in the orphanage, then runs away from it to join a gang of children. She meets a musician who tries to protect her, so he convinces her to work with him and sing, but she gets tired of the life of poverty and runs away from him. After her escape, he discovers that she is the granddaughter of a Pasha, so he tries to help her return to her family.', 'Yasmine is the daughter of a wealthy man who was not interested in females, so he left her at the door of an orphanage. She grows up in the orphanage, then runs away from it to join a gang of children. She meets a musician who tries to protect her, so he convinces her to work with him and sing, but she gets tired of the life of poverty and runs away from him. After her escape, he discovers that she is the granddaughter of a Pasha, so he tries to help her return to her family.', 10.0, '["دراما", "موسيقى", "كوميديا"]'::jsonb, '[{"name": "فيروز", "character": "Qatqoutta/Yasmine", "profile_path": "/342nVt8x2J6w0wV1GOExrThp6XI.jpg"}, {"name": "زكي رستم", "character": "Yasmine''s grandfather (Abu Saad)", "profile_path": "/6E4bPZW5yLDBcJ3BzSP4jSnniYU.jpg"}, {"name": "أنور وجدي", "character": "Wahid Ezzat", "profile_path": "/aVbL8O1vZqEnphiuVEsCEd1px3I.jpg"}, {"name": "مديحة يسري", "character": "Souad - Yasmine''s mother", "profile_path": "/uddi9WvjFlv9j5dVo28CO4KVbS2.jpg"}, {"name": "عبدالعزيز خليل", "character": "Dabour", "profile_path": "/j1Jfk3sTJnHWJKwK5gWYqpMRYVl.jpg"}, {"name": "محمد الديب", "character": "Adel (Abu Yasmine)", "profile_path": "/tnBTbqiyqiOsl3iwEsEx09aJFvu.jpg"}]'::jsonb, 122) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (94, 'movie', 'الستات', 'Women', 'الستات', 'الستات', 1992, 758207, 'movie', '/ucFRA877995T7Zlr7yExenQVbEW.jpg', NULL, 'Azmi is an editor-in-chief of a newspaper. His dealings with people are serious and away from compliments.  Norhan, the famous artist, tries to get close to him by giving precious gifts to him and his wife, so that he publishes news about her, but he refuses,which makes her nitpick on him.', 'Azmi is an editor-in-chief of a newspaper. His dealings with people are serious and away from compliments.  Norhan, the famous artist, tries to get close to him by giving precious gifts to him and his wife, so that he publishes news about her, but he refuses,which makes her nitpick on him.', 6.0, '["كوميديا", "دراما"]'::jsonb, '[{"name": "محمود ياسين", "character": "Azmy", "profile_path": "/pGYBLZoB2F0jokdFY1Gob7uJmA5.jpg"}, {"name": "فيفي عبده", "character": "Shukria", "profile_path": "/6sxWWWXVEbBm14YUlkgEtx6Ab5F.jpg"}, {"name": "إيمان", "character": "Nourhan", "profile_path": "/bwkL58ilgI0iK1u25NOR3ITt9No.jpg"}, {"name": "عبلة كامل", "character": "Soad", "profile_path": "/wVFfL9ZEQx4LZ4AfVvx2K8ab80b.jpg"}, {"name": "هالة صدقي", "character": "Sohier", "profile_path": "/ymiqUiUibhbed7L1i5pNxTcTwBQ.jpg"}, {"name": "علا رامي", "character": "Rawia", "profile_path": "/81FAfrE031PHjUFfPWYdpX0xZcJ.jpg"}]'::jsonb, 123) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EX