INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (96, 'movie', 'عفريته هانم', 'Afrita Hanem: The Genie Lady', 'عفريتة هانم', 'عفريته هانم', 1949, 284726, 'movie', '/vl5OIrNpkEo8434u7vhD4Yu8j2G.jpg', NULL, 'يحب المطرب (عصفور) ابنة صاحب الملهى الذي يعمل به (علية) الراقصة، ولكنها تميل إلى (ميمي بك) الشاب الثري، يعثر فيها عصفور على مصباح سحري يلمسه لتخرج منه عفريتة، تبدأ في تحقيق كل رغبات عصفور فتهبه قصرًا، لكنه مازال يبحث على الحب، فهل سيجده؟', 'The fortunes of down-on-his-luck crooner Asfour change overnight when he discovers a mysterious lamp housing a charming genie. She can make anything he wishes come true, so he asks for help in luring his distracted girlfriend from the charms of a rich competitor. But Asfour soon learns he should be careful what to wish for, as he soon realizes his heart may lie elsewhere.', 6.3, '["موسيقى", "كوميديا", "فانتازيا"]'::jsonb, '[{"name": "فريد الأطرش", "character": "عصفور", "profile_path": "/3M2dhjmPucvJyLwwT2GEct5Ukr1.jpg"}, {"name": "سامية جمال", "character": "كهرمانة/سمسمة", "profile_path": "/7oEqOHkig8YMOZUQQ041rNapJZ5.jpg"}, {"name": "إسماعيل يس", "character": "بقو", "profile_path": "/rMq2iI5br3Qy1zrNYc0XsTzNQKa.jpg"}, {"name": "لولا صدقي", "character": "علية", "profile_path": "/A9DaOtc2qPAzWg36wSKrr5SyBsH.jpg"}, {"name": "إستيفان روستي", "character": "قشطة", "profile_path": "/zZl80ZEhb3wK5lLqWu6H9LsrHct.jpg"}, {"name": "زينات صدقي", "character": "وردة", "profile_path": "/lV5fIfqK2Pzz2sFWv1rSpMVrwx9.jpg"}]'::jsonb, 115) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar