INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (97, 'movie', 'سر طاقية الاخفاء', 'The Secret of the Magic Hat', 'سر طاقية الاخفاء', 'سر طاقيه الاخفاء', 1959, 514356, 'movie', '/5rLU2iF4h7dZhRraqXLqLxPrfdK.jpg', '/tvfThcdHUF8KZyuWrATZiYrbQAQ.jpg', 'يلهو "فصيح" في معمل والده العطار، فيتسبب في ظهور عفريت، يحترق العفريت مخلفاً بودرة تخفي ما تقع عليه، تتعرض طاقية لهذه البودرة وتكتسب خاصية تخفي من يرتديها، ليكتشف "عصفور" قدرات الطاقية، فيقوم بإستعمالها، لكن يكتشف عدوه السر، ويبدا بإستخدام الطاقية ضده', '"Fasih" plays in his father''s lab, the Attar, which causes a demon to appear. The sprite burns, leaving a powder that hides what falls on it. A taqiyya is exposed to this powder and acquires a property that hides the one who wears it. Asfour discovers the capabilities of the trap, and uses it, but his enemy discovers the secret, and begins using Cap is against him', 8.3, '["كوميديا", "فانتازيا"]'::jsonb, '[{"name": "توفيق الدقن", "character": "", "profile_path": "/nDAT4oc0dqBP4YV2m2NRm92rsV5.jpg"}, {"name": "برلنتي عبدالحميد", "character": "", "profile_path": "/eXlFczCO4eNgDS8zewux7dm1QSt.jpg"}, {"name": "عبدالمنعم إبراهيم", "character": "", "profile_path": "/Ae0DVAvlWuyT02B9yflrC7R34MM.jpg"}, {"name": "زهرة العلا", "character": "", "profile_path": "/mb3nrkoYuKVfQsrkkoCe4nYhjxa.jpg"}, {"name": "أحمد فرحات", "character": "", "profile_path": "/pT9T78KZsyZ26hN60NYCXz9RBh7.jpg"}]'::jsonb, 95) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (98, 'movie', 'من غير ميعاد', 'Men Gheir Ma''ad', 'من غير ميعاد', 'من غير ميعاد', 1962, 771337, 'movie', '/oxaOX9DGGjPj7VEElxZxkdmt8bo.jpg', '/bkrh3eFxuIuAKGxjVNFfRI6gDUN.jpg', 'تقع سلوى في حب وحيد، ولا تخبر أحدًا بذلك، بينما هو لا يبادلها نفس الشعور، حيث أنه يحب نادية، وفي نفس الوقت يقع كمال في حب نادية، ولا يخبر أحدًا بذلك، ولا يعلم أن صديقه وحيد يحبها هو الأخر، وعندما يعلم كمال بذلك، يقرر الابتعاد، والسؤال هو: هل ستعرف نادية بحب كمال لها، وحب سلوى لوحيد أم لا؟', 'Salwa (Soad Hosni)  secretly loves Waheed (Mohamed Sultan) . While Waheed loves Nadia (Nadia Lotfy). Meanwhile, Kamal (Moharram Fouad) falls in love with Nadia too, and keeps his love discreet .But when he knows that his friend ,Waheed, loves her, he decides to keep a distance from Nadia.', 8.0, '["رومنسية", "موسيقى", "دراما"]'::jsonb, '[{"name": "سعاد حسني", "character": "سلوى", "profile_path": "/ulWhmq32VFr98H5SoOqbEHa9T34.jpg"}, {"name": "محرم فؤاد", "character": "كمال", "profile_path": "/tX9IwEgtJ4gJQgqGBXlrNt7b905.jpg"}, {"name": "نادية لطفي", "character": "نادية", "profile_path": "/6qJAcrxlLPC6b7YfM8LXn2Xdej6.jpg"}, {"name": "فاخر فاخر", "character": "الخال", "profile_path": "/fY75rNCWbPDWeuedSsomjhiP3Ts.jpg"}, {"name": "زوزو ماضي", "character": "الأم", "profile_path": "/yU7XANi9bNpW1KoDVKfm1P31eaX.jpg"}, {"name": "سمير صبري", "character": "سمير", "profile_path": "/qNCXv1BxUdkSov7pOQmaFiWxCzX.jpg"}]'::jsonb, 105) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (99, 'movie', 'الكيت كات', 'Kit Kat', 'الكيت كات', 'الكيت كات', 1991, 68738, 'movie', '/bRY2zqXOk1kjH4wlSKK2rCP2cJt.jpg', '/rcJWnb2ziCW0Jwplui7amMkm4XW.jpg', 'في حى الكيت كات، تبدو شخصية الشيخ حسنى الكفيف كراصد ليوميات أبناء الحى ونبض لهمومه الحقيقية التي يتسامى عليها رغم فقدانه البصر وزوجته وعمله، يعش مع أمه المسنة وأبنه الشاب المحبط، دون أن يتخلى عن الأمل والبسمة والضحكة، وينطق للتعبير عن هوايته للغناء ليلا في جلسات تدخين المخدرات لينسى واقعه المظلم بعد بيع منزله.. لا يجد يوسف ابن حسنى وظيفة عقب تخرجه من الجامعة، كما يفشل في العثور على عقد عمل بالخارج وتكشف علاقته بجارته الشابة المطلقة فاطمة عن اصابته بعجز جنسى، عندما يموت أحد أبناء الحى، يحضر الشيخ حسنى واجب العزاء ومع أغفال غلق مكبر السوت عقب انتهاء تلاوة القرآن يكشف الشيخ حسنى عن فضائح بعض أهالي الكيت كات ليسمعها الجميع، ومنها خيانة المعلم هرم لصديقه المريض مع زوجته الحسناء، وهروب روايح من زوجها الصائغ متبلد الإحساس، وحتى علاقته الخاصة بأم روايح وعلاقة ابنه بفاطمة.', 'Sheikh Hosny is a blind man who lives with his old mother and his frustrated son in the Kit Kat neighborhood. His son Youssef dreams of going to Europe to find work, and has a relationship with a divorced woman named Fatima. Sheikh Hosny refuses to admit his handicap and dreams of riding a motorcycle like every sighted person, he also spends his nights smoking hash with the locals in order to forget his miseries after the loss of his wife and selling his father''s house.', 7.5, '["كوميديا", "دراما"]'::jsonb, '[{"name": "محمود عبدالعزيز", "character": "Sheikh Hosny", "profile_path": "/2tTG533lGmSsybIVOR6lYkFQ3t5.jpg"}, {"name": "شريف منير", "character": "Youssef", "profile_path": "/69ttY5VkABXQeTcFZBkxcxvaXjf.jpg"}, {"name": "عايدة رياض", "character": "Fatima", "profile_path": "/68kUd6yuCLUaIGy1PbBwYsPYPji.jpg"}, {"name": "نجاح الموجي", "character": "Al Haram", "profile_path": "/1f0fbgqiLpoevn58YkP5K8BrwpN.jpg"}, {"name": "أحمد كمال", "character": "Suliman", "profile_path": "/uAPid7JIyxd3fj7O35X8lOjTCyT.jpg"}, {"name": "أحمد سامي عبدالله", "character": "Megahed", "profile_path": "/2BTgVRSyvl7a988YurnpoYg6X26.jpg"}]'::jsonb, 130) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
