INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (101, 'series', 'بورتريه', 'بورتريه', 'بورتريه', 'بورتريه', 2020, 227577, 'tv', '/1HxvPFoqEy1oWolIhNUtXjsXvZD.jpg', '/qZK651ZPdrYPuILzXj8q2Gq2XIb.jpg', 'يصير حازم رئيس تحرير مجلة متخصصة في مجال الاقتصاد بتشجيع من حبيبة والده السابقة، ويقع في حب ابنة شقيقتها ريما، لكن المشكلة أن هناك عداء قديم بين والدي حازم وريما بسبب راندا.', 'يصير حازم رئيس تحرير مجلة متخصصة في مجال الاقتصاد بتشجيع من حبيبة والده السابقة، ويقع في حب ابنة شقيقتها ريما، لكن المشكلة أن هناك عداء قديم بين والدي حازم وريما بسبب راندا.', NULL, '["دراما"]'::jsonb, '[{"name": "فادي صبيح", "character": "", "profile_path": "/sT8eh6gx7DHa4RGuC69HV50YMHW.jpg"}, {"name": "أكثم حمادة", "character": "", "profile_path": "/7nRIeQk9b2bL90PxgaGgKfPSlmM.jpg"}, {"name": "Madiha Knefati", "character": "", "profile_path": "/3yt6YsorlgZxnn6U90kHeKvkorN.jpg"}, {"name": "Taraf Al Taqi", "character": "", "profile_path": "/5sPSmqkFP5Wt6zUF93JUNQnMwIC.jpg"}, {"name": "Haval Hamdy", "character": "", "profile_path": "/Ao8haBj6j2QDI1SHnYe11zAY773.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (102, 'movie', 'الحلال يكسب', 'El-Halal Yksab', 'الحلال يكسب', 'الحلال يكسب', 1985, 1326416, 'movie', '/2BHoPJSSxHWkBwbNj6gePDvyHTJ.jpg', '/n30wkUmSM0zOPvlx4w7pdG37SIs.jpg', 'بعد أن يجري الطبيب فؤاد عملية لشمس وينقذ حياتها، تتعلق به وتطلب منه الزواج، ليخفي عنها بأنه مرتبط بنرجس، خوفًا من تدهور حالتها الصحية، ليتزوج منها ومن نرجس بنفس الوقت، ويقنع شمس أن نرجس هي شقيقته، لتتصاعد الأحداث.', 'After Dr. Fouad performs an operation on Shams and saves her life, she becomes attached to him and asks him to marry her. He hides from her that he is engaged to Narges, fearing that her health will deteriorate, so he marries her and Narges at the same time, and convinces Shams that Narges is his sister, and events escalate.', 0.0, '["دراما"]'::jsonb, '[{"name": "آثار الحكيم", "character": "شمس", "profile_path": "/rMReSo8HZHpOri7fbZQPmMzDGAn.jpg"}, {"name": "حسين فهمي", "character": "فؤاد", "profile_path": "/6u4eciBbQGsq5fmTFXj7eznUQxv.jpg"}, {"name": "يونس شلبي", "character": "علي", "profile_path": "/jLtc7MnYVPHGdIyIhKeVESVdpb7.jpg"}, {"name": "صلاح السعدني", "character": "لمعي", "profile_path": "/28grVfa5TiWx8JP7MteCPR0AGND.jpg"}, {"name": "معالي زايد", "character": "نرجس", "profile_path": "/oAALG7p4ReXhOgtZQehCtYcfkR1.jpg"}, {"name": "زيزي مصطفى", "character": "زوبه", "profile_path": "/pg17ZdCBNhEKrwXYS8OlZpheSG5.jpg"}]'::jsonb, 95) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = 