INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (104, 'movie', 'أدهم الشرقاوي', 'Adham Al-Sharqawi', 'أدهم الشرقاوي', 'ادهم الشرقاوي', 1964, 759643, 'movie', '/wZhYML9YeIDmmWW5xtkIW7KgeLO.jpg', '/g3GyF8C4FJXw3fTIBQy4pHPPJp3.jpg', 'The story of the Arabic Robin Hood, the legendary local hero Adham Al-Sharqawi who persisted in resisting the British occupation for years and tried to alleviate the suffering of the people of his village.', 'The story of the Arabic Robin Hood, the legendary local hero Adham Al-Sharqawi who persisted in resisting the British occupation for years and tried to alleviate the suffering of the people of his village.', 10.0, '["دراما", "تاريخ"]'::jsonb, '[{"name": "عبدالله غيث", "character": "Adham Al-Sharqawi", "profile_path": "/7dVgNjKzIHWW80eMKRu7ko3Ywnz.jpg"}, {"name": "لبنى عبدالعزيز", "character": "Salma", "profile_path": "/tVhd8DJbpaUhy68kfq60phc0Ulz.jpg"}, {"name": "شويكار", "character": "", "profile_path": "/bWeR0PIZR1E809vfKEPXuH6vibn.jpg"}, {"name": "توفيق الدقن", "character": "Maghawri", "profile_path": "/nDAT4oc0dqBP4YV2m2NRm92rsV5.jpg"}, {"name": "سميحة أيوب", "character": "Khadija - Sheikh Shalabi''s wife", "profile_path": "/v9UWzWFkewvX4ZRnYI7bXy0kII3.jpg"}, {"name": "صلاح منصور", "character": "Sheikh Shalabi", "profile_path": null}]'::jsonb, 105) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (105, 'movie', 'عروس النيل', 'Arouss el Nil', 'عروس النيل', 'عروس النيل', 1963, 414010, 'movie', '/OTC3YzVrMwtjkk5DAy4kFczCz8.jpg', NULL, 'يذهب الجيولوجي (سامي) إلى الأقصر لمتابعة عمليات التنقيب عن البترول. ويُمنع على أساس أن المنطقة تستخدم كمقبرة لعرائس النيل، يرى سامي فتاة جميلة في زي عروس النيل تدعى هاميس تطالبه بوقف الحفر ، وأخبرته أنها ابنة آتون إلة الشمس وآخر عروس نيل وأن والدها أرسلها إلى الأرض لتمنع انتهاك حرمات مقابر عرائس النيل.', 'When an oil engineer starts digging for oil in Luxor he disturbs the spirits of ancient Egyptians buried there. A spirit, Last Bride of the Nile, is sent to get him to stop the drilling.', 5.9, '["كوميديا", "فانتازيا", "رومنسية"]'::jsonb, '[{"name": "رشدي أباظة", "character": "Sami Fouad", "profile_path": "/julfbz4ZSohGcXmldmAbMVNV7kD.jpg"}, {"name": "لبنى عبدالعزيز", "character": "Hamis/Journalist Nadia Hamdi", "profile_path": "/tVhd8DJbpaUhy68kfq60phc0Ulz.jpg"}, {"name": "عبدالمنعم إبراهيم", "character": "Fathy", "profile_path": "/Ae0DVAvlWuyT02B9yflrC7R34MM.jpg"}, {"name": "شويكار", "character": "Didi", "profile_path": "/bWeR0PIZR1E809vfKEPXuH6vibn.jpg"}, {"name": "الضيف أحمد", "character": "", "profile_path": "/mInXtgIPmci2EOJZnU3fP53i3g3.jpg"}, {"name": "فؤاد شفيق", "character": "Dr. Hassan / archaeologist", "profile_path": "/epZOd1iafMRQ9McneFxSbmYJfT2.jpg"}]'::jsonb, 105) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCL