INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (106, 'movie', 'حكاية جواز', 'Hekayet Gawaz', 'حكاية جواز', 'حكايه جواز', 1964, 722235, 'movie', '/fUj8DWlej4bFz6OphRVszVk48IN.jpg', '/44WUTLRw0vIIvJY4hkG6o8l48IJ.jpg', 'في ليلة زفاف محمد (شكري سرحان) وعديله (سعاد حسني)، يصل خطاب لمحمد يفيد بترقيته ونقله للعمل في جبل عتاقة، تعارض أمها عزيزة (ماري منيب) أن تذهب ابنتها معه لمكان عمله فيسافر محمد بمفرده، تتصدى عديله لأمها وتلحق بزوجها، كذلك يتزوج أخوها حسن (حسن يوسف) من حبيبته منى (آمال فريد) رغم اعتراض أمها التي تريد تزويجها من أحد أقاربها، وتتوالى الأحداث مابين شد وجذب الزوج والزوجة والحماه.', 'On the night of the wedding of Mohamed (Shukry Sarhan) with Adela (Souad Hosny), a letter arrives to Mohamed benefits that he was promoted and so moved to work in the Jabal "Ataka", but her mother, Aziza (Mary Munib) opposed her daughter from going with her husband to his place of work ,so Mohamed travels alone, Adila challenged her mother and follow her husband.', 7.0, '["كوميديا", "رومنسية"]'::jsonb, '[{"name": "سعاد حسني", "character": "Adela عديلة منصور", "profile_path": "/ulWhmq32VFr98H5SoOqbEHa9T34.jpg"}, {"name": "شكري سرحان", "character": "Mohammed محمد", "profile_path": "/aDtuqqgvwAMkmbjVK4jFhKDaLPr.jpg"}, {"name": "ماري منيب", "character": "Aziza عزيزة أم عديلة", "profile_path": "/sNbjkyALRmYiC66k1A6NeCaVB0D.jpg"}, {"name": "أمينة رزق", "character": "Karima كريمة أم محمد", "profile_path": "/o9O2H8OGVwj96IABWqutZsAHPj7.jpg"}, {"name": "حسن يوسف", "character": "Hassan حسن منصور", "profile_path": "/jPtJpKZxfOH7Cj2AfxdvHpLMYMx.jpg"}, {"name": "حسن فايق", "character": "Mansour منصور", "profile_path": "/9tUSkaTQHN695k6jOL30Vpbczbn.jpg"}]'::jsonb, 90) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (111, 'movie', 'ابن الحاج أحمد', 'ابن الحاج احمد', 'ابن الحاج احمد', 'ابن الحاج احمد', 2023, 1094581, 'movie', '/ykNyRtQeebGh2P6kNHh7Tv3EHPc.jpg', '/xXsiYQpHyLEyryOEuQkoZ0qOVBW.jpg', 'يتورط شاب يدعى (أحمد) يعمل بائعًا بمتجر بقالة والده في متاعب جمة، بعدما يجد نفسه في مواجهة إحدى العصابات الخطيرة، مما يحتم عليه التعاون مع الشابة (نبيلة) والتصدي للخطر معًا.', 'يتورط شاب يدعى (أحمد) يعمل بائعًا بمتجر بقالة والده في متاعب جمة، بعدما يجد نفسه في مواجهة إحدى العصابات الخطيرة، مما يحتم عليه التعاون مع الشابة (نبيلة) والتصدي للخطر معًا.', 3.7, '["كوميديا"]'::jsonb, '[{"name": "شيكو", "character": "", "profile_path": "/gurvnsbru3btbeENF3HANKw2VM8.jpg"}, {"name": "رحمة أحمد فرج", "character": "", "profile_path": "/fGXxmZ2BVf2B6nbBAurJCaalCRU.jpg"}, {"name": "سيد رجب", "character": "", "profile_path": "/r6zPbQX4Rj4Y1ynk5Ym4kfdYBpq.jpg"}, {"name": "عايدة رياض", "character": "", "profile_path": "/68kUd6yuCLUaIGy1PbBwYsPYPji.jpg"}, {"name": "صبري فواز", "character": "", "profile_path": "/6YYhKaE8MlMnFCySd9zmCS9RMQM.jpg"}]'::jsonb, 97) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (112, 'movie', 'حملة فرعون', 'Pharaoh''s War', 'حملة فرعون', 'حمله فرعون', 2019, 620632, 'movie', '/9MsNf5FhkYvZtLFN1ajQFv775aY.jpg', '/10TknfMWOONfJa8lcFLGLkEp1vX.jpg', 'تدور أحداث الفيلم في إطار تشويقي مثير حول الشاب يحيى الشهير بفرعون، والذي يدير أكبر شبكة اغتيالات منظمة في مصر، ويضطر إلى التوجه إلى سوريا لتحرير ابنه من قبل إحدى العصابات الداعشية، وإنقاذه برفقة مجموعة من أصدقائه، الذين يظن بعضهم أنهم سافروا إلى هناك للبحث عن كنز كبير في منطقة الصراع.', 'Yehia, known as Pharaoh, reassembles a group of six of his old friends, each with a unique combating skill, to travel to Syria under the pretense of bounty hunting. Their real mission is to save his kidnapped son from the hands of Franco and his ISIS gangsters after they assaulted Syrian refugees, including Yehia''s wife, and took away the children to a district that is currently under his control.', 6.4, '["حركة", "إثارة"]'::jsonb, '[{"name": "مايك تايسون", "character": "Rick", "profile_path": "/7eI1WK9985q8XiUgg3rDjOwa3MR.jpg"}, {"name": "Hafþór Júlíus Björnsson", "character": "Frank", "profile_path": "/wDyF1bkjZb2c4zw7hi27LZh2H6a.jpg"}, {"name": "عمرو سعد", "character": "Yahya Firon", "profile_path": "/ii5oJije7WOfqBwyxAt4YettAnj.jpg"}, {"name": "محمد لطفي", "character": "Hamzah el-Argantini", "profile_path": "/Akh0XZ1gRWeMWAmDz7kbg6xwz4V.jpg"}, {"name": "روبي", "character": "Dahab", "profile_path": "/oHnmUfGuJuNdS2QcoZlKUZwfHAi.jpg"}, {"name": "بيومي فؤاد", "character": "Sayyed Wilah", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}]'::jsonb, 110) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (114, 'movie', 'ابن حميدو', 'Son of Hamido', 'ابن حميدو', 'ابن حميدو', 1957, 337198, 'movie', '/wTmap1VscyKJzKwzONnwEMsOlvb.jpg', '/lYVdDnjUpLjteWYGeK4rO52WV7e.jpg', 'و يعملان في سلك الشرطة، ويفدان إلى السويس من أجل إحباط عملية مخدرات كبرى يتورط فيها الباز أفندي، ويقعان في الحب مع بنات المعلم حنفي شيخ الصيادين', 'Ebn Hameedo is an undercover police officer who arrives with his colleague Hassan at a fishing area near Suez where drug trafficking is practiced. They meet two sisters, Azeeza, the younger, and Hameeda, the older maiden. They rent a room in their father’s house and fall in love with the two girls. Their love could have led to marriage had it not been for al-Baaz Effendi who wanted to marry Azeeza and tried to get rid of Hassan. Al-Baaz is also involved in the narcotics business. so they track him down in order to catch the rest of the gang.', 7.1, '["كوميديا"]'::jsonb, '[{"name": "إسماعيل يس", "character": "ابن حميدو", "profile_path": "/rMq2iI5br3Qy1zrNYc0XsTzNQKa.jpg"}, {"name": "أحمد رمزي", "character": "حسن", "profile_path": "/qeuyXQVUdJsuWwsSEUYDWW22nVz.jpg"}, {"name": "هند رستم", "character": "عزيزة", "profile_path": "/gpj25cQGBszyGxUHVeDGq2bD8fy.jpg"}, {"name": "عبدالفتاح القصري", "character": "الريس حنفي", "profile_path": "/yS18wQrZZxfhB5UjMtzi9cwcpxZ.jpg"}, {"name": "زينات صدقي", "character": "حميدة", "profile_path": "/lV5fIfqK2Pzz2sFWv1rSpMVrwx9.jpg"}, {"name": "توفيق الدقن", "character": "الباز أفندي", "profile_path": "/nDAT4oc0dqBP4YV2m2NRm92rsV5.jpg"}]'::jsonb, 110) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (115, 'movie', 'تايه في أمريكا', 'Lost in the USA', 'تايه في أمريكا', 'تايه في امريكا', 2002, 534355, 'movie', '/7sfcIxIIwHHN9aagkgLSi7SG3X3.jpg', '/1YLGjZH3X9OQiwmnEwEQCHBmFLU.jpg', 'Sherif al-Masri travels to America without a specific goal or relatives or friends there. Once he arrives in America, he discovers that he will suffer from high prices and does not know anyone, and by chance he listens to the dialogue of two ladies waiting for a person named Adel who is one of their old relatives in Egypt and does not even know his form. It is clear that he failed to attend, Sharif takes advantage of the situation and turns into a fair character..', 'Sherif al-Masri travels to America without a specific goal or relatives or friends there. Once he arrives in America, he discovers that he will suffer from high prices and does not know anyone, and by chance he listens to the dialogue of two ladies waiting for a person named Adel who is one of their old relatives in Egypt and does not even know his form. It is clear that he failed to attend, Sharif takes advantage of the situation and turns into a fair character..', 6.0, '["رومنسية", "دراما", "كوميديا"]'::jsonb, '[{"name": "خالد النبوي", "character": "Sherif", "profile_path": "/dCZgjQ42Wm7vbQWNGsJEGOMBeBB.jpg"}, {"name": "حلا شيحة", "character": "Noor", "profile_path": "/fXcS9eioNf6X5au9yx3XU4SLm3U.jpg"}, {"name": "محمد لطفي", "character": "Adel", "profile_path": "/Akh0XZ1gRWeMWAmDz7kbg6xwz4V.jpg"}, {"name": "إيمان", "character": "Nahla", "profile_path": "/bwkL58ilgI0iK1u25NOR3ITt9No.jpg"}, {"name": "Rajia Baroudi", "character": "Eman", "profile_path": "/d7Mh3nEY4TI2pVGrvDTkFT66ssu.jpg"}, {"name": "Don Yanan", "character": "Frank", "profile_path": "/1qoNWgMNGDVDiIPKZXaZaL2gJET.jpg"}]'::jsonb, 98) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (116, 'movie', 'مراتي وزوجتي', 'My Wife and My Wifey', 'مراتي و زوجتي', 'مراتي وزوجتي', 2014, 300821, 'movie', '/tfPg7UYZBMEbdLLy6yAR858tod.jpg', '/PZaQ7rQJDs0RRRAx1DnT7hj8pd.jpg', 'تدور أحداث الفيلم في إطار كوميدي ساخر حول شاب (رامز جلال) والذي يتزوج إحدى الفتيات المهتمين بحقوق المرأة ومواجهة التحديات التي تعيقها في تحقيق أحلامها، ولكن ذلك ساعد على عدم تواجدها مع زوجها الوقت الكافي وعدم اهتمامها بحياتها الزوجية، مما أدى به إلى أن يتزوج مرة أخرى، الأمر الذي ورطة في العديد من المشاكل والمفارقات الكوميدية والتي تحول حياته إلى كتلة من الجحيم.', 'A comedy about (Ramez Galal) who marries a girl interested in women''s rights , which makes her too busy and lacks interest in her marital life and that leads him to marry another woman, and he gets into many problems, and comical paradoxes that turn his life into hell.', 3.9, '["كوميديا"]'::jsonb, '[{"name": "رامز جلال", "character": "", "profile_path": "/AtDCtYZBTswr4OXJVwvZOhrPUbj.jpg"}, {"name": "إدوارد", "character": "", "profile_path": "/4zMVIGh9IQoDiTWvEy9i2lGYCZA.jpg"}, {"name": "رجاء الجداوي", "character": "", "profile_path": "/mgZFyKbzxEbT0PZbDSZ2Ue0rAXo.jpg"}, {"name": "حسن حسني", "character": "", "profile_path": "/vMG9Carh5bi18v5unk06aYvvKZw.jpg"}, {"name": "سامي مغاوري", "character": "", "profile_path": "/675TmIEoWDqpHYF5BCe0moimtXr.jpg"}, {"name": "يوسف عيد", "character": "", "profile_path": "/no3W8JMDXcQufoLrQYs2bPGNdyh.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (117, 'movie', 'ماكو', 'Mako', 'ماكو', 'ماكو', 2021, 772307, 'movie', '/AqdLsMSMenIcjHYuHvQG0Rt4q1N.jpg', '/kzY6EOitaLo1ykGLCTRmMQAznOL.jpg', 'Eight documentary makers decide to go to the location of Elsalam Ship which sunk years ago to make a new documntary where they face unforseen dangers.', 'Eight documentary makers decide to go to the location of Elsalam Ship which sunk years ago to make a new documntary where they face unforseen dangers.', 5.4, '["دراما", "إثارة", "مغامرة", "رعب"]'::jsonb, '[{"name": "بسمة", "character": "رنا بهجت", "profile_path": "/uHesQTc5W7cEIzC7LktGX9isl62.jpg"}, {"name": "نيقولا معوض", "character": "شريف ناهي", "profile_path": "/k4y3zv6mwrhS5yLgkJhM50cM0IL.jpg"}, {"name": "ناهد السباعي", "character": "غرام", "profile_path": "/twgDjrSS472cFD84HytIwHrORNZ.jpg"}, {"name": "منذر رياحنة", "character": "بشري", "profile_path": "/gFcuGTwyqcGegvm7UGiqmty7kIc.jpg"}, {"name": "Murat Yıldırım", "character": "مراد", "profile_path": "/qQmVCeZs4Hji41loNk6KHRNNJZJ.jpg"}, {"name": "عمرو وهبة", "character": "تيمور", "profile_path": "/5vWR6lJ6s3pPAaujCQ0KvJBUYmi.jpg"}]'::jsonb, 91) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (118, 'movie', 'حب في الزنزانة', 'Love in a Jail Cell', 'حب في الزنزانة', 'حب في الزنزانه', 1983, 514332, 'movie', '/hQaybEsWcD7niqjktJ62s4d8i24.jpg', '/6JbP8AY5nKmR6V0ndpvdTyaQdJ4.jpg', 'رجل أعمال يدعى الشرنوبي (جميل راتب) يتاجر في الأغذية الفاسدة يدفعه جشعه وجبروته للاتفاق مع أحد الشباب (عادل إمام) للاعتراف بجريمة بدلا منه ويحكم عليه بالسجن. وخلف أبواب الزنزانة يتعرف على سجينة تدعى فايزة (سعاد حسني) بسجن النساء وقع في حبها وتبادلا كل منهما مشاعر الحب من خلال الرسائل، وعندما تم الإفراج عنهما تزوجا وقررا الانتقام من ذلك التاجر الجشع، فيتسلل لبيته ويقتله في نفس لحظة ولادة ابنه من فايزة، لينتهي مستقبل الأب لحظة ولادة إبنه.', 'A wrongfully convicted man falls in love with his fellow inmate. They decide to get married after their release and seek revenge on a corrupt businessman.', 6.0, '["رومنسية", "دراما"]'::jsonb, '[{"name": "عادل إمام", "character": "صلاح الغرباوي", "profile_path": "/vPEubkxYDRfkSUDoAfJUWQgg4cD.jpg"}, {"name": "سعاد حسني", "character": "فايزة حسن", "profile_path": "/ulWhmq32VFr98H5SoOqbEHa9T34.jpg"}, {"name": "يحيى الفخراني", "character": "فاروق - مزور العملة", "profile_path": "/lzQT2AX0yDTe63eYMjFuTIUGf4X.jpg"}, {"name": "عبدالمنعم مدبولي", "character": "أبو الفتوح - مساعد الشرنوبي", "profile_path": "/i0UKxWD32NJXYyUUIPHr9V9Vigw.jpg"}, {"name": "جميل راتب", "character": "الشرنوبي - رجل الأعمال الفاسد", "profile_path": "/9ZNYtVH3LAq5UtGVnyPZvoKqlSp.jpg"}, {"name": "علي الشريف", "character": "Shamshon", "profile_path": "/yqbj6gAt8clSeV3P0ymXqx5QN8g.jpg"}]'::jsonb, 124) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (119, 'movie', 'غصن الزيتون', 'Ghosn Al-Zaytoun', 'غصن الزيتون', 'غصن الزيتون', 1962, 797420, 'movie', '/jwy30z2F7wvfQzjXyYghgi1X0z3.jpg', '/uyAHAMeXTUFGcbGI3anfHe6PqOr.jpg', 'تدور أحداث الفيلم حول عبده (أحمد مظهر) الذي يعمل مدرسًا في إحدى مدارس الفتيات بدلا من زميله جمال (عمر الحريري) الذي نال شعبية واسعة بين الفتيات، وخاصة عطيات (سعاد حسني). يتزوج عبده من تلميذته عطيات، ولكن علاقتهما الزوجية ينتابها الكثير من التوتر بسبب شك عبده الدائم في زوجته، واعتقاده بأنها على علاقة بجمال.', 'The film''s events revolve around Abdo (Ahmed Mazhar), who works as a teacher in a girls'' school instead of his colleague Jamal (Omar Al-Hariri), who has gained wide popularity among the girls, especially Attiyat (Souad Hosni). Abdo marries his student Atiyat, but their marital relationship experiences a lot of tension because of Abdo''s constant suspicion of his wife and his belief that she is having an affair with Jamal.', 7.0, '["دراما", "رومنسية"]'::jsonb, '[{"name": "أحمد مظهر", "character": "عبده", "profile_path": "/7B1ShnTfRABhkzG6Wm3FO3P3Hof.jpg"}, {"name": "سعاد حسني", "character": "عطيات", "profile_path": "/ulWhmq32VFr98H5SoOqbEHa9T34.jpg"}, {"name": "عمر الحريري", "character": "جمال", "profile_path": "/2UjTbJxOgc96wpO8zTzCgSu1Puf.jpg"}, {"name": "عبدالمنعم إبراهيم", "character": "حموده", "profile_path": "/Ae0DVAvlWuyT02B9yflrC7R34MM.jpg"}, {"name": "عبدالوارث عسر", "character": "خليل أفندي", "profile_path": "/8TH7Oe9MyFSY1Mqq84OQ0uXdZvk.jpg"}, {"name": "أحمد أباظة", "character": "الشيخ البهبهاني", "profile_path": "/9whRz7zqddw7pIpC5V7tR0ffvUo.jpg"}]'::jsonb, 120) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (120, 'movie', 'صباحو كدب', 'Morning Lies', 'صباحو كدب', 'صباحو كدب', 2006, 181441, 'movie', '/a7bAAoXxIVW0XcJhcl1AIByNp2X.jpg', '/1bmZxYr12wpHEaLlzJUPf4ZSftz.jpg', 'نعناع (احمد ادم) مدرس موسيقى كفيف , يعيش فى منزل ورثه عن والدته مع زوج امه ( سعيد طرابيك) و زوجته الجديدة(ميسرة), يعلمان بأن قطعة الارض التى ورثها قد تضاعف ثمنها , فيقرران خداعه واقناعه بالزواج بفتاة ليل (اميرة فتحى) على أنهاممرضة , ولكنه يكتشف الحقيقة', 'Ne’naa, (Ahmad Adam) a blind music teacher lives with his stepfather Zeinhom (Saeed Tarabeek) and his stepfather’s new wife who both want to seize his inheritance. They introduce a prostitute, Poussy (Amira Fathy), as a nurse to make him fall for her and steal his heritage.', 5.7, '["دراما", "كوميديا"]'::jsonb, '[{"name": "أحمد آدم", "character": "Abdel Moneim Hafez / Ne3na3", "profile_path": "/lTA1mYQBPF42peiKKD8ArSI1sko.jpg"}, {"name": "Amira Fathy", "character": "Samia Lotfy / Boussy", "profile_path": "/uSw1fgLa1rhDMG6oJI7yRDcr8xB.jpg"}, {"name": "لطفي لبيب", "character": "Sayed - School Principal", "profile_path": "/guGZ0Xv4csBj10ipPlQAgf0yq6o.jpg"}, {"name": "محمد شرف", "character": "Shafiq", "profile_path": "/w8QXglT2mEiT51GTuMOZND3H5M.jpg"}, {"name": "سعيد طرابيك", "character": "Zainhom", "profile_path": "/4oFrjTGPqio4pOxmEDD1RBYLfwV.jpg"}, {"name": "ميسرة", "character": "Sabah (Zainhom''s Wife)", "profile_path": "/6zB3ROdU1VLKk7aHblbNhCJp50k.jpg"}]'::jsonb, 97) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (121, 'movie', 'سمير أبو النيل', 'Samir Abu el Nil', 'سمير أبو النيل', 'سمير ابو النيل', 2013, 172420, 'movie', '/arXNfRFPCoXMCa1juie0Nl5LE6Q.jpg', '/w9sozm34kOLldwKFk0je838DHez.jpg', 'في إطار كوميدي تدور أحداث الفيلم حول الشاب البخيل سمير أبو النيل (أحمد مكي) الذي يقطن بحي شعبي، ونتيجة لبخله الشديد تقع له العديد من المفارقات والمشاكل مع أهل منطقته، ويزيد من كرههم له لسوء معاملته', 'Samir Abo El-Nil (Ahmed Makki) lives in a local neighborhood where he gets into problems with its residents because of his stinginess . When his cousin Hussein Abo El-Nil (Hussein Al-Imam) leaves him a fortune , he starts a satellite channel where he discusses his relations with those around him.', 4.8, '["كوميديا"]'::jsonb, '[{"name": "أحمد مكي", "character": "", "profile_path": "/9uK9EhWwhB2mepg73CB3wN64DlU.jpg"}, {"name": "محمد لطفي", "character": "", "profile_path": "/Akh0XZ1gRWeMWAmDz7kbg6xwz4V.jpg"}, {"name": "حسين الإمام", "character": "", "profile_path": "/wxzEgNYhCKHA0lYleMgo0FeC671.jpg"}, {"name": "دينا الشربيني", "character": "", "profile_path": "/yKIdQwGzMtYN7j75gSQOYQOwVXz.jpg"}, {"name": "نيكول سابا", "character": "", "profile_path": "/qpPzWzoP3X7W6iwYwXhByCBZwXU.jpg"}, {"name": "منة شلبي", "character": "", "profile_path": "/oxX093z8VFpDUTDTR0T0WFaMIos.jpg"}]'::jsonb, 106) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (122, 'movie', 'خيال مآتة', 'Scarecrow', 'خيال مآتة', 'خيال ماته', 2019, 621333, 'movie', '/vhfdoYKSecU4wiN3qEgc4WCa6WH.jpg', '/gOvc4gCWE2OPHegH3zrktZTAnBf.jpg', 'تدور أحداث العمل حول جد قام بسرقة تحفة فنية نادرة تخص المطربة الراحلة (أم كلثوم) في شبابه، ولكن بعد مرور السنوات يجد الجد نفسه مطارد من قبل الطامعين في الحصول على هذه القطعة، ولذلك يلجأ لمساعدة حفيده الوحيد.', 'The story revolves around a grandfather who stole a rare masterpiece belonging to the late singer (Umm Kulthum) in his youth, but after years passes, he finds himself chased by those who want to have this piece, which makes him resort to the help of his only grandson.', 4.9, '["كوميديا"]'::jsonb, '[{"name": "أحمد حلمي", "character": "زيزو / يكن", "profile_path": "/xVhX7ia3ptI43V65Os90gbfgxAe.jpg"}, {"name": "منة شلبي", "character": "أسيا", "profile_path": "/oxX093z8VFpDUTDTR0T0WFaMIos.jpg"}, {"name": "بيومي فؤاد", "character": "مزلاوي", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "حسن حسني", "character": "خليل مرسي الرجابي", "profile_path": "/vMG9Carh5bi18v5unk06aYvvKZw.jpg"}, {"name": "خالد الصاوي", "character": "القيصر", "profile_path": "/t4Z5PVsbFgN6RsN1bksjDwZlkhc.jpg"}, {"name": "لطفي لبيب", "character": "زغلول النادي", "profile_path": "/guGZ0Xv4csBj10ipPlQAgf0yq6o.jpg"}]'::jsonb, 120) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (123, 'movie', 'وكالة البلح', 'Wikalet El-Balah Market', 'وكالة البلح', 'وكاله البلح', 1982, 406857, 'movie', '/aiali1LPJN1QrSzC9jWerCeKGU6.jpg', '/30gN09nrgx8nlF8yknpiawseAaG.jpg', 'تدور قصة العمل في وكالة البلح، حول المعلمة نعمة الله والتي تسيطر على التجارة في المنطقة ولتحقيق ذلك تتخلص من جميع منافسيها، إلى أن تتعرف على عبد الله الشاب الفقير وتتزوجه وتجعله المالك لكل شيء، لتنقلب الأحداث رأساً على عقب', 'The events take place in Wikalet El-Balah, where Master Nehmatullah takes controls of the trade in the region by getting rid of her competitors. She marries the poor young Abdullah and makes him in charge of everything which turns the events upside down.', 5.0, '["دراما", "إثارة", "جريمة"]'::jsonb, '[{"name": "نادية الجندي", "character": "NematAllah", "profile_path": "/az5y9WqFd2FRJ2nAmzHH3KWVCWc.jpg"}, {"name": "محمود ياسين", "character": "Abdullah", "profile_path": "/pGYBLZoB2F0jokdFY1Gob7uJmA5.jpg"}, {"name": "محمود عبدالعزيز", "character": "Abdoun", "profile_path": "/2tTG533lGmSsybIVOR6lYkFQ3t5.jpg"}, {"name": "وحيد سيف", "character": "Riyad Al-Dabash", "profile_path": "/eDLRmet0ePsP3GPN05wy4f6uxrS.jpg"}, {"name": "سيد زيان", "character": "Haluma Al-Jahsh", "profile_path": "/tUJSBZ1XguLh2l2jbqKLvrRxJyi.jpg"}, {"name": "سمية الألفي", "character": "Mervat", "profile_path": "/oMDBD5PigdxTDDjhWaqr05LaJbf.jpg"}]'::jsonb, 140) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_memb