INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (124, 'movie', 'مقلب حرامية', 'Thieves Trick', 'مقلب حرامية', 'مقلب حراميه', 2009, 57807, 'movie', '/m3LM64Y1kOW639cnqtB85Z6GMbO.jpg', '/prbqeHyphdINZQk5qMoBQUmSs3M.jpg', 'عصابة من اللصوص الظرفاء تلتقي وتقرر القيام بسرقة العمر ..فهل ينجحوا ؟؟', 'A band of thieves get together and begin planning the heist of a lifetime. Will they succeed or will their planning be in vain?', 5.5, '["جريمة", "كوميديا"]'::jsonb, '[{"name": "محمود عبدالمغني", "character": "سيد استك", "profile_path": "/78NvDJqQ2X71GDKXDIpH0kqEdvp.jpg"}, {"name": "عمرو يوسف", "character": "علي مللي", "profile_path": "/vYyvP5NHlVUNdKmUgX3e7X5sAW.jpg"}, {"name": "ماجد الكدواني", "character": "توفيق آلارم", "profile_path": "/iBOBl5XrufQr67yqUU7YOUXoY54.jpg"}, {"name": "أحمد السعدني", "character": "زكي كود", "profile_path": "/bWNJ21irKIjy4aT0GB3EEAZAri8.jpg"}, {"name": "شريف سلامة", "character": "صلاح سقاطة", "profile_path": "/1KK2HlLD8m7B0qhOb7OJmvUzGCl.jpg"}, {"name": "صلاح عبدالله", "character": "جابر", "profile_path": "/dlpv6csuikKoRAhOQQEdkvmZwUX.jpg"}]'::jsonb, 89) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (125, 'movie', 'بدل فاقد', 'Badal Faqed', 'بدل فاقد', 'بدل فاقد', 2009, 514345, 'movie', '/A2FCFh84mcmAfCpgLqnSyz4wMyQ.jpg', '/7ql8p0CaVmoJGXoBCiqxNQBpJoO.jpg', 'تدور أحداث الفيلم حول توأم فارقت بينهم الأيام حيث كل واحد فيهم تربى في بيئة مختلفة واحد تبنته راقصة وعاش معها فى منطقة عشوائية حياة فقيرة مهمشة، والأخر تبنته عائلة طيبة رفيعة المستوى، فيصبح الأول تاجرا للمخدرات والثانى ضابط شرطة', 'The film''s events revolve around twins separated by days, each of them raised in a different environment. One was adopted by a dancer and lived with her in a poor, marginalized life in a slum area, and the other was adopted by a good, high-ranking family, and the first became a drug dealer and the second a police officer.', 7.0, '["حركة", "دراما", "إثارة"]'::jsonb, '[{"name": "أحمد عز", "character": "فارس \\ نبيل", "profile_path": "/mgQhox7AbzVsQ8xeTZvkK5Gvkd4.jpg"}, {"name": "منة شلبي", "character": "مى", "profile_path": "/oxX093z8VFpDUTDTR0T0WFaMIos.jpg"}, {"name": "محمد لطفي", "character": "خداش", "profile_path": "/Akh0XZ1gRWeMWAmDz7kbg6xwz4V.jpg"}, {"name": "أحمد فؤاد سليم", "character": "اللواء محسن", "profile_path": "/q1NbI2PzKHoF1AxCHgMju9we4qP.jpg"}, {"name": "رشا مهدي", "character": "حبيبة", "profile_path": "/vW8406dXmroguoJDP51keIVSWS3.jpg"}, {"name": "سوسن بدر", "character": "زوجة اللواء محسن", "profile_path": "/yHgnipZ0bDUjjdf1Pu9S7bEhcun.jpg"}]'::jsonb, 107) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (126, 'movie', 'تتح', 'Tattah', 'تتح', 'تتح', 2013, 189017, 'movie', '/rF3diGnjQrxkDEFjyv1yiz5PoZS.jpg', '/kRBdKvqbfOcvMiO03kDp69sv9mG.jpg', 'تدور أحداث الفيلم حول تتح (محمد سعد)؛ الرجل الفقير ضيق الرزق الذي يعيش في أحد أحياء عابدين، والذي يتعرف على فتاة جميلة عن طريق الإنترنت (دوللي شاهين) بمساعدة ابن أخته (عمر مصطفى متولي) الذي يعيش معه، تبدأ حياة تتح في التغير تمامًا، عندما تتعرض هذه الفتاة للاختطاف من قبل مجهولين ويحاول هو  إنقاذها.', 'This satirical comedy revolves around Tatah, a maladjusted, poor man from Abdeen who befriends a woman online with help from his nephew. Just as his life starts to change, the woman is kidnapped and he sets out to save her.', 4.7, '["كوميديا"]'::jsonb, '[{"name": "محمد سعد", "character": "تتح", "profile_path": "/zpIK3GYmqDPumneEDf0aqsqxhV1.jpg"}, {"name": "Dolly Shaheen", "character": "", "profile_path": "/fSGf6JSAhoOOEVAn4yQ2eGoBD9X.jpg"}, {"name": "سيد رجب", "character": "", "profile_path": "/r6zPbQX4Rj4Y1ynk5Ym4kfdYBpq.jpg"}, {"name": "رجاء الجداوي", "character": "", "profile_path": "/mgZFyKbzxEbT0PZbDSZ2Ue0rAXo.jpg"}, {"name": "Marwa", "character": "", "profile_path": "/r5U9tc4yaGjqlvD3kdbhM7M3SS2.jpg"}, {"name": "هياتم", "character": "", "profile_path": "/3N1VF6VybQrWeIT6XNqyyd1t7oB.jpg"}]'::jsonb, 112) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (127, 'movie', 'تيتة رهيبة', 'Horrible Grandma', 'تيتة رهيبة', 'تيته رهيبه', 2012, 246823, 'movie', '/2tIgs4MC3TPH84srRjCfuVruw27.jpg', '/x1oP4Mu1bsE4lutlGlloOHPiLB9.jpg', 'يهرب روؤف (محمد هنيدي) من أشباح سيطرة جدته راوية هانم (سميحة أيوب) عليه بعد سفرها إلى ألمانيا ويقيم مع جده رمان (عبد الرحمن أبو زهرة)، وعقب وفاته يقرر الزواج من الفتاة منار (إيمي سمير غانم) التي تعلق بها قلبه، لكن عودة جدته وإقامتها معه تقلب حياته رأسا على عقب فتعود للسيطرة عليه مرة أخرى وتتحكم في حياته وحياة زوجته بشكل كبير.', 'Raouf escapes of the control his grandmother Rawyah Hanim after she traveed to Germany and he movd with his grandfather Romman. After his grandfather''s death, he decided to marry Manar, who he is attached to, but as his grandmother returned home and moved to live with him, life turned upside down dramatically as she tries to control his and his wife''s lives.', 5.6, '["كوميديا"]'::jsonb, '[{"name": "محمد هنيدي", "character": "", "profile_path": "/duDDRRuYjC3qvabxA4w1e1y7g6R.jpg"}, {"name": "إيمي سمير غانم", "character": "", "profile_path": "/ugym5uaaNM0xeAOQBPe1LtLq7XD.jpg"}, {"name": "باسم سمرة", "character": "", "profile_path": "/tKhneTl9BL6W1jIgTV43o5duFPx.jpg"}, {"name": "عبدالرحمن أبو زهرة", "character": "", "profile_path": "/8IZuTHmfKwnPTxOGPoegE4mCW8r.jpg"}, {"name": "محمد فراج", "character": "", "profile_path": "/hjMAlmyVRbZe9mRrhjO0l5EpsAn.jpg"}, {"name": "سميحة أيوب", "character": "", "profile_path": "/v9UWzWFkewvX4ZRnYI7bXy0kII3.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (128, 'movie', 'عروسة وجوز عرسان', 'Bride and two grooms', 'عروسة وجوز عرسان', 'عروسه وجوز عرسان', 1982, 751052, 'movie', '/sdUhNi4kLlnK7vkr8wsy40NoLZL.jpg', '/qdlGMNU47u56v0OKxpnCjWRz8PA.jpg', 'Soria works in the theatrical troupe "Asfour Troupe" and marries the director, Essam, despite the actor Shaker being in love with her. Essam travels abroad, and the ship he''s on sinks. After the legal waiting period for a missing spouse passes, Soria marries Shaker. Essam suddenly returns, shocking everyone with his reappearance. He is unaware that his wife married his friend during his absence. Soria is torn – Essam insists on reclaiming her, while she feels affection for both husbands. Sensing Soria''s inner conflict, Shaker divorces her and marries his colleague Sanaa. Meanwhile, Essam returns to Soria once again.', 'Soria works in the theatrical troupe "Asfour Troupe" and marries the director, Essam, despite the actor Shaker being in love with her. Essam travels abroad, and the ship he''s on sinks. After the legal waiting period for a missing spouse passes, Soria marries Shaker. Essam suddenly returns, shocking everyone with his reappearance. He is unaware that his wife married his friend during his absence. Soria is torn – Essam insists on reclaiming her, while she feels affection for both husbands. Sensing Soria''s inner conflict, Shaker divorces her and marries his colleague Sanaa. Meanwhile, Essam returns to Soria once again.', 8.0, '["كوميديا", "دراما", "عائلي"]'::jsonb, '[{"name": "سمير غانم", "character": "", "profile_path": "/vSqmd98zrxOAnDFnBGnt4Wihn7B.jpg"}, {"name": "يونس شلبي", "character": "", "profile_path": "/jLtc7MnYVPHGdIyIhKeVESVdpb7.jpg"}, {"name": "إسعاد يونس", "character": "", "profile_path": "/jP7Sc5tSneEBTmni0npq87obq1g.jpg"}, {"name": "وحيد سيف", "character": "", "profile_path": "/eDLRmet0ePsP3GPN05wy4f6uxrS.jpg"}, {"name": "معالي زايد", "character": "", "profile_path": "/oAALG7p4ReXhOgtZQehCtYcfkR1.jpg"}, {"name": "محمد رضا", "character": "", "profile_path": "/c45atsICuA4BShxcd8qIGOHp2QU.jpg"}]'::jsonb, 0) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (129, 'movie', 'دكان شحاته', 'Shehata''s Store', 'دكان شحاتة', 'دكان شحاته', 2009, 63362, 'movie', '/8mPlmM4vLd6i4chNs0YpnWjN7JM.jpg', '/7FxglaP95uSFtRG0YC4Rw2PYHkJ.jpg', 'يناقش الفيلم في دراما اجتماعية، ضياع القيم الأصيلة في الأسرة المصرية، وما يترتب على ذهابها، من خلال قصة شحاتة (عمرو سعد) الذي شب على إهمال أشقائه له، وسطوتهم عليه، ومعاملتهم السيئة له، بالرغم من حبه الشديد لهم، وكيف أدت الغيرة المشتعلة بينهم إلى مأساة.', 'Shehata is the son of a modest gardener who saved all his money to open a fruit stand and named it after his favorite son. Shehata''s siblings get so jealous of their brother and plot against him. A representation of the downfall of society and its decaying morals.', 6.3, '["دراما", "جريمة", "إثارة", "رومنسية"]'::jsonb, '[{"name": "عمرو سعد", "character": "شحاته", "profile_path": "/ii5oJije7WOfqBwyxAt4YettAnj.jpg"}, {"name": "Haifa Wehbe", "character": "بيسة", "profile_path": "/ht9N2jOcT9EChL7JWWYQLl93s1w.jpg"}, {"name": "عمرو عبدالجليل", "character": "كرم", "profile_path": "/5H6iU6KXLvfLPzjPIm3DMkOGtf0.jpg"}, {"name": "أحمد وفيق", "character": "", "profile_path": "/fBYFStyMSTDBZH3egH5j7xpCh3H.jpg"}, {"name": "محمد كريم", "character": "سالم", "profile_path": "/oRPuk2qnUM9EV8shBJE7lKPv78R.jpg"}, {"name": "محمود حميدة", "character": "حجاج", "profile_path": "/8uSJfakEstaPOBqCtn1oIzJm7VZ.jpg"}]'::jsonb, 128) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (131, 'movie', 'أشباح أوروبا', 'Renegades of Europe', 'اشباح اوروبا', 'اشباح اوروبا', 2022, 635604, 'movie', '/y92cTW9pIw3K2AX7l9R6GS1FKZ2.jpg', '/hG27MxNSEz8CxWsh8VrkuJGOFPh.jpg', 'ينطلق ثلاثة توائم من صعيد مصر إلى إسبانيا باحثين عن إرث والدتهم الراحلة، وهناك تقربهم سلسلة من الأحداث الخطرة من فهم جذورهم.', 'A wife gives birth to sextuplets, forcing the husband to sell three of their children due to poverty. When the wife finds out, she decides to leave her husband and travel abroad and many conflicts arise between siblings in the future.', 5.7, '["حركة", "دراما"]'::jsonb, '[{"name": "Haifa Wehbe", "character": "لي لي / هويدا", "profile_path": "/ht9N2jOcT9EChL7JWWYQLl93s1w.jpg"}, {"name": "أحمد الفيشاوي", "character": "مارتن / بركات", "profile_path": "/4bmLaXHBRZi6Sn6XE1eCAM6KDs0.jpg"}, {"name": "مصطفى خاطر", "character": "چو / عبودا", "profile_path": "/pj5b1XP1iM8BaCKb6QOdZpAD8xW.jpg"}, {"name": "أروى جودة", "character": "ايڤا", "profile_path": "/j4G85Ddx2E0Lr6zXNcviCx9jkFs.jpg"}, {"name": "باسم سمرة", "character": "هارون", "profile_path": "/tKhneTl9BL6W1jIgTV43o5duFPx.jpg"}, {"name": "عباس أبو الحسن", "character": "سليم", "profile_path": "/wXbXtPndb6EAaIaOBbDweMufjBD.jpg"}]'::jsonb, 77) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (132, 'movie', 'أولاد حريم كريم', 'Awlad Hareem Karim', 'اولاد حريم كريم', 'اولاد حريم كريم', 2023, 1129293, 'movie', '/1BbYw0r94sIN93hgSNzf7MUsVvu.jpg', '/blG8GQNdLpZAMP1x63DneCq0gQB.jpg', 'تدور احداث حين تنشأ علاقة حب بين (كريم حسين) و(آيلا)، وعندما يتقدم للزواج منها يكتشف والدها (كريم الحسيني) أنه ابن زميلته وحبيبته السابقة (مها)، ثم يستعيدان علاقة الصداقة القديمة مع صديقتيهما (هالة) و(دينا).', 'A romantic relationship develops between Karim Hussein and Ayla, and when he proposes to her, her father Karim El Husseiny discovers that he is the son of his ex-college sweetheart Maha, then they rekindle their old friendship with their two friends Hala and Dina.', 4.3, '["رومنسية", "كوميديا"]'::jsonb, '[{"name": "مصطفى قمر", "character": "", "profile_path": "/uZull5mK6khuL0cJR7S3YYayRq7.jpg"}, {"name": "داليا البحيري", "character": "", "profile_path": "/asZcD9JJAhD5NZbayPKqXE19Qui.jpg"}, {"name": "علا غانم", "character": "", "profile_path": "/u5crUAuOlylo0yFq0dCzZyZv9Om.jpg"}, {"name": "بسمة", "character": "", "profile_path": "/uHesQTc5W7cEIzC7LktGX9isl62.jpg"}, {"name": "خالد سرحان", "character": "", "profile_path": "/fmPmWfGd85UHuG30ldCtBaN9J51.jpg"}, {"name": "بشرى", "character": "", "profile_path": "/q5tSanaqYG1ko6dR3PMWaFtN6tL.jpg"}]'::jsonb, 106) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
