INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (146, 'movie', 'دعوة المظلوم', 'دعوة المظلوم', 'دعوة المظلوم', 'دعوه', 1956, 1099192, 'movie', '/mrPgP0XAPC19646uHo0vkA0gxoM.jpg', NULL, 'قصة حب متبادلة بين هدى والثري محسن، اللذان يتزوجان ويعيشان حياة سعيدة، ولكن تشعر ابنة خال محسن بالغيرة من هذا الزواج، لأنها تحب محسن، فتسعى إلى فسخ هذا الزواج، فتعمل على تدبير خطة، حيث تستعين بشقيق إحدى صديقاتها، ويصاب محسن بشلل', 'قصة حب متبادلة بين هدى والثري محسن، اللذان يتزوجان ويعيشان حياة سعيدة، ولكن تشعر ابنة خال محسن بالغيرة من هذا الزواج، لأنها تحب محسن، فتسعى إلى فسخ هذا الزواج، فتعمل على تدبير خطة، حيث تستعين بشقيق إحدى صديقاتها، ويصاب محسن بشلل', NULL, '[]'::jsonb, '[{"name": "عمر الحريري", "character": "محسن", "profile_path": "/2UjTbJxOgc96wpO8zTzCgSu1Puf.jpg"}, {"name": "صلاح نظمي", "character": "فريد", "profile_path": "/n0jY20G7CvG7nS7aoKGa8Awfxpi.jpg"}, {"name": "سلوي محمود", "character": "ليلى", "profile_path": "/redCHQdqiJvW9qUskuDDxc2YTPu.jpg"}, {"name": "زهرة العلا", "character": "هدى", "profile_path": "/mb3nrkoYuKVfQsrkkoCe4nYhjxa.jpg"}, {"name": "سميحة توفيق", "character": "زوزو", "profile_path": "/93vO1rq6tfdRb4SGwTHCMouMcBT.jpg"}]'::jsonb, 95) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
