INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (150, 'movie', 'همسات الليل', 'همسات الليل', 'همسات الليل', 'همسات', 1977, 750798, 'movie', '/xZpM1tL0qWIrxdAH7AidlhKUN7Z.jpg', NULL, 'يجمع الحب بين كريمة ومحسن، إلا أن الابن طارق يقف حائلًا بينهما لأنه يرغب أن تكون أمه له وحده وليس لأحدًا غيره، تتفق كريمة مع محسن على الزواج، تحاول الأم إخراج ابنها من هذا الموقف من خلال دفعه للزواج من مديحة، وبعد زواج طارق من مديحة يفشل في القيام بواجباته كزوج، تحاول والدته مساعدة ابنها بالأخذ بنصيحة أحد الأطباء بدفع ابنها لإقامة علاقة مع فتاة من بائعات الهوى لتحفيزه على القيام بواجباته الزوجية.', 'يجمع الحب بين كريمة ومحسن، إلا أن الابن طارق يقف حائلًا بينهما لأنه يرغب أن تكون أمه له وحده وليس لأحدًا غيره، تتفق كريمة مع محسن على الزواج، تحاول الأم إخراج ابنها من هذا الموقف من خلال دفعه للزواج من مديحة، وبعد زواج طارق من مديحة يفشل في القيام بواجباته كزوج، تحاول والدته مساعدة ابنها بالأخذ بنصيحة أحد الأطباء بدفع ابنها لإقامة علاقة مع فتاة من بائعات الهوى لتحفيزه على القيام بواجباته الزوجية.', NULL, '[]'::jsonb, '[{"name": "محمود ياسين", "character": "", "profile_path": "/pGYBLZoB2F0jokdFY1Gob7uJmA5.jpg"}, {"name": "نور الشريف", "character": "", "profile_path": "/wBFojkh5Tr2JCHWkQ7sfmo2SKgd.jpg"}, {"name": "ناهد شريف", "character": "", "profile_path": "/4IxyzS7FAiok8W3LWcqASymMKJ7.jpg"}, {"name": "عفاف شعيب", "character": "", "profile_path": "/fvI9NmH9x1ur9M5WI0wqQkni040.jpg"}, {"name": "مريم فخر الدين", "character": "", "profile_path": "/xrJVs2VO7HjOkYWpuKBtEI2mpuU.jpg"}]'::jsonb, 70) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, ove