INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (177, 'series', 'الثمن', 'الثمن', 'الثمن', 'مسلسل الثمن', 2023, 211782, 'tv', '/uFEV0Tsns33zKyuc12l4XCBoba7.jpg', '/dRV1lMIxQBlIgngufjrQeRX1JJm.jpg', 'تلجأ أرملة لخيارها الوحيد المتبقي لتغطية تكاليف علاج ابنها من السرطان، وهو أن تطلب المال من مديرها الذي يشترط عليها تمضية ليلة واحدة معه.', 'تلجأ أرملة لخيارها الوحيد المتبقي لتغطية تكاليف علاج ابنها من السرطان، وهو أن تطلب المال من مديرها الذي يشترط عليها تمضية ليلة واحدة معه.', 6.6, '["دراما"]'::jsonb, '[{"name": "باسل خياط", "character": "Zein", "profile_path": "/3e5iMDJTQdzy4tyCyRulPEAY0Ml.jpg"}, {"name": "رزان جمال", "character": "Sarah", "profile_path": "/nFFZGLhGera8UHImoKNMU63tSDP.jpg"}, {"name": "Hadi Mokdad", "character": "Ibrahim", "profile_path": "/rAX82GhdkGXBHcsZ0fDWGfMtf0.jpg"}, {"name": "سارة أبي كنعان", "character": "Tima", "profile_path": "/vTDUsabi7gIM5Tf5hifx5VRW27.jpg"}, {"name": "نيقولا معوض", "character": "Karam", "profile_path": "/k4y3zv6mwrhS5yLgkJhM50cM0IL.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (178, 'movie', 'فارس الظلام', 'The Dark Knight', 'The Dark Knight', 'the dark knight', 2008, 155, 'movie', '/6Z9znq1IxwknrdPbXyr7NJJPhpP.jpg', '/9FE5eD92WfVCiivM9Pq9GVSrlWk.jpg', 'يبدأ باتمان فى محاربة العدو الجديد (الجوكر) الذي يسعى لنشر الذعر والشر في جوثام، وإثبات أن العيش بدون قواعد أفضل، مما يؤدي لصراع بين الاثنين يشترك فيه المفتش جوردن والمدعى العام هارفي دينت وراشيل صديقة بروس وين.', 'يبدأ باتمان فى محاربة العدو الجديد (الجوكر) الذي يسعى لنشر الذعر والشر في جوثام، وإثبات أن العيش بدون قواعد أفضل، مما يؤدي لصراع بين الاثنين يشترك فيه المفتش جوردن والمدعى العام هارفي دينت وراشيل صديقة بروس وين.', 8.5, '["حركة", "جريمة", "إثارة"]'::jsonb, '[{"name": "كريستيان بيل", "character": "Bruce Wayne", "profile_path": "/7Pxez9J8fuPd2Mn9kex13YALrCQ.jpg"}, {"name": "هيث ليدجر", "character": "Joker", "profile_path": "/AdWKVqyWpkYSfKE5Gb2qn8JzHni.jpg"}, {"name": "آرون إيكهارت", "character": "Harvey Dent", "profile_path": "/u5JjnRMr9zKEVvOP7k3F6gdcwT6.jpg"}, {"name": "مايكل كين", "character": "Alfred", "profile_path": "/bVZRMlpjTAO2pJK6v90buFgVbSW.jpg"}, {"name": "Maggie Gyllenhaal", "character": "Rachel", "profile_path": "/vsfkWdYWmA9CpzMHTJzrFxlDnEZ.jpg"}]'::jsonb, 152) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (179, 'movie', 'استهلال', 'Inception', 'Inception', 'inception', 2010, 27205, 'movie', '/okXrvv9kCNrYTpjMQTpmzXV9JCi.jpg', '/8ZTVqvKDQ8emSGUEMjsS4yHAwrp.jpg', 'يُعرض على (كوب)، وهو لصٌ بارع يتخصص في سرقة أسرار الشركات عبر التسلل إلى العقل الباطن لأهدافه، فرصة لاستعادة حياته السابقة مقابل تنفيذ مهمة يُعتقد أنها مستحيلة: "الاستهلال"، وهي زرع فكرة في العقل الباطن لشخص آخر بحيث يظن أنها فكرته هو.', 'يُعرض على (كوب)، وهو لصٌ بارع يتخصص في سرقة أسرار الشركات عبر التسلل إلى العقل الباطن لأهدافه، فرصة لاستعادة حياته السابقة مقابل تنفيذ مهمة يُعتقد أنها مستحيلة: "الاستهلال"، وهي زرع فكرة في العقل الباطن لشخص آخر بحيث يظن أنها فكرته هو.', 8.4, '["حركة", "خيال علمي", "مغامرة"]'::jsonb, '[{"name": "ليوناردو دي كابريو", "character": "Dom Cobb", "profile_path": "/wo2hJpn04vbtmh0B9utCFdsQhxM.jpg"}, {"name": "جوزيف غوردون-ليفيت", "character": "Arthur", "profile_path": "/z2FA8js799xqtfiFjBTicFYdfk.jpg"}, {"name": "渡辺謙", "character": "Saito", "profile_path": "/psAXOYp9SBOXvg6AXzARDedNQ9P.jpg"}, {"name": "توم هاردي", "character": "Eames", "profile_path": "/d81K0RH8UX7tZj49tZaQhZ9ewH.jpg"}, {"name": "إليوت بيج", "character": "Ariadne", "profile_path": "/nXO8DE4biVXY4UDYP0NdIY1zvXS.jpg"}]'::jsonb, 148) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (180, 'movie', 'بين النجوم', 'Interstellar', 'Interstellar', 'interstellar', 2014, 157336, 'movie', '/rR8bjK9dOXXH9H8AdpfPTlRx8Fy.jpg', '/5XNQBqnBwPA9yT0jZ0p3s8bbLh0.jpg', 'يعيش كوبر، رائد الفضاء السابق الذي يعمل مزارعًا، في مستقبل تعاني فيه الأرض من أزمات بيئية تهدد بقاء البشرية. عندما يكتشف وجود طريق غامض عبر الفضاء، ينضم إلى مهمة سرية لاستكشاف عوالم بعيدة يمكن أن توفر للبشرية فرصة جديدة للحياة. يسافر كوبر مع فريق من العلماء عبر ثقب دودي بالقرب من زحل، ويواجهون كواكب مجهولة وظروفًا قاسية تجعل مرور الوقت مختلفًا عن الأرض. وبينما يحاول كوبر إنقاذ مستقبل البشرية، يظل أكبر دافع له هو العودة إلى أطفاله، لتتحول رحلته إلى صراع بين العلم والوقت والحب.', 'يعيش كوبر، رائد الفضاء السابق الذي يعمل مزارعًا، في مستقبل تعاني فيه الأرض من أزمات بيئية تهدد بقاء البشرية. عندما يكتشف وجود طريق غامض عبر الفضاء، ينضم إلى مهمة سرية لاستكشاف عوالم بعيدة يمكن أن توفر للبشرية فرصة جديدة للحياة. يسافر كوبر مع فريق من العلماء عبر ثقب دودي بالقرب من زحل، ويواجهون كواكب مجهولة وظروفًا قاسية تجعل مرور الوقت مختلفًا عن الأرض. وبينما يحاول كوبر إنقاذ مستقبل البشرية، يظل أكبر دافع له هو العودة إلى أطفاله، لتتحول رحلته إلى صراع بين العلم والوقت والحب.', 8.5, '["مغامرة", "دراما", "خيال علمي"]'::jsonb, '[{"name": "ماثيو ماكونهي", "character": "Cooper", "profile_path": "/lCySuYjhXix3FzQdS4oceDDrXKI.jpg"}, {"name": "آن هاثاواي", "character": "Brand", "profile_path": "/nbccV2pMoyLTCeg5DQip24Eq0Jp.jpg"}, {"name": "مايكل كين", "character": "Professor Brand", "profile_path": "/bVZRMlpjTAO2pJK6v90buFgVbSW.jpg"}, {"name": "جيسيكا شاستاين", "character": "Murph", "profile_path": "/eQKnihReJeB9vQEa5gySzAlKfZt.jpg"}, {"name": "كيسي أفليك", "character": "Tom", "profile_path": "/304ilSygaCRWykoBWAL67TOw8g9.jpg"}]'::jsonb, 169) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (181, 'movie', 'المجالد', 'Gladiator', 'Gladiator', 'gladiator', 2000, 98, 'movie', '/3ThtMXP24MxSkUOTqFElQdWzAXe.jpg', '/jhk6D8pim3yaByu1801kMoxXFaX.jpg', 'في روما القديمة، تتحول حياة الجنرال العظيم ماكسيموس إلى مأساة عندما يقتل الإمبراطور الجديد كومودوس عائلته ويرسله للعبودية. يجد ماكسيموس نفسه مجبراً على القتال كمصارع في حلبات الموت، متخذاً طريقاً دموياً نحو روما حيث يسعى للانتقام من الطاغية الذي دمر حياته.', 'في روما القديمة، تتحول حياة الجنرال العظيم ماكسيموس إلى مأساة عندما يقتل الإمبراطور الجديد كومودوس عائلته ويرسله للعبودية. يجد ماكسيموس نفسه مجبراً على القتال كمصارع في حلبات الموت، متخذاً طريقاً دموياً نحو روما حيث يسعى للانتقام من الطاغية الذي دمر حياته.', 8.2, '["حركة", "دراما", "مغامرة"]'::jsonb, '[{"name": "راسل كرو", "character": "Maximus", "profile_path": "/uxiXuVH4vNWrKlJMVVPG1sxAJFe.jpg"}, {"name": "خواكين فينيكس", "character": "Commodus", "profile_path": "/u38k3hQBDwNX0VA22aQceDp9Iyv.jpg"}, {"name": "كوني نيلسن", "character": "Lucilla", "profile_path": "/gSQ3O3PJ6ly6nT63joOtfZyscFP.jpg"}, {"name": "أوليفر ريد", "character": "Proximo", "profile_path": "/dWfotc1X71wNCGyPO9hXpv8U9Gw.jpg"}, {"name": "ريتشارد هاريس", "character": "Marcus Aurelius", "profile_path": "/lCvcVMuxrg1f5A8OMqY9AqkkcZR.jpg"}]'::jsonb, 155) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (182, 'movie', 'المنتقمون: نهاية اللعبة', 'Avengers: Endgame', 'Avengers: Endgame', 'avengers endgame', 2019, 299534, 'movie', '/ydgRpTwwiBkBL1GtNJdTUmNnRVR.jpg', '/2xfV5Zdq4kCsFVReRXJKnJaUFCD.jpg', 'بعد الأحداث المدمّرة لفيلم Avengers: Infinity War، أصبح الكون في حالة خراب بسبب أفعال الفضائي المجنون، ثانوس. وبمساعدة الحلفاء المتبقين، يجب على المنتقمين أن يجتمعوا مرة أخرى من أجل التراجع عن أفعال ثانوس وإعادة النظام إلى الكون مرة أخيرة، مهما كانت العواقب التي قد تنتظرهم.', 'بعد الأحداث المدمّرة لفيلم Avengers: Infinity War، أصبح الكون في حالة خراب بسبب أفعال الفضائي المجنون، ثانوس. وبمساعدة الحلفاء المتبقين، يجب على المنتقمين أن يجتمعوا مرة أخرى من أجل التراجع عن أفعال ثانوس وإعادة النظام إلى الكون مرة أخيرة، مهما كانت العواقب التي قد تنتظرهم.', 8.2, '["مغامرة", "خيال علمي", "حركة"]'::jsonb, '[{"name": "روبرت داوني جونيور", "character": "Tony Stark / Iron Man", "profile_path": "/5qHNjhtjMD4YWH3UP0rm4tKwxCL.jpg"}, {"name": "كريس إيفانز", "character": "Steve Rogers / Captain America", "profile_path": "/3bOGNsHlrswhyW79uvIHH1V43JI.jpg"}, {"name": "مارك رافالو", "character": "Bruce Banner / Hulk", "profile_path": "/5GilHMOt5PAQh6rlUKZzGmaKEI7.jpg"}, {"name": "كريس هيمسوورث", "character": "Thor", "profile_path": "/piQGdoIQOF3C1EI5cbYZLAW1gfj.jpg"}, {"name": "سكارليت جوهانسون", "character": "Natasha Romanoff / Black Widow", "profile_path": "/druW5adKddizHNSoPbI0q7Mvn0K.jpg"}]'::jsonb, 181) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rat