INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (183, 'movie', 'جون ويك: الفصل ٤', 'John Wick: Chapter 4', 'John Wick: Chapter 4', 'john wick chapter 4', 2023, 603692, 'movie', '/j6Zcib1u1QhBs0KVKU8yxOugkAv.jpg', '/7I6VUdPj6tQECNHdviJkUHD2u89.jpg', 'بعدما اكتشف طريقة ستمكنه من القضاء على المجلس الأعلى واستعادة حريته، يجد جون ويك نفسه في مواجهة مع عدو جديد تدفعه للشك حتى في أصدقاؤه القدامى.', 'بعدما اكتشف طريقة ستمكنه من القضاء على المجلس الأعلى واستعادة حريته، يجد جون ويك نفسه في مواجهة مع عدو جديد تدفعه للشك حتى في أصدقاؤه القدامى.', 7.7, '["حركة", "إثارة", "جريمة"]'::jsonb, '[{"name": "كيانو ريفز", "character": "John Wick", "profile_path": "/8RZLOyYGsoRe9p44q3xin9QkMHv.jpg"}, {"name": "دوني ين", "character": "Caine", "profile_path": "/hTlhrrZMj8hZVvD17j4KyAFWBHc.jpg"}, {"name": "بيل سكارسغارد", "character": "Marquis", "profile_path": "/xBXLx1m0uzhXIbY3wN8lmPGeUHl.jpg"}, {"name": "إيان ماكشين", "character": "Winston", "profile_path": "/rteBJYNgD1yGsHg2HGZAIrYHz1t.jpg"}, {"name": "Laurence Fishburne", "character": "Bowery King", "profile_path": "/2GbXERENPpl5MmlqOLlPVaVtifD.jpg"}]'::jsonb, 170) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (184, 'movie', 'ماكس المجنون  طريق الغضب', 'Mad Max: Fury Road', 'Mad Max: Fury Road', 'mad max fury road', 2015, 76341, 'movie', '/rvoQHUQGskr7HIQdsyYeOe0GYiL.jpg', '/uT895WNwm0aIJRtGizcQhrejWUo.jpg', 'في أقصى أطراف الأرض، وسط صحراء قاحلة وعالم ممزق، يقاتل الجميع بجنون من أجل البقاء. في قلب الفوضى، يهرب متمردان... وقد يكون بيدهما أمل استعادة النظام.', 'في أقصى أطراف الأرض، وسط صحراء قاحلة وعالم ممزق، يقاتل الجميع بجنون من أجل البقاء. في قلب الفوضى، يهرب متمردان... وقد يكون بيدهما أمل استعادة النظام.', 7.6, '["حركة", "مغامرة", "خيال علمي"]'::jsonb, '[{"name": "توم هاردي", "character": "Max Rockatansky", "profile_path": "/d81K0RH8UX7tZj49tZaQhZ9ewH.jpg"}, {"name": "تشارليز ثيرون", "character": "Imperator Furiosa", "profile_path": "/gd7ShD0yt4bsR2STeQ19KQ6hvXL.jpg"}, {"name": "نيكولاس هولت", "character": "Nux", "profile_path": "/pXm8GWTm9eIA8pUGOjvmYjlxamu.jpg"}, {"name": "هيو كايس-بيرن", "character": "Immortan Joe", "profile_path": "/7XSPjKNwmyEPMnmoVSQ42ykMz6M.jpg"}, {"name": "جوش هيلمان", "character": "Slit", "profile_path": "/1thwLjrgvFv7ifjyVtTKQh23OCh.jpg"}]'::jsonb, 120) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (185, 'movie', 'السلاح الأمثل: مافريك', 'Top Gun: Maverick', 'Top Gun: Maverick', 'top gun maverick', 2022, 361743, 'movie', '/AnxpYFkCarHnT6yrgVW8WmJ5SMk.jpg', '/AaV1YIdWKnjAIAOe8UUKBFm327v.jpg', 'بعد أكثر من ثلاثين عامًا من الخدمة كأحد أبرز طياري البحرية، وبعد تجنّبه الترقية في الرتب التي كانت ستُبقيه على الأرض، يجد "بيت ''مافريك'' ميتشل" نفسه يدرب مجموعة من خريجي "توب غان" على مهمة خاصة من نوع لم يسبق لأي طيار حي أن خاضها.', 'بعد أكثر من ثلاثين عامًا من الخدمة كأحد أبرز طياري البحرية، وبعد تجنّبه الترقية في الرتب التي كانت ستُبقيه على الأرض، يجد "بيت ''مافريك'' ميتشل" نفسه يدرب مجموعة من خريجي "توب غان" على مهمة خاصة من نوع لم يسبق لأي طيار حي أن خاضها.', 8.2, '["حركة", "دراما"]'::jsonb, '[{"name": "توم كروز", "character": "Capt. Pete ''Maverick'' Mitchell", "profile_path": "/3mShHjSQR7NXOVbdTu5rT2Qd0MN.jpg"}, {"name": "مايلز تيلر", "character": "Lt. Bradley ''Rooster'' Bradshaw", "profile_path": "/kDf3sW3USjEBDQ3Ua7lbwOfwty6.jpg"}, {"name": "جنيفر كونلي", "character": "Penny Benjamin", "profile_path": "/wdmcJagSRJ65AuJ4IUCzuHAdvgy.jpg"}, {"name": "بشير صلاح الدين", "character": "Wo-1. Bernie ''Hondo'' Coleman", "profile_path": "/ZL5MRzjd6kWkvQXqh5mgPY1CKP.jpg"}, {"name": "جون هام", "character": "Adm. Beau ''Cyclone'' Simpson", "profile_path": "/mrXE5fZbEDPc7BEE5G21J6qrwzi.jpg"}]'::jsonb, 131) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, r