INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (192, 'movie', 'السرعة والغضب ٩', 'F9', 'F9', 'fast furious 9', 2021, 385128, 'movie', '/eBRVLUoOqM0qVOgKAwjlqeaQ3za.jpg', '/xXHZeb1yhJvnSHPzZDqee0zfMb6.jpg', 'بعد اﻷحداث التي جرت في الجزء السابق The Fate Of the Furious، تقرر سايفر تلقي المساعدة من جاكوب، شقيق دوم الأصغر من أجل تنفيذ خطة انتقام من دوم وفريقه .', 'بعد اﻷحداث التي جرت في الجزء السابق The Fate Of the Furious، تقرر سايفر تلقي المساعدة من جاكوب، شقيق دوم الأصغر من أجل تنفيذ خطة انتقام من دوم وفريقه .', 7.0, '["حركة", "مغامرة", "جريمة"]'::jsonb, '[{"name": "فين ديزل", "character": "Dominic Toretto", "profile_path": "/nZdVry7lnUkE24PnXakok9okvL4.jpg"}, {"name": "Michelle Rodriguez", "character": "Letty Ortiz", "profile_path": "/wVcbrae4eRqGMFZz8Eh52Dl1biP.jpg"}, {"name": "Tyrese Gibson", "character": "Roman Pearce", "profile_path": "/jxoy4fbXNKFQtBdK73cLXEz3ufS.jpg"}, {"name": "Ludacris", "character": "Tej Parker", "profile_path": "/erkJijujhe48vhJ8iCEtVpNEeVn.jpg"}, {"name": "جون سينا", "character": "Jakob Toretto", "profile_path": "/rgB2eIOt7WyQjdgJCOuESdDlrjg.jpg"}]'::jsonb, 143) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
