INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (195, 'movie', 'المهمة المستحيلة: انحدار‎', 'Mission: Impossible - Fallout', 'Mission: Impossible - Fallout', 'mission impossible fallout', 2018, 353081, 'movie', '/lonGvu7rQ4D1WboRLsJ5Pzpy0dm.jpg', '/3IzR3VhZAyhxVnuRRUHFLkfK4hT.jpg', 'عندما تنتهي مهمة صندوق النقد الدولي بشكل سيئ، يواجه العالم عواقب وخيمة. كما يأخذ إيثان هانت على عاتقه أن يفي بالتوجيهات الاصلية، تبدأ وكالة المخابرات المركزية بالتشكيك في ولائه ودوافعه. يجد فريق صندوق النقد الدولي نفسه في سباق مع الزمن، يلاحقون من قبل المرتزقه بينما يحاولون منع كارثة عالمية.', 'عندما تنتهي مهمة صندوق النقد الدولي بشكل سيئ، يواجه العالم عواقب وخيمة. كما يأخذ إيثان هانت على عاتقه أن يفي بالتوجيهات الاصلية، تبدأ وكالة المخابرات المركزية بالتشكيك في ولائه ودوافعه. يجد فريق صندوق النقد الدولي نفسه في سباق مع الزمن، يلاحقون من قبل المرتزقه بينما يحاولون منع كارثة عالمية.', 7.4, '["حركة", "مغامرة"]'::jsonb, '[{"name": "توم كروز", "character": "Ethan Hunt", "profile_path": "/3mShHjSQR7NXOVbdTu5rT2Qd0MN.jpg"}, {"name": "هنري كافيل", "character": "August Walker", "profile_path": "/kN3A5oLgtKYAxa9lAkpsIGYKYVo.jpg"}, {"name": "فينج راميز", "character": "Luther Stickell", "profile_path": "/5pD48M3Mustr93gY5KLFDqF1fiv.jpg"}, {"name": "سايمون بيج", "character": "Benji Dunn", "profile_path": "/jw8bEEoTOithyNf0qxu4Zt1yaKp.jpg"}, {"name": "ريبيكا فيرغسون", "character": "Ilsa Faust", "profile_path": "/ty8ZPzaCBBlqIr5qzpOXI24iC8j.jpg"}]'::jsonb, 147) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating 