INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (196, 'movie', 'المتحولون: صعود الوحوش', 'Transformers: Rise of the Beasts', 'Transformers: Rise of the Beasts', 'transformers rise of the beasts', 2023, 667538, 'movie', '/gPbM0MK8CP8A174rmUwGsADNYKD.jpg', '/2vFuG6bWGyQUzYS9d69E5l85nIz.jpg', 'تدور احداث الفيلم في إطار من الحركة والخيال العلمي، تظهر مجموعة من الحيوانات الآلية، مما يطلق العنان لحربا كبرى يشارك بها كافة المتحولون.', 'تدور احداث الفيلم في إطار من الحركة والخيال العلمي، تظهر مجموعة من الحيوانات الآلية، مما يطلق العنان لحربا كبرى يشارك بها كافة المتحولون.', 7.2, '["خيال علمي", "مغامرة", "حركة"]'::jsonb, '[{"name": "أنتوني راموس", "character": "Noah Diaz", "profile_path": "/gCeRfH3aetIpZwKxe8Wl4ZYcQg5.jpg"}, {"name": "Dominique Fishback", "character": "Elena Wallace", "profile_path": "/zduC0PM7xKzFX4F7DH8CCt5gt6O.jpg"}, {"name": "بيتر كولين", "character": "Optimus Prime (voice)", "profile_path": "/9Snf4fBUkk5MrAjqtNtgZRJYJbj.jpg"}, {"name": "رون بيرلمان", "character": "Optimus Primal (voice)", "profile_path": "/nfky6J9ueey1gMdWMNU9k9YdfGP.jpg"}, {"name": "بيتر دينكلاج", "character": "Scourge (voice)", "profile_path": "/9CAd7wr8QZyIN0E7nm8v1B6WkGn.jpg"}]'::jsonb, 127) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
