INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (198, 'movie', 'الأسد الملك', 'The Lion King', 'The Lion King', 'the lion king', 1994, 8587, 'movie', '/l0DfggxJn89s0hOv8vVK6fa1QCX.jpg', '/q00H8EqULYSK74lgevMkhmGGLHn.jpg', 'أسد أمير صغير يطرد من أرضه من قبل عمه القاسي، الذي يدعي أنه كان السبب في موت والده. بينما يحكم العم المملكة بمخلب من حديد، يكبر الأمير خارج السافانا، ويعيش وفقًا لفلسفة "هاكونا ماتاتا"، أي أن تنسى الماضي ولا تقلق. لكن عندما يطارده ماضيه، يجب على الأمير الشاب أن يقرر مصيره: هل سيبقى منبوذاً أم يواجه مخاوفه ويصبح ما يحتاج إليه؟', 'أسد أمير صغير يطرد من أرضه من قبل عمه القاسي، الذي يدعي أنه كان السبب في موت والده. بينما يحكم العم المملكة بمخلب من حديد، يكبر الأمير خارج السافانا، ويعيش وفقًا لفلسفة "هاكونا ماتاتا"، أي أن تنسى الماضي ولا تقلق. لكن عندما يطارده ماضيه، يجب على الأمير الشاب أن يقرر مصيره: هل سيبقى منبوذاً أم يواجه مخاوفه ويصبح ما يحتاج إليه؟', 8.3, '["رسوم متحركة", "عائلي", "دراما"]'::jsonb, '[{"name": "ماثيو برودريك", "character": "Simba (voice)", "profile_path": "/papqFgpyroZJEqd7WvuNGN8ti2k.jpg"}, {"name": "Moira Kelly", "character": "Nala (voice)", "profile_path": "/oUuY9xERN1rpb7dPKchM5QQKEyt.jpg"}, {"name": "جيرمي أيرونز", "character": "Scar (voice)", "profile_path": "/w8Ct1q02Ht3sWdOSqfp3B85TzT.jpg"}, {"name": "Nathan Lane", "character": "Timon (voice)", "profile_path": "/jLPp3RoDhwOpLimKj3NhhBofPfT.jpg"}, {"name": "Ernie Sabella", "character": "Pumbaa (voice)", "profile_path": "/rALAxs5zUfQS3bZrEcns86gCHwI.jpg"}]'::jsonb, 89) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (199, 'movie', 'هاري بوتر وحجر الفيلسوف', 'Harry Potter and the Philosopher''s Stone', 'Harry Potter and the Philosopher''s Stone', 'harry potter and the sorcerer s stone', 2001, 671, 'movie', '/wWsjPFuYYewEcDlXizYGeUpbdEU.jpg', '/1XAC6RPT01UX9EQGy2JVn5c8pgy.jpg', 'يلتحق صبي يتيم بمدرسة للسحر، حيث يكتشف حقيقة نفسه وعائلته والشر الرهيب الذي يطارد عالم السحر.', 'يلتحق صبي يتيم بمدرسة للسحر، حيث يكتشف حقيقة نفسه وعائلته والشر الرهيب الذي يطارد عالم السحر.', 7.9, '["مغامرة", "فانتازيا"]'::jsonb, '[{"name": "دانيال رادكليف", "character": "Harry Potter", "profile_path": "/uUFfo8RANo7tuckB6AZAnESne55.jpg"}, {"name": "روبرت غرينت", "character": "Ron Weasley", "profile_path": "/q2KZZ0ltTEl7Sf8volNFV1JDEP4.jpg"}, {"name": "إيما واتسون", "character": "Hermione Granger", "profile_path": "/mf0OANvWYSzU1d8yggrhyw8IbIz.jpg"}, {"name": "ريتشارد هاريس", "character": "Albus Dumbledore", "profile_path": "/lCvcVMuxrg1f5A8OMqY9AqkkcZR.jpg"}, {"name": "توم فيلتون", "character": "Draco Malfoy", "profile_path": "/etmtUBzJ1i1XJTLS6MkotJFE1se.jpg"}]'::jsonb, 152) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (200, 'movie', 'الرجل العنكبوت: لا طريق للوطن', 'Spider-Man: No Way Home', 'Spider-Man: No Way Home', 'spider man no way home', 2021, 634649, 'movie', '/2maUA8Y4kxJ9UtLHYDhf9FSTd7u.jpg', '/uyrOU4BDm2kbVxFsMiDFIHDhc4d.jpg', 'بعد أن كُشِفَت هوية سبايدرمان، يطلب بيتر المساعدة من دكتور سترينج. وعندما تسوء الأمور بسبب تعويذة، يبدأ أعداء خطرون من عوالم أخرى بالظهور.', 'بعد أن كُشِفَت هوية سبايدرمان، يطلب بيتر المساعدة من دكتور سترينج. وعندما تسوء الأمور بسبب تعويذة، يبدأ أعداء خطرون من عوالم أخرى بالظهور.', 7.9, '["حركة", "مغامرة", "خيال علمي"]'::jsonb, '[{"name": "توم هولاند", "character": "Peter Parker / Spider-Man", "profile_path": "/xKBAaPIa1c7tzZD3Y0MhBLv4hPE.jpg"}, {"name": "زيندايا", "character": "MJ", "profile_path": "/1qup8tSt95HLbcy2c2xrx4iJNxv.jpg"}, {"name": "بيندكت كامبرباتش", "character": "Doctor Strange", "profile_path": "/wz3MRiMmoz6b5X3oSzMRC9nLxY1.jpg"}, {"name": "Jacob Batalon", "character": "Ned Leeds", "profile_path": "/53YhaL4xw4Sb1ssoHkeSSBaO29c.jpg"}, {"name": "جون فافرو", "character": "Happy Hogan", "profile_path": "/tnx7iMVydPQXGOoLsxXl84PXtbA.jpg"}]'::jsonb, 148) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (201, 'movie', 'جومانجي: مرحبًا بكم في الأدغال', 'Jumanji: Welcome to the Jungle', 'Jumanji: Welcome to the Jungle', 'jumanji welcome to the jungle', 2017, 353486, 'movie', '/pSgXKPU5h6U89ipF7HBYajvYt7j.jpg', '/zZKmEmRDc7ZjFucPm2UGNgDRlDc.jpg', 'أربعة طلاب بالمدرسة الثانوية يكتشفون لعبة قديمة تقحمهم داخل الغابة المرتبطة بإعدادات اللعبة ووحدة تحكمها، حرفيًا اللعبة تتجسد في اختياراتهم التي تقف عليها أنشطتهم، ليدركوا مع الوقت أن (جومانجي) ليست مجرد لعبة، بل تحدي للبقاء على قيد الحياة.', 'أربعة طلاب بالمدرسة الثانوية يكتشفون لعبة قديمة تقحمهم داخل الغابة المرتبطة بإعدادات اللعبة ووحدة تحكمها، حرفيًا اللعبة تتجسد في اختياراتهم التي تقف عليها أنشطتهم، ليدركوا مع الوقت أن (جومانجي) ليست مجرد لعبة، بل تحدي للبقاء على قيد الحياة.', 6.8, '["مغامرة", "كوميديا", "فانتازيا"]'::jsonb, '[{"name": "دوين جونسون", "character": "Spencer", "profile_path": "/5QApZVV8FUFlVxQpIK3Ew6cqotq.jpg"}, {"name": "كيفن هارت", "character": "Fridge", "profile_path": "/byiNydUlM6oP8diA7WMvYbNM7a1.jpg"}, {"name": "جاك بلاك", "character": "Bethany", "profile_path": "/59IhgCtiWI5yTfzPhsjzg7GjCjm.jpg"}, {"name": "Karen Gillan", "character": "Martha", "profile_path": "/qYx8CflXVq48nGKX1IJsDrAj0sT.jpg"}, {"name": "ريس داربي", "character": "Nigel", "profile_path": "/65Zy72IsUjopCkRt0s55Tk68GIm.jpg"}]'::jsonb, 119) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED