INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (202, 'movie', 'البحث عن نيمو', 'Finding Nemo', 'Finding Nemo', 'finding nemo', 2003, 12, 'movie', '/thqTmnNXS5sRAgqYsL6XoBb8AzI.jpg', '/eCynaAOgYYiw5yN5lBwz3IxqvaW.jpg', 'القصة عن سمكتين (من نوع كلون أو المهرج) تعيشان في المحيط الهادئ وبعد وضع الأنثى للبيوض تهاجم من قبل سمكة البينارا فتموت ويرعى الأب "مرهف" البيضة الوحيدة المتبقية ويسميها "نيمو" بناء لرغبة الأم "مرجانة". يحاول "مرهف" حماية ابنه من الخطر بهوس زائد عن الحد فيتمرد نيمو ويذهب ناحية قارب لقوم بتبين شجاعتة لأبوه ويقع في يد غواص ياخذه إلى أستراليا في سيدنى فيبدأ مرهف رحلة عبر المحيط لإيجاده مع سمكة تعاني من فقدان ذاكرة مؤقت! اسمها "دوري" في حين يحاول الابن الخروج من حوض الأسماك الذي وضعه فيه دكتور أسنان وبمساعدة بعض الأصدقاء لنيمو في الخروج من الحوض وبالفعل ينجحو ويعود الابن لأبوه.', 'القصة عن سمكتين (من نوع كلون أو المهرج) تعيشان في المحيط الهادئ وبعد وضع الأنثى للبيوض تهاجم من قبل سمكة البينارا فتموت ويرعى الأب "مرهف" البيضة الوحيدة المتبقية ويسميها "نيمو" بناء لرغبة الأم "مرجانة". يحاول "مرهف" حماية ابنه من الخطر بهوس زائد عن الحد فيتمرد نيمو ويذهب ناحية قارب لقوم بتبين شجاعتة لأبوه ويقع في يد غواص ياخذه إلى أستراليا في سيدنى فيبدأ مرهف رحلة عبر المحيط لإيجاده مع سمكة تعاني من فقدان ذاكرة مؤقت! اسمها "دوري" في حين يحاول الابن الخروج من حوض الأسماك الذي وضعه فيه دكتور أسنان وبمساعدة بعض الأصدقاء لنيمو في الخروج من الحوض وبالفعل ينجحو ويعود الابن لأبوه.', 7.8, '["رسوم متحركة", "عائلي", "مغامرة"]'::jsonb, '[{"name": "Albert Brooks", "character": "Marlin (voice)", "profile_path": "/8iDSGu5l93N7benjf6b3AysBore.jpg"}, {"name": "ألين دي جينيريس", "character": "Dory (voice)", "profile_path": "/z8IEEid4z63CBlJtxrTKEfsW7NA.jpg"}, {"name": "Alexander Gould", "character": "Nemo (voice)", "profile_path": "/zzfj8LHhSiRntnyThvOBirEEmII.jpg"}, {"name": "Willem Dafoe", "character": "Gill (voice)", "profile_path": "/ui8e4sgZAwMPi3hzEO53jyBJF9B.jpg"}, {"name": "Geoffrey Rush", "character": "Nigel (voice)", "profile_path": "/npXFjaFQzBNroCEPllGPTZ5IisA.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (203, 'movie', 'أفاتار: أسلوب المياه', 'Avatar: The Way of Water', 'Avatar: The Way of Water', 'avatar the way of water', 2022, 76600, 'movie', '/cBajHfu0jK6P0DRr5iG17oH19Bb.jpg', '/kJsPVzdyBrYHLomuNv5SJDXUQ2f.jpg', 'يحاول كل من جيك سولي ونيتيري أن يقوما بكل ما في وسعهما كي يظل معًا، ولكن يتحتم عليهما مفارقة منزلهما واكتشاف أرجاء شتى على كوكب باندورا لينهيا ما بدآه.', 'يحاول كل من جيك سولي ونيتيري أن يقوما بكل ما في وسعهما كي يظل معًا، ولكن يتحتم عليهما مفارقة منزلهما واكتشاف أرجاء شتى على كوكب باندورا لينهيا ما بدآه.', 7.6, '["حركة", "مغامرة", "خيال علمي"]'::jsonb, '[{"name": "سام ورذينجتن", "character": "Jake Sully", "profile_path": "/mflBcox36s9ZPbsZPVOuhf6axaJ.jpg"}, {"name": "زوي سالدانا", "character": "Neytiri", "profile_path": "/vQBwmsSOAd0JDaEcZ5p43J9xzsY.jpg"}, {"name": "Sigourney Weaver", "character": "Kiri", "profile_path": "/wTSnfktNBLd6kwQxgvkqYw6vEon.jpg"}, {"name": "Stephen Lang", "character": "Colonel Miles Quaritch", "profile_path": "/gnO5VfkDgA2fsHweD0622LUY3Hu.jpg"}, {"name": "كيت وينسليت", "character": "Ronal", "profile_path": "/6qNnMsKtKz9si5rabpUEG85UfHp.jpg"}]'::jsonb, 192) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (204, 'movie', 'اليتا: ملاك المعركة', 'Alita: Battle Angel', 'Alita: Battle Angel', 'alita battle angel', 2019, 399579, 'movie', '/if0yU7MrnWbC9OZth3nxbEBOWbt.jpg', '/jXDselREPq8TOVGM4dzBBUM7xVk.jpg', 'ملاك يسقط. محارب يرتفع.INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (206, 'series', 'حارة القبة', 'حارة القبة', 'حارة القبة', 'مسلسل حاره القبه', 2021, 122865, 'tv', '/4YvZNdsH1b3uXgcHX95RiEwMP2.jpg', '/doaL6RPb6f5LOUi0MGQ1ExUjBsw.jpg', 'تدور الأحداث في إطار الدراما الممزوجة بالتشويق، حول فترة (السفربرلك) والحكم العثماني لبلاد الشام في القرن التاسع عشر، وتسليط الضوء على أهل مدينة الشام القديمة ومعاناتهم من الفقر والجوع والتشرد', 'تدور الأحداث في إطار الدراما الممزوجة بالتشويق، حول فترة (السفربرلك) والحكم العثماني لبلاد الشام في القرن التاسع عشر، وتسليط الضوء على أهل مدينة الشام القديمة ومعاناتهم من الفقر والجوع والتشرد', NULL, '["دراما"]'::jsonb, '[{"name": "عباس النوري", "character": "أبو العز", "profile_path": "/7DsjxullF8RvtGW3AIT7ejVkyoG.jpg"}, {"name": "Sulafa Memar", "character": "أم العز", "profile_path": "/ufo1sRlNI287q0y3CNEM34cTgHQ.jpg"}, {"name": "خالد القيش", "character": "غازي بيك", "profile_path": "/mb5pzHCFhN3vgVFr1g7AzyCQJlX.jpg"}, {"name": "فادي صبيح", "character": "طبنجة", "profile_path": "/sT8eh6gx7DHa4RGuC69HV50YMHW.jpg"}, {"name": "نادين تحسين بيك", "character": "أم سليم", "profile_path": "/vUwsBAExr8vimdS7l95YyB0drOe.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_