INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (207, 'series', 'جعفر العمدة', 'جعفر العمدة', 'جعفر العمدة', 'مسلسل جعفر العمده', 2023, 218739, 'tv', '/hqaW4C5AFeBLsuJ2NLzglwvvOyD.jpg', '/evUOX9GnscnDy3WxhzAKv9Rlrcp.jpg', 'عندما تطلب امرأة اسمها عايدة قرضا كبيرا من رجل الأعمال الثري جعفر العمدة، يضع عليها شرطا للموافقة: أن تكون زوجته لمدة 400 يوم.', 'عندما تطلب امرأة اسمها عايدة قرضا كبيرا من رجل الأعمال الثري جعفر العمدة، يضع عليها شرطا للموافقة: أن تكون زوجته لمدة 400 يوم.', 6.9, '["كوميديا", "حركة ومغامرة", "دراما"]'::jsonb, '[{"name": "محمد رمضان", "character": "جعفر العمده", "profile_path": "/2UlMUlVJqW59dvXQ0NOQPPnlPWc.jpg"}, {"name": "هالة صدقي", "character": "الملكه صفصف", "profile_path": "/ymiqUiUibhbed7L1i5pNxTcTwBQ.jpg"}, {"name": "أحمد داش", "character": "سيف", "profile_path": "/245ZMf36BbsVLX0rdgBA4FxUTnn.jpg"}, {"name": "إيمان العاصي", "character": "دلال", "profile_path": "/raeuNnSkVgDJ1lbbYFeWVcIqSm9.jpg"}, {"name": "زينة", "character": "عايده", "profile_path": "/rzViYmGwblIdvKbIqhr1t56MSO9.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (208, 'series', 'الاختيار', 'الاختيار', 'الاختيار', 'مسلسل الاختيار', 2020, 102045, 'tv', '/6o6qYyegwuTXABK7bqSD32aXzYy.jpg', '/xJwRWUsATroJvuJXiaMJ038Zf8l.jpg', 'يتناول المسلسل حياة أحمد صابر المنسي قائد الكتيبة 103 صاعقة، الذي استشهد في كمين مربع البرث بمدينة رفح المصرية عام 2017 أثناء التصدي لهجوم إرهابي في سيناء.', 'يتناول المسلسل حياة أحمد صابر المنسي قائد الكتيبة 103 صاعقة، الذي استشهد في كمين مربع البرث بمدينة رفح المصرية عام 2017 أثناء التصدي لهجوم إرهابي في سيناء.', 6.7, '["دراما", "حرب وسياسة", "حركة ومغامرة"]'::jsonb, '[{"name": "ياسر جلال", "character": "الفريق أول عبد الفتاح السيسي", "profile_path": "/eKv8dyxnnBtUofwzq4VjuvwAoEq.jpg"}, {"name": "أحمد السقا", "character": "مصطفى", "profile_path": "/4UhDFNeJ7UVjcyNfMINdHLSqA7q.jpg"}, {"name": "أحمد عز", "character": "مروان العدوي", "profile_path": "/mgQhox7AbzVsQ8xeTZvkK5Gvkd4.jpg"}, {"name": "كريم عبدالعزيز", "character": "", "profile_path": "/j1RlG5Oaq2UvUhUhllwteES3yvb.jpg"}, {"name": "Mohamed Hamdy", "character": "خالد", "profile_path": "/cvhBBp5ezTeKzeNUQUSiX9eDCec.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (209, 'series', 'الكبير أوي', 'الكبير أوي', 'الكبير أوي', 'مسلسل الكبير اوي', 2010, 52698, 'tv', '/vZ6mCFQazwMxZ1uOm2OmGX9tA5e.jpg', '/wZsD7yIXU4f7IORXEv2lb5MKao0.jpg', 'بعد وفاة الكبير آوي تدور أحداث المسلسل حول مواقف كوميدية بين أبنائه واختلاف ثقافتهم وعاداتهم وتقاليدهم', 'بعد وفاة الكبير آوي تدور أحداث المسلسل حول مواقف كوميدية بين أبنائه واختلاف ثقافتهم وعاداتهم وتقاليدهم', 7.0, '["كوميديا", "عائلي", "دراما"]'::jsonb, '[{"name": "أحمد مكي", "character": "Al Kabeer, Johnny and Hazalqoum", "profile_path": "/9uK9EhWwhB2mepg73CB3wN64DlU.jpg"}, {"name": "محمد سلام", "character": "هجرس", "profile_path": "/pnOF9xHx4LbEHsRunfyRnfV1uDc.jpg"}, {"name": "مصطفى غريب", "character": "", "profile_path": "/glzcFTExMpbS6Jnfwtmkv4x2hDR.jpg"}, {"name": "رحمة أحمد فرج", "character": "مربوحة", "profile_path": "/fGXxmZ2BVf2B6nbBAurJCaalCRU.jpg"}, {"name": "حاتم صلاح", "character": "", "profile_path": "/4nK9HwqU6GuMWKXPJ6DAipBDdKX.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (212, 'series', 'ولد الغلابة', 'ولد الغلابة', 'ولد الغلابة', 'مسلسل ولد الغلابه', 2019, 88930, 'tv', '/dE7H9H1fKzWGgiJ7ObFByjPGBLi.jpg', '/yM4TlpqHW3dTGNDXCCgTwp5VpUG.jpg', 'رجل صعيدي يُدعى (عيسى) يعاني الفقر، يضطر للعمل في مهنتين بسبب الظروف المادية التي يتعرض لها خلال الأحداث، الأولى مدرس بإحدى المدارس الحكومية، والثانية يعمل ليلاً سائق لدى (ضاحي)، ومع تصاعد الأحداث يُجبر على فعل أشياء تتعارض مع مبادئه، وتشتعل الحرب بينه وبين (ضاحي).', 'رجل صعيدي يُدعى (عيسى) يعاني الفقر، يضطر للعمل في مهنتين بسبب الظروف المادية التي يتعرض لها خلال الأحداث، الأولى مدرس بإحدى المدارس الحكومية، والثانية يعمل ليلاً سائق لدى (ضاحي)، ومع تصاعد الأحداث يُجبر على فعل أشياء تتعارض مع مبادئه، وتشتعل الحرب بينه وبين (ضاحي).', 5.0, '["دراما"]'::jsonb, '[{"name": "أحمد السقا", "character": "Issa", "profile_path": "/4UhDFNeJ7UVjcyNfMINdHLSqA7q.jpg"}, {"name": "مي عمر", "character": "Farah", "profile_path": "/52e4H8J66b2jMBSt9SrlQgisirB.jpg"}, {"name": "هبة مجدي", "character": "", "profile_path": "/vNF2s8blamOHDhDk3uYpGaVgWTD.jpg"}, {"name": "محمد ممدوح", "character": "Dahi", "profile_path": "/wH6JHGej3ISZr1vQZxOGmlHHErH.jpg"}, {"name": "إدوارد", "character": "", "profile_path": "/4zMVIGh9IQoDiTWvEy9i2lGYCZA.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
