INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (215, 'series', 'مسرح مصر', 'مسرح مصر', 'مسرح مصر', 'مسرح مصر', 2014, 78619, 'tv', '/dqREepBp8WvCpz6kHBJDYiivkMG.jpg', '/u61WBJhGsmpJhJXwbbDtiWPtSXw.jpg', 'مجموعة من المسرحيات التي تُقدم على شكل حلقات، لكل حلقة اسم ومضمون مختلف في إطار كوميدي ترفيهي ساخر.', 'مجموعة من المسرحيات التي تُقدم على شكل حلقات، لكل حلقة اسم ومضمون مختلف في إطار كوميدي ترفيهي ساخر.', 8.0, '["كوميديا"]'::jsonb, '[{"name": "أشرف عبدالباقي", "character": "", "profile_path": "/5Kazsywa6e7bftoQcJEGXCLJHRZ.jpg"}, {"name": "علي الربيع", "character": "", "profile_path": "/uJHx2Gsa46WMGXFWZEIivKGHZnH.jpg"}, {"name": "محمد عبد الرحمن", "character": "", "profile_path": "/cmvZyoAQ5a6YrMJ5HRNbK6N5nUU.jpg"}, {"name": "مصطفى خاطر", "character": "", "profile_path": "/pj5b1XP1iM8BaCKb6QOdZpAD8xW.jpg"}, {"name": "حمدي الميرغني", "character": "", "profile_path": "/sJg1gQuFiGJ2dU7QabKlEpe1rGC.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (216, 'series', 'نسل الأغراب', 'نسل الأغراب', 'نسل الأغراب', 'مسلسل نسل الاغراب', 2021, 121486, 'tv', '/tz4gBrbcmbKiEHreEy4WfeCxhJT.jpg', '/qzunkgKzsd2R2xXwhpo3hr21v5K.jpg', 'يتناول العمل في إطار درامي اجتماعي قصة من قصص المجتمع الصعيدي المصري، فبعد اتهامه بالقتل وقضاء فترة عقوبة طويلة بالسجن، يخرج فيجد صديقه قد تزوج من امرأته ونسب ابنه إليه، فيقرر الانتقام منه.', 'يتناول العمل في إطار درامي اجتماعي قصة من قصص المجتمع الصعيدي المصري، فبعد اتهامه بالقتل وقضاء فترة عقوبة طويلة بالسجن، يخرج فيجد صديقه قد تزوج من امرأته ونسب ابنه إليه، فيقرر الانتقام منه.', 6.0, '["دراما"]'::jsonb, '[{"name": "أحمد السقا", "character": "Assaf El-Ghareeb", "profile_path": "/4UhDFNeJ7UVjcyNfMINdHLSqA7q.jpg"}, {"name": "أمير كرارة", "character": "Ghofran El-Ghareeb", "profile_path": "/cfdecL9iTJfhFN2UNNLRVQPr5e.jpg"}, {"name": "مي عمر", "character": "Galila El-Ghareeb", "profile_path": "/52e4H8J66b2jMBSt9SrlQgisirB.jpg"}, {"name": "دياب", "character": "Ali El-Ghareeb", "profile_path": "/9iQyinwVufcPXPAeDxIE8eaaDIr.jpg"}, {"name": "إدوارد", "character": "Hasib El-Ghareeb", "profile_path": "/4zMVIGh9IQoDiTWvEy9i2lGYCZA.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
