INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (223, 'series', 'خريف القلب', 'خريف القلب', 'خريف القلب', 'مسلسل خريف القلب', 2024, 251691, 'tv', '/nsudkqxrw1wK0ZRRytPVKQvQzoD.jpg', '/bxE1p8mFcwPfq88U0aL3pJSpPqD.jpg', 'في إطار درامي، ينكشف سر قديم إثر حادث سير مروع، بعد أن صدم رجل الأعمال (راشد) العاملة المكافحة (نهلة)، حيث تم تبديل ابنتيهما قبل سبعة عشر عاما لحظة ولادة الطفلتين بالمستشفى.', 'في إطار درامي، ينكشف سر قديم إثر حادث سير مروع، بعد أن صدم رجل الأعمال (راشد) العاملة المكافحة (نهلة)، حيث تم تبديل ابنتيهما قبل سبعة عشر عاما لحظة ولادة الطفلتين بالمستشفى.', 4.5, '["دراما", "عائلي"]'::jsonb, '[{"name": "عبدالمحسن النمر", "character": "راشد", "profile_path": "/vfHsm67Ow2p86IPhPe5P8hhYdzw.jpg"}, {"name": "إلهام علي", "character": "نهلة", "profile_path": "/hA4lnJug2lmzbokUgqDO9ZuV9Ra.jpg"}, {"name": "إبراهيم الحربي", "character": "راجح", "profile_path": "/d8HpMIl32tmglNHvMTQZZoEqAr7.jpg"}, {"name": "مروه محمد", "character": "ناهد", "profile_path": "/jPL2i6OZZ547zT0J869OXyq6SFt.jpg"}, {"name": "لبنى عبدالعزيز", "character": "فرح", "profile_path": "/khio3GlGNpHGG0eg8x4Em49ukss.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (233, 'movie', 'أوبنهايمر', 'Oppenheimer', 'Oppenheimer', 'oppenheimer', 2023, 872585, 'movie', '/miFcvcpi7L5QVs5o29hlreSPzVi.jpg', '/neeNHeXjMF5fXoCJRsOmkNGC7q.jpg', 'فلم يحكي السيرة الذاتية وقصة العالم الأمريكي روبرت أوبنهايمر ودوره في تطوير القنبلة الذرية، وكيف غير مشروع مانهاتن من كل شيء في العالم.', 'فلم يحكي السيرة الذاتية وقصة العالم الأمريكي روبرت أوبنهايمر ودوره في تطوير القنبلة الذرية، وكيف غير مشروع مانهاتن من كل شيء في العالم.', 8.0, '["دراما", "تاريخ"]'::jsonb, '[{"name": "كيليان مورفي", "character": "J. Robert Oppenheimer", "profile_path": "/2lKs67r7FI4bPu0AXxMUJZxmUXn.jpg"}, {"name": "إيميلي بلنت", "character": "Kitty Oppenheimer", "profile_path": "/5nCSG5TL1bP1geD8aaBfaLnLLCD.jpg"}, {"name": "مات ديمون", "character": "Leslie Groves", "profile_path": "/aCvBXTAR9B1qRjIRzMBYhhbm1fR.jpg"}, {"name": "روبرت داوني جونيور", "character": "Lewis Strauss", "profile_path": "/5qHNjhtjMD4YWH3UP0rm4tKwxCL.jpg"}, {"name": "فلورنس بيو", "character": "Jean Tatlock", "profile_path": "/1Uvfh7xL4U2evkhs0M3C7BbBYFf.jpg"}]'::jsonb, 181) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
