INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (255, 'series', 'لن أعيش في جلباب أبي', 'لن أعيش في جلباب أبي', 'لن أعيش في جلباب أبي', 'مسلسل لن اعيش في جلباب ابي', 1996, 52697, 'tv', '/9hN6TAz3WOYFbWQ1Qa6kVFcDw81.jpg', '/nUtD7bcHq8fVbyEPjYvFtfx33bt.jpg', 'تدور أحداث المسلسل حول قصة الصعود من القاع إلى القمة لعبد الغفور البرعي (نور الشريف) بداية من وكالة الحاج إبراهيم سردينة (عبد الرحمن أبو زهرة) إلى أن يصبح صاحب عمل خاص يجني منه ثروة، أثناء ذلك يكون قد أعجب بفاطمة (عبلة كامل) بائعة الكشري، التي تبادله الإعجاب، تمر الأيام ويتزوج من فاطمة وينجب ولده عبد الوهاب (محمد رياض)، وأربع فتيات (سنية، وبهيرة، ونفيسة، ونظيرة)، وعلى الرغم من توافر مقومات السعادة في حياة عبد الغفور البرعي، فإنه عانى من ابتعاد ولده الوحيد عنه، وإصرار عبد الوهاب على بناء عالم خاص جداً بعيداً عن والده ونفوذه.', 'تدور أحداث المسلسل حول قصة الصعود من القاع إلى القمة لعبد الغفور البرعي (نور الشريف) بداية من وكالة الحاج إبراهيم سردينة (عبد الرحمن أبو زهرة) إلى أن يصبح صاحب عمل خاص يجني منه ثروة، أثناء ذلك يكون قد أعجب بفاطمة (عبلة كامل) بائعة الكشري، التي تبادله الإعجاب، تمر الأيام ويتزوج من فاطمة وينجب ولده عبد الوهاب (محمد رياض)، وأربع فتيات (سنية، وبهيرة، ونفيسة، ونظيرة)، وعلى الرغم من توافر مقومات السعادة في حياة عبد الغفور البرعي، فإنه عانى من ابتعاد ولده الوحيد عنه، وإصرار عبد الوهاب على بناء عالم خاص جداً بعيداً عن والده ونفوذه.', 8.6, '["دراما"]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (259, 'series', 'تحت الوصاية', 'تحت الوصاية', 'تحت الوصاية', 'مسلسل تحت الوصايه', 2023, 220993, 'tv', '/ty7omzefDbQvQDl9ic69TEloQTL.jpg', '/mwsOLsPY39rNRm2KjmwEgLA92CK.jpg', 'بعد وفاة زوجها، تكافح أم لولدين جاهدة في مواجهة مجتمع ذكوري بهدف الحفاظ على حضانة أولادها، حتى لو كان ذلك يحتم عليها أن تصبح صيادة سمك', 'بعد وفاة زوجها، تكافح أم لولدين جاهدة في مواجهة مجتمع ذكوري بهدف الحفاظ على حضانة أولادها، حتى لو كان ذلك يحتم عليها أن تصبح صيادة سمك', 7.1, '["دراما"]'::jsonb, '[{"name": "منى زكي", "character": "Hanan", "profile_path": "/qXImbMkrqYpWg2jEerb1RDPr3hN.jpg"}, {"name": "دياب", "character": "Saleh Atia", "profile_path": "/9iQyinwVufcPXPAeDxIE8eaaDIr.jpg"}, {"name": "عمر شريف", "character": "Yaseen", "profile_path": "/iSiOazDKO0tIChVnn79oJJGYTHp.jpg"}, {"name": "نهى عابدين", "character": "Mona", "profile_path": "/c1lw85Nj891RTEpdewaZElNBcjW.jpg"}, {"name": "مها نصار", "character": "Sana''", "profile_path": "/dpYRToSEhTnstpegQxaMWDfjaJB.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
