INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (280, 'movie', 'كثيب: القسم الثاني', 'Dune: Part Two', 'Dune: Part Two', 'dune part two', 2024, 693134, 'movie', '/3fZc7kZ09aZB0rtYBVK2hPojZec.jpg', '/eZ239CUp1d6OryZEBPnO2n87gMG.jpg', 'تابع الرحلة الأسطورية لبول أتريدس وهو يتحد مع تشاني وفريمن أثناء وجوده في طريق حربي للانتقام من المتآمرين الذين دمروا عائلته. في مواجهة الاختيار بين حب حياته ومصير الكون المعروف ، يسعى بولس إلى منع مستقبل رهيب لا يستطيع التنبؤ به سواه.', 'تابع الرحلة الأسطورية لبول أتريدس وهو يتحد مع تشاني وفريمن أثناء وجوده في طريق حربي للانتقام من المتآمرين الذين دمروا عائلته. في مواجهة الاختيار بين حب حياته ومصير الكون المعروف ، يسعى بولس إلى منع مستقبل رهيب لا يستطيع التنبؤ به سواه.', 8.1, '["خيال علمي", "مغامرة"]'::jsonb, '[{"name": "تيموثي شالاماي", "character": "Paul Atreides", "profile_path": "/dFxpwRpmzpVfP1zjluH68DeQhyj.jpg"}, {"name": "زيندايا", "character": "Chani", "profile_path": "/1qup8tSt95HLbcy2c2xrx4iJNxv.jpg"}, {"name": "ريبيكا فيرغسون", "character": "Jessica", "profile_path": "/ty8ZPzaCBBlqIr5qzpOXI24iC8j.jpg"}, {"name": "خافيير باردم", "character": "Stilgar", "profile_path": "/zfRID0jx8DKBluPGU9xtk9sZWUt.jpg"}, {"name": "جوش برولين", "character": "Gurney Halleck", "profile_path": "/sX2etBbIkxRaCsATyw5ZpOVMPTD.jpg"}]'::jsonb, 167) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (281, 'movie', 'باربي', 'Barbie', 'Barbie', 'barbie', 2023, 346698, 'movie', '/e8Lng7AmGnCYLq7XPQnI9prRF3S.jpg', '/1esAE8sLJRWWFsLLeh5r3g2WanI.jpg', 'تعيش دمية في مدينة باربيلاند تُدعى باربي، وحينما تُطرد من المدينة بسبب عدم كونها مثالية، تنطلق باربي في مغامرة بالعالم الحقيقي على أمل إثبات جدارتها والعودة إلى وطنها.', 'تعيش دمية في مدينة باربيلاند تُدعى باربي، وحينما تُطرد من المدينة بسبب عدم كونها مثالية، تنطلق باربي في مغامرة بالعالم الحقيقي على أمل إثبات جدارتها والعودة إلى وطنها.', 6.9, '["كوميديا", "مغامرة", "فانتازيا"]'::jsonb, '[{"name": "مارجو روبي", "character": "Barbie", "profile_path": "/euDPyqLnuwaWMHajcU3oZ9uZezR.jpg"}, {"name": "رايان غوسلينغ", "character": "Ken", "profile_path": "/lyUyVARQKhGxaxy0FbPJCQRpiaW.jpg"}, {"name": "أمريكا فيرارا", "character": "Gloria", "profile_path": "/7q9uUWnaIjveX8DTU2lcA7mA3dp.jpg"}, {"name": "اريانا غرينبلات", "character": "Sasha", "profile_path": "/lp7lzzBE7EYTMvSb4foN5LyZUkP.jpg"}, {"name": "إيسا راي", "character": "Barbie", "profile_path": "/uFjimuDgBv8kckApr19t8DykxPH.jpg"}]'::jsonb, 114) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (283, 'movie', 'المجالد 2', 'Gladiator II', 'Gladiator II', 'gladiator ii', 2024, 558449, 'movie', '/wCfFdowd6U7BdMRKPpUhTM0E9vQ.jpg', '/tOqIwliWMovSIZ9DyvHcHI7p2im.jpg', 'تدور أحداث العمل حول (لوشيوس)، ابن حبيبة (ماكسيموس) والتي تُعرف باسم (لوسيا)، ذلك في أعقاب وفاة (ماكسيموس) وانقلاب موازين القوة.', 'تدور أحداث العمل حول (لوشيوس)، ابن حبيبة (ماكسيموس) والتي تُعرف باسم (لوسيا)، ذلك في أعقاب وفاة (ماكسيموس) وانقلاب موازين القوة.', 6.6, '["حركة", "مغامرة", "دراما"]'::jsonb, '[{"name": "بول ميسكال", "character": "Lucius", "profile_path": "/vrzZ41TGNAFgfmZjC2sOJySzBLd.jpg"}, {"name": "دنزل واشنطن", "character": "Macrinus", "profile_path": "/jj2Gcobpopokal0YstuCQW0ldJ4.jpg"}, {"name": "بيدرو باسكال", "character": "General Acacius", "profile_path": "/oKcMbVn0NJTNzQt0ClKKvVXkm60.jpg"}, {"name": "كوني نيلسن", "character": "Lucilla", "profile_path": "/gSQ3O3PJ6ly6nT63joOtfZyscFP.jpg"}, {"name": "Joseph Quinn", "character": "Emperor Geta", "profile_path": "/zshhuioZaH8S5ZKdMcojzWi1ntl.jpg"}]'::jsonb, 148) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (300, 'movie', 'عسل أسود', 'عسل أسود', 'عسل أسود', 'عسل اسود', 2010, 84250, 'movie', '/7IRqRKyPth00lITljHES4zAsdyk.jpg', '/fiXkW2f7HzkjrelKnkqwtpeROVU.jpg', 'بعد غياب طويل، يعود شاب مصري يحمل الجنسية الأمريكية إلى وطنه مصر، وهو يحمل في قلبه الكثير من الحنين والصور الجميلة عن بلده الأم. لكن زيارته تكشف له واقعًا مختلفًا عمّا تخيله، وتضعه في مواقف تختبر فهمه للهوية والانتماء.', 'بعد غياب طويل، يعود شاب مصري يحمل الجنسية الأمريكية إلى وطنه مصر، وهو يحمل في قلبه الكثير من الحنين والصور الجميلة عن بلده الأم. لكن زيارته تكشف له واقعًا مختلفًا عمّا تخيله، وتضعه في مواقف تختبر فهمه للهوية والانتماء.', 7.5, '["كوميديا", "دراما"]'::jsonb, '[{"name": "أحمد حلمي", "character": "مصري", "profile_path": "/xVhX7ia3ptI43V65Os90gbfgxAe.jpg"}, {"name": "إدوارد", "character": "سعيد", "profile_path": "/4zMVIGh9IQoDiTWvEy9i2lGYCZA.jpg"}, {"name": "لطفي لبيب", "character": "راضي", "profile_path": "/guGZ0Xv4csBj10ipPlQAgf0yq6o.jpg"}, {"name": "إنعام سالوسة", "character": "أم سعيد", "profile_path": "/bbvYQgJBUXDOUkkoZ609kgFD9wD.jpg"}, {"name": "طارق الأمير", "character": "منصف", "profile_path": "/jj6DaKgiRZWdgpWVerr0IAfrEQY.jpg"}]'::jsonb, 120) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
