INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (349, 'series', 'أحلى صوت', 'The Voice أحلى صوت', 'The Voice أحلى صوت', 'the voice احلي صوت', 2012, 79354, 'tv', '/pWZLo2LJa6Evf4sIghPQZ24vt6i.jpg', '/4ymYfH8PL5ztov7vc5k5QePfsh9.jpg', 'برنامج مواهب يبحث عن الأصوات الغنائية الإستثنائية في العالم العربي، تتكفل لجنة مؤلفة من أربعة مدربين صقل المواهب وتدريبها، للكشف عن الصوت الأحلى بينها.', 'برنامج مواهب يبحث عن الأصوات الغنائية الإستثنائية في العالم العربي، تتكفل لجنة مؤلفة من أربعة مدربين صقل المواهب وتدريبها، للكشف عن الصوت الأحلى بينها.', NULL, '["واقع"]'::jsonb, '[{"name": "Rahma Riyad", "character": "", "profile_path": "/tw0rpo7GCI5pnS0J4lI7vgY8k1e.jpg"}, {"name": "أحمد سعد", "character": "", "profile_path": "/nAaZ6l8oJSvKy3DFbc8C5X2ZKve.jpg"}, {"name": "Nassif Zeytoun", "character": "", "profile_path": "/9Cp5QQCLHbVyzgk6epcNj67W9qs.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (350, 'series', 'شارع الأعشى', 'شارع الأعشى', 'شارع الأعشى', 'مسلسل شارع الاعشي', 2025, 283620, 'tv', '/rAbN8corGlIr1Y496e4a1mF1hUN.jpg', '/jvrBmMuH98ydy3UopFB2t485E6K.jpg', 'يستعرض المسلسل التحولات الاجتماعية التي شهدتها السعودية في السبعينيات وقضايا الحب والصراعات العائلية والأحلام والطموحات التي تصطدم بالعادات والتقاليد.', 'يستعرض المسلسل التحولات الاجتماعية التي شهدتها السعودية في السبعينيات وقضايا الحب والصراعات العائلية والأحلام والطموحات التي تصطدم بالعادات والتقاليد.', 9.0, '["عائلي"]'::jsonb, '[{"name": "إلهام علي", "character": "وضحى", "profile_path": "/hA4lnJug2lmzbokUgqDO9ZuV9Ra.jpg"}, {"name": "خالد صقر", "character": "أبو إبراهيم", "profile_path": "/7tZXXnEOGQEQDSIlb5xohiPzbWp.jpg"}, {"name": "عائشة كاي", "character": "أم إبراهيم", "profile_path": "/rDMdK8Vjl7ZQzepxFLVX7vN7b5F.jpg"}, {"name": "الاء سالم", "character": "عواطف", "profile_path": "/lOMXUrOzsZ0WJcup1Y2kVBjidEI.jpg"}, {"name": "ناصر الدوسري", "character": "خالد", "profile_path": "/dRRD3DZvgOjWW9krqpX75unIU18.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (351, 'movie', 'البدلة', 'البدلة', 'البدلة', 'فيلم البدله', 2018, 532108, 'movie', '/qYmdApNCqwDN6Q09NQeJBQPUAFs.jpg', '/oKXLdkWsva7SoXF7KjKwn6weBdM.jpg', 'تدور القصة حول حمادة، ووليد اللذين ولدا في نفس اليوم فاشلين في الحياة، يقرران الذهاب إلى حفلة تنكرية، ويتنكران في زي رجال الشرطة لمقابلة زملائهم القدامى، الأمر الذي يجعل الجميع يعتقد بأنهما شرطيين حقيقيين، وتقع لهما العديد من الأحداث والمشاكل.', 'تدور القصة حول حمادة، ووليد اللذين ولدا في نفس اليوم فاشلين في الحياة، يقرران الذهاب إلى حفلة تنكرية، ويتنكران في زي رجال الشرطة لمقابلة زملائهم القدامى، الأمر الذي يجعل الجميع يعتقد بأنهما شرطيين حقيقيين، وتقع لهما العديد من الأحداث والمشاكل.', 5.9, '["حركة", "كوميديا", "دراما"]'::jsonb, '[{"name": "تامر حسني", "character": "Walid Gamal", "profile_path": "/2YGi3xoFD3EKXUKprTkRXVRHquH.jpg"}, {"name": "أكرم حسني", "character": "Hamadah Ainel-Aql", "profile_path": "/tZGdekospdRJ9XZ25hQ7W6RwB9M.jpg"}, {"name": "ماجد المصري", "character": "Markos", "profile_path": "/hCFDKcAiotPNs5cvlhHXgFS6dX0.jpg"}, {"name": "أمينة خليل", "character": "Rim", "profile_path": "/eHJBpaypMN52VSIF84r5MgvC0Mr.jpg"}, {"name": "Mahmoud El-Bezzawy", "character": "Chief prosecutor", "profile_path": null}]'::jsonb, 97) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
