INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (355, 'series', 'الخائن', 'Sadakatsiz', 'Sadakatsiz', 'مسلسل الخائن', 2020, 110562, 'tv', '/vxNi0jCKuJHoE64A0jyAbG4Mg5Y.jpg', '/76aveobsWhFYon5DHP7CAjo9GYJ.jpg', 'عندما تكتشف آسيا أنها كانت تعيش في شبكة من الأكاذيب، يتداعى كل شيء من حولها، فتقرر أن تنتقم جميع من خانها من أصدقائها.', 'عندما تكتشف آسيا أنها كانت تعيش في شبكة من الأكاذيب، يتداعى كل شيء من حولها، فتقرر أن تنتقم جميع من خانها من أصدقائها.', 8.1, '["دراما"]'::jsonb, '[{"name": "جانسو ديري", "character": "Asya Arslan", "profile_path": "/erjCquhIaIGkgumxnS4LKMpZChe.jpg"}, {"name": "Caner Cindoruk", "character": "Volkan Arslan", "profile_path": "/nZ2BkGLDGBReXXRzN8xf2wc9dQa.jpg"}, {"name": "ميليس سيزن", "character": "Derin Güçlü", "profile_path": "/kiTyCXXX1s6vtwtjKGCYKkhwTsx.jpg"}, {"name": "Eren Vurdem", "character": "Mert Gelik", "profile_path": "/xDJNxVvWN5EMhRi3X1sgBJwIOig.jpg"}, {"name": "Alp Akar", "character": "Ali Arslan", "profile_path": "/77DRKxlmeFDCEJ9gEyBTS8C01ug.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (356, 'series', 'بوليفارد المواهب', 'بوليفارد المواهب', 'بوليفارد المواهب', 'بوليفارد المواهب', 2021, 137863, 'tv', NULL, '/c5sBmTcTBA6oviXMgs2hqda2MhR.jpg', 'يتنافس مجموعة من المغنيين الشبه محترفين في مسابقة بوليفارد المواهب على مدى عدة جولات أملا بأن يصبح أحدهم نجما غنائيا مشهورا في الشرق الأوسط', 'يتنافس مجموعة من المغنيين الشبه محترفين في مسابقة بوليفارد المواهب على مدى عدة جولات أملا بأن يصبح أحدهم نجما غنائيا مشهورا في الشرق الأوسط', NULL, '[]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (357, 'movie', 'العميل صفر', 'Badh', 'Badh', 'فيلم العميل صفر', 2025, 1383247, 'movie', '/sLjHm8eKrC27wykgmih6vVCxjbi.jpg', '/lkkWEkEb0v8NKAlBQ6xLyiap3DY.jpg', 'تدور أحداث الفيلم العميل صفر حول ألما، التي تضطر إلى العودة لهويتها السابقة كعميلة استخبارات وقاتلة محترفة تُعرف باسم "باض"، بعد إصابة ضابط الشرطة إلياس بطلق ناري ودخوله في غيبوبة. وبينما تسعى للانتقام وكشف الحقيقة، تبدأ بتعقب أفراد عائلة الخوري والقضاء عليهم واحدًا تلو الآخر، ما يثير غضب زعيم العائلة منصور. لكن مع انكشاف الأسرار، تكتشف أن منصور يعمل مع جوانا، الضابطة السابقة في وحدتها الاستخباراتية، لتجد نفسها في مواجهة مؤامرة أخطر مما كانت تتوقع.', 'تدور أحداث الفيلم العميل صفر حول ألما، التي تضطر إلى العودة لهويتها السابقة كعميلة استخبارات وقاتلة محترفة تُعرف باسم "باض"، بعد إصابة ضابط الشرطة إلياس بطلق ناري ودخوله في غيبوبة. وبينما تسعى للانتقام وكشف الحقيقة، تبدأ بتعقب أفراد عائلة الخوري والقضاء عليهم واحدًا تلو الآخر، ما يثير غضب زعيم العائلة منصور. لكن مع انكشاف الأسرار، تكتشف أن منصور يعمل مع جوانا، الضابطة السابقة في وحدتها الاستخباراتية، لتجد نفسها في مواجهة مؤامرة أخطر مما كانت تتوقع.', 5.6, '["حركة", "إثارة"]'::jsonb, '[{"name": "مارين فاكت", "character": "Badh Siracine", "profile_path": "/uerTjXw6DWirxXTlZqNYxwHUZV7.jpg"}, {"name": "Emmanuelle Bercot", "character": "Joanna Walter", "profile_path": "/xywoj2EBThgQE8izX7979MmrlOd.jpg"}, {"name": "Grégoire Colin", "character": "Sam", "profile_path": "/jtolsceVVsMT1wWi8m8pdtaUE4f.jpg"}, {"name": "Stanislas Merhar", "character": "Hadrien Tassigny", "profile_path": "/mydjB3KiYv5ytseH5Y5laew6bvl.jpg"}, {"name": "Niels Schneider", "character": "Alex", "profile_path": "/eG7go6nzgnb791avzYoN7GSqPd6.jpg"}]'::jsonb, 84) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (358, 'series', 'الحصن', 'Takeshi''s Castle', 'Takeshi''s Castle', 'برنامج الحصن', 2002, 5689, 'tv', '/5rSiau1StRsoiaR9Jdxa2rQIML2.jpg', '/fmVdPHPA0nEFw92oZr16khbuUOI.jpg', 'الحصن في الدبلجة العربية أو قلعة تاكيشي (باليابانية: 風雲！たけし城 ,Fūun! Takeshi-jō) هو برنامج مسابقات ألعاب جسدية ترفيهية أقيم في اليابان من عام 1986 إلى 1990 على شاشة تي بي إس. وعرض على جزأين. يشارك عدد كبير من المتسابقين من كل أرجاء اليابان في المنافسة والمغامرة والترفية.', 'الحصن في الدبلجة العربية أو قلعة تاكيشي (باليابانية: 風雲！たけし城 ,Fūun! Takeshi-jō) هو برنامج مسابقات ألعاب جسدية ترفيهية أقيم في اليابان من عام 1986 إلى 1990 على شاشة تي بي إس. وعرض على جزأين. يشارك عدد كبير من المتسابقين من كل أرجاء اليابان في المنافسة والمغامرة والترفية.', 7.8, '["كوميديا", "واقع", "عائلي"]'::jsonb, '[{"name": "Mary Scheer", "character": "", "profile_path": "/51LZcrFlk0ocIhNvC7DoP0UwVGh.jpg"}, {"name": "Joey de Leon", "character": "", "profile_path": "/zgoKnOgQiK8ScMziQTuBXTBdkQA.jpg"}, {"name": "Craig Charles", "character": "", "profile_path": "/91wCJbGDEKzT7G35X04PdKIOKFS.jpg"}, {"name": "John Cervenka", "character": "", "profile_path": null}, {"name": "ビートたけし", "character": "", "profile_path": "/6pnXXkCx8wkCHvOrcWjaY58KA7k.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (359, 'movie', 'وقفة رجالة', 'وقفة رجالة', 'وقفة رجالة', 'فيلم وقفه رجاله', 2021, 785861, 'movie', '/sx4cvAJaG9Uk5NkK8doG4j13upQ.jpg', '/w0OT65o1soARwceOyXfU2omZokJ.jpg', 'فيلم كوميدي تدور أحداثه حول مجموعة من الأصدقاء يجتمعون من جديد لمساعدة أحدهم في العثور على طريقه للخروج من مشكلة كبيرة. ومع تعقيد الوضع، يضطرون إلى القيام برحلة إلى بلدة ساحلية.', 'فيلم كوميدي تدور أحداثه حول مجموعة من الأصدقاء يجتمعون من جديد لمساعدة أحدهم في العثور على طريقه للخروج من مشكلة كبيرة. ومع تعقيد الوضع، يضطرون إلى القيام برحلة إلى بلدة ساحلية.', 6.9, '["كوميديا"]'::jsonb, '[{"name": "سيد رجب", "character": "عادل", "profile_path": "/r6zPbQX4Rj4Y1ynk5Ym4kfdYBpq.jpg"}, {"name": "ماجد الكدواني", "character": "شُهدي", "profile_path": "/iBOBl5XrufQr67yqUU7YOUXoY54.jpg"}, {"name": "بيومي فؤاد", "character": "عزايزي", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "شريف دسوقي", "character": "حسين", "profile_path": "/dT4V6FdpobWJQMFz575t4On5hXl.jpg"}, {"name": "محمد سلام", "character": "مصطفى", "profile_path": "/pnOF9xHx4LbEHsRunfyRnfV1uDc.jpg"}]'::jsonb, 112) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (360, 'movie', 'بداية باتمان', 'Batman Begins', 'Batman Begins', 'batman begins', 2005, 272, 'movie', '/9WO6y90Q275A8tiMNrJ28fxwU9H.jpg', '/9IIBboV7MCT0bTxzXHmWK1Hq558.jpg', 'مدفوعًا بالمأساة ، كرّس الملياردير بروس واين حياته لكشف ودحر الفساد الذي ابتلي بمنزله ، مدينة جوثام. غير قادر على العمل داخل النظام ، بدلاً من ذلك ، أنشأ هوية جديدة ، رمزًا للخوف على عالم الجريمة الإجرامي - باتمان.', 'مدفوعًا بالمأساة ، كرّس الملياردير بروس واين حياته لكشف ودحر الفساد الذي ابتلي بمنزله ، مدينة جوثام. غير قادر على العمل داخل النظام ، بدلاً من ذلك ، أنشأ هوية جديدة ، رمزًا للخوف على عالم الجريمة الإجرامي - باتمان.', 7.7, '["دراما", "جريمة", "حركة"]'::jsonb, '[{"name": "كريستيان بيل", "character": "Bruce Wayne / Batman", "profile_path": "/7Pxez9J8fuPd2Mn9kex13YALrCQ.jpg"}, {"name": "مايكل كين", "character": "Alfred", "profile_path": "/bVZRMlpjTAO2pJK6v90buFgVbSW.jpg"}, {"name": "ليام نيسون", "character": "Ducard", "profile_path": "/sRLev3wJioBgun3ZoeAUFpkLy0D.jpg"}, {"name": "Katie Holmes", "character": "Rachel Dawes", "profile_path": "/gDhc9rLbhpXdY8lISD7yPiIhvp4.jpg"}, {"name": "غاري أولدمان", "character": "Jim Gordon", "profile_path": "/yhaSM5habNNI1Tf4ALRwRk3VvSZ.jpg"}]'::jsonb, 140) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (361, 'movie', 'المنتقمون: الحرب الأبدية', 'Avengers: Infinity War', 'Avengers: Infinity War', 'avengers infinity war', 2018, 299536, 'movie', '/pig5cJjP08d9OUgBXNjiqbU6RjH.jpg', '/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', 'مع استمرار المنتقمون وحلفائهم في حماية العالم من التهديدات التي لا يمكن لأي بطل لوحده التعامل معها، ظهر خطر جديد من الظلال الكوني - ثانوس -  مستبد من العار المجحف، هدفه هو جمع كل حجارة اللانهاية الستة، التي تحمل قوة لا يمكن تصورها، واستخدامها لإلحاق إرادته الملتوية على كل الواقع. لقد قادت كل الأمور التي كافحها المنتقمون حتى هذه اللحظة  - لم يكن مصير الأرض ووجودها أكثر غموضاً من ذي قبل.', 'مع استمرار المنتقمون وحلفائهم في حماية العالم من التهديدات التي لا يمكن لأي بطل لوحده التعامل معها، ظهر خطر جديد من الظلال الكوني - ثانوس -  مستبد من العار المجحف، هدفه هو جمع كل حجارة اللانهاية الستة، التي تحمل قوة لا يمكن تصورها، واستخدامها لإلحاق إرادته الملتوية على كل الواقع. لقد قادت كل الأمور التي كافحها المنتقمون حتى هذه اللحظة  - لم يكن مصير الأرض ووجودها أكثر غموضاً من ذي قبل.', 8.2, '["مغامرة", "حركة", "خيال علمي"]'::jsonb, '[{"name": "روبرت داوني جونيور", "character": "Tony Stark / Iron Man", "profile_path": "/5qHNjhtjMD4YWH3UP0rm4tKwxCL.jpg"}, {"name": "كريس إيفانز", "character": "Steve Rogers / Captain America", "profile_path": "/3bOGNsHlrswhyW79uvIHH1V43JI.jpg"}, {"name": "كريس هيمسوورث", "character": "Thor", "profile_path": "/piQGdoIQOF3C1EI5cbYZLAW1gfj.jpg"}, {"name": "جوش برولين", "character": "Thanos", "profile_path": "/sX2etBbIkxRaCsATyw5ZpOVMPTD.jpg"}, {"name": "مارك رافالو", "character": "Bruce Banner / Hulk", "profile_path": "/5GilHMOt5PAQh6rlUKZzGmaKEI7.jpg"}]'::jsonb, 149) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (362, 'movie', 'المعادل 3', 'The Equalizer 3', 'The Equalizer 3', 'the equalizer 3', 2023, 926393, 'movie', '/b0Ej6fnXAP8fK75hlyi2jKqdhHz.jpg', '/gystuaqp5AkVqqu3Nf0564zeOv4.jpg', 'يعود روبرت ماكال في مغامرة جديدة بجنوب إيطاليا؛ حينما يكتشف أن أصدقاؤه رهائن تحت قبضة مجموعة من المجرمين هناك.', 'يعود روبرت ماكال في مغامرة جديدة بجنوب إيطاليا؛ حينما يكتشف أن أصدقاؤه رهائن تحت قبضة مجموعة من المجرمين هناك.', 7.3, '["حركة", "إثارة", "جريمة"]'::jsonb, '[{"name": "دنزل واشنطن", "character": "Robert McCall", "profile_path": "/jj2Gcobpopokal0YstuCQW0ldJ4.jpg"}, {"name": "داكوتا فانينغ", "character": "Emma Collins", "profile_path": "/hwcO08SVWkelfvgfIa5HsTMxsK8.jpg"}, {"name": "Eugenio Mastrandrea", "character": "Gio Bonucci", "profile_path": "/tFvgQP7j3F0ATXxzLS2yOaeU05Q.jpg"}, {"name": "ديفيد دينمان", "character": "Frank Conroy", "profile_path": "/4I06ZD8SQ6pU1QYShiUXb711fJW.jpg"}, {"name": "Gaia Scodellaro", "character": "Aminah", "profile_path": "/5hk50qopSbFHDqWlHzBeN7crEVj.jpg"}]'::jsonb, 109) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (363, 'movie', 'فيوريوسا: ملحمة ماد ماكس', 'Furiosa: A Mad Max Saga', 'Furiosa: A Mad Max Saga', 'furiosa a mad max saga', 2024, 786892, 'movie', '/m6ODgYEzw4ETeVyIfW8yQWwtH2S.jpg', '/raph7qjAGTMXaIjVxt6ZDSXRzUr.jpg', 'مع سقوط العالم، يتم اختطاف فيوريوسا الصغيرة وتقع في أيدي حشد كبير من راكبي الدراجات النارية بقيادة أمير الحرب ديمنتوس. ويجب على فيوريوسا أن تنجو من العديد من المصاعب وأن تجد طريقها إلى المنزل.', 'مع سقوط العالم، يتم اختطاف فيوريوسا الصغيرة وتقع في أيدي حشد كبير من راكبي الدراجات النارية بقيادة أمير الحرب ديمنتوس. ويجب على فيوريوسا أن تنجو من العديد من المصاعب وأن تجد طريقها إلى المنزل.', 7.4, '["حركة", "خيال علمي", "مغامرة"]'::jsonb, '[{"name": "أنيا تايلور", "character": "Furiosa", "profile_path": "/qYNofOjlRke2MlJVihmJmEdQI4v.jpg"}, {"name": "كريس هيمسوورث", "character": "Dementus", "profile_path": "/piQGdoIQOF3C1EI5cbYZLAW1gfj.jpg"}, {"name": "توم بيرك", "character": "Praetorian Jack", "profile_path": "/4IHlAZ9bJ82VAd6HUOWFgo81SDq.jpg"}, {"name": "Alyla Browne", "character": "Young Furiosa", "profile_path": "/h9qYvAqEZS6HTQhE8zLA0q3u52n.jpg"}, {"name": "George Shevtsov", "character": "The History Man", "profile_path": "/cuOoCZShfvNrOvrWqH2dPyBfrZS.jpg"}]'::jsonb, 149) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (364, 'movie', 'غدار', 'Insidious', 'Insidious', 'insidious', 2011, 49018, 'movie', '/1egpmVXuXed58TH2UOnX1nATTrf.jpg', '/tJvRdhlkonjBLBUpTqp0RPPujxJ.jpg', 'تحاول عائلة منع الأرواح الشريرة من محاصرة ابنهم دالتون بعد دخوله في غيبوبة عقب حادثة غامضة وخارقة للعادة حدثت له في القبو، فهل ستنجح العائلة في استعادة الابن؟', 'تحاول عائلة منع الأرواح الشريرة من محاصرة ابنهم دالتون بعد دخوله في غيبوبة عقب حادثة غامضة وخارقة للعادة حدثت له في القبو، فهل ستنجح العائلة في استعادة الابن؟', 7.0, '["رعب", "إثارة"]'::jsonb, '[{"name": "باتريك ويلسون", "character": "Josh Lambert", "profile_path": "/oym6H2QD9esk4yABjCHaUoNAOa8.jpg"}, {"name": "روز بيرن", "character": "Renai Lambert", "profile_path": "/4Vd7w19asuBfUGgz0NIuQI5wxIA.jpg"}, {"name": "Lin Shaye", "character": "Elise Rainier", "profile_path": "/aL87Za52elH81zMiXQn5C7AXAeg.jpg"}, {"name": "تاي سيمبكينز", "character": "Dalton Lambert", "profile_path": "/8FyJcMFmPdCSfz2Zc5ZcAKrIorj.jpg"}, {"name": "باربرا هيرشي", "character": "Lorraine Lambert", "profile_path": "/6swwfge3HlvyBVRSNwroFtMcgNB.jpg"}]'::jsonb, 102) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (365, 'movie', 'بليد رانر 2049', 'Blade Runner 2049', 'Blade Runner 2049', 'blade runner 2049', 2017, 335984, 'movie', '/tvUCcLra2WbjwcFjtsq0gLpvMNh.jpg', '/gNdLJU9TxrpGx4dkZidjys3fyy0.jpg', 'ثلاثين سنة بعد أحداث الفيلم الأول، بليد رنر جديد،ضابط لوس انجلوس "كي"  يكشف عن سر مدفون منذ زمن بعيد من المحتمل له أن يدفع ماتبقى من المجتمع نحو الفوضى، إكتشاف كي يقوده لمهمة ايجاد ريك ديكارد ضابط لوس انجلوس و بليد رنر سابق مفقود منذ ثلاثين عاماً.', 'ثلاثين سنة بعد أحداث الفيلم الأول، بليد رنر جديد،ضابط لوس انجلوس "كي"  يكشف عن سر مدفون منذ زمن بعيد من المحتمل له أن يدفع ماتبقى من المجتمع نحو الفوضى، إكتشاف كي يقوده لمهمة ايجاد ريك ديكارد ضابط لوس انجلوس و بليد رنر سابق مفقود منذ ثلاثين عاماً.', 7.6, '["خيال علمي", "دراما"]'::jsonb, '[{"name": "رايان غوسلينغ", "character": "''K''", "profile_path": "/lyUyVARQKhGxaxy0FbPJCQRpiaW.jpg"}, {"name": "هاريسون فورد", "character": "Rick Deckard", "profile_path": "/pjBMJVPpcZK23Vt1nzr1zEBTWrP.jpg"}, {"name": "آنا دي أرماس", "character": "Joi", "profile_path": "/eDuBeSHV0R7vuCnHHXrfa7d7IfB.jpg"}, {"name": "ديف باتيستا", "character": "Sapper Morton", "profile_path": "/snk6JiXOOoRjPtHU5VMoy6qbd32.jpg"}, {"name": "روبين رايت", "character": "Lieutenant Joshi", "profile_path": "/d3rIv0y2p0jMsQ7ViR7O1606NZa.jpg"}]'::jsonb, 164) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (366, 'movie', 'الساموراي الأخير', 'The Last Samurai', 'The Last Samurai', 'the last samurai', 2003, 616, 'movie', '/a8jmJPs5eZBARmnuEEvZwbjwyz4.jpg', '/z354BaTVzKj7E60WLzDoSmUuO4u.jpg', 'ناثان ألجرين أمريكي تم توظيفه لتعليم الجيش الياباني أساليب الحرب الحديثة ، والتي تجده يتعلم احترام الساموراي والمبادئ الشريفة التي تحكمهم. بعد الضغط عليه لتدمير طريقة حياة الساموراي باسم التحديث والتجارة المفتوحة ، قرر Algren أن يصبح هو نفسه المحارب النهائي وأن يقاتل من أجل حقهم في الوجود.', 'ناثان ألجرين أمريكي تم توظيفه لتعليم الجيش الياباني أساليب الحرب الحديثة ، والتي تجده يتعلم احترام الساموراي والمبادئ الشريفة التي تحكمهم. بعد الضغط عليه لتدمير طريقة حياة الساموراي باسم التحديث والتجارة المفتوحة ، قرر Algren أن يصبح هو نفسه المحارب النهائي وأن يقاتل من أجل حقهم في الوجود.', 7.6, '["دراما", "حركة", "حرب"]'::jsonb, '[{"name": "توم كروز", "character": "Nathan Algren", "profile_path": "/3mShHjSQR7NXOVbdTu5rT2Qd0MN.jpg"}, {"name": "渡辺謙", "character": "Moritsugu Katsumoto", "profile_path": "/psAXOYp9SBOXvg6AXzARDedNQ9P.jpg"}, {"name": "Timothy Spall", "character": "Simon Graham", "profile_path": "/pcR6t8kpAgGwIUo4UjlP5gyKkNA.jpg"}, {"name": "طوني غولدوين", "character": "Col. Benjamin Bagley", "profile_path": "/A3hXimbzDtFxQ1PXNo8gG7RZeN4.jpg"}, {"name": "هيرويوكي سانادا", "character": "Ujio", "profile_path": "/SOwDxhGnRccP2lAtssQ7TxCzOe.jpg"}]'::jsonb, 154) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.g