INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (367, 'movie', 'نهوض فارس الظلام', 'The Dark Knight Rises', 'The Dark Knight Rises', 'the dark knight rises', 2012, 49026, 'movie', '/gDQLSmVsPxvOmQIAVFcl6Akn7Nh.jpg', '/y2DB71C4nyIdMrANijz8mzvQtk6.jpg', 'ثمان سنواتٍ مضت تحمْل فيها باتمان (كريستيان بال) مسئولية موت هارفي دنت حتى أنه عاش في ظلامٍ حالكٍ لفترةٍ طويلةٍ نتيجة ذلك. يعود باتمان مرةً أخرى عندما يهدد الشرير المقنع باين (توم هاردي) مدينة جوثام ويقودها نحو الهاوية؛ فيحاول باتمان إنقاذ المدينة وسكان المدينة من هذه العقلية الإجرامية. حيث إن باين ما هو إلا قائدٌ إرهابيٌ يقود مدينة جوثام للهلاك. في جوٍ مليءٍ بالتشويق والإثارة تدور معاركٌ حامية بين باتمان وباين وتتعقد الأحداث لتصل لمدى لا يتخيله أحد.', 'ثمان سنواتٍ مضت تحمْل فيها باتمان (كريستيان بال) مسئولية موت هارفي دنت حتى أنه عاش في ظلامٍ حالكٍ لفترةٍ طويلةٍ نتيجة ذلك. يعود باتمان مرةً أخرى عندما يهدد الشرير المقنع باين (توم هاردي) مدينة جوثام ويقودها نحو الهاوية؛ فيحاول باتمان إنقاذ المدينة وسكان المدينة من هذه العقلية الإجرامية. حيث إن باين ما هو إلا قائدٌ إرهابيٌ يقود مدينة جوثام للهلاك. في جوٍ مليءٍ بالتشويق والإثارة تدور معاركٌ حامية بين باتمان وباين وتتعقد الأحداث لتصل لمدى لا يتخيله أحد.', 7.8, '["حركة", "جريمة", "دراما", "إثارة"]'::jsonb, '[{"name": "كريستيان بيل", "character": "Bruce Wayne", "profile_path": "/7Pxez9J8fuPd2Mn9kex13YALrCQ.jpg"}, {"name": "غاري أولدمان", "character": "Commissioner Gordon", "profile_path": "/yhaSM5habNNI1Tf4ALRwRk3VvSZ.jpg"}, {"name": "توم هاردي", "character": "Bane", "profile_path": "/d81K0RH8UX7tZj49tZaQhZ9ewH.jpg"}, {"name": "جوزيف غوردون-ليفيت", "character": "Blake", "profile_path": "/z2FA8js799xqtfiFjBTicFYdfk.jpg"}, {"name": "آن هاثاواي", "character": "Selina", "profile_path": "/nbccV2pMoyLTCeg5DQip24Eq0Jp.jpg"}]'::jsonb, 165) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUD