INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (368, 'movie', 'العظمة', 'The Prestige', 'The Prestige', 'the prestige', 2006, 1124, 'movie', '/jidaV7LzX2BOy8ciGiZYiMQwksG.jpg', '/z3br1ub7spqGMkxgjgJSdM4DC21.jpg', 'يتنافس الساحران روبرت أنجير وألفريد بوردن في لندن أواخر القرن التاسع عشر، بعدما تحولت صداقتهما إلى عداوة شرسة بسبب حادث مأساوي. يسعى كل منهما إلى التفوق على الآخر وتقديم الخدعة الأكثر إبهارًا، فيبدأ الصراع بينهما بالتصاعد حتى يصبح هوسًا يدفعهما إلى التضحية بكل شيء من أجل كشف أسرار منافسه والتفوق عليه. ومع استخدامهما أساليب أكثر خطورة وغموضًا، تتشابك الخدع والأسرار والخيانة، لتكشف المنافسة عن عواقب مدمرة تتجاوز حدود المسرح.', 'يتنافس الساحران روبرت أنجير وألفريد بوردن في لندن أواخر القرن التاسع عشر، بعدما تحولت صداقتهما إلى عداوة شرسة بسبب حادث مأساوي. يسعى كل منهما إلى التفوق على الآخر وتقديم الخدعة الأكثر إبهارًا، فيبدأ الصراع بينهما بالتصاعد حتى يصبح هوسًا يدفعهما إلى التضحية بكل شيء من أجل كشف أسرار منافسه والتفوق عليه. ومع استخدامهما أساليب أكثر خطورة وغموضًا، تتشابك الخدع والأسرار والخيانة، لتكشف المنافسة عن عواقب مدمرة تتجاوز حدود المسرح.', 8.2, '["دراما", "غموض", "خيال علمي"]'::jsonb, '[{"name": "هيو جاكمان", "character": "Robert Angier", "profile_path": "/oX6CpXmnXCHLyqsa4NEed1DZAKx.jpg"}, {"name": "كريستيان بيل", "character": "Alfred Borden", "profile_path": "/7Pxez9J8fuPd2Mn9kex13YALrCQ.jpg"}, {"name": "مايكل كين", "character": "Cutter", "profile_path": "/bVZRMlpjTAO2pJK6v90buFgVbSW.jpg"}, {"name": "بايبر بيرابو", "character": "Julia McCullough", "profile_path": "/5XrzISDEox0KubRDzJU668Oxmxy.jpg"}, {"name": "Rebecca Hall", "character": "Sarah", "profile_path": "/coC58ANiDbqRIyle5zEl9QDektf.jpg"}]'::jsonb, 130) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = E