INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (369, 'movie', 'المهمة المستحيلة: أمة منشقة', 'Mission: Impossible - Rogue Nation', 'Mission: Impossible - Rogue Nation', 'mission impossible rogue nation', 2015, 177677, 'movie', '/n1UCFfRqZlWo4UuAizVhAFEylGT.jpg', '/vYIUN5rrCncHFY8WvcuXQlM4hk5.jpg', 'بعد حل وحدة المهام المستحيلة (IMF) يجد العميل إيثان هانت (توم كروز) نفسه بمفرده، بينما يواجه فريقه شبكة خاصة من العملاء ذوي المهارات العالية تحمل اسم النقابة، حيث تضم أفرادًا على أعلى تدريب يسعون لتكوين نظام عالمي جديد أيًا كان الثمن، عبر سلسلة متصاعدة من الهجمات الإرهابية. يجمع إيثان فريقًا ويوحد قواه مع العميلة السابقة إلسا فاوست (ريبيكا فيرجسون) بعد أن تبرأت منها الاستخبارات البريطانية، رغم إنها قد تكون جزءًا من تلك المجموعة المارقة، ليواجه هذا الفريق أكثر مهمة مستحيلة له على الإطلاق.', 'بعد حل وحدة المهام المستحيلة (IMF) يجد العميل إيثان هانت (توم كروز) نفسه بمفرده، بينما يواجه فريقه شبكة خاصة من العملاء ذوي المهارات العالية تحمل اسم النقابة، حيث تضم أفرادًا على أعلى تدريب يسعون لتكوين نظام عالمي جديد أيًا كان الثمن، عبر سلسلة متصاعدة من الهجمات الإرهابية. يجمع إيثان فريقًا ويوحد قواه مع العميلة السابقة إلسا فاوست (ريبيكا فيرجسون) بعد أن تبرأت منها الاستخبارات البريطانية، رغم إنها قد تكون جزءًا من تلك المجموعة المارقة، ليواجه هذا الفريق أكثر مهمة مستحيلة له على الإطلاق.', 7.2, '["حركة", "مغامرة"]'::jsonb, '[{"name": "توم كروز", "character": "Ethan Hunt", "profile_path": "/3mShHjSQR7NXOVbdTu5rT2Qd0MN.jpg"}, {"name": "جيرمي رينر", "character": "William Brandt", "profile_path": "/yB84D1neTYXfWBaV0QOE9RF2VCu.jpg"}, {"name": "سايمون بيج", "character": "Benji Dunn", "profile_path": "/jw8bEEoTOithyNf0qxu4Zt1yaKp.jpg"}, {"name": "ريبيكا فيرغسون", "character": "Ilsa Faust", "profile_path": "/ty8ZPzaCBBlqIr5qzpOXI24iC8j.jpg"}, {"name": "فينج راميز", "character": "Luther Stickell", "profile_path": "/5pD48M3Mustr93gY5KLFDqF1fiv.jpg"}]'::jsonb, 131) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (370, 'movie', 'كابتن أمريكا: الحرب الأهلية', 'Captain America: Civil War', 'Captain America: Civil War', 'captain america civil war', 2016, 271110, 'movie', '/sRnRPoTbACDUb9pHIpadrOfcSIv.jpg', '/wdwcOBMkt3zmPQuEMxB3FUtMio2.jpg', 'يؤدي التدخل السياسي في شؤون المنتقمين إلى حدوث شرخ بين كابتن أمريكا وآيرون مان.', 'يؤدي التدخل السياسي في شؤون المنتقمين إلى حدوث شرخ بين كابتن أمريكا وآيرون مان.', 7.5, '["مغامرة", "حركة", "خيال علمي"]'::jsonb, '[{"name": "كريس إيفانز", "character": "Steve Rogers / Captain America", "profile_path": "/3bOGNsHlrswhyW79uvIHH1V43JI.jpg"}, {"name": "روبرت داوني جونيور", "character": "Tony Stark / Iron Man", "profile_path": "/5qHNjhtjMD4YWH3UP0rm4tKwxCL.jpg"}, {"name": "سكارليت جوهانسون", "character": "Natasha Romanoff / Black Widow", "profile_path": "/druW5adKddizHNSoPbI0q7Mvn0K.jpg"}, {"name": "سيباستيان ستان", "character": "Bucky Barnes / Winter Soldier", "profile_path": "/mLqE91qUnE8fbfMvsXD7BcWJKNK.jpg"}, {"name": "أنتوني ماكي", "character": "Sam Wilson / Falcon", "profile_path": "/eZSIDrtTzhvabyjrmIITQLsjx8h.jpg"}]'::jsonb, 147) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (371, 'movie', 'مملكة كوكب القرود', 'Kingdom of the Planet of the Apes', 'Kingdom of the Planet of the Apes', 'kingdom of the planet of the apes', 2024, 653346, 'movie', '/2FpXJl3cnU4BvKyAvlWN1Yra3Wk.jpg', '/fypydCipcWDKDTTCoPucBsdGYXW.jpg', 'بعد عدة أجيال من حكم قيصر، أصبحت القرود الآن الجنس المهيمن وتعيش بسلام بينما تم تقليص البشر للعيش في الظل. مع قيام زعيم قرد طاغية جديد ببناء إمبراطوريته، ينطلق قرد شاب في رحلة شاقة ستجعله يشكك في كل ما يعرفه عن الماضي ويتخذ قرارات ستحدد مستقبل القرود والبشر على حد سواء.', 'بعد عدة أجيال من حكم قيصر، أصبحت القرود الآن الجنس المهيمن وتعيش بسلام بينما تم تقليص البشر للعيش في الظل. مع قيام زعيم قرد طاغية جديد ببناء إمبراطوريته، ينطلق قرد شاب في رحلة شاقة ستجعله يشكك في كل ما يعرفه عن الماضي ويتخذ قرارات ستحدد مستقبل القرود والبشر على حد سواء.', 7.1, '["خيال علمي", "مغامرة", "حركة"]'::jsonb, '[{"name": "أوين تيج", "character": "Noa", "profile_path": "/tgCkGE0LIggyjMmgSwHhpZAkfJs.jpg"}, {"name": "فريا ألان", "character": "Nova / Mae", "profile_path": "/8RuLG2mePw8YgFNUjWROBuxMrwT.jpg"}, {"name": "كيفن دوراند", "character": "Proximus Caesar", "profile_path": "/hINvryvce5tpod6kTnUg9ZTH8wg.jpg"}, {"name": "بيتر ماكون", "character": "Raka", "profile_path": "/jF4jzgtWB2NAJ6BfVTSDQOlOHLr.jpg"}, {"name": "ويليام ميسي", "character": "Trevathan", "profile_path": "/hdVEGSrP8qWlJnt0v5vSVcGOjy7.jpg"}]'::jsonb, 145) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres,