INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (372, 'movie', 'فضائي: رومولوس', 'Alien: Romulus', 'Alien: Romulus', 'alien romulus', 2024, 945961, 'movie', '/2uSWRTtCG336nuBiG8jOTEUKSy8.jpg', '/iYqSQaWDttQIQzsxg9xHyg0bttG.jpg', 'أثناء استكشافهم للأجزاء العميقة من محطة فضائية مهجورة، يواجه مجموعة من المستعمرين الشباب في الفضاء أكثر أشكال الحياة رعبًا في الكون.', 'أثناء استكشافهم للأجزاء العميقة من محطة فضائية مهجورة، يواجه مجموعة من المستعمرين الشباب في الفضاء أكثر أشكال الحياة رعبًا في الكون.', 7.2, '["رعب", "خيال علمي"]'::jsonb, '[{"name": "كايلي سبيني", "character": "Rain", "profile_path": "/6gUzyMnwo7TjZA7E1Amd1GI8JGw.jpg"}, {"name": "David Jonsson", "character": "Andy", "profile_path": "/2ZZNGZw57KKMrVIr27g7W16G0jV.jpg"}, {"name": "Archie Renaux", "character": "Tyler", "profile_path": "/uTd18t2VJovN2jSJyhuG8Yy3PV6.jpg"}, {"name": "إيزابيلا ميرسيد", "character": "Kay", "profile_path": "/7O5GWIH8IHwU4kGZIhC3JkGDiZr.jpg"}, {"name": "Spike Fearn", "character": "Bjorn", "profile_path": "/o1WcXkDdlN5wdL5WIuGXNpNouZ9.jpg"}]'::jsonb, 119) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (373, 'movie', 'المكان الهادئ: اليوم الأول', 'A Quiet Place: Day One', 'A Quiet Place: Day One', 'a quiet place day one', 2024, 762441, 'movie', '/179t66Owa5nxcB5nxBbV8PUSOri.jpg', '/6XjMwQTvnICBz6TguiDKkDVHvgS.jpg', 'يستكشف العمل بدايات نهاية العالم، بظهور مخلوقات مفترسة، وكيف أصبح على البشر العيش في هدوء تام ليتمكنوا من تفادي تلك المخلوقات المميتة، وتتوالى الأحداث.', 'يستكشف العمل بدايات نهاية العالم، بظهور مخلوقات مفترسة، وكيف أصبح على البشر العيش في هدوء تام ليتمكنوا من تفادي تلك المخلوقات المميتة، وتتوالى الأحداث.', 6.6, '["رعب", "خيال علمي", "إثارة"]'::jsonb, '[{"name": "لوبيتا نيونقو", "character": "Samira", "profile_path": "/y40Wu1T742kynOqtwXASc5Qgm49.jpg"}, {"name": "Joseph Quinn", "character": "Eric", "profile_path": "/zshhuioZaH8S5ZKdMcojzWi1ntl.jpg"}, {"name": "ألكس وولف", "character": "Reuben", "profile_path": "/7PMu5zFOEH7PqFDzrKThgKD4Ndf.jpg"}, {"name": "دجيمون هونسو", "character": "Henri", "profile_path": "/tpvtxxvCx2Mb5DV632hmuYlHoiY.jpg"}, {"name": "Eliane Umuhire", "character": "Zena", "profile_path": "/u2q6nQtLsKGyTnWHtmKGyeYAyXq.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (374, 'movie', 'حافة الغد', 'Edge of Tomorrow', 'Edge of Tomorrow', 'edge of tomorrow', 2014, 137113, 'movie', '/nBM9MMa2WCwvMG4IJ3eiGUdbPe6.jpg', '/4V1yIoAKPMRQwGBaSses8Bp2nsi.jpg', 'رجلٌ يقاتل في حربٍ ضدّ كائناتٍ فضائية، عليه أن يعيش اليوم نفسه كلّما مات، إلى أن يجد طريقةً لإيقاف مصدر طاقتهم بمساعدة جنديٍّ من النخبة.', 'رجلٌ يقاتل في حربٍ ضدّ كائناتٍ فضائية، عليه أن يعيش اليوم نفسه كلّما مات، إلى أن يجد طريقةً لإيقاف مصدر طاقتهم بمساعدة جنديٍّ من النخبة.', 7.6, '["حركة", "خيال علمي"]'::jsonb, '[{"name": "توم كروز", "character": "Cage", "profile_path": "/3mShHjSQR7NXOVbdTu5rT2Qd0MN.jpg"}, {"name": "إيميلي بلنت", "character": "Rita", "profile_path": "/5nCSG5TL1bP1geD8aaBfaLnLLCD.jpg"}, {"name": "برندان غليسون", "character": "General Brigham", "profile_path": "/ctPPJu5ZYDZr1IPmzoNpezczrm0.jpg"}, {"name": "بِلْ باكْسْتون", "character": "Master Sergeant Farell", "profile_path": "/aLdNe6mt1cSi2zWlUYRregzfis5.jpg"}, {"name": "Jonas Armstrong", "character": "Skinner", "profile_path": "/7Ia8Dfhqa2bH43NeKSZiPZ9wHAF.jpg"}]'::jsonb, 113) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (375, 'movie', 'قلب شجاع', 'Braveheart', 'Braveheart', 'braveheart', 1995, 197, 'movie', '/or1gBugydmjToAEq7OZY0owwFk.jpg', '/1m1c5gIWWkb1FEC9lzsoXHhhs7b.jpg', 'غضب المحارب الاسكتلندي ويليام والاس من ذبح مورون وعروسه الجديدة وحبه للطفولة ، ويقتل فصيلة من جنود اللورد الإنجليز المحليين. هذا يقود القرية إلى التمرد ، وفي النهاية ، تنهض الدولة بأكملها ضد الحكم الإنجليزي.', 'غضب المحارب الاسكتلندي ويليام والاس من ذبح مورون وعروسه الجديدة وحبه للطفولة ، ويقتل فصيلة من جنود اللورد الإنجليز المحليين. هذا يقود القرية إلى التمرد ، وفي النهاية ، تنهض الدولة بأكملها ضد الحكم الإنجليزي.', 7.9, '["حركة", "دراما", "تاريخ", "حرب"]'::jsonb, '[{"name": "Mel Gibson", "character": "William Wallace", "profile_path": "/jnqHMaOslt8cef2atSmOpGRvNla.jpg"}, {"name": "Catherine McCormack", "character": "Murron MacClannough", "profile_path": "/vYyMCGKeIUTZMdEgVwQCgX7q1T3.jpg"}, {"name": "Sophie Marceau", "character": "Princess Isabelle", "profile_path": "/b56TRCVVMZ2LMZqzXg0FxeGMd0u.jpg"}, {"name": "Patrick McGoohan", "character": "King Edward", "profile_path": "/xtUMgFYGF7KmJg1KqiYQuwYTTe3.jpg"}, {"name": "Angus Macfadyen", "character": "Robert the Bruce", "profile_path": "/yUuA7U3lw6yM0Eb6mD83qYeevH2.jpg"}]'::jsonb, 178) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (376, 'movie', 'جون ويك: الفصل 3 - الاستعداد للحرب', 'John Wick: Chapter 3 - Parabellum', 'John Wick: Chapter 3 - Parabellum', 'john wick chapter 3 parabellum', 2019, 458156, 'movie', '/zpAxJtE9vElzuwSAvgxl5b3RxY9.jpg', '/vVpEOvdxVBP2aV166j5Xlvb5Cdc.jpg', 'يعود القاتل الخارق جون ويك باربعة عشر مليون دولار على رأسه وجيش من القتلة الذين يصطادون المكافآت على دربه. بعد قتل عضو في جماعة القتله الدولية الغامضة  "هاي تايبل" جون ويك هو طارد، لكن أكثر الرجال والنساء ضرباً في العالم ينتظرونه بكل منعطف.', 'يعود القاتل الخارق جون ويك باربعة عشر مليون دولار على رأسه وجيش من القتلة الذين يصطادون المكافآت على دربه. بعد قتل عضو في جماعة القتله الدولية الغامضة  "هاي تايبل" جون ويك هو طارد، لكن أكثر الرجال والنساء ضرباً في العالم ينتظرونه بكل منعطف.', 7.4, '["حركة", "إثارة", "جريمة"]'::jsonb, '[{"name": "كيانو ريفز", "character": "John Wick", "profile_path": "/8RZLOyYGsoRe9p44q3xin9QkMHv.jpg"}, {"name": "هالي بيري", "character": "Sofia", "profile_path": "/84HRDZodRCuBSpYGSc3ow8WucI4.jpg"}, {"name": "إيان ماكشين", "character": "Winston", "profile_path": "/rteBJYNgD1yGsHg2HGZAIrYHz1t.jpg"}, {"name": "Laurence Fishburne", "character": "Bowery King", "profile_path": "/2GbXERENPpl5MmlqOLlPVaVtifD.jpg"}, {"name": "Mark Dacascos", "character": "Zero", "profile_path": "/trOACuJz1KzhB51qe6asaxRuxrh.jpg"}]'::jsonb, 131) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runti