INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (377, 'movie', 'الشعوذة', 'The Conjuring', 'The Conjuring', 'the conjuring', 2013, 138843, 'movie', '/gDmi9udysk1OTYPgk4YG4UXRkLv.jpg', '/ecKQlAEG95k62SMGhvX83oEqANK.jpg', 'تدور القصة في إطار رعب عن إيد وارين (باتريك ويلسون)، وزوجته لورين (فيرا فارميجا)، اللذين يعملان كمحققين في الخوارق الطبيعية ويحوزان على شهرة عالمية، تطلب مساعدتهما أسرة روجر (رون ليفينجستون)؛ حيث تتعرض للترهيب من قوى الظلام في مزرعة منعزلة، وبينما يضطران لمواجهة كيان شيطاني قوي، تقع عائلة وارين في أكثر الحالات رعباً في حياتهما..', 'تدور القصة في إطار رعب عن إيد وارين (باتريك ويلسون)، وزوجته لورين (فيرا فارميجا)، اللذين يعملان كمحققين في الخوارق الطبيعية ويحوزان على شهرة عالمية، تطلب مساعدتهما أسرة روجر (رون ليفينجستون)؛ حيث تتعرض للترهيب من قوى الظلام في مزرعة منعزلة، وبينما يضطران لمواجهة كيان شيطاني قوي، تقع عائلة وارين في أكثر الحالات رعباً في حياتهما..', 7.5, '["رعب", "إثارة"]'::jsonb, '[{"name": "فيرا فارميغا", "character": "Lorraine Warren", "profile_path": "/5Vs7huBmTKftwlsc2BPAntyaQYj.jpg"}, {"name": "باتريك ويلسون", "character": "Ed Warren", "profile_path": "/oym6H2QD9esk4yABjCHaUoNAOa8.jpg"}, {"name": "Lili Taylor", "character": "Carolyn Perron", "profile_path": "/vWcMUi3QyvCr3QuFbjtwyPx7WtU.jpg"}, {"name": "Ron Livingston", "character": "Roger Perron", "profile_path": "/pr5CjWnkaf5WKTIYh8wtNufjmyb.jpg"}, {"name": "Hayley McFarland", "character": "Nancy", "profile_path": "/mapxc0eyuNFqj9IybLmMIofhuzF.jpg"}]'::jsonb, 112) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (378, 'movie', 'المقاطعة 9', 'District 9', 'District 9', 'district 9', 2009, 17654, 'movie', '/tuGlQkqLxnodDSk6mp5c2wvxUEd.jpg', '/jhM3wgWUrrOkz9r4xwV5cV5RhI4.jpg', 'قبل ثلاثين عامًا ، وصل الفضائيون إلى الأرض. ليس للغزو أو تقديم المساعدة ، ولكن للبحث عن ملجأ من كوكبهم المحتضر منفصلة عن البشر في منطقة جنوب إفريقيا تسمى المنطقة 9 ، تتم إدارة الأجانب بواسطة شركة Multi-National United ، التي لا تهتم برفاهية الأجانب ولكنها ستفعل أي شيء لإتقان تقنيتهم المتقدمة. عندما يتعاقد الوكيل الميداني للشركة مع فيروس غامض يبدأ في تغيير حمضه النووي ، فهناك مكان واحد فقط يمكنه إخفاءه: المنطقة 9.', 'قبل ثلاثين عامًا ، وصل الفضائيون إلى الأرض. ليس للغزو أو تقديم المساعدة ، ولكن للبحث عن ملجأ من كوكبهم المحتضر منفصلة عن البشر في منطقة جنوب إفريقيا تسمى المنطقة 9 ، تتم إدارة الأجانب بواسطة شركة Multi-National United ، التي لا تهتم برفاهية الأجانب ولكنها ستفعل أي شيء لإتقان تقنيتهم المتقدمة. عندما يتعاقد الوكيل الميداني للشركة مع فيروس غامض يبدأ في تغيير حمضه النووي ، فهناك مكان واحد فقط يمكنه إخفاءه: المنطقة 9.', 7.5, '["خيال علمي"]'::jsonb, '[{"name": "شارلتو كوبلي", "character": "Wikus van de Merwe", "profile_path": "/em89OJJvBRX7kNJJPASmNKQujsC.jpg"}, {"name": "Jason Cope", "character": "Christopher Johnson / Grey Bradnam / Trent", "profile_path": "/xEqMZClrQQvaygQakUwtS5l7TYH.jpg"}, {"name": "Nathalie Boltt", "character": "Sarah Livingstone - Sociologist", "profile_path": "/mYvZlMSwvv6WDfJHfV6bYm4ddES.jpg"}, {"name": "Sylvaine Strike", "character": "Dr Katrina McKenzie", "profile_path": "/A1O7oEwqy3vebOdnXhyRtKCBeg4.jpg"}, {"name": "Elizabeth Mkandawie", "character": "Interviewee", "profile_path": "/qqiB2LLwNjaEnivKXaRm5opKU4b.jpg"}]'::jsonb, 112) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (379, 'movie', 'طروادة', 'Troy', 'Troy', 'troy', 2004, 652, 'movie', '/rlxHRbiLXs2F4LSSaFz3JKFAnqe.jpg', '/wyFJcodi5T9LJAeiE8Se7ScdOFj.jpg', 'في عام 1250 قبل الميلاد، خلال أواخر العصر البرونزي، يبدأ صراع بين أمتين صاعدتين. يُقنع "باريس"، أمير "طروادة"، "هيلين"، ملكة "إسبرطة"، بترك زوجها "مينيلاوس" والإبحار معه إلى "طروادة". وعندما يكتشف "مينيلاوس" أن زوجته قد اختطفها الطرواديون، يطلب من شقيقه "أغاممنون" مساعدته على استعادتها. لكن "أغاممنون" يرى في ذلك فرصة لتوسيع نفوذه، فيُبحر إلى "طروادة" على رأس ألف سفينة تقل نحو 50 ألف محارب يوناني.', 'في عام 1250 قبل الميلاد، خلال أواخر العصر البرونزي، يبدأ صراع بين أمتين صاعدتين. يُقنع "باريس"، أمير "طروادة"، "هيلين"، ملكة "إسبرطة"، بترك زوجها "مينيلاوس" والإبحار معه إلى "طروادة". وعندما يكتشف "مينيلاوس" أن زوجته قد اختطفها الطرواديون، يطلب من شقيقه "أغاممنون" مساعدته على استعادتها. لكن "أغاممنون" يرى في ذلك فرصة لتوسيع نفوذه، فيُبحر إلى "طروادة" على رأس ألف سفينة تقل نحو 50 ألف محارب يوناني.', 7.2, '["حرب", "حركة", "تاريخ"]'::jsonb, '[{"name": "براد بيت", "character": "Achilles", "profile_path": "/ajNaPmXVVMJFg9GWmu6MJzTaXdV.jpg"}, {"name": "أورلاندو بلوم", "character": "Paris", "profile_path": "/lwQoA0qJTCZ6l2FH6PjmhRQjiaB.jpg"}, {"name": "إريك بانا", "character": "Hector", "profile_path": "/l9yoDgw3YFC2gMD1HTo5djGOwSY.jpg"}, {"name": "برايان كوكس", "character": "Agamemnon", "profile_path": "/scSjbFCTRngXlkJRoKptM5kQGw7.jpg"}, {"name": "شون بين", "character": "Odysseus", "profile_path": "/kTjiABk3TJ3yI0Cto5RsvyT6V3o.jpg"}]'::jsonb, 196) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLU