INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (381, 'series', 'عروس إسطنبول', 'İstanbullu Gelin', 'İstanbullu Gelin', 'مسلسل عروس اسطنبول', 2017, 70798, 'tv', '/alVrRNxDGOlULYdXgnOpPrVP7KL.jpg', '/raosbKSonz7ZkuZsfxHG5LgH0Wl.jpg', 'فاروق هو مالك شركة حافلات وزعيم عائلة نافذة في مدينة بورصة، إحدى المدن الكبرى في تركيا. يلتقي فاروق بفتاة عازفة كمان ويقع في حبها. لكن والدة فاروق المتسلطة لا تشعر بالسعادة تجاه علاقة ابنها بها.', 'فاروق هو مالك شركة حافلات وزعيم عائلة نافذة في مدينة بورصة، إحدى المدن الكبرى في تركيا. يلتقي فاروق بفتاة عازفة كمان ويقع في حبها. لكن والدة فاروق المتسلطة لا تشعر بالسعادة تجاه علاقة ابنها بها.', 7.5, '["دراما", "عائلي", "كوميديا"]'::jsonb, '[{"name": "Aslı Enver", "character": "Süreyya Deniz/Boran", "profile_path": "/ElAAxwuUmv8vldYXZrty8uCT7G.jpg"}, {"name": "Özcan Deniz", "character": "Faruk Boran", "profile_path": "/1xugZDdp0vskwozHBSTCIFQPjCV.jpg"}, {"name": "Salih Bademci", "character": "Fikret Boran", "profile_path": "/4ScTjg1DLmfd1rW423OmJE7ns9G.jpg"}, {"name": "Dilara Aksüyek", "character": "İpek Dokuyucu/Boran", "profile_path": "/vmRnHNGI4KCRhrkEpzD8OLeNt1Q.jpg"}, {"name": "İpek Bilgin", "character": "Esma Boran", "profile_path": "/cmFNIqTHgVzZG7wFjES9HMQs1fn.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
