INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (383, 'series', 'الطبيب المعجزة', 'Mucize Doktor', 'Mucize Doktor', 'مسلسل الطبيب المعجزه', 2019, 92967, 'tv', '/zpXb8OihnIfSIVJIdds7APfLzZR.jpg', '/j9orEeA4twmIEQtHdaAW0L1L7nE.jpg', 'تنقلب وحدة جراحية مميزة رأسًا على عقب عندما ينضم مقيم جديد غريب إلى الفريق. يعاني علي من متلازمة سافانت، مما يجعل من الصعب عليه التواصل مع الآخرين، على الرغم من أنه طبيب استثنائي.', 'تنقلب وحدة جراحية مميزة رأسًا على عقب عندما ينضم مقيم جديد غريب إلى الفريق. يعاني علي من متلازمة سافانت، مما يجعل من الصعب عليه التواصل مع الآخرين، على الرغم من أنه طبيب استثنائي.', 8.1, '["دراما"]'::jsonb, '[{"name": "Taner Ölmez", "character": "Dr. Ali Vefa", "profile_path": "/QG3bNfNw5aRqEzhttSIEey4nBt.jpg"}, {"name": "Onur Tuna", "character": "Dr. Ferman Eryiğit", "profile_path": "/kSxQUj9iampPna4XyuFfDvDEFcx.jpg"}, {"name": "Sinem Ünsal", "character": "Dr. Nazlı Gülengül", "profile_path": "/z7LF1TP34VGJiL3bwxNHJHRCPQE.jpg"}, {"name": "هازال تورسان", "character": "Beliz Boysal", "profile_path": "/i6g679VSuNgGvcEb5ioJHFDXTdf.jpg"}, {"name": "مراد أيجن", "character": "Dr. Tanju Korman", "profile_path": "/52rOMVqVfaJYQX8TF3gWzKMHHDK.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
