INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (385, 'movie', 'بئر الخيانة', 'بئر الخيانة', 'بئر الخيانة', 'مسلسل الخيانه', 1987, 514373, 'movie', '/vCVvXQzVcUa08tHW5cyaknjvR1A.jpg', '/rsE0mm403Id7ZQqfuLRYtQd6txj.jpg', 'يعيش اللص جابر عبدالغفار (نور الشريف) على سرقة البضائع بميناء الإسكندرية، وذات يوم يتم القبض عليه وترحيله للجيش لتأدية الخدمة العسكرية، يهرب من الجيش إلى إيطاليا بطريقة غير مشروعة، بعد وصوله إيطاليا يعاني من قسوة المعيشة فيتوجه إلى مكتب عمل باحثا عن عمل، بعد اكتشافه إن هذا المكتب يتبع للموساد يقرر التعامل معهم ويعرض خدماته للعمل كجاسوس، يتم تجنيده وتدريبه على أعلى مستوى وإرساله لميناء الإسكندرية كرجل أعمال لجمع معلومات هامة عن النشاط البحري للجيش المصري، تعلم المخابرات المصرية حقيقة جابر منذ البداية ويتم إسناد مهمة القبض عليه وترحيله لمصر للضابط أحمد عزت (عزت العلايلي)، فتتصاعد الأحداث.', 'يعيش اللص جابر عبدالغفار (نور الشريف) على سرقة البضائع بميناء الإسكندرية، وذات يوم يتم القبض عليه وترحيله للجيش لتأدية الخدمة العسكرية، يهرب من الجيش إلى إيطاليا بطريقة غير مشروعة، بعد وصوله إيطاليا يعاني من قسوة المعيشة فيتوجه إلى مكتب عمل باحثا عن عمل، بعد اكتشافه إن هذا المكتب يتبع للموساد يقرر التعامل معهم ويعرض خدماته للعمل كجاسوس، يتم تجنيده وتدريبه على أعلى مستوى وإرساله لميناء الإسكندرية كرجل أعمال لجمع معلومات هامة عن النشاط البحري للجيش المصري، تعلم المخابرات المصرية حقيقة جابر منذ البداية ويتم إسناد مهمة القبض عليه وترحيله لمصر للضابط أحمد عزت (عزت العلايلي)، فتتصاعد الأحداث.', 6.0, '["دراما"]'::jsonb, '[{"name": "نور الشريف", "character": "Gaber", "profile_path": "/wBFojkh5Tr2JCHWkQ7sfmo2SKgd.jpg"}, {"name": "عزت العلايلي", "character": "", "profile_path": "/noiZR9ty9cPCHRYQJzfH2bX8Elm.jpg"}, {"name": "دلال عبدالعزيز", "character": "", "profile_path": "/oIW8HsQaRbb1j81Fi4FghJryuTj.jpg"}, {"name": "عبدالعزيز مخيون", "character": "", "profile_path": "/p0R8Ky3FLTTA