INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (401, 'series', 'توب غير', 'Top Gear', 'Top Gear', 'top gear', 2002, 45, 'tv', '/aqM6QnuhSXzjHlKbXyKUqxaGiWu.jpg', '/bJROfBstoARn6vOqqPylYLpGYDH.jpg', 'توب غير هو برنامج تلفازي بريطاني يهتم بالمركبات والسيارات، وهو برنامج الواقع الأكثر مشاهدة على الإطلاق. يمتاز البرنامج بطابعه المميز والفكاهي والمثير للجدل في بعض الأحيان. يقدم البرنامج جيرمي كلاركسون ورتشارد هاموند وجيمس ماي، وإلى جانبهم سائق التجارب الغامض ذا ستيغ.', 'توب غير هو برنامج تلفازي بريطاني يهتم بالمركبات والسيارات، وهو برنامج الواقع الأكثر مشاهدة على الإطلاق. يمتاز البرنامج بطابعه المميز والفكاهي والمثير للجدل في بعض الأحيان. يقدم البرنامج جيرمي كلاركسون ورتشارد هاموند وجيمس ماي، وإلى جانبهم سائق التجارب الغامض ذا ستيغ.', 7.6, '["واقع", "حوار"]'::jsonb, '[{"name": "Chris Harris", "character": "Self - Host", "profile_path": "/pe5nxuoiQT4rGpQeQvJI3gTngKv.jpg"}, {"name": "Paddy McGuinness", "character": "Self - Host", "profile_path": "/2LMYFeIQF4r1OrtGHvE7ocZoGX7.jpg"}, {"name": "Andrew Flintoff", "character": "Self - Host", "profile_path": "/ztEATDmigzCuTUi47i3ktyimRve.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (402, 'movie', 'السرعة والعضب تقدم: هوبز و شاو', 'Fast & Furious Presents: Hobbs & Shaw', 'Fast & Furious Presents: Hobbs & Shaw', 'hobbs shaw', 2019, 384018, 'movie', '/2196YzqbaWDGaXyBjsC67ZFcZT0.jpg', '/hpgda6P9GutvdkDX5MUJ92QG9aj.jpg', 'منذ أن تواجه وكيل خدمة الأمن الدبلوماسي الأمريكي - هوبز- و المنبوذ - شاو - ، قاما فقط بتبادل الضربات والكلمات السيئة.', 'منذ أن تواجه وكيل خدمة الأمن الدبلوماسي الأمريكي - هوبز- و المنبوذ - شاو - ، قاما فقط بتبادل الضربات والكلمات السيئة.', 6.8, '["حركة", "مغامرة", "كوميديا"]'::jsonb, '[{"name": "دوين جونسون", "character": "Luke Hobbs", "profile_path": "/5QApZVV8FUFlVxQpIK3Ew6cqotq.jpg"}, {"name": "جيسون ستاثام", "character": "Deckard Shaw", "profile_path": "/pXGSq2UpcDE2NMF8LR56QZf5U1q.jpg"}, {"name": "إدريس إلبا", "character": "Brixton", "profile_path": "/be1bVF7qGX91a6c5WeRPs5pKXln.jpg"}, {"name": "فانيسا كيربي", "character": "Hattie Shaw", "profile_path": "/tViEEsjvbhrJxWsOipUqIYjdHEb.jpg"}, {"name": "Helen Mirren", "character": "Queenie Shaw", "profile_path": "/1reKRrsdsHXJaRVHVyOEg4oPTcZ.jpg"}]'::jsonb, 136) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (403, 'movie', 'الناقل', 'The Transporter', 'The Transporter', 'the transporter', 2002, 4108, 'movie', '/6PHPfviijGs1h7ckj1HGUwv8QpU.jpg', '/8dXR9R0NUo4eyS4hnYOsCywmo16.jpg', 'القواعد مصنوعة ليتم كسرها.  ضابط القوات الخاصة السابق ، فرانك مارتن ، سيقدم أي شيء لأي شخص بالسعر المناسب ، وسياسته التي لا تطرح أسئلة تضعه في ارتفاع الطلب. ولكن عندما يدرك أن حمولته الأخيرة على قيد الحياة ، فإنها تطلق سلسلة خطيرة من الأحداث. يتم تهريب لاي المقيدة والمكممة إلى فرنسا من قبل رجل أعمال أمريكي مشبوه ، ويعمل فرانك على إنقاذها حيث يتم الكشف عن أنشطته غير القانونية من قبل محقق فرنسي.', 'القواعد مصنوعة ليتم كسرها.  ضابط القوات الخاصة السابق ، فرانك مارتن ، سيقدم أي شيء لأي شخص بالسعر المناسب ، وسياسته التي لا تطرح أسئلة تضعه في ارتفاع الطلب. ولكن عندما يدرك أن حمولته الأخيرة على قيد الحياة ، فإنها تطلق سلسلة خطيرة من الأحداث. يتم تهريب لاي المقيدة والمكممة إلى فرنسا من قبل رجل أعمال أمريكي مشبوه ، ويعمل فرانك على إنقاذها حيث يتم الكشف عن أنشطته غير القانونية من قبل محقق فرنسي.', 6.7, '["حركة", "جريمة", "إثارة"]'::jsonb, '[{"name": "جيسون ستاثام", "character": "Frank Martin", "profile_path": "/pXGSq2UpcDE2NMF8LR56QZf5U1q.jpg"}, {"name": "شو كي", "character": "Lai", "profile_path": "/jNaUWRClE4aFnguPZKQeVqfugPd.jpg"}, {"name": "فرانسيس بيرلاند", "character": "Tarconi", "profile_path": "/5TDYSUfCj8vaG5sqJXUU06Cvafa.jpg"}, {"name": "ماث سكولز", "character": "Wall Street", "profile_path": "/1dPinwDyFIEN30wUQG9Mm3Emnjh.jpg"}, {"name": "ريك يونج", "character": "Mr Kwai", "profile_path": "/zJvNZ8ejr08nEBPfSBev5lj558x.jpg"}]'::jsonb, 92) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXC