INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (407, 'movie', 'منزل آمن', 'Safe House', 'Safe House', 'safe house', 2025, 1522923, 'movie', '/jlQW7qPp9j6yGqiIEcB3uNYbjys.jpg', '/ptHXfOc0gEIG8CrieQ3t8MUBuiP.jpg', 'تدور احداث الفيلم حين يتبع العمل قصة ستة عملاء فدراليين يختبئون بعد هجومٍ إرهابي في لوس أنجلوس، لكن الشكوك تبدأ في التصاعد بينهم حين يدركون أن المنفذ الحقيقي للهجوم قد يكون واحدًا منهم.', 'تدور احداث الفيلم حين يتبع العمل قصة ستة عملاء فدراليين يختبئون بعد هجومٍ إرهابي في لوس أنجلوس، لكن الشكوك تبدأ في التصاعد بينهم حين يدركون أن المنفذ الحقيقي للهجوم قد يكون واحدًا منهم.', 6.4, '["حركة", "إثارة"]'::jsonb, '[{"name": "Lucien Laviscount", "character": "Anderson", "profile_path": "/3GndTFV0wMGDwocS4rP5Z194uYu.jpg"}, {"name": "هانا جون كامين", "character": "Owens", "profile_path": "/V8P9EVelewGVXbuyEylqrzF6iG.jpg"}, {"name": "لويس تان", "character": "Choi", "profile_path": "/yMr3mwHHBpfbXwDDkahOzFtTCak.jpg"}, {"name": "هولت مكالاني", "character": "Halton", "profile_path": "/xHnvYcJv6YEku9pIg8LoDNHWQy.jpg"}, {"name": "إيثان إمبري", "character": "Sorello", "profile_path": "/feYnMlTejbHfkhD1akVVXKWG0u1.jpg"}]'::jsonb, 90) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (408, 'movie', 'رامبو 5: الدماء الأخيرة', 'Rambo: Last Blood', 'Rambo: Last Blood', 'rambo last blood', 2019, 522938, 'movie', '/kTQ3J8oTTKofAVLYnds2cHUz9KO.jpg', '/spYx9XQFODuqEVoPpvaJI1ksAVt.jpg', 'يعود (جون رامبو) بعد سنوات طوال من أجل استكمال مهمته الأخيرة، حيث يسعى للانتقام من كل من خانوه، وتبدأ رحلة من المخاطر في الفصل الأخير من مغامرات (رامبو).', 'يعود (جون رامبو) بعد سنوات طوال من أجل استكمال مهمته الأخيرة، حيث يسعى للانتقام من كل من خانوه، وتبدأ رحلة من المخاطر في الفصل الأخير من مغامرات (رامبو).', 6.5, '["حركة", "إثارة", "دراما"]'::jsonb, '[{"name": "سيلفستر ستالون", "character": "John Rambo", "profile_path": "/gn3pDWthJqR0VDYGViGD3048og7.jpg"}, {"name": "Paz Vega", "character": "Carmen", "profile_path": "/fNLlJysFd5f0Q8Lj20EZpU8BiRN.jpg"}, {"name": "Sergio Peris-Mencheta", "character": "Hugo Martínez", "profile_path": "/uPE1n0JpbicJ5gm2fNarbsx6Nc4.jpg"}, {"name": "Adriana Barraza", "character": "María Beltrán", "profile_path": "/kfww4YbO9J2HpCldEqyyhQugwy5.jpg"}, {"name": "Yvette Monreal", "character": "Gabriela", "profile_path": "/ub3IyLYc71IZIRzyUhrqOebRcDp.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (409, 'movie', 'المدمر: مصير مظلم', 'Terminator: Dark Fate', 'Terminator: Dark Fate', 'terminator dark fate', 2019, 290859, 'movie', '/vqzNJRH4YyquRiWxCCOH0aXggHI.jpg', '/a6cDxdwaQIFjSkXf7uskg78ZyTq.jpg', 'مرحبا بكم في اليوم التالي ليوم القيامة  بعد عقود من منع سارة كونور يوم القيامة ، يتم إرسال فاصل جديد قاتل للقضاء على زعيم المقاومة المستقبلي. في معركة لإنقاذ البشرية ، تتعاون سارة كونور المتمرسة في المعركة مع حليف غير متوقع وجندي خارق محسن لإيقاف فاصل الأكثر دموية حتى الآن.', 'مرحبا بكم في اليوم التالي ليوم القيامة  بعد عقود من منع سارة كونور يوم القيامة ، يتم إرسال فاصل جديد قاتل للقضاء على زعيم المقاومة المستقبلي. في معركة لإنقاذ البشرية ، تتعاون سارة كونور المتمرسة في المعركة مع حليف غير متوقع وجندي خارق محسن لإيقاف فاصل الأكثر دموية حتى الآن.', 6.4, '["خيال علمي", "حركة", "مغامرة", "إثارة"]'::jsonb, '[{"name": "ليندا هاميلتون", "character": "Sarah Connor", "profile_path": "/7FNn9Z5xkRS9EFbGL2tpmpph9xV.jpg"}, {"name": "أرنولد شوارزنيجر", "character": "T-800 / Carl", "profile_path": "/2marNcjIfCUE5Z2HyrcEiJHPbsA.jpg"}, {"name": "ماكنزي ديفيس", "character": "Grace", "profile_path": "/CEpYCoD6erYRYekmFHuQAULLD5.jpg"}, {"name": "Natalia Reyes", "character": "Daniella \"Dani\" Ramos", "profile_path": "/9N7FNKUhjtinrNPy8ANvXrB7iEr.jpg"}, {"name": "Gabriel Luna", "character": "Gabriel / REV-9", "profile_path": "/bIPORtYxTJPEUJIThbZrpqf4A11.jpg"}]'::jsonb, 128) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, ge