INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (410, 'series', 'Hawaii Five-0', 'Hawaii Five-0', 'Hawaii Five-0', 'hawaii five 0', 2010, 32798, 'tv', '/sIdCKlmM2nU4akIvFQaAIiU8YES.jpg', '/tLccUh3uazZ9TkLhe53UwprJhI4.jpg', 'لا تملك جزيرة هاواي جهاز شرطة خاص بها, و لكن يأمر حاكم الجزيرة بتكوين فرقة عمليات خاصة تدعي Five-0 للتحقيق في الجرائم الخطيرة اللتي تحدث علي الجزيرة. يترأس الفريق ضابط احتياط من البحرية الأمريكية، ويتمكن بمساعدة نائبه من إيقاف وإحباط العديد من مختلف أنواع الجرائم, مثل الإرهاب والجريمة المنظمة.', 'لا تملك جزيرة هاواي جهاز شرطة خاص بها, و لكن يأمر حاكم الجزيرة بتكوين فرقة عمليات خاصة تدعي Five-0 للتحقيق في الجرائم الخطيرة اللتي تحدث علي الجزيرة. يترأس الفريق ضابط احتياط من البحرية الأمريكية، ويتمكن بمساعدة نائبه من إيقاف وإحباط العديد من مختلف أنواع الجرائم, مثل الإرهاب والجريمة المنظمة.', 7.7, '["جريمة", "دراما", "حركة ومغامرة"]'::jsonb, '[{"name": "Alex O''Loughlin", "character": "Steve McGarrett", "profile_path": "/l3Cd7jD3r3TLkqWaDijmK7GgWxo.jpg"}, {"name": "Scott Caan", "character": "Danny ''Danno'' Williams", "profile_path": "/hX5X4K7BfzOOGcxiNQ24EpPZrfC.jpg"}, {"name": "Ian Anthony Dale", "character": "Adam Noshimuri", "profile_path": "/x5ePN7j7C4ZmytO5VoUOpiPEyRm.jpg"}, {"name": "Meaghan Rath", "character": "Tani Rey", "profile_path": "/wP2p5xEDwt6c4m1iHHdCmDxqEGF.jpg"}, {"name": "Beulah Koale", "character": "Junior Reigns", "profile_path": "/payzbNPVpNXgX5SBtWBLNWfdfuS.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDE