INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (412, 'movie', 'الناقل 2', 'Transporter 2', 'Transporter 2', 'transporter 2', 2005, 9335, 'movie', '/cdm17vK8PxHfTi7ayZf6WKbOgUO.jpg', '/lbs1ood36hzj0O0cqW2a8MqptOh.jpg', 'يعيش السائق المحترف فرانك مارتن في ميامي ، حيث يقوم مؤقتا بملء صديق كسائق لصانع سياسة حكومي لمكافحة المخدرات وعائلته. يتم استهداف الصبي الصغير في الأسرة للاختطاف ، ويشارك فرانك على الفور في حماية الطفل وفضح الخاطفين.', 'يعيش السائق المحترف فرانك مارتن في ميامي ، حيث يقوم مؤقتا بملء صديق كسائق لصانع سياسة حكومي لمكافحة المخدرات وعائلته. يتم استهداف الصبي الصغير في الأسرة للاختطاف ، ويشارك فرانك على الفور في حماية الطفل وفضح الخاطفين.', 6.3, '["حركة", "إثارة", "جريمة"]'::jsonb, '[{"name": "جيسون ستاثام", "character": "Frank Martin", "profile_path": "/pXGSq2UpcDE2NMF8LR56QZf5U1q.jpg"}, {"name": "Amber Valletta", "character": "Audrey Billings", "profile_path": "/6KSsLN9XFucycN5yw4FGeByHrVx.jpg"}, {"name": "Alessandro Gassmann", "character": "Gianni Chellini", "profile_path": "/1RgJdkPXpwfQWumzZ4h3KKxVv4V.jpg"}, {"name": "Kate Nauta", "character": "Lola", "profile_path": "/cbTZfha344j1vshNuITeupmnK2C.jpg"}, {"name": "Matthew Modine", "character": "Jefferson Billings", "profile_path": "/z974QEHL12qUvLyk6hlWGAmDgom.jpg"}]'::jsonb, 88) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (413, 'movie', 'المرتزقة 4', 'Expend4bles', 'Expend4bles', 'expend4bles', 2023, 299054, 'movie', '/zNhUmqYeDHklzGyfYbOq1F9zaAb.jpg', '/rMvPXy8PUjj1o8o1pzgQbdNCsvj.jpg', 'يعود فريق المرتزقة من جديد من أجل التصدي لتاجر أسلحة يمتلك جيشًا كبيرًا يسعى من خلاله لتدمير كل شيء.', 'يعود فريق المرتزقة من جديد من أجل التصدي لتاجر أسلحة يمتلك جيشًا كبيرًا يسعى من خلاله لتدمير كل شيء.', 6.0, '["حركة", "مغامرة", "إثارة"]'::jsonb, '[{"name": "جيسون ستاثام", "character": "Lee Christmas", "profile_path": "/pXGSq2UpcDE2NMF8LR56QZf5U1q.jpg"}, {"name": "50 سنت", "character": "Drew \"Easy Day\" Farrell", "profile_path": "/7VfwFIwBxy7qBUErosWRDQOovl9.jpg"}, {"name": "ميغان فوكس", "character": "Gina", "profile_path": "/zQp2YM0zbC27Ws97LNbyicysk8p.jpg"}, {"name": "دولف لندجرين", "character": "Gunner Jensen", "profile_path": "/fB1tOws6Gav0xE8LYlELEb82hJt.jpg"}, {"name": "توني جا", "character": "Decha", "profile_path": "/wsGEaIscm7y0nvJK39rR6SnkuLr.jpg"}]'::jsonb, 103) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (414, 'movie', 'المفترس: الأراضي القاحلة', 'Predator: Badlands', 'Predator: Badlands', 'predator', 2025, 1242898, 'movie', '/6guUtmn3SCjwVDtXqOBMDtF2csH.jpg', '/82lM4GJ9uuNvNDOEpxFy77uv4Ak.jpg', 'بعد أن نُبذ من قبيلته، يسعى صيّاد فضائي لإثبات نفسه واستعادة مكانته، فيتحالف مع رفيق غير متوقّع وينطلقان معًا في رحلة خطرة، بحثًا عن الخصم الأعظم... ذاك الذي قد يمنحه النصر عليه شرفًا مفقودًا، أو يُخلّد سقوطه إلى الأبد.', 'بعد أن نُبذ من قبيلته، يسعى صيّاد فضائي لإثبات نفسه واستعادة مكانته، فيتحالف مع رفيق غير متوقّع وينطلقان معًا في رحلة خطرة، بحثًا عن الخصم الأعظم... ذاك الذي قد يمنحه النصر عليه شرفًا مفقودًا، أو يُخلّد سقوطه إلى الأبد.', 7.8, '["حركة", "خيال علمي", "مغامرة"]'::jsonb, '[{"name": "إيل فانينغ", "character": "Thia / Tessa", "profile_path": "/ucC5faqfEYVhoC25M6Hi3znZmab.jpg"}, {"name": "ديميتريوس كولوماتانجي", "character": "Dek / Father", "profile_path": "/rmIZTT1AZK3C9fYhEOtGKtSrF8E.jpg"}, {"name": "Ravi Narayan", "character": "Bud", "profile_path": "/iM9dr3AjXTt7IGpRzZlQVG7hINa.jpg"}, {"name": "Michael Homick", "character": "Kwei (Suit)", "profile_path": "/a7IFYVtmNvBMJ7c20BVMc0LX6PT.jpg"}, {"name": "Stefan Grube", "character": "Kwei (voice)", "profile_path": "/7SJ13Np7xL20YJjPiUbM7PshdYA.jpg"}]'::jsonb, 107) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
