INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (416, 'series', 'إن سي آي أس', 'NCIS', 'NCIS', 'ncis', 2003, 4614, 'tv', '/6WEjJ0AE8MjrZc92k1mrrvrw5Un.jpg', '/nn3SuLTO4hum8yAxaY4ql8h6kRk.jpg', 'تتناول حلقات المسلسل قصة العديد من المخاطر التي يتعرض لها العملاء السريين التابعين لمكتب العمليات الخاصة، والذي يتوجب عليهم التخفي الدائم في عملهم عن طريق استخدام هويات مزيفة للإيقاع بالخارجين عن القانون والذين يمثلون خطرا وتهديدا كبيرا على الأمن القومي.', 'تتناول حلقات المسلسل قصة العديد من المخاطر التي يتعرض لها العملاء السريين التابعين لمكتب العمليات الخاصة، والذي يتوجب عليهم التخفي الدائم في عملهم عن طريق استخدام هويات مزيفة للإيقاع بالخارجين عن القانون والذين يمثلون خطرا وتهديدا كبيرا على الأمن القومي.', 7.6, '["جريمة", "دراما", "حركة ومغامرة"]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (417, 'movie', 'Superfast!', 'Superfast!', 'Superfast!', 'fast furious 8', 2015, 325358, 'movie', '/iuIWl90qCpoxv6g775JB6Kg0m86.jpg', '/v7JSw9XCkdv533TP7VabRZJ63PC.jpg', 'ينضم الشرطي المتخفي (لوكاس وايت) إلى مجموعة متسابقي السيارات التي يقودها (فين سيرنتينو) في (لوس أنجلوس)، والذين يخططون بدورهم للانقلاب على زعيم الجريمة (خوان كارلوس دا سول) في الولاية، والاستيلاء على الأموال التي يخفيها بحوزته، ولأجل ذلك يضع (فين) خطة جريئة وغريبة في نفس الوقت.', 'ينضم الشرطي المتخفي (لوكاس وايت) إلى مجموعة متسابقي السيارات التي يقودها (فين سيرنتينو) في (لوس أنجلوس)، والذين يخططون بدورهم للانقلاب على زعيم الجريمة (خوان كارلوس دا سول) في الولاية، والاستيلاء على الأموال التي يخفيها بحوزته، ولأجل ذلك يضع (فين) خطة جريئة وغريبة في نفس الوقت.', 5.1, '["كوميديا", "حركة"]'::jsonb, '[{"name": "Alex Ashbaugh", "character": "Officer Lucas White", "profile_path": "/glVapnYT6mboBBr3amgiPtsBjUa.jpg"}, {"name": "Dale Pavinski", "character": "Vin Serento", "profile_path": "/rnIEL4LbYHPJGAtUnrEdMmhjxF8.jpg"}, {"name": "Andrea Navedo", "character": "Michelle", "profile_path": "/yUmB8TKeY0eAQSO54BbxdyEhUrP.jpg"}, {"name": "Lili Mirojnick", "character": "Jordana", "profile_path": "/ndoDSg6ENP5i5XJmFrhdmRlvCsW.jpg"}, {"name": "Gonzalo Menendez", "character": "Detective Hanover", "profile_path": "/nWvWfIwLZVXjZUru5DG08nAnPW4.jpg"}]'::jsonb, 99) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cas