INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (418, 'movie', 'كرانك', 'Crank', 'Crank', 'crank', 2006, 1948, 'movie', '/rsKmhnvzJezjwC1Ud2Hh37oNpdQ.jpg', '/8JPz1636hMcaADngF4H4KOxXfp1.jpg', 'يعمل تشيف تشيلويس قاتلًا محترفًا لحساب منظمةٍ إجرامية، ولكنه يسأم من عمله، ويقرر أن يعتزل ليعيش في هدوءٍ مع صديقته إيف التي لا تعلم شيئًا عن طبيعة عمله.  ولكن ما لا يعلمه تشيف أن عدوه اللدود فيرونا قد حقنه بسمٍ خاص يُسمى كوكتيل بكين، سوف يؤدي هذا السم لموته إذا انخفض عدد ضربات قلبه عن رقمٍ محددٍ.  يصبح على تشيف أن يجاهد من أجل الحفاظ على حياته. ويبدأ مع صديقيه كارليتو ودوك مهمة صعبة لحماية إيف، والانتقام من فيرونا، وإيجاد المصل اللازم لإيقاف مفعول السم.', 'يعمل تشيف تشيلويس قاتلًا محترفًا لحساب منظمةٍ إجرامية، ولكنه يسأم من عمله، ويقرر أن يعتزل ليعيش في هدوءٍ مع صديقته إيف التي لا تعلم شيئًا عن طبيعة عمله.  ولكن ما لا يعلمه تشيف أن عدوه اللدود فيرونا قد حقنه بسمٍ خاص يُسمى كوكتيل بكين، سوف يؤدي هذا السم لموته إذا انخفض عدد ضربات قلبه عن رقمٍ محددٍ.  يصبح على تشيف أن يجاهد من أجل الحفاظ على حياته. ويبدأ مع صديقيه كارليتو ودوك مهمة صعبة لحماية إيف، والانتقام من فيرونا، وإيجاد المصل اللازم لإيقاف مفعول السم.', 6.7, '["حركة", "إثارة", "جريمة"]'::jsonb, '[{"name": "جيسون ستاثام", "character": "Chev", "profile_path": "/pXGSq2UpcDE2NMF8LR56QZf5U1q.jpg"}, {"name": "Amy Smart", "character": "Eve", "profile_path": "/9GQwkmqd5klfXvhd29YI5OKAx3N.jpg"}, {"name": "Jose Pablo Cantillo", "character": "Verona", "profile_path": "/qtNesvN1bAQ779gJBt3LYDsm8f7.jpg"}, {"name": "Efren Ramirez", "character": "Kaylo", "profile_path": "/vo4IDt4NeNCHBXLz58Wjlx5994a.jpg"}, {"name": "Dwight Yoakam", "character": "Doc Miles", "profile_path": "/lMqcRiQs2OELf0xvFbLbX4nnXi8.jpg"}]'::jsonb, 88) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en