INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (420, 'movie', 'المعادل 2', 'The Equalizer 2', 'The Equalizer 2', 'the equalizer 2', 2018, 345887, 'movie', '/cQvc9N6JiMVKqol3wcYrGshsIdZ.jpg', '/a24i4Qw6qFTtkFLQsncv8WPwevj.jpg', 'روبرت مكال، الذي يقدم العدالة للمُستغلين والمضطهدين، يشرع في السعي الدؤوب حول العالم للثأر عندما تُقتل صديقته له لفترة طويلة.', 'روبرت مكال، الذي يقدم العدالة للمُستغلين والمضطهدين، يشرع في السعي الدؤوب حول العالم للثأر عندما تُقتل صديقته له لفترة طويلة.', 6.8, '["حركة", "إثارة", "جريمة"]'::jsonb, '[{"name": "دنزل واشنطن", "character": "Robert McCall", "profile_path": "/jj2Gcobpopokal0YstuCQW0ldJ4.jpg"}, {"name": "بيدرو باسكال", "character": "Dave York", "profile_path": "/oKcMbVn0NJTNzQt0ClKKvVXkm60.jpg"}, {"name": "Ashton Sanders", "character": "Miles Whittaker", "profile_path": "/2hMKOd6TLQWwLAS6ztUcZj8IZAC.jpg"}, {"name": "Orson Bean", "character": "Sam Rubinstein", "profile_path": "/2iz769YdycczgnGPZyXNsaN3TGR.jpg"}, {"name": "بيل بولمان", "character": "Brian Plummer", "profile_path": "/AlLhgmcX5zh3frPT82OSPY9gqXO.jpg"}]'::jsonb, 121) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (421, 'movie', 'المرتزقة 3', 'The Expendables 3', 'The Expendables 3', 'the expendables 3', 2014, 138103, 'movie', '/9zpuW7dIiUYRU9o0BDEMeUEwbfA.jpg', '/xSfBWkAarrPwwfiGBAMt8wqxUUH.jpg', 'في جو من الحركة والتشويق، يرصد الفيلم عمليات فرقة المرتزقة بقيادة بارني روس (سيلفيستر ستالون)، حيث يجد بارني روس نفسه وجهًا لوجه ضد كونراد ستون بانكس (ميل جيبسون). كونراد كان أحد أعضاء الفرقة في الماضي، لكنه خانها فقام بارني بقتله. يكتشف بارني بالصدفة أن كونراد لا يزال حيا، وأنه قد أصبح أحد عتاة اﻹجرام في العالم، فيقوم بتجنيد جيلًا جديدًا للفرقة أصغر سنًا من أجل مساندة ومساعدة الفرقة في القضاء على عدوها اللدود.', 'في جو من الحركة والتشويق، يرصد الفيلم عمليات فرقة المرتزقة بقيادة بارني روس (سيلفيستر ستالون)، حيث يجد بارني روس نفسه وجهًا لوجه ضد كونراد ستون بانكس (ميل جيبسون). كونراد كان أحد أعضاء الفرقة في الماضي، لكنه خانها فقام بارني بقتله. يكتشف بارني بالصدفة أن كونراد لا يزال حيا، وأنه قد أصبح أحد عتاة اﻹجرام في العالم، فيقوم بتجنيد جيلًا جديدًا للفرقة أصغر سنًا من أجل مساندة ومساعدة الفرقة في القضاء على عدوها اللدود.', 6.2, '["حركة", "مغامرة", "إثارة"]'::jsonb, '[{"name": "سيلفستر ستالون", "character": "Barney Ross", "profile_path": "/gn3pDWthJqR0VDYGViGD3048og7.jpg"}, {"name": "جيسون ستاثام", "character": "Lee Christmas", "profile_path": "/pXGSq2UpcDE2NMF8LR56QZf5U1q.jpg"}, {"name": "هاريسون فورد", "character": "Max Drummer", "profile_path": "/pjBMJVPpcZK23Vt1nzr1zEBTWrP.jpg"}, {"name": "أرنولد شوارزنيجر", "character": "Trench", "profile_path": "/2marNcjIfCUE5Z2HyrcEiJHPbsA.jpg"}, {"name": "Mel Gibson", "character": "Conrad Stonebanks", "profile_path": "/jnqHMaOslt8cef2atSmOpGRvNla.jpg"}]'::jsonb, 126) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (422, 'movie', 'إيه في بي: الفضائي ضد المفترس', 'AVP: Alien vs. Predator', 'AVP: Alien vs. Predator', 'alien vs predator', 2004, 395, 'movie', '/ySWu5bCnnmgV1cVacvFnFIhgOjp.jpg', '/xvq1RLaiwSdHwPHe7WUhqZa1rCA.jpg', 'تدور أحداث الفيلم في مطلع القرن الحادي والعشرين ،حول مجموعة من علماء الآثار والمهندسين الذين يتوجهون تحت قيادة رجل الأعمال تشارلز ويلاند (لانس هنريكسون) إلى قارة أنتارتيكا في بعثةٍ علمية ،بغرض الكشف عن هرمٍ قديمٍ مدفون تحت الجليد، يعُتقد بأنه موجود من قبل بناء الأهرامات المصرية وأهرامات الآزتيك، وهناك يجدون أنفسهم في خضم معركة شرسة حتى الموت تدور بين كلٍ من الكائنات الفضائية والمفترسين.', 'تدور أحداث الفيلم في مطلع القرن الحادي والعشرين ،حول مجموعة من علماء الآثار والمهندسين الذين يتوجهون تحت قيادة رجل الأعمال تشارلز ويلاند (لانس هنريكسون) إلى قارة أنتارتيكا في بعثةٍ علمية ،بغرض الكشف عن هرمٍ قديمٍ مدفون تحت الجليد، يعُتقد بأنه موجود من قبل بناء الأهرامات المصرية وأهرامات الآزتيك، وهناك يجدون أنفسهم في خضم معركة شرسة حتى الموت تدور بين كلٍ من الكائنات الفضائية والمفترسين.', 6.0, '["مغامرة", "خيال علمي", "حركة", "رعب"]'::jsonb, '[{"name": "سانا لاثان", "character": "Alexa Woods", "profile_path": "/mYrlBt33pPbdsgscTuWdHScu7md.jpg"}, {"name": "Lance Henriksen", "character": "Charles Bishop Weyland", "profile_path": "/1PkFmD5HdjmRa2DumtwINnnAjTH.jpg"}, {"name": "Ian Whyte", "character": "Scar", "profile_path": "/svlJyDgPbTHoGjbQKU4S2J6g5hi.jpg"}, {"name": "Raoul Bova", "character": "Sebastian de Rosa", "profile_path": "/hJQCTTCB6mCspjjhOkXQ5u0ekWj.jpg"}, {"name": "Ewen Bremner", "character": "Graeme Miller", "profile_path": "/u80rtfJRqCg4qKcdEPmYv8IkCvu.jpg"}]'::jsonb, 101) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXC