INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (423, 'series', 'رجل في قلب النار', 'Man on Fire', 'Man on Fire', 'man on fire', 2026, 223386, 'tv', '/9cZzmT8rhBXbZ1QFBPs3ggABYB3.jpg', '/dMCfHJRnAZfKoPTjYyZk2QCL8au.jpg', 'مثقلًا بآلام الماضي ومطاردًا من أعدائه، يقاتل جندي سابق في القوات الخاصة لحماية فتاة مراهقة في شوارع "ريو دي جانيرو" التي لا تعرف الرحمة.', 'مثقلًا بآلام الماضي ومطاردًا من أعدائه، يقاتل جندي سابق في القوات الخاصة لحماية فتاة مراهقة في شوارع "ريو دي جانيرو" التي لا تعرف الرحمة.', 7.4, '["حركة ومغامرة", "جريمة"]'::jsonb, '[{"name": "Yahya Abdul-Mateen II", "character": "John Creasy", "profile_path": "/79VdVjUoiYGcgjOT9UmE5XIpoZM.jpg"}, {"name": "Billie Boullet", "character": "Poe Rayburn", "profile_path": "/2T18NEAVoU8cWWpAtaI6fTrdolX.jpg"}, {"name": "Scoot McNairy", "character": "Henry Tappan", "profile_path": "/oP2LJEqupxVZ2XdEW1lN5Q5LF3M.jpg"}, {"name": "أليس براغا", "character": "Valeria Melo", "profile_path": "/d9JdgvUiqyWuGQLmozNfGZOpIBz.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (424, 'series', 'علاء الدين المسلسل', 'Aladdin', 'Aladdin', 'aladdin', 1994, 2745, 'tv', '/7uHmsNOPfAKm8bQA89RIk1afReN.jpg', '/jPyKuRjloYkjVWNPtXCrYxtg3Bu.jpg', 'تبدأ القصة مع السلطان الذي يبحث عن زوج لابنته بدر البدور، فيخطر في بال الوزير فكرة، فيفكر أن تتزوج بدر البدور من ابن الوزير. وفي مكان آخر اقشر واقيشر الذين يبحثون عن المصباح العجيب، ولكن يجب على شاب تنطبق عليه المواصفات أن يأخذه. وفي مكان آخر، قرر علاء الدين أن يخرج في سفر للتجارة، فباع دكان أبوه، وحاولت أمه أن تمنعه، ولكن التجار الذي اتفق معهم سرقوه وضاع في الغابة. وفي نفس الوقت هربت بدر البدور من القصر خوفا من مراسم الزواج من ابن الوزير.', 'تبدأ القصة مع السلطان الذي يبحث عن زوج لابنته بدر البدور، فيخطر في بال الوزير فكرة، فيفكر أن تتزوج بدر البدور من ابن الوزير. وفي مكان آخر اقشر واقيشر الذين يبحثون عن المصباح العجيب، ولكن يجب على شاب تنطبق عليه المواصفات أن يأخذه. وفي مكان آخر، قرر علاء الدين أن يخرج في سفر للتجارة، فباع دكان أبوه، وحاولت أمه أن تمنعه، ولكن التجار الذي اتفق معهم سرقوه وضاع في الغابة. وفي نفس الوقت هربت بدر البدور من القصر خوفا من مراسم الزواج من ابن الوزير.', 7.0, '["حركة ومغامرة", "رسوم متحركة", "كوميديا", "خيال علمي وفانتازيا", "أطفال"]'::jsonb, '[{"name": "Scott Weinger", "character": "Aladdin (voice)", "profile_path": "/5EvrWMz2xi3hOkrEMNGH2Rts2jz.jpg"}, {"name": "Linda Larkin", "character": "Jasmine (voice)", "profile_path": "/uN35v1Z374JvfdnDJBVmvnB2JNQ.jpg"}, {"name": "دان كاستلانيتا", "character": "Genie (voice)", "profile_path": "/AmeqWhP4A46AWkM4kVphg6jOTQX.jpg"}, {"name": "Gilbert Gottfried", "character": "Iago (voice)", "profile_path": "/hkkAgJD0HKcuyd8EuvhyN5vHcDQ.jpg"}, {"name": "فرانك ويلكر", "character": "Abu (voice)", "profile_path": "/aC37aQtsfZZDZN5y3paDTLJJHCi.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EX