INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (429, 'movie', 'ريدي بلاير وان', 'Ready Player One', 'Ready Player One', 'ready player one', 2018, 333339, 'movie', '/pU1ULUq8D3iRxl1fdX2lZIzdHuI.jpg', '/5a7lMDn3nAj2ByO0X1fg6BhUphR.jpg', 'في المستقبل القريب، يحاول الشاب المنبوذ (وايد) الهروب من رعبه اليومي عن طريق التحاقه بلعبة إلكترونية تُدعى (الواحة). وعندما يموت مؤسس اللعبة البليونير، تُعرَض ثروته على اللاعبين كجائزة لمن يصل إلى نقطة معينة باللعبة، يجد وايد نفسه مُحاصرًا بديون خصومه من الشركة؛ في الواقع وداخل اللعبة على حد سواء.', 'في المستقبل القريب، يحاول الشاب المنبوذ (وايد) الهروب من رعبه اليومي عن طريق التحاقه بلعبة إلكترونية تُدعى (الواحة). وعندما يموت مؤسس اللعبة البليونير، تُعرَض ثروته على اللاعبين كجائزة لمن يصل إلى نقطة معينة باللعبة، يجد وايد نفسه مُحاصرًا بديون خصومه من الشركة؛ في الواقع وداخل اللعبة على حد سواء.', 7.6, '["مغامرة", "حركة", "خيال علمي"]'::jsonb, '[{"name": "Tye Sheridan", "character": "Parzival / Wade", "profile_path": "/d5ZS2fjqC98cIGkhEGX0fRYhku4.jpg"}, {"name": "أوليفيا كوك", "character": "Art3mis / Samantha", "profile_path": "/wf71ctooNlVmiT8dxx0QmRAzyiX.jpg"}, {"name": "بن مندلسون", "character": "Sorrento", "profile_path": "/pA9mu9D2IolVA0v2Yo0tJm6uUyI.jpg"}, {"name": "Lena Waithe", "character": "Aech / Helen", "profile_path": "/yidK25mjpxTTYCICmZnxgks6utx.jpg"}, {"name": "تي جاي ميلر", "character": "I-R0k (voice)", "profile_path": "/rRrVvBxOkyYM5XdLXimShHR1Itn.jpg"}]'::jsonb, 140) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.