INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (430, 'movie', 'كوكو', 'Coco', 'Coco', 'coco', 2017, 354912, 'movie', '/SImOPMuE5fIbEziSd35VyUfHus.jpg', '/g7CHF8gTLGooTbP4GznIGwaqAGL.jpg', 'الاحتفال بالعمرINSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (431, 'movie', 'حكاية لعبة ٤', 'Toy Story 4', 'Toy Story 4', 'toy story 4', 2019, 301528, 'movie', '/ds8GyaDSW6RTlZIXlrh20Ja9VFY.jpg', '/q62bpQ67qaXY0u6b2wFEnQYIbPd.jpg', 'كان "وودي" دائمًا واثقًا من مكانته في العالم، ومكرّسًا نفسه لرعاية طفلِه، سواء كان "آندي" أو "بوني". لكن بعد أن تصنع "بوني" لعبة جديدة على مضض تُدعى "فوركي"، تخوض مغامرة على الطريق برفقة أصدقاء قدامى وجدد، فتتحدى كل ما يؤمن به "وودي" عن الوفاء والغاية، وما يعنيه حقًا أن تكون لعبة.', 'كان "وودي" دائمًا واثقًا من مكانته في العالم، ومكرّسًا نفسه لرعاية طفلِه، سواء كان "آندي" أو "بوني". لكن بعد أن تصنع "بوني" لعبة جديدة على مضض تُدعى "فوركي"، تخوض مغامرة على الطريق برفقة أصدقاء قدامى وجدد، فتتحدى كل ما يؤمن به "وودي" عن الوفاء والغاية، وما يعنيه حقًا أن تكون لعبة.', 7.5, '["عائلي", "كوميديا", "رسوم متحركة", "مغامرة"]'::jsonb, '[{"name": "توم هانكس", "character": "Woody (voice)", "profile_path": "/oFvZoKI6lvU03n4YoNGAll9rkas.jpg"}, {"name": "Tim Allen", "character": "Buzz Lightyear (voice)", "profile_path": "/woWhZzFILVhYMAvsPL171HjMY0y.jpg"}, {"name": "Annie Potts", "character": "Bo Peep (voice)", "profile_path": "/nugPVN28qOhOIoHawrDJ6fIfrxR.jpg"}, {"name": "توني هايل", "character": "Forky (voice)", "profile_path": "/3dEyZgTye0Ec17VGKp0mJ3aU6ty.jpg"}, {"name": "كيغان-مايكل كي", "character": "Ducky (voice)", "profile_path": "/xmdzYXP9j87a43FSiL138nLesuS.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (432, 'movie', 'البحث عن دوري', 'Finding Dory', 'Finding Dory', 'finding dory', 2016, 127380, 'movie', '/pFHAkjvImCq5pGggbTteUhAsInl.jpg', '/wijltj1toRcicHlCn8Cpsp4yPXe.jpg', 'بعد أن علما نيمو ووالده مارلن أن دوري عرفت مكان عائلتها يقرران مساعدتها في البحث، ويذهبان إلى كاليفورنيا من خلال التيار السريع بمساعدة السلاحف، وعند وصولهم إلى هُناك عانوا الصعوبات بعد أن واجهوا حباراً مُفترسا طاردهم حتى وصلوا إلى منطقة آمنة، ذهبت دوري إلى سطح الماء بعد أن سمعت صوتاً خفياً، لكنها اختُطفت من قِبل عمال المعهد البحري في مورو باي، وانفصلت عن نيمو ووالده', 'بعد أن علما نيمو ووالده مارلن أن دوري عرفت مكان عائلتها يقرران مساعدتها في البحث، ويذهبان إلى كاليفورنيا من خلال التيار السريع بمساعدة السلاحف، وعند وصولهم إلى هُناك عانوا الصعوبات بعد أن واجهوا حباراً مُفترسا طاردهم حتى وصلوا إلى منطقة آمنة، ذهبت دوري إلى سطح الماء بعد أن سمعت صوتاً خفياً، لكنها اختُطفت من قِبل عمال المعهد البحري في مورو باي، وانفصلت عن نيمو ووالده', 7.0, '["مغامرة", "رسوم متحركة", "عائلي"]'::jsonb, '[{"name": "ألين دي جينيريس", "character": "Dory (voice)", "profile_path": "/z8IEEid4z63CBlJtxrTKEfsW7NA.jpg"}, {"name": "Albert Brooks", "character": "Marlin (voice)", "profile_path": "/8iDSGu5l93N7benjf6b3AysBore.jpg"}, {"name": "إد أونيل", "character": "Hank (voice)", "profile_path": "/4RrxSno3UEtGWuMm4yJoaFzckpL.jpg"}, {"name": "Hayden Rolence", "character": "Nemo (voice)", "profile_path": "/7VVdyfGSiq9asqfaUw4gDBLopun.jpg"}, {"name": "ديان كيتون", "character": "Jenny (voice)", "profile_path": "/A8B3BsFgbmw2WEmJuQX38qeU9eR.jpg"}]'::jsonb, 97) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id,