INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (433, 'movie', 'ملكة الثلج', 'Frozen', 'Frozen', 'frozen', 2013, 109445, 'movie', '/Mj9orZts8X8mZLvOwXjGCP9DTA.jpg', '/rj58WQ9ImI0mYDptXdM7euX1Wjt.jpg', 'تحلم الأميرة الشابة آنا من أرينديل بالعثور على الحب الحقيقي في تتويج أختها إلسا. يأخذها القدر في رحلة خطيرة في محاولة لإنهاء الشتاء الأبدي الذي سقط على المملكة. يرافقها رجل توصيل الثلج كريستوف ، الرنة سفين ، ورجل الثلج أولاف. في مغامرة حيث ستكتشف ما تعنيه الصداقة والشجاعة والأسرة والحب الحقيقي حقا.', 'تحلم الأميرة الشابة آنا من أرينديل بالعثور على الحب الحقيقي في تتويج أختها إلسا. يأخذها القدر في رحلة خطيرة في محاولة لإنهاء الشتاء الأبدي الذي سقط على المملكة. يرافقها رجل توصيل الثلج كريستوف ، الرنة سفين ، ورجل الثلج أولاف. في مغامرة حيث ستكتشف ما تعنيه الصداقة والشجاعة والأسرة والحب الحقيقي حقا.', 7.2, '["رسوم متحركة", "عائلي", "مغامرة", "فانتازيا"]'::jsonb, '[{"name": "كريستين بيل", "character": "Anna (voice)", "profile_path": "/rP74dJXl7EjinGM0shQtUOlH5s2.jpg"}, {"name": "Idina Menzel", "character": "Elsa (voice)", "profile_path": "/eGsyJmAZNV5tUU4RYy2DIRlFVpW.jpg"}, {"name": "جوناثان غروف", "character": "Kristoff (voice)", "profile_path": "/3kmnYKAzSc3Lp7iK5pcj97Hx9Cm.jpg"}, {"name": "جوش غاد", "character": "Olaf (voice)", "profile_path": "/17iKlfWZBDTAucqjkhRKHr9xjIz.jpg"}, {"name": "Santino Fontana", "character": "Hans (voice)", "profile_path": "/3EtNGPVBN5bBamV817n43kFd4MB.jpg"}]'::jsonb, 102) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = E