INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (434, 'movie', 'طلب زواج', 'The Proposal', 'The Proposal', 'the proposal', 2009, 18240, 'movie', '/6stnAm1wSek8ZrislwK4xGTyCnt.jpg', '/ojgXOhVi9Yk8irDpRfDkIzdD1LK.jpg', 'تلجأ مديرة تحرير بدار نشر لطلب الزواج من موظف تحت قيادتها، لتتمكن من الحفاظ على الإقامة في الولايات المتحدة، فتبدأ في التودد إليه رغم شخصيتها الحازمة.', 'تلجأ مديرة تحرير بدار نشر لطلب الزواج من موظف تحت قيادتها، لتتمكن من الحفاظ على الإقامة في الولايات المتحدة، فتبدأ في التودد إليه رغم شخصيتها الحازمة.', 7.2, '["كوميديا", "رومنسية", "دراما"]'::jsonb, '[{"name": "Sandra Bullock", "character": "Margaret Tate", "profile_path": "/4rfjISL3Flx16jfiusXoHbpt87X.jpg"}, {"name": "رايان رينولدز", "character": "Andrew Paxton", "profile_path": "/trzgptffGvAlAT6MEu01fz47cLW.jpg"}, {"name": "مالين أكرمان", "character": "Gertrude", "profile_path": "/u38qRcCAiO3SZdFKJKx3fncDyef.jpg"}, {"name": "كريج تي نيلسون", "character": "Joe Paxton", "profile_path": "/rMh8qdexFKmc7mq7oLzsLLvCCjs.jpg"}, {"name": "ماري ستينبرجن", "character": "Grace Paxton", "profile_path": "/yJhfuqS3yXW7kLSyvRU6n3b35mq.jpg"}]'::jsonb, 108) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (435, 'movie', 'ليلة في المتحف', 'Night at the Museum', 'Night at the Museum', 'night at the museum', 2006, 1593, 'movie', '/pDsAAYf6Zn0yiAGJ6lYGs6hoZ4E.jpg', '/1ZVlzOBYCggLzvVYHK7Im6LohjC.jpg', 'تسود الفوضى في متحف التاريخ الطبيعي عندما يثير الحارس الليلي لاري دالي عن طريق الخطأ لعنة قديمة ، ويوقظ أتيلا الهون وجيشًا من المصارعين وديناصور ريكس ومعروضات أخرى.', 'تسود الفوضى في متحف التاريخ الطبيعي عندما يثير الحارس الليلي لاري دالي عن طريق الخطأ لعنة قديمة ، ويوقظ أتيلا الهون وجيشًا من المصارعين وديناصور ريكس ومعروضات أخرى.', 6.6, '["فانتازيا", "عائلي", "كوميديا"]'::jsonb, '[{"name": "بن ستيلر", "character": "Larry Daley", "profile_path": "/scgpxhI05JpdNXXfmpK6z0rPOWN.jpg"}, {"name": "Carla Gugino", "character": "Rebecca", "profile_path": "/dAqGOsHSzlP6RhaUURX2NrwITaq.jpg"}, {"name": "ديك فان دايك", "character": "Cecil", "profile_path": "/jXAeNx7mYdirzMHcqPyj5VXxcXi.jpg"}, {"name": "Mickey Rooney", "character": "Gus", "profile_path": "/eYuayEC3xhXQf3Z1Cy6AVMEcgZb.jpg"}, {"name": "Bill Cobbs", "character": "Reginald", "profile_path": "/xRBrI4rPkZuMBMDh8GPke20ZgUv.jpg"}]'::jsonb, 108) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (436, 'movie', 'لا لا لاند', 'La La Land', 'La La Land', 'la la land', 2016, 313369, 'movie', '/ff0zxwoyaG95kytpMuTVseDndIE.jpg', '/nlPCdZlHtRNcF6C9hzUH4ebmV1w.jpg', 'تقدم ميا ، الممثلة الطموحة ، اللاتيه لنجوم السينما بين الاختبارات وسيباستيان ، موسيقي الجاز ، يخدش من خلال لعب حفلات الكوكتيل في الحانات الصغيرة ، ولكن مع تزايد النجاح ، يواجهون قرارات تبدأ بإفساد النسيج الهش لحبهم. والأحلام التي عملوا بجد للحفاظ عليها في بعضهم البعض تهدد بتمزيقهم.', 'تقدم ميا ، الممثلة الطموحة ، اللاتيه لنجوم السينما بين الاختبارات وسيباستيان ، موسيقي الجاز ، يخدش من خلال لعب حفلات الكوكتيل في الحانات الصغيرة ، ولكن مع تزايد النجاح ، يواجهون قرارات تبدأ بإفساد النسيج الهش لحبهم. والأحلام التي عملوا بجد للحفاظ عليها في بعضهم البعض تهدد بتمزيقهم.', 7.9, '["كوميديا", "دراما", "رومنسية"]'::jsonb, '[{"name": "رايان غوسلينغ", "character": "Sebastian", "profile_path": "/lyUyVARQKhGxaxy0FbPJCQRpiaW.jpg"}, {"name": "إيما ستون", "character": "Mia", "profile_path": "/cZ8a3QvAnj2cgcgVL6g4XaqPzpL.jpg"}, {"name": "جون لجند", "character": "Keith", "profile_path": "/cCv0YBy2YFFWp9h3kvNPmwWwrCD.jpg"}, {"name": "روزماري ديويت", "character": "Laura", "profile_path": "/44sxIdGtYN24R14OmnZbCpcd8J8.jpg"}, {"name": "Finn Wittrock", "character": "Greg", "profile_path": "/gwGMGTmli0uBF7eAhhXePWhYNFJ.jpg"}]'::jsonb, 129) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXC