INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (437, 'movie', 'رجل حر', 'Free Guy', 'Free Guy', 'free guy', 2021, 550988, 'movie', '/27RSsd5qG479jl4sjdJJWdjt9OY.jpg', '/rOJb0yQOCny0bPjg8bCLw8DyAD7.jpg', 'يعيش "جاي" في عالم غريب بمهنة صراف في أحد البنوك، وتزداد مخاوفه في الحياة حينما يشك أنه يعيش داخل لعبة فيديو، ليدخل في سباق مع الزمن لإنقاذ لعبة الفيديو قبل قيام مطوريها بإغلاقها.', 'يعيش "جاي" في عالم غريب بمهنة صراف في أحد البنوك، وتزداد مخاوفه في الحياة حينما يشك أنه يعيش داخل لعبة فيديو، ليدخل في سباق مع الزمن لإنقاذ لعبة الفيديو قبل قيام مطوريها بإغلاقها.', 7.4, '["كوميديا", "مغامرة", "خيال علمي"]'::jsonb, '[{"name": "رايان رينولدز", "character": "Guy", "profile_path": "/trzgptffGvAlAT6MEu01fz47cLW.jpg"}, {"name": "جودي كومر", "character": "Millie Rusk / Molotovgirl", "profile_path": "/AfsBpnfw0E2h8NZK4zkFcOjYlEb.jpg"}, {"name": "ليل ريل هوري", "character": "Buddy", "profile_path": "/9MDi35Fy6ym7SYbO3B04vf1vBnm.jpg"}, {"name": "جو كيري", "character": "Keys", "profile_path": "/ayIAVLMfZGEGIFwAo3pPnY7p59.jpg"}, {"name": "Utkarsh Ambudkar", "character": "Mouser", "profile_path": "/vUW5bFrkjWikNFzh5B6F11r5C3X.jpg"}]'::jsonb, 115) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (438, 'movie', 'قلباً وقالباً', 'Inside Out', 'Inside Out', 'inside out', 2015, 150540, 'movie', '/sCoh9F6BRsvvkYwFNNlKvIla6sQ.jpg', '/o3i6AfTcWAuNvzAUV3q5lOmi6Gx.jpg', 'عندما تنتقل "رايلي" البالغة من العمر 11 عامًا إلى مدينة جديدة، تتعاون مشاعرها الداخلية لمساعدتها على التأقلم مع التغيير. يعمل كل من "الفرح" و"الخوف" و"الغضب" و"الاشمئزاز" و"الحزن" معًا للحفاظ على توازنها، لكن بعد أن يضيع "الفرح" و"الحزن"، ينطلقان في رحلة عبر أماكن غريبة وغير مألوفة في محاولة للعودة إلى موطنهما داخل عقل "رايلي".', 'عندما تنتقل "رايلي" البالغة من العمر 11 عامًا إلى مدينة جديدة، تتعاون مشاعرها الداخلية لمساعدتها على التأقلم مع التغيير. يعمل كل من "الفرح" و"الخوف" و"الغضب" و"الاشمئزاز" و"الحزن" معًا للحفاظ على توازنها، لكن بعد أن يضيع "الفرح" و"الحزن"، ينطلقان في رحلة عبر أماكن غريبة وغير مألوفة في محاولة للعودة إلى موطنهما داخل عقل "رايلي".', 7.9, '["رسوم متحركة", "عائلي", "مغامرة", "دراما", "كوميديا"]'::jsonb, '[{"name": "آيمي بولر", "character": "Joy (voice)", "profile_path": "/rwmvRonpluV6dCPiQissYrchvSD.jpg"}, {"name": "فيليس سميث", "character": "Sadness (voice)", "profile_path": "/h9w9pQbiderRWAC2mi7spjzuIGz.jpg"}, {"name": "ريتشارد كيند", "character": "Bing Bong (voice)", "profile_path": "/yWmuVQeQUzb5OSMVDoWkR0IylCK.jpg"}, {"name": "بيل هادر", "character": "Fear (voice)", "profile_path": "/qyT50vQ9PQIEctE1IxDTEsBKstU.jpg"}, {"name": "Lewis Black", "character": "Anger (voice)", "profile_path": "/f6660RU8eG10Rrk0Fnfih90b0ME.jpg"}]'::jsonb, 95) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdro