INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (439, 'movie', 'حكاية لعبة ٣', 'Toy Story 3', 'Toy Story 3', 'toy story 3', 2010, 10193, 'movie', '/jV4eWv8jPH5uLa5yNUfRqWdWZTG.jpg', '/uAfhsySkr1UzQg1zdg3dZQRz9Fd.jpg', 'لم يلعب "آندي" بـ"وودي" و"باز" وبقية ألعابه منذ سنوات. ومع استعداد "آندي" للذهاب إلى الجامعة، تجد المجموعة نفسها قد تُركت عن طريق الخطأ في مركز رعاية نهارية مشبوه. يتعين على الألعاب أن تتكاتف للهروب والعودة إلى منزل "آندي".', 'لم يلعب "آندي" بـ"وودي" و"باز" وبقية ألعابه منذ سنوات. ومع استعداد "آندي" للذهاب إلى الجامعة، تجد المجموعة نفسها قد تُركت عن طريق الخطأ في مركز رعاية نهارية مشبوه. يتعين على الألعاب أن تتكاتف للهروب والعودة إلى منزل "آندي".', 7.8, '["رسوم متحركة", "عائلي", "كوميديا"]'::jsonb, '[{"name": "توم هانكس", "character": "Woody (voice)", "profile_path": "/oFvZoKI6lvU03n4YoNGAll9rkas.jpg"}, {"name": "Tim Allen", "character": "Buzz Lightyear (voice)", "profile_path": "/woWhZzFILVhYMAvsPL171HjMY0y.jpg"}, {"name": "Joan Cusack", "character": "Jessie (voice)", "profile_path": "/59UIeHZFYrKyP20lXqijtfTXglO.jpg"}, {"name": "Don Rickles", "character": "Mr. Potato Head (voice)", "profile_path": "/iGMOVxIQoTPepRvqSCtRulfpx7u.jpg"}, {"name": "والاس شون", "character": "Rex (voice)", "profile_path": "/wVaM1WlFKDce4esThwL4XtNLhOe.jpg"}]'::jsonb, 103) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (440, 'movie', 'خلطبيطة بالصلصة', 'Ratatouille', 'Ratatouille', 'ratatouille', 2007, 2062, 'movie', '/lBfftNxNUTvuWyVnhvQuvj2IOnI.jpg', '/qxGmHvmjlBlH5WZOhdHEHAjHaMB.jpg', '"ريمي"، فأر يمتلك حاسة تذوق أكثر رُقيًا بكثير من بقية أبناء فصيلته. يحلم بأن يصبح طاهيًا، طاهيًا يبتكر الأطباق بدلًا من البحث عن بقايا الطعام. وعندما تقوده الأقدار إلى ما تحت أحد أرقى مطاعم باريس، يُقيم تحالفًا غير مألوف مع أحد العاملين الشباب في المطبخ، ساعيًا إلى تحقيق طموحاته في فن الطهي.  ومع انكشاف حياته المزدوجة، يجد "ريمي" نفسه مضطرًا للتعامل مع شكوك رئيس الطهاة المتحذلق "سكينر"، ورفض مستعمرته الخاصة له، والحضور المثير للرهبة لناقد الطعام الشهير "أنتون إيغو"، الذي يمكن لحكمه أن يصنع مستقبل الطاهي أو يحطمه.', '"ريمي"، فأر يمتلك حاسة تذوق أكثر رُقيًا بكثير من بقية أبناء فصيلته. يحلم بأن يصبح طاهيًا، طاهيًا يبتكر الأطباق بدلًا من البحث عن بقايا الطعام. وعندما تقوده الأقدار إلى ما تحت أحد أرقى مطاعم باريس، يُقيم تحالفًا غير مألوف مع أحد العاملين الشباب في المطبخ، ساعيًا إلى تحقيق طموحاته في فن الطهي.  ومع انكشاف حياته المزدوجة، يجد "ريمي" نفسه مضطرًا للتعامل مع شكوك رئيس الطهاة المتحذلق "سكينر"، ورفض مستعمرته الخاصة له، والحضور المثير للرهبة لناقد الطعام الشهير "أنتون إيغو"، الذي يمكن لحكمه أن يصنع مستقبل الطاهي أو يحطمه.', 7.8, '["رسوم متحركة", "كوميديا", "عائلي", "فانتازيا"]'::jsonb, '[{"name": "باتن أوزوالت", "character": "Remy (voice)", "profile_path": "/ljQvjbPmcIAl205Lb2Mu4CW8WO7.jpg"}, {"name": "إيان هولم", "character": "Skinner (voice)", "profile_path": "/cOJDgvgj4nMec6Inzj1H5nugTO5.jpg"}, {"name": "Lou Romano", "character": "Linguini (voice)", "profile_path": "/1qOuqRzlp5BghzTkYSN3MsaEXgF.jpg"}, {"name": "Brian Dennehy", "character": "Django (voice)", "profile_path": "/cg7CwS1vMJXCzZ0FUm4RbrjAJ2t.jpg"}, {"name": "بيتر سوهن", "character": "Emile (voice)", "profile_path": "/8cQGViF2lXlcsAIvFUMWboXYXIu.jpg"}]'::jsonb, 111) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
