INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (443, 'movie', 'سبايدرمان: بعيدًا عن الوطن', 'Spider-Man: Far From Home', 'Spider-Man: Far From Home', 'spider man far from home', 2019, 429617, 'movie', '/cPEwCfmwZMKuOWKvj7tDVlbiGJp.jpg', '/vamhMTvh9m9zFHDoR0v1nRtf6T4.jpg', 'يواجه بيتر باركر، البطل الخارق المحبوب سبايدرمان، أربعة وحوش عنصرية مدمرة أثناء عطلته في أوروبا. وسرعان ما يتلقى المساعدة من ميستيريو، بطل آخر ذو أصول غامضة.', 'يواجه بيتر باركر، البطل الخارق المحبوب سبايدرمان، أربعة وحوش عنصرية مدمرة أثناء عطلته في أوروبا. وسرعان ما يتلقى المساعدة من ميستيريو، بطل آخر ذو أصول غامضة.', 7.4, '["حركة", "مغامرة", "خيال علمي"]'::jsonb, '[{"name": "توم هولاند", "character": "Peter Parker / Spider-Man", "profile_path": "/xKBAaPIa1c7tzZD3Y0MhBLv4hPE.jpg"}, {"name": "جيك جيلنهال", "character": "Quentin Beck / Mysterio", "profile_path": "/ct2Gh2sJSxd4yaMrSsqSt1HpIC3.jpg"}, {"name": "صامويل جاكسون", "character": "Nick Fury", "profile_path": "/qdfRtvPCj51C9Uy5VEgjgj69JyV.jpg"}, {"name": "ماريسا تومي", "character": "May Parker", "profile_path": "/vAQ10fvGfVyuJdMNKVMA4ZkacWL.jpg"}, {"name": "جون فافرو", "character": "Happy Hogan", "profile_path": "/tnx7iMVydPQXGOoLsxXl84PXtbA.jpg"}]'::jsonb, 129) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (444, 'movie', 'مغامرة ذاتية', 'Soul', 'Soul', 'soul', 2020, 508442, 'movie', '/tYdEoMovmyUnQ6DyUvtCHomVGly.jpg', '/rQaHA74pevnGsxcKGaoZVGWe9TC.jpg', 'هل كل هذا العيش يستحق الموت حقا؟  جو غاردنر مدرس في مدرسة إعدادية يحب موسيقى الجاز. بعد تجربة ناجحة في نادي "هاف نوت" ، يتعرض فجأة لحادث يفصل روحه عن جسده ويتم نقله إلى ندوة أنت، وهو مركز تتطور فيه الأرواح وتكتسب العواطف قبل نقلها إلى طفل حديث الولادة. يجب على جو طلب المساعدة من النفوس الأخرى في التدريب ، مثل 22 ، وهي روح أمضت دهورا في ندوة أنت، من أجل العودة إلى الأرض.', 'هل كل هذا العيش يستحق الموت حقا؟  جو غاردنر مدرس في مدرسة إعدادية يحب موسيقى الجاز. بعد تجربة ناجحة في نادي "هاف نوت" ، يتعرض فجأة لحادث يفصل روحه عن جسده ويتم نقله إلى ندوة أنت، وهو مركز تتطور فيه الأرواح وتكتسب العواطف قبل نقلها إلى طفل حديث الولادة. يجب على جو طلب المساعدة من النفوس الأخرى في التدريب ، مثل 22 ، وهي روح أمضت دهورا في ندوة أنت، من أجل العودة إلى الأرض.', 8.1, '["رسوم متحركة", "عائلي", "دراما", "موسيقى", "فانتازيا"]'::jsonb, '[{"name": "جيمي فوكس", "character": "Joe Gardner (voice)", "profile_path": "/zD8Nsy4Xrghp7WunwpCj5JKBPeU.jpg"}, {"name": "تينا فاي", "character": "22 (voice)", "profile_path": "/yPTAi1iucXf85UpiFPtyiTSM6do.jpg"}, {"name": "Graham Norton", "character": "Moonwind (voice)", "profile_path": "/zndDiPrNXtbxGLVhFhSlpCkaHIH.jpg"}, {"name": "ريتشيل هاوس", "character": "Terry (voice)", "profile_path": "/2LCQF7Bn0I91o17GGkox0ZhhbE7.jpg"}, {"name": "أليس براغا", "character": "Counselor Jerry (voice)", "profile_path": "/d9JdgvUiqyWuGQLmozNfGZOpIBz.jpg"}]'::jsonb, 101) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXC