INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (445, 'movie', 'فوق', 'Up', 'Up', 'up', 2009, 14160, 'movie', '/fPtAMZkhSZuz71XVm94F1n6f1oZ.jpg', '/hGGC9gKo7CFE3fW07RA587e5kol.jpg', 'الفيلم يتحدث عن ذكريات العجوز كارل فريدريكسون (كرم فَريد زين في النسخة العربية) البالغ 87 عاماً الذي حلم طيلة حياته هو وزوجته أن يزورا حدائق وغابات أمريكا الجنوبية، إلا أنها توفيت قبل أن يحقق لها ما تريد، فيقرر الذهاب إلى هناك مباشرة. ولأنه كان بائعا للبالون يقرر السفر إلى هناك مع منزله الذي يحمل معه كل ذكرياته، بأن يرفع البيت بعدد كبير من البالون المليء بالهيليوم ويبحر به كالمنطاد. ومع انطلاقه فوق لا يلاحظ العجوز أن أحد الأطفال الفضوليين قد تعلق بشرفة المنزل وارتفع معه. وهنا تبدأ المغامرة حيث رجل عجوز وطفل شقي في مغامرة بغابات وأدغال فنزويلا.', 'الفيلم يتحدث عن ذكريات العجوز كارل فريدريكسون (كرم فَريد زين في النسخة العربية) البالغ 87 عاماً الذي حلم طيلة حياته هو وزوجته أن يزورا حدائق وغابات أمريكا الجنوبية، إلا أنها توفيت قبل أن يحقق لها ما تريد، فيقرر الذهاب إلى هناك مباشرة. ولأنه كان بائعا للبالون يقرر السفر إلى هناك مع منزله الذي يحمل معه كل ذكرياته، بأن يرفع البيت بعدد كبير من البالون المليء بالهيليوم ويبحر به كالمنطاد. ومع انطلاقه فوق لا يلاحظ العجوز أن أحد الأطفال الفضوليين قد تعلق بشرفة المنزل وارتفع معه. وهنا تبدأ المغامرة حيث رجل عجوز وطفل شقي في مغامرة بغابات وأدغال فنزويلا.', 8.0, '["رسوم متحركة", "كوميديا", "عائلي", "مغامرة"]'::jsonb, '[{"name": "Ed Asner", "character": "Carl Fredricksen (voice)", "profile_path": "/AeVizz1AfAB2TbsfyzgBvqeSR3G.jpg"}, {"name": "كريستوفر بلامر", "character": "Charles Muntz (voice)", "profile_path": "/u0YBwss0ebEUp8sjRtQKnK2wZdR.jpg"}, {"name": "Jordan Nagai", "character": "Russell (voice)", "profile_path": "/j1kVS2sI3wWIHCCzzYD1buXAP9e.jpg"}, {"name": "Bob Peterson", "character": "Dug / Alpha (voice)", "profile_path": "/dJe3nTCIToebjj1WHFHP7LmZKyk.jpg"}, {"name": "ديلروي ليندو", "character": "Beta (voice)", "profile_path": "/kLwUBBmEIdchrLqwsYzgLB2B6q5.jpg"}]'::jsonb, 96) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (446, 'movie', 'شركة المرعبين المحدودة', 'Monsters, Inc.', 'Monsters, Inc.', 'monsters inc', 2001, 585, 'movie', '/oLKR5TveXBdAI50TpxXS1hURG9Y.jpg', '/sDTnMOJ3H5wI38OxObmCtK7wfd5.jpg', 'تدور أحداث الفيلم عن مدينة للوحوش. شركة المرعبين المحدودة هي شركة توليد الطاقة للمدينة، والتي تستعمل كمصدر للطاقة صراخ الأطفال، لهذا يحاولون تخويفهم. وفي محاولة أحد الموظفين (راندل) بالاتفاق مع مدير الشركة أبو عنكبوت لتوفير الطاقة والتي أصبحت الشركة تعانى من قلتها بسبب عدم خوف الاطفال من المخوفاتيه يقوم هذا الموظف باختراع جهاز مهمته أن يأخذ الصراخ من الأطفال بالقوه. يكتشف شلبى سلوفان عن وجود باب بعد ساعات العمل، ومن هذا الباب تدخل طفله إلى مدينة المرعبيين. وهنا تبدأ الأحداث حيث يسعى شلبى سلوفان وماردوشوشنى إلى إعادة الطفلة إلى بيتها في ظل مطاردة من اندل للقبض على الطفلة وتجربة الجهاز عليها. أثناء هذه المطاردة يكتشفون ان مدير الشركة أبو عنكبوت مشترك في هذه الجريمة. وبعد عدة أحداث يتم القبض على أبو عنكبوت ويتم نفى اندل إلى عالم البشر. كما يكتشفون مصدر جديد للطاقة بدلا من تخويف وهو الضحك. ويستلم شلبى سلوفان إدارة الشركة والتي تعود للنمو من جديد.', 'تدور أحداث الفيلم عن مدينة للوحوش. شركة المرعبين المحدودة هي شركة توليد الطاقة للمدينة، والتي تستعمل كمصدر للطاقة صراخ الأطفال، لهذا يحاولون تخويفهم. وفي محاولة أحد الموظفين (راندل) بالاتفاق مع مدير الشركة أبو عنكبوت لتوفير الطاقة والتي أصبحت الشركة تعانى من قلتها بسبب عدم خوف الاطفال من المخوفاتيه يقوم هذا الموظف باختراع جهاز مهمته أن يأخذ الصراخ من الأطفال بالقوه. يكتشف شلبى سلوفان عن وجود باب بعد ساعات العمل، ومن هذا الباب تدخل طفله إلى مدينة المرعبيين. وهنا تبدأ الأحداث حيث يسعى شلبى سلوفان وماردوشوشنى إلى إعادة الطفلة إلى بيتها في ظل مطاردة من اندل للقبض على الطفلة وتجربة الجهاز عليها. أثناء هذه المطاردة يكتشفون ان مدير الشركة أبو عنكبوت مشترك في هذه الجريمة. وبعد عدة أحداث يتم القبض على أبو عنكبوت ويتم نفى اندل إلى عالم البشر. كما يكتشفون مصدر جديد للطاقة بدلا من تخويف وهو الضحك. ويستلم شلبى سلوفان إدارة الشركة والتي تعود للنمو من جديد.', 7.9, '["رسوم متحركة", "كوميديا", "عائلي", "فانتازيا"]'::jsonb, '[{"name": "John Goodman", "character": "Sullivan (voice)", "profile_path": "/yyYqoyKHO7hE1zpgEV2XlqYWcNV.jpg"}, {"name": "بيلي كريستال", "character": "Mike (voice)", "profile_path": "/jfcCceTnP7rrHz1pSjCxiqRosw3.jpg"}, {"name": "Mary Gibbs", "character": "Boo (voice)", "profile_path": "/nqYOXIaf8ztfacrludRtS1Bytzz.jpg"}, {"name": "ستيف بوشيمي", "character": "Randall (voice)", "profile_path": "/n0pZumkrcZrAPMoPq684RhYnjPV.jpg"}, {"name": "James Coburn", "character": "Waternoose (voice)", "profile_path": "/9GApjInyrVvjnTAr652C1aViPqZ.jpg"}]'::jsonb, 92) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (447, 'movie', 'الشيطان يرتدي برادا', 'The Devil Wears Prada', 'The Devil Wears Prada', 'the devil wears prada', 2006, 350, 'movie', '/8912AsVuS7Sj915apArUFbv6F9L.jpg', '/gkh6Nt8DtY1XT4gQsyFq9XAVJlJ.jpg', 'تطمح (أندريا) المتخرجة حديثًا للعمل في إحدي مجلات الموضة، وتقبل للعمل بأحد أشهر تلك المجلات، ولكن للعمل كمساعدة ثانية لرئيسة التحرير (ميراندا)، ولكي تضمن أندريا الحفاظ على وظيفتها المستقبلية، عليها أن تنال رضا رئيستها المتسلطة والقوية.', 'تطمح (أندريا) المتخرجة حديثًا للعمل في إحدي مجلات الموضة، وتقبل للعمل بأحد أشهر تلك المجلات، ولكن للعمل كمساعدة ثانية لرئيسة التحرير (ميراندا)، ولكي تضمن أندريا الحفاظ على وظيفتها المستقبلية، عليها أن تنال رضا رئيستها المتسلطة والقوية.', 7.4, '["دراما", "كوميديا"]'::jsonb, '[{"name": "Meryl Streep", "character": "Miranda Priestly", "profile_path": "/g5cVxQBAQ3AXt3LhdBXtbbN47Uc.jpg"}, {"name": "آن هاثاواي", "character": "Andy Sachs", "profile_path": "/nbccV2pMoyLTCeg5DQip24Eq0Jp.jpg"}, {"name": "إيميلي بلنت", "character": "Emily", "profile_path": "/5nCSG5TL1bP1geD8aaBfaLnLLCD.jpg"}, {"name": "ستانلي توتشي", "character": "Nigel", "profile_path": "/q4TanMDI5Rgsvw4SfyNbPBh4URr.jpg"}, {"name": "سايمون بيكر", "character": "Christian Thompson", "profile_path": "/oay0Lo2zl0lJdguptxgx1BK9Xq7.jpg"}]'::jsonb, 109) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (448, 'movie', 'أفاتار', 'Avatar', 'Avatar', 'avatar', 2009, 19995, 'movie', '/8Zhq0uyk9MLaqJNW3EhDHepAFSP.jpg', '/vL5LR6WdxWPjLPFRLe133jXWsh5.jpg', 'في القرن الثاني والعشرين، يُرسَل جندي سابق من مشاة البحرية الأمريكية، يعاني من شلل في ساقيه، إلى قمر يُدعى باندورا في مهمة فريدة من نوعها. لكن مع مرور الوقت، يجد نفسه ممزقًا بين تنفيذ الأوامر التي تلقّاها وبين حماية حضارة غريبة أصبحت تعني له الكثير.', 'في القرن الثاني والعشرين، يُرسَل جندي سابق من مشاة البحرية الأمريكية، يعاني من شلل في ساقيه، إلى قمر يُدعى باندورا في مهمة فريدة من نوعها. لكن مع مرور الوقت، يجد نفسه ممزقًا بين تنفيذ الأوامر التي تلقّاها وبين حماية حضارة غريبة أصبحت تعني له الكثير.', 7.6, '["خيال علمي", "حركة", "مغامرة"]'::jsonb, '[{"name": "سام ورذينجتن", "character": "Jake Sully", "profile_path": "/mflBcox36s9ZPbsZPVOuhf6axaJ.jpg"}, {"name": "زوي سالدانا", "character": "Neytiri", "profile_path": "/vQBwmsSOAd0JDaEcZ5p43J9xzsY.jpg"}, {"name": "Sigourney Weaver", "character": "Dr. Grace Augustine", "profile_path": "/wTSnfktNBLd6kwQxgvkqYw6vEon.jpg"}, {"name": "Stephen Lang", "character": "Colonel Miles Quaritch", "profile_path": "/gnO5VfkDgA2fsHweD0622LUY3Hu.jpg"}, {"name": "Michelle Rodriguez", "character": "Trudy Chacon", "profile_path": "/wVcbrae4eRqGMFZz8Eh52Dl1biP.jpg"}]'::jsonb, 162) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (449, 'movie', 'إنكانتو', 'Encanto', 'Encanto', 'encanto', 2021, 568124, 'movie', '/3Ndm4UkVOmuEYTwRoSJh4BCR9rq.jpg', '/3G1Q5xF40HkUBJXxt2DQgQzKTp5.jpg', 'قصة غير عادية تدور حول "آل مادريغال" الذين يعيشون في الخفاء على جبال "كولومبيا" في منزل سحري في بلدة نابضة بالحياة في مكان ساحر عجيب اسمه "إنكانتو". سحر "إنكانتو" بارك كل طفل في العائلة بهبة مميزة بدءاً من القوة الخارقة إلى القدرة على الشفاء باستثناء طفلة واحدة وهي "ميرابيل". لكن عندما تكتشف أن السحر المحيط بـ"إنكانتو" في خطر، تقرر بصفتها الوحيدة العادية في العائلة أنها قد تكون بارقة الأمل الأخيرة لعائلتها الاستثنائية.', 'قصة غير عادية تدور حول "آل مادريغال" الذين يعيشون في الخفاء على جبال "كولومبيا" في منزل سحري في بلدة نابضة بالحياة في مكان ساحر عجيب اسمه "إنكانتو". سحر "إنكانتو" بارك كل طفل في العائلة بهبة مميزة بدءاً من القوة الخارقة إلى القدرة على الشفاء باستثناء طفلة واحدة وهي "ميرابيل". لكن عندما تكتشف أن السحر المحيط بـ"إنكانتو" في خطر، تقرر بصفتها الوحيدة العادية في العائلة أنها قد تكون بارقة الأمل الأخيرة لعائلتها الاستثنائية.', 7.6, '["رسوم متحركة", "كوميديا", "عائلي", "فانتازيا"]'::jsonb, '[{"name": "ستيفاني بياتريس", "character": "Mirabel Madrigal (voice)", "profile_path": "/7gNPOlsVIdg7QQOv1gRfHjv1Sdb.jpg"}, {"name": "María Cecilia Botero", "character": "Abuela Alma Madrigal (voice)", "profile_path": "/nH6eBBgv1PI9J6Ftkn01ny1TMt1.jpg"}, {"name": "جون ليجويزامو", "character": "Bruno Madrigal (voice)", "profile_path": "/kwYCdxTlDh9zauUCg4mp2XTCQTw.jpg"}, {"name": "Diane Guerrero", "character": "Isabela Madrigal (voice)", "profile_path": "/suyRRuMIjBdAzTxdFM7U9zHMPTv.jpg"}, {"name": "Jess Darrow", "character": "Luisa Madrigal (voice)", "profile_path": "/rJojc1ZUasEnUxSk7lL42RxyQbP.jpg"}]'::jsonb, 102) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
