INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (451, 'series', 'ذئاب الجبل', 'ذئاب الجبل', 'ذئاب الجبل', 'مسلسل ذئاب الجبل', 1993, 90993, 'tv', '/ylANiaoNJspwMJaC0VX8GmOIZZh.jpg', '/tl5XZpbS2qxT6ZqV9sJMCFzrqci.jpg', 'يحكي المسلسل عن الصعيد المصري وتقاليده وعاداته والعصبية الشديدة التي تحوي هذا المجتمع وهذا في إطار قصة بلدة  تسمى بهتون الجبل التي تحوي عائلة هوارة التي تحتوي العديد من العادات العصبية والتي قام فيها الشيخ بدار بمخالفة ا لعادات والتقاليد  وزوج ابنته الي رجل غريب عن العائلة. وسط رفض اخيها.', 'يحكي المسلسل عن الصعيد المصري وتقاليده وعاداته والعصبية الشديدة التي تحوي هذا المجتمع وهذا في إطار قصة بلدة  تسمى بهتون الجبل التي تحوي عائلة هوارة التي تحتوي العديد من العادات العصبية والتي قام فيها الشيخ بدار بمخالفة ا لعادات والتقاليد  وزوج ابنته الي رجل غريب عن العائلة. وسط رفض اخيها.', 9.0, '["دراما", "عائلي"]'::jsonb, '[{"name": "أحمد عبدالعزيز", "character": "", "profile_path": "/1WioRpCGUOqtE02t7Eutj4CNqIH.jpg"}, {"name": "شريف منير", "character": "", "profile_path": "/69ttY5VkABXQeTcFZBkxcxvaXjf.jpg"}, {"name": "سماح أنور", "character": "", "profile_path": "/l8qoHeDrHdqYZz1wUDCfurbHMzF.jpg"}, {"name": "زوزو نبيل", "character": "", "profile_path": "/xozRPPfJFkxL0bQQCTYmzsFZxwI.jpg"}, {"name": "عبدالله غيث", "character": "", "profile_path": "/7dVgNjKzIHWW80eMKRu7ko3Ywnz.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (452, 'series', 'ليالي الصالحية', 'ليالي الصالحية', 'ليالي الصالحية', 'مسلسل ليالي الصالحيه', 2004, 53923, 'tv', '/lByUBDpDZgPghpX92yykIGli35A.jpg', '/kLGwv4bZIWAbuzP3j0DTk9W0n7T.jpg', 'يترك “أبو ناجي” مبلغ من المال قدره 500 برغوث ذهبي كأمانة عند أبو مخرز، ولكن قبل موت أبو مخرز يترك الأمانة عند المعلم عمر، وبعد فترة زمنية طويلة، يخرج مخرز من السجن، فتخبره أمه عن الأمانة وتحرضه على ابن عمه عمر لتبدأ الخلافات.', 'يترك “أبو ناجي” مبلغ من المال قدره 500 برغوث ذهبي كأمانة عند أبو مخرز، ولكن قبل موت أبو مخرز يترك الأمانة عند المعلم عمر، وبعد فترة زمنية طويلة، يخرج مخرز من السجن، فتخبره أمه عن الأمانة وتحرضه على ابن عمه عمر لتبدأ الخلافات.', 6.4, '["دراما", "عائلي"]'::jsonb, '[{"name": "عباس النوري", "character": "المعلم عمر", "profile_path": "/7DsjxullF8RvtGW3AIT7ejVkyoG.jpg"}, {"name": "كاريس بشار", "character": "سعدية", "profile_path": "/m55P3chgUAAfawfG5vg6aRXvemU.jpg"}, {"name": "منى واصف", "character": "أمينة", "profile_path": "/lx2GQ3a7KHpITya81AwaGciTlHN.jpg"}, {"name": "بسام كوسا", "character": "المخرز", "profile_path": "/2s3MDeiyNXzed2N3flDG3wUSlWV.jpg"}, {"name": "سامية الجزائري", "character": "أم صادق", "profile_path": "/acWzsDDRO1zrXI8iaHMa3JWVQfv.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (453, 'series', 'أم هارون', 'أم هارون', 'أم هارون', 'مسلسل ام هارون', 2020, 102512, 'tv', '/qnhJkUJUqQhXoR787U1UoeDgbJZ.jpg', '/rZEGrcTbq9sr5wGbAE9Tu7IQY5v.jpg', 'تدور الأحداث في منطقة الخليج في فترة أربعينيات القرن الماضي، حيث قصة طبيبة يهودية تٌدعى أم هارون تعيش وسط أهل البلدة في الكويت، وتوجه تحديات عدة هي وأسرتها والجالية اليهودية.', 'تدور الأحداث في منطقة الخليج في فترة أربعينيات القرن الماضي، حيث قصة طبيبة يهودية تٌدعى أم هارون تعيش وسط أهل البلدة في الكويت، وتوجه تحديات عدة هي وأسرتها والجالية اليهودية.', 5.0, '["دراما"]'::jsonb, '[{"name": "حياة الفهد", "character": "", "profile_path": "/nEmxxaudEUpXIikCGSEI5I8eAwO.jpg"}, {"name": "عبدالمحسن النمر", "character": "", "profile_path": "/vfHsm67Ow2p86IPhPe5P8hhYdzw.jpg"}, {"name": "إلهام علي", "character": "", "profile_path": "/hA4lnJug2lmzbokUgqDO9ZuV9Ra.jpg"}, {"name": "روان مهدي", "character": "", "profile_path": "/cCXnqONQUv1vrDvLg5uzDMyW4oY.jpg"}, {"name": "أحمد الجسمي", "character": "", "profile_path": "/esPdMnDd0tibWcIJjo4LNs3FuQy.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (454, 'series', 'تغيير جو', 'تغيير جو', 'تغيير جو', 'مسلسل تغيير جو', 2023, 220960, 'tv', '/zzab4dvbY4cpMRfW8QMKXmBvFdY.jpg', '/cuRAkk8zmJTrpBKmqmJAuUWVEbZ.jpg', 'تشك شريفة، المرأة الذكية التي تعاني من بعض أعراض البارانويا، أن بعضا من أقاربها في بيروت يحاولون الاستيلاء على عقار تملكه هناك، فتقرر مغادرة مصر والتوجه إلى لبنان لاكتشاف الحقيقة.', 'تشك شريفة، المرأة الذكية التي تعاني من بعض أعراض البارانويا، أن بعضا من أقاربها في بيروت يحاولون الاستيلاء على عقار تملكه هناك، فتقرر مغادرة مصر والتوجه إلى لبنان لاكتشاف الحقيقة.', 4.4, '["دراما"]'::jsonb, '[{"name": "منة شلبي", "character": "", "profile_path": "/oxX093z8VFpDUTDTR0T0WFaMIos.jpg"}, {"name": "إياد نصار", "character": "", "profile_path": "/1rMMqeDTEWIpEVIEfBYbOTow6kA.jpg"}, {"name": "شيرين", "character": "", "profile_path": "/cWrLR7cg9ldnoGo0pDtPfD0em59.jpg"}, {"name": "ميرفت أمين", "character": "", "profile_path": "/wJnpt9qKrUL3ac0zCpUaYm0t7Zq.jpg"}, {"name": "Saleh Bakri", "character": "", "profile_path": "/nx5owXvKk9QPOXbluDZhtAaUlRB.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (455, 'series', 'الهيبة: راس الجبل', 'الهيبة: راس الجبل', 'الهيبة: راس الجبل', 'مسلسل الهيبه الجبل', 2026, 310575, 'tv', '/tOGB4nYRVFC0KFQRP3uTQSbIzla.jpg', '/5KtLRyeDy21MC1STnjazkfjXk6K.jpg', 'تعود ياسمينا مع ابنها من مونتريال إلى المغرب لدفن زوجها، لكن تحاصرها "رأس الجبل" في عالم من الاتجار والنفوذ العشائري ويحكمه صهرها ليل، وهو زعيم القرية الذي يهابه الجميع.', 'تعود ياسمينا مع ابنها من مونتريال إلى المغرب لدفن زوجها، لكن تحاصرها "رأس الجبل" في عالم من الاتجار والنفوذ العشائري ويحكمه صهرها ليل، وهو زعيم القرية الذي يهابه الجميع.', 6.0, '["دراما", "حركة ومغامرة"]'::jsonb, '[{"name": "Assaad Bouab", "character": "Layl", "profile_path": "/zIqK5a0H3e6z2vFhRDdWQCMQIRT.jpg"}, {"name": "Hiba Bennani", "character": "Yasmina", "profile_path": "/7IRzUznlWjWofmYt3qvUkk2RFTy.jpg"}, {"name": "Nora Skalli", "character": "Ghalia", "profile_path": "/ndIAo1jMtjpkWGTeiNKwXuN0Ae6.jpg"}, {"name": "Amine Ennaji", "character": "Axel", "profile_path": "/c29gNwh767I2aDqBqX8YFQHSThR.jpg"}, {"name": "Oussama Bastaoui", "character": "Qais", "profile_path": "/pYybDxZrIQHksQpp0dARbZ0cK0i.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (456, 'series', 'العتاولة', 'العتاولة', 'العتاولة', 'مسلسل العتاوله', 2024, 244644, 'tv', '/iShiXPsBLiB3mK0pKptYkXuUSx4.jpg', '/6migs4HciLIa37QhCyJrNX7IlO2.jpg', 'بعد وقوعه في الحب، يعزم نصار، وهو سارق محترف، على الخروج من عالم الاجرام. لكنه سرعان ما يجد نفسه وسط حرب شرسة تخوضها ضده الجهات المتضررة من قراره.', 'بعد وقوعه في الحب، يعزم نصار، وهو سارق محترف، على الخروج من عالم الاجرام. لكنه سرعان ما يجد نفسه وسط حرب شرسة تخوضها ضده الجهات المتضررة من قراره.', 7.0, '["دراما"]'::jsonb, '[{"name": "أحمد السقا", "character": "", "profile_path": "/4UhDFNeJ7UVjcyNfMINdHLSqA7q.jpg"}, {"name": "طارق لطفي", "character": "", "profile_path": "/2O7gt6p3zr4OWC308Sfc5i2Ch1x.jpg"}, {"name": "زينة", "character": "", "profile_path": "/rzViYmGwblIdvKbIqhr1t56MSO9.jpg"}, {"name": "مصطفى أبو سريع", "character": "", "profile_path": "/2zTPCaxAS0LzA2Zovwp94BcYIgC.jpg"}, {"name": "باسم سمرة", "character": "", "profile_path": "/tKhneTl9BL6W1jIgTV43o5duFPx.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
