INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (459, 'series', 'الشهد والدموع', 'الشهد والدموع', 'الشهد والدموع', 'مسلسل الشهد والدموع', 1983, 54138, 'tv', '/j95ia7Jvq8n8IvKXdaqSCdHkGlb.jpg', '/lxfpnzasA8WnGeOIEMiCApD61Iw.jpg', 'تدور أحداث المسلسل حول الشقيقين حافظ وشوقي أبناء الحاج رضوان، اللذين تختلف مساراتهما الحياتية تمام الاختلاف، فبينما ينغمس شوقي في حياة اللهو والترف، ينشغل شقيقه حافظ في العمل بالتجارة مع والده، وتبدأ بينهما بوادر صراع على عدة مستويات، وفي نفس الوقت يتزوج حافظ من دولت، وشوقي من زينب، لتشتعل أرضية صراع جديدة.', 'تدور أحداث المسلسل حول الشقيقين حافظ وشوقي أبناء الحاج رضوان، اللذين تختلف مساراتهما الحياتية تمام الاختلاف، فبينما ينغمس شوقي في حياة اللهو والترف، ينشغل شقيقه حافظ في العمل بالتجارة مع والده، وتبدأ بينهما بوادر صراع على عدة مستويات، وفي نفس الوقت يتزوج حافظ من دولت، وشوقي من زينب، لتشتعل أرضية صراع جديدة.', 9.5, '["دراما"]'::jsonb, '[{"name": "يوسف شعبان", "character": "حافظ رضوان", "profile_path": "/svhdm3fdJKkJdG5tCSSYV6Mynju.jpg"}, {"name": "عفاف شعيب", "character": "زينب", "profile_path": "/fvI9NmH9x1ur9M5WI0wqQkni040.jpg"}, {"name": "جليلة محمود", "character": "سنية", "profile_path": "/xiggXWvyeUjhUP7WE3CCHIrNQFi.jpg"}, {"name": "صبري عبدالمنعم", "character": "مختار البرهامي", "profile_path": "/mD3kaGX3ub0EzniUJmtiZ0D4cXA.jpg"}, {"name": "سيد عبدالكريم", "character": "عبودة", "profile_path": "/l0J6I5igZHwvadC0s9zwh13heDU.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (460, 'series', 'الوتد', 'الوتد', 'الوتد', 'مسلسل الوتد', 1996, 195603, 'tv', '/8YnxEBiTZJSDG4uoyHs476AgYcY.jpg', '/8BHQbExPOmZKfPhLkqP9gjkizvV.jpg', 'تدور أحداث المسلسل حول فاطمة تعلبة، أم صعيدية ترغب في استقرار عائلتها، تتدخل الأم في جميع اختيارات أولادها المختلفة للحفاظ على وحدة البيت، كما تحاول هذه الأم توسعة ممتلكات وأراضي العائلة.', 'تدور أحداث المسلسل حول فاطمة تعلبة، أم صعيدية ترغب في استقرار عائلتها، تتدخل الأم في جميع اختيارات أولادها المختلفة للحفاظ على وحدة البيت، كما تحاول هذه الأم توسعة ممتلكات وأراضي العائلة.', 7.7, '[]'::jsonb, '[{"name": "هدى سلطان", "character": "Fatma Ta''laba", "profile_path": "/uGSvgQIO6xHIGJI5YuwpuBMQ5uF.jpg"}, {"name": "يوسف شعبان", "character": "Darweesh", "profile_path": "/svhdm3fdJKkJdG5tCSSYV6Mynju.jpg"}, {"name": "هالة فاخر", "character": "Bahyia", "profile_path": "/omSAstcoVGK4Cldav56rIa9v15m.jpg"}, {"name": "حنان ترك", "character": "Basima", "profile_path": "/xwt3vXxlnn3ACC3pNAPVtffxYSP.jpg"}, {"name": "عبدالله محمود", "character": "Issa", "profile_path": null}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
