INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (462, 'series', 'مارغريت', 'مارغريت', 'مارغريت', 'مسلسل مارغريت', 2021, 121627, 'tv', '/qCksJ6LffLbpD8mb2G200oTM0L5.jpg', '/vnhcZVI8453eQvCVDTmod0MWJi8.jpg', 'تحكي الأحداث في إطار درامي تشويقي عن سيدة بريطانية من أصول عربية، تعيش في أوساط المجتمع الخليجي، وتتشابك قصتها مع قصص المحيطين، وتحدث لها مفارقات كثيرة بسبب بعض السلوكيات العربية.', 'تحكي الأحداث في إطار درامي تشويقي عن سيدة بريطانية من أصول عربية، تعيش في أوساط المجتمع الخليجي، وتتشابك قصتها مع قصص المحيطين، وتحدث لها مفارقات كثيرة بسبب بعض السلوكيات العربية.', NULL, '["دراما"]'::jsonb, '[{"name": "حياة الفهد", "character": "مارغريت", "profile_path": "/nEmxxaudEUpXIikCGSEI5I8eAwO.jpg"}, {"name": "حسن البلام", "character": "", "profile_path": "/izVxeXMxNPMDtsbIqWu7EUuZNCU.jpg"}, {"name": "سعاد علي", "character": "", "profile_path": "/q6w79Qa1arE3IKLYff3IRyuc5mk.jpg"}, {"name": "حمد العماني", "character": "", "profile_path": "/dxty7GdQU3BPRiRnIq4IIaFlBGB.jpg"}, {"name": "هبة الدري", "character": "", "profile_path": "/wQ9UtCHH0cyCNewEms1Fk2ahaN0.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (463, 'series', 'كلبش', 'كلبش', 'كلبش', 'مسلسل كلبش', 2017, 72048, 'tv', '/kyksiL8EukkmIpcRyHoYbBtUna6.jpg', '/n4CdU1SmHwkPBSwwIDnApV1XfpC.jpg', 'تدور احداث المسلسل في إطار درامي بوليسي حول ضابط يقع في مأزق كبير، فما هو هذا المأزق، وهل سيخرج منه؟', 'تدور احداث المسلسل في إطار درامي بوليسي حول ضابط يقع في مأزق كبير، فما هو هذا المأزق، وهل سيخرج منه؟', 5.7, '["دراما"]'::jsonb, '[{"name": "أمير كرارة", "character": "Selim El Ansary", "profile_path": "/cfdecL9iTJfhFN2UNNLRVQPr5e.jpg"}, {"name": "هالة فاخر", "character": "Selim''s Mother", "profile_path": "/omSAstcoVGK4Cldav56rIa9v15m.jpg"}, {"name": "هشام سليم", "character": "Akram Safwan", "profile_path": "/mEsLAwETgrWHGwLviulP8TlXclb.jpg"}, {"name": "أحمد عبدالعزيز", "character": "اللواء جلال", "profile_path": "/1WioRpCGUOqtE02t7Eutj4CNqIH.jpg"}, {"name": "يسرا اللوزي", "character": "Reem", "profile_path": "/2glB9fdsojFGY4uronEqPb8tpjj.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (464, 'series', 'للموت', 'للموت', 'للموت', 'مسلسل للموت', 2021, 121745, 'tv', '/6oulvhrVLb8MlC8hFxQk9SmAClF.jpg', '/4I2H2c6pR7Ws4I8SBAMh6PkdkKz.jpg', 'بعد انكشاف لعبتهما، تتعرض ريم وسحر لمحاولة انتقام سرعان ما تقلب صداقتهما إلى معركة بقاء شرسة تبدأ بفضح خفايا الماضي.', 'بعد انكشاف لعبتهما، تتعرض ريم وسحر لمحاولة انتقام سرعان ما تقلب صداقتهما إلى معركة بقاء شرسة تبدأ بفضح خفايا الماضي.', 6.4, '["دراما"]'::jsonb, '[{"name": "ماغي بو غصن", "character": "سحر", "profile_path": "/1CuNxLM4UkgsBfykwYKNhLCnEFG.jpg"}, {"name": "Daniella Rahme", "character": "Reem", "profile_path": "/xtcDjb02Ne7GKfIclNA0V5nSkFc.jpg"}, {"name": "Randa Kaadi", "character": "", "profile_path": "/vzk7uhUEh1cEQqDLcEtLPVQQxgV.jpg"}, {"name": "Khitam Al Lahham", "character": "", "profile_path": "/rkhOkZLDspMFC1Ed7XFk0ahPQLu.jpg"}, {"name": "كارول عبود", "character": "", "profile_path": "/aZL0Ing7w7wK27KiiP79CKowudy.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (465, 'series', 'صيد العقارب', 'صيد العقارب', 'صيد العقارب', 'مسلسل صيد العقارب', 2024, 245982, 'tv', '/msRUKW5jz6jK2FYJxRk4230wu4I.jpg', '/iGaloTIJ8sEYiB1B17WHjpaJOiV.jpg', 'بعد مقتل أخيها الكبير، يتوجب على عايدة، المرأة القوية والمحنكة، تجاوز تقاليد عائلتها المحافظة لتولي زمام الأمور والانتقام له.', 'بعد مقتل أخيها الكبير، يتوجب على عايدة، المرأة القوية والمحنكة، تجاوز تقاليد عائلتها المحافظة لتولي زمام الأمور والانتقام له.', NULL, '["دراما"]'::jsonb, '[{"name": "غادة عبدالرازق", "character": "", "profile_path": "/57KpAr5jKo8updReZSqig12LycM.jpg"}, {"name": "محمد علاء", "character": "", "profile_path": "/umn2Hx3luXbMpEZyEt4lkkSXRd3.jpg"}, {"name": "رياض الخولي", "character": "", "profile_path": "/wLxEujKCEvcACU1Vsc2Wa1vPC3Q.jpg"}, {"name": "أحمد سعيد عبدالغني", "character": "", "profile_path": "/xNK32PrpCGpaIjjB3cjI9wNvnuW.jpg"}, {"name": "أحمد ماهر", "character": "", "profile_path": "/tpQq9hoXKlZR6oP1GI7CzMl5SOB.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
