INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (468, 'series', 'كف ودفوف', 'كف ودفوف', 'كف ودفوف', 'مسلسل كف ودفوف', 2021, 132819, 'tv', '/ddEktTjBDAtLjMo8oN3MACgrQY.jpg', '/g1HGH8oCru8R0tP46zcIHvZcZFM.jpg', 'تدور أحداث «كف ودفوف» حول فرقتين شعبيّتين، الأولى نسائية تقودها سليمة (هدى حسين) والثانية تجمع الرجال. يصوّر العمل الصراعات القائمة بين الفرقتين، والعلاقات بين أفرادها.', 'تدور أحداث «كف ودفوف» حول فرقتين شعبيّتين، الأولى نسائية تقودها سليمة (هدى حسين) والثانية تجمع الرجال. يصوّر العمل الصراعات القائمة بين الفرقتين، والعلاقات بين أفرادها.', 8.0, '[]'::jsonb, '[{"name": "هدى حسين", "character": "سليمة", "profile_path": "/zbxjoLw97rKbDpPK2TX1Sxp1HNd.jpg"}, {"name": "إبراهيم الحساوي", "character": "مبارك", "profile_path": "/xnJwa46Wmohw6bk39j0yHQUr1OB.jpg"}, {"name": "لطيفة المجرن", "character": "أم سامي", "profile_path": "/cggZiTpFDNmee2GUi5Cuotay9Oj.jpg"}, {"name": "قحطان القحطاني", "character": "عبدالوهاب", "profile_path": "/92FLXTEuRIYVWdGXKloT5zjw7Fx.jpg"}, {"name": "شيماء علي", "character": "هيا", "profile_path": "/cKHSbdoV1aSgot1Opz2MH5e4prr.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (469, 'series', 'طريق المجد', '花开锦绣', '花开锦绣', 'مسلسل طريق', 2026, 287496, 'tv', '/erj7cX8aa1jndO9HlmoyRcJNLQL.jpg', '/zyAFGC97834c2Ld4xPY02uacdQk.jpg', 'ملخص: وُلد تشاو لينغ في عالم تهريب الملح القاسي، وهو شاب جريء وشديد الولاء يحلم بمصير أعظم من أصوله المتواضعة. تتقاطع طرقه مع فو تينغيون، وهي سيدة شابة نبيلة اتُهمت زوراً بعلاقة غير مشروعة، فيضطر الاثنان للفرار بحياتهما. وبينما تطاردهما عائلتاهما القويتان والبلاط الإمبراطوري وتختبران صمودهما، يقفان معاً في وجه كل المحن، ويتحديان القدر المرسوم لهما، ويصيغان قصة حب أسطورية مقدر لها أن تدوم.', 'ملخص: وُلد تشاو لينغ في عالم تهريب الملح القاسي، وهو شاب جريء وشديد الولاء يحلم بمصير أعظم من أصوله المتواضعة. تتقاطع طرقه مع فو تينغيون، وهي سيدة شابة نبيلة اتُهمت زوراً بعلاقة غير مشروعة، فيضطر الاثنان للفرار بحياتهما. وبينما تطاردهما عائلتاهما القويتان والبلاط الإمبراطوري وتختبران صمودهما، يقفان معاً في وجه كل المحن، ويتحديان القدر المرسوم لهما، ويصيغان قصة حب أسطورية مقدر لها أن تدوم.', 8.0, '["دراما"]'::jsonb, '[{"name": "丁禹兮", "character": "Zhao Ling", "profile_path": "/ellcOuCs2mo1Oh9zO2Qhb0OoZ4d.jpg"}, {"name": "邓恩熙", "character": "Fu Tingyun", "profile_path": "/mljbAriACCCSNYAe6bDMiCFgViu.jpg"}, {"name": "范诗然", "character": "Fan Yake", "profile_path": "/l8NLIJWLSP5J5tplzUM0XKtL6xC.jpg"}, {"name": "董子凡", "character": "Yu Jingxiu", "profile_path": "/x97b3NOgk9RuPCOeWjZJ21vC0gK.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (470, 'series', 'زلزال', 'زلزال', 'زلزال', 'مسلسل زلزال', 2019, 88929, 'tv', '/aD9JQfzOwvzW8qdw9ZZbJ7RIBtp.jpg', '/9ejO7DAcpw0RPEUSAgQsGuOb0Az.jpg', 'وتدور أحداث مسلسل " زلزال" في فترة زلزال 1992، عن رجل يشتري منزلا بأقساط محددة المدة والقيمة، وحين يأتي موعد سداد القسط الأخير، يطالب صاحب المنزل بتسجيل البيت باسمه والتنازل عن ملكيته، إلا أن البائع يُماطل إلى أن يقع "زلزال 1992" الذي يلقى فيه الشاري حتفه وينهار المنزل على إثر الزلزال وتبعاته، فيرفض حينها البائع تسليم قطعة الأرض التي كان المنزل يقع عليها لورثة الراحل، ما يخلق صدامًا بينه وبين ابن المتوفى، وعلى الرغم من وجود قصة حب تجمع الأخير بابنة البائع، فإن والد الفتاة يقف عائقا بينهما.', 'وتدور أحداث مسلسل " زلزال" في فترة زلزال 1992، عن رجل يشتري منزلا بأقساط محددة المدة والقيمة، وحين يأتي موعد سداد القسط الأخير، يطالب صاحب المنزل بتسجيل البيت باسمه والتنازل عن ملكيته، إلا أن البائع يُماطل إلى أن يقع "زلزال 1992" الذي يلقى فيه الشاري حتفه وينهار المنزل على إثر الزلزال وتبعاته، فيرفض حينها البائع تسليم قطعة الأرض التي كان المنزل يقع عليها لورثة الراحل، ما يخلق صدامًا بينه وبين ابن المتوفى، وعلى الرغم من وجود قصة حب تجمع الأخير بابنة البائع، فإن والد الفتاة يقف عائقا بينهما.', 7.8, '["حركة ومغامرة"]'::jsonb, '[{"name": "محمد رمضان", "character": "Mohamed Harbi", "profile_path": "/2UlMUlVJqW59dvXQ0NOQPPnlPWc.jpg"}, {"name": "حلا شيحة", "character": "Safia", "profile_path": "/fXcS9eioNf6X5au9yx3XU4SLm3U.jpg"}, {"name": "ماجد المصري", "character": "Khalil", "profile_path": "/hCFDKcAiotPNs5cvlhHXgFS6dX0.jpg"}, {"name": "منى عبدالغني", "character": "Laila", "profile_path": "/7Ux8pVWn61NxJwGp5O3gxC7W1ko.jpg"}, {"name": "محمود حجازي", "character": "Abd El-Halim", "profile_path": "/7wd5VukHLz4mbCVd4rb3wzxnMD8.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
