INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (473, 'series', 'راجل وست ستات', 'راجل وست ستات', 'راجل وست ستات', 'مسلسل راجل وست ستات', 2006, 84774, 'tv', '/kp2DiPrglWFpqb4LqtEZIETuWcM.jpg', '/5KjR4YYrtyumNRrs4vRThuMwkdk.jpg', 'يواصل عادل (أشرف عبدالباقي) مواقفه اليومية المليئة بالكثير من المفارقات الكوميدية مع جميع افراد عائلته الذين يعيشون معه في نفس المنزل: زوجته، والدته، شقيقته، حماته، شقيقة زوجته، ابنته، بالاضافة إلى رمزي الذي يعمل معه في البازار الذي يملكه عادل.', 'يواصل عادل (أشرف عبدالباقي) مواقفه اليومية المليئة بالكثير من المفارقات الكوميدية مع جميع افراد عائلته الذين يعيشون معه في نفس المنزل: زوجته، والدته، شقيقته، حماته، شقيقة زوجته، ابنته، بالاضافة إلى رمزي الذي يعمل معه في البازار الذي يملكه عادل.', 7.5, '["عائلي", "كوميديا"]'::jsonb, '[{"name": "أشرف عبدالباقي", "character": "Adel/Rawwash", "profile_path": "/5Kazsywa6e7bftoQcJEGXCLJHRZ.jpg"}, {"name": "لقاء الخميسي", "character": "Rania", "profile_path": "/tLtGPJHNnAvoFAaqOz4Q0Cf6CRy.jpg"}, {"name": "نيفين محمد", "character": "Naglaa", "profile_path": null}, {"name": "منة عرفة", "character": "Yasmin", "profile_path": "/hgPm7TthqrOE2PkwlWvZ8g93nUT.jpg"}, {"name": "نهى لطفي", "character": "", "profile_path": "/cg5nY3Z9yRrIU5dYpPLEvOSraCq.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
