INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (477, 'movie', 'ولاد رزق 2: عودة أسود الأرض', 'ولاد رزق 2: عودة أسود الأرض', 'ولاد رزق 2: عودة أسود الأرض', 'فيلم ولاد رزق 2', 2019, 620371, 'movie', '/hA8Gmyiw0NYuRnuwEb0Iezs7fZM.jpg', '/lwedewSQWXGhD8w94Qt64fpwsCs.jpg', 'بعد مرور 3 سنوات منذ انتهاء أحداث الجزء الأول، يحاول الأخوة الأربعة بشتى الطرق الحفاظ على العهد الذي قطعوه على أنفسهم بالابتعاد عن حياة السرقة والجريمة، لكن حدث واحد يطرأ على حياتهم يغير كل ذلك، ويدخلهم في عوالم جديدة عليهم، ويضعهم في مواجهات شديدة الخطورة مع عدد من المجرمين المحترفين.', 'بعد مرور 3 سنوات منذ انتهاء أحداث الجزء الأول، يحاول الأخوة الأربعة بشتى الطرق الحفاظ على العهد الذي قطعوه على أنفسهم بالابتعاد عن حياة السرقة والجريمة، لكن حدث واحد يطرأ على حياتهم يغير كل ذلك، ويدخلهم في عوالم جديدة عليهم، ويضعهم في مواجهات شديدة الخطورة مع عدد من المجرمين المحترفين.', 7.2, '["دراما", "حركة"]'::jsonb, '[{"name": "أحمد عز", "character": "Reda Rizk", "profile_path": "/mgQhox7AbzVsQ8xeTZvkK5Gvkd4.jpg"}, {"name": "عمرو يوسف", "character": "Rabih Rizk", "profile_path": "/vYyvP5NHlVUNdKmUgX3e7X5sAW.jpg"}, {"name": "أحمد الفيشاوي", "character": "Rajab Rizk", "profile_path": "/4bmLaXHBRZi6Sn6XE1eCAM6KDs0.jpg"}, {"name": "أحمد داود", "character": "Atef", "profile_path": "/a7p4iWp2i5yymtdRmGMtyPHGZHh.jpg"}, {"name": "كريم قاسم", "character": "Ramadan Rizk", "profile_path": "/nB52EaGeMPCmcoVJoWEZrO3gckX.jpg"}]'::jsonb, 120) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, 