INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (479, 'series', 'ريّح المدام', 'ريّح المدام', 'ريّح المدام', 'مسلسل ريح المدام', 2017, 72298, 'tv', '/fyaMrhKRtptztpWMChPudOXUAK9.jpg', '/zovcLL3Issakqg293FUvTCC1q2k.jpg', 'تدور أحداث المسلسل في حلقات منفصلة متصلة حول سلطان الذي يعمل مخرجًا للإعلانات، وهو دائم الوقوع في المشكلات بسبب علاقاته النسائية، ومع زوجته داليا التي تفقد الذاكرة وتقوم في كل مرة بالتحول إلى شخصية مختلفة، ولكنه لا يستطيع حل أي من مشكلاته ومشكلات زوجته ويعتمد في حلها على صديقه بهجت والذي يقوم بحل كل تلك المشكلات له.', 'تدور أحداث المسلسل في حلقات منفصلة متصلة حول سلطان الذي يعمل مخرجًا للإعلانات، وهو دائم الوقوع في المشكلات بسبب علاقاته النسائية، ومع زوجته داليا التي تفقد الذاكرة وتقوم في كل مرة بالتحول إلى شخصية مختلفة، ولكنه لا يستطيع حل أي من مشكلاته ومشكلات زوجته ويعتمد في حلها على صديقه بهجت والذي يقوم بحل كل تلك المشكلات له.', 7.8, '["كوميديا"]'::jsonb, '[{"name": "أحمد فهمي", "character": "", "profile_path": "/amY80XOZGwcZ8W1qUrTOxNSJy4V.jpg"}, {"name": "أكرم حسني", "character": "", "profile_path": "/tZGdekospdRJ9XZ25hQ7W6RwB9M.jpg"}, {"name": "مي عمر", "character": "", "profile_path": "/52e4H8J66b2jMBSt9SrlQgisirB.jpg"}, {"name": "رجاء الجداوي", "character": "", "profile_path": "/mgZFyKbzxEbT0PZbDSZ2Ue0rAXo.jpg"}, {"name": "Ali Hemeida", "character": "", "profile_path": null}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.ru