INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (483, 'series', 'في بيتنا روبوت', 'في بيتنا روبوت', 'في بيتنا روبوت', 'مسلسل في بيتنا روبوت', 2021, 117314, 'tv', '/ldjZ3r6J7qSGe6IHLoFZsVOb0XU.jpg', '/qdB0YIZhaMS2SqoNabXkMFPqAvI.jpg', 'يعمل شاب يُدعى يوسف على مشروع تصنيع إنسان آلي بذكاء اصطناعي، وحينما ينجح في تصنيع النموذجين زومبا ولذيذ، سرعان ما تنقلب حياته وحياة عائلته رأسا على عقب.', 'يعمل شاب يُدعى يوسف على مشروع تصنيع إنسان آلي بذكاء اصطناعي، وحينما ينجح في تصنيع النموذجين زومبا ولذيذ، سرعان ما تنقلب حياته وحياة عائلته رأسا على عقب.', 7.2, '["كوميديا", "خيال علمي وفانتازيا"]'::jsonb, '[{"name": "Hesham Gamal", "character": "Yousuf", "profile_path": "/ewAFQ7wRSajpUFnHmvFI19cHhtW.jpg"}, {"name": "ليلى أحمد زاهر", "character": "Sara", "profile_path": "/hkHnRrcu0mtpgysBaXyzGYxalQv.jpg"}, {"name": "عمرو وهبة", "character": "Lazez", "profile_path": "/5vWR6lJ6s3pPAaujCQ0KvJBUYmi.jpg"}, {"name": "شيماء سيف", "character": "Zumba", "profile_path": "/n5IyDKHdVSY4fDjqXjt5nuyOD9N.jpg"}, {"name": "Donia Samy", "character": "Hadir", "profile_path": null}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (484, 'movie', 'كازابلانكا', 'كازابلانكا', 'كازابلانكا', 'فيلم كازابلانكا', 2019, 603404, 'movie', '/yOHJYF9chII7UOsf5Lk7GKiXUsn.jpg', '/ripsaXE9rbwpeJSMZH6JlBrEVsh.jpg', 'في إطار الإثارة والتشويق تدور أحداث الفيلم حول ثلاثة أصدقاء (عمر المر، عرابي، رشيد) يشكلون عصابة للسطو على السفن، يُطلق عليهم (هجامين البحر)، يتم تكليفهم بمهمة خطيرة ضد رجال المافيا، وهي السطو على شحنة ألماس كبيرة، ولكن (عرابي) يقرر تنفيذ العملية لحسابه الشخصي، ويهرب على المغرب، فتبدأ تصفية الحسابات والمعارك الضارية.', 'في إطار الإثارة والتشويق تدور أحداث الفيلم حول ثلاثة أصدقاء (عمر المر، عرابي، رشيد) يشكلون عصابة للسطو على السفن، يُطلق عليهم (هجامين البحر)، يتم تكليفهم بمهمة خطيرة ضد رجال المافيا، وهي السطو على شحنة ألماس كبيرة، ولكن (عرابي) يقرر تنفيذ العملية لحسابه الشخصي، ويهرب على المغرب، فتبدأ تصفية الحسابات والمعارك الضارية.', 6.4, '["حركة", "دراما"]'::jsonb, '[{"name": "أمير كرارة", "character": "عمر المر", "profile_path": "/cfdecL9iTJfhFN2UNNLRVQPr5e.jpg"}, {"name": "غادة عادل", "character": "فيفا", "profile_path": "/z2bEbhdv3gRKPeZ9aASshDgWDEP.jpg"}, {"name": "إياد نصار", "character": "رشيد", "profile_path": "/1rMMqeDTEWIpEVIEfBYbOTow6kA.jpg"}, {"name": "عمرو عبدالجليل", "character": "عرابي", "profile_path": "/5H6iU6KXLvfLPzjPIm3DMkOGtf0.jpg"}, {"name": "خالد أرغنتش", "character": "دراچون", "profile_path": "/7L5ivMz1S7ArHTvUaslVVV3ML42.jpg"}]'::jsonb, 104) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres,