INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (488, 'series', 'نيللي وشريهان', 'نيللي وشريهان', 'نيللي وشريهان', 'مسلسل نيللي وشريهان', 2016, 84334, 'tv', '/mrG6HYWdRSlJAkcRWZeuwLG6lHf.jpg', '/b9vFwm1ZDpDBruLQAyVKNJlDJYy.jpg', 'تدور أحداث المسلسل في إطار كوميدي اجتماعي، حيث تُجسّد (دنيا) دور فتاة ثرية تُدعى نيللي، وتجسد "إيمي" شخصية فتاة فقيرة تُدعى "شريهان"، إلى جانب كونهما ابنتا عم، فهما شخصيتان متنافراتان تمامًا، لكنهما تضطران لتنحية الخلافات جنبًا، لحل لغز ميكي، الذي يوصلهم إلى ميراث جدهما ميكاوي أبو الخير.', 'تدور أحداث المسلسل في إطار كوميدي اجتماعي، حيث تُجسّد (دنيا) دور فتاة ثرية تُدعى نيللي، وتجسد "إيمي" شخصية فتاة فقيرة تُدعى "شريهان"، إلى جانب كونهما ابنتا عم، فهما شخصيتان متنافراتان تمامًا، لكنهما تضطران لتنحية الخلافات جنبًا، لحل لغز ميكي، الذي يوصلهم إلى ميراث جدهما ميكاوي أبو الخير.', 8.8, '["كوميديا", "دراما"]'::jsonb, '[{"name": "دنيا سمير غانم", "character": "Nelly Mekkawy", "profile_path": "/kNXX9aE5XpW2igRuEzAlbJ0r1yL.jpg"}, {"name": "إيمي سمير غانم", "character": "Sherihan Mekkawy", "profile_path": "/ugym5uaaNM0xeAOQBPe1LtLq7XD.jpg"}, {"name": "مصطفى خاطر", "character": "Seif", "profile_path": "/pj5b1XP1iM8BaCKb6QOdZpAD8xW.jpg"}, {"name": "محمد سلام", "character": "Hani El-Dabdoub", "profile_path": "/pnOF9xHx4LbEHsRunfyRnfV1uDc.jpg"}, {"name": "أحمد حلاوة", "character": "Uncle Bondoq/Bendari", "profile_path": "/h9QqZbvZP7ZgLMRkMpkr0XFEnJV.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres,