INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (493, 'movie', 'الحرب العالمية الثالثة', 'الحرب العالمية الثالثة', 'الحرب العالمية الثالثة', 'فيلم الحرب العالميه الثالثه', 2014, 300561, 'movie', '/z98klip6miQI5hHcD4icatrw0j8.jpg', '/d1hNTaGI109sMJHNarJMD3YAIm7.jpg', 'تدور أحداث الفيلم في متحف شمع، حيث يضم المتحف مجموعة تماثيل لأشهر شخصيات التاريخ مثل توت عنخ آمون والزعيم أحمد عرابي ومحمد علي باشا وغاندي وأم كلثوم ونابليون وكذلك أفراد من الجيش المصري في حرب أكتوبر وغيرهم، هذه التماثيل تدب فيها الحياة فقط بعد منتصف الليل وحتى الساعة الخامسة صباحًا، ويتصادف قبل موعد استيقاظهم بقليل دخول خميس (أحمد فهمي) لهذا المبنى المهجور بحثًا عن كرته التي قذفها داخله أثناء لعبه', 'تدور أحداث الفيلم في متحف شمع، حيث يضم المتحف مجموعة تماثيل لأشهر شخصيات التاريخ مثل توت عنخ آمون والزعيم أحمد عرابي ومحمد علي باشا وغاندي وأم كلثوم ونابليون وكذلك أفراد من الجيش المصري في حرب أكتوبر وغيرهم، هذه التماثيل تدب فيها الحياة فقط بعد منتصف الليل وحتى الساعة الخامسة صباحًا، ويتصادف قبل موعد استيقاظهم بقليل دخول خميس (أحمد فهمي) لهذا المبنى المهجور بحثًا عن كرته التي قذفها داخله أثناء لعبه', 7.0, '["كوميديا", "فانتازيا"]'::jsonb, '[{"name": "شيكو", "character": "توت عنخ أمون", "profile_path": "/gurvnsbru3btbeENF3HANKw2VM8.jpg"}, {"name": "أحمد فهمي", "character": "خميس", "profile_path": "/amY80XOZGwcZ8W1qUrTOxNSJy4V.jpg"}, {"name": "هشام ماجد", "character": "علاء الدين", "profile_path": "/p8jemmilRFz892wz4KBPNWuxhAN.jpg"}, {"name": "بيومي فؤاد", "character": "محمد علي", "profile_path": "/79rD72T50i6tohSW9OLrahNExjP.jpg"}, {"name": "إنعام سالوسة", "character": "هويدا", "profile_path": "/bbvYQgJBUXDOUkkoZ609kgFD9wD.jpg"}]'::jsonb, 100) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
