INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (495, 'series', 'لهفة', 'لهفة', 'لهفة', 'مسلسل لهفه', 2015, 84782, 'tv', '/dI9MkAptYtxUUgwfP9Rx7lkvg06.jpg', '/nclZZS7Yn1g1Hk4Zt1Odxi1fSj5.jpg', 'في قالب كوميدي، تتركز أحداث المسلسل حول فتاة طموح ترغب طيلة حياتها بالعمل في مجال التمثيل، وتحاول الاعتماد على خالها الذي يعمل ريجسيرًا لكي يساعدها على تحقيق ما تصبو إليه، فهي لا تريد أن تتحول في النهاية إلى مجرد كومبارس كما هو حال والدها، وفي محاولاتها لتحقيق الأمر، تصطدم الفتاة بالكثير من المفاجآت الفارقة.', 'في قالب كوميدي، تتركز أحداث المسلسل حول فتاة طموح ترغب طيلة حياتها بالعمل في مجال التمثيل، وتحاول الاعتماد على خالها الذي يعمل ريجسيرًا لكي يساعدها على تحقيق ما تصبو إليه، فهي لا تريد أن تتحول في النهاية إلى مجرد كومبارس كما هو حال والدها، وفي محاولاتها لتحقيق الأمر، تصطدم الفتاة بالكثير من المفاجآت الفارقة.', 7.0, '["كوميديا"]'::jsonb, '[{"name": "دنيا سمير غانم", "character": "Lahfa", "profile_path": "/kNXX9aE5XpW2igRuEzAlbJ0r1yL.jpg"}, {"name": "سمير غانم", "character": "El-Halawany", "profile_path": "/vSqmd98zrxOAnDFnBGnt4Wihn7B.jpg"}, {"name": "محمد سلام", "character": "Mortada", "profile_path": "/pnOF9xHx4LbEHsRunfyRnfV1uDc.jpg"}, {"name": "علي الربيع", "character": "Ayman", "profile_path": "/uJHx2Gsa46WMGXFWZEIivKGHZnH.jpg"}, {"name": "هناء الشوربجي", "character": "Ebtehal", "profile_path": "/8ROuHPttds8mdqEVRQEi6YbwWN6.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members,