INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (496, 'series', 'يوميات ونيس', 'يوميات ونيس', 'يوميات ونيس', 'مسلسل ونيس', 1994, 55991, 'tv', '/jz6NCOJ6wYvw2yhGXZ502FiyjKK.jpg', '/96m1mj9mm7s1m8zTzHWlQb6xLSf.jpg', 'يقوم ونيس (محمد صبحي) وزوجته مايسة (سعاد نصر) على تربية أبناءهما الأربعة على الأخلاق والقيم الصالحة، وأثناء تأديتهم لهذه الرسالة يكتشفان أنهما يخالفان الكثير من القيم التي يحاولنان زرعها في أولادهما، فيحاولان التصحيح من نفسيهما.', 'يقوم ونيس (محمد صبحي) وزوجته مايسة (سعاد نصر) على تربية أبناءهما الأربعة على الأخلاق والقيم الصالحة، وأثناء تأديتهم لهذه الرسالة يكتشفان أنهما يخالفان الكثير من القيم التي يحاولنان زرعها في أولادهما، فيحاولان التصحيح من نفسيهما.', 8.0, '["دراما", "كوميديا"]'::jsonb, '[{"name": "محمد صبحي", "character": "Wanees ونيس أبو الفضل جاد الله عويس عبدالحق", "profile_path": "/elWUufkz6FsANx773tzAo7dKUmD.jpg"}, {"name": "جميل راتب", "character": "Abu Al Fadl Jadallah Ewees Abdulhaq أبو الفضل", "profile_path": "/9ZNYtVH3LAq5UtGVnyPZvoKqlSp.jpg"}, {"name": "ريم أحمد", "character": "Huda هدى", "profile_path": "/sDJ1QOkCDZsuZTA3GI1jG8cCLJs.jpg"}, {"name": "هدى هاني", "character": "Jehad", "profile_path": "/n4uG5B9ZOLFZqCHWKoNVMl8B8Tl.jpg"}, {"name": "شعبان حسين", "character": "", "profile_path": "/qbEm0V5GeRuiWOPaozVl19FtTY2.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
