INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (502, 'movie', 'قلب أمه', 'قلب أمه', 'قلب أمه', 'فيلم قلب امه', 2018, 527735, 'movie', '/b04eCPftbA6nhfIwkT8qB0gi4DS.jpg', '/cuDUHErG5RYa31Thc1MQUnLRE9k.jpg', 'تدور الأحداث في إطار كوميدي حول زعيم عصابة يُدعى (مجدي تختوخ) يدخل في مشاجرة يُصاب على إثرها؛ وينُقل إلى المستشفى في حالة خطيرة حيث يحتاج إلى نقل قلب، وفي ذات الوقت تتوفى والدة الشاب (يونس)؛ فيلجأ اﻷطباء إلى نقل قلب والدته إلى (تختوخ) ﻹنقاذ حياته، فيتعامل مع (يونس) بطريقة حنان الأم وخوفها عليه.', 'تدور الأحداث في إطار كوميدي حول زعيم عصابة يُدعى (مجدي تختوخ) يدخل في مشاجرة يُصاب على إثرها؛ وينُقل إلى المستشفى في حالة خطيرة حيث يحتاج إلى نقل قلب، وفي ذات الوقت تتوفى والدة الشاب (يونس)؛ فيلجأ اﻷطباء إلى نقل قلب والدته إلى (تختوخ) ﻹنقاذ حياته، فيتعامل مع (يونس) بطريقة حنان الأم وخوفها عليه.', 5.8, '["كوميديا"]'::jsonb, '[{"name": "هشام ماجد", "character": "يونس عبد الحي", "profile_path": "/p8jemmilRFz892wz4KBPNWuxhAN.jpg"}, {"name": "نور قدري", "character": "عليا", "profile_path": "/mhUfVbHy4YHx72T9ZUD0wCLG4qU.jpg"}, {"name": "شيكو", "character": "مجدي تختوخ", "profile_path": "/gurvnsbru3btbeENF3HANKw2VM8.jpg"}, {"name": "دلال عبدالعزيز", "character": "خلود أحمد السمنودي - أم يونس", "profile_path": "/oIW8HsQaRbb1j81Fi4FghJryuTj.jpg"}, {"name": "محمد أسامة", "character": "عوني", "profile_path": "/khnJ5LVjOjLPuTPNnPzEpCRtPT3.jpg"}]'::jsonb, 101) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, 