INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (509, 'movie', 'لا تتنفس 2', 'Don''t Breathe 2', 'Don''t Breathe 2', 'don 2', 2021, 482373, 'movie', '/pvHgnEY5GUtLkgS2cmLPtFQPhoK.jpg', '/3ULzK4XTSC1wal11K7459fxnjjA.jpg', 'كان الرجل الأعمى يختبئ منذ عدة سنوات في كوخ معزول وقام بتربية فتاة صغيرة يتيمة من حريق منزل مدمر. تتحطم حياتهم الهادئة معا عندما تختطف مجموعة من المجرمين الفتاة ، مما يجبر الرجل الأعمى على مغادرة ملاذه الآمن لإنقاذها.', 'كان الرجل الأعمى يختبئ منذ عدة سنوات في كوخ معزول وقام بتربية فتاة صغيرة يتيمة من حريق منزل مدمر. تتحطم حياتهم الهادئة معا عندما تختطف مجموعة من المجرمين الفتاة ، مما يجبر الرجل الأعمى على مغادرة ملاذه الآمن لإنقاذها.', 7.0, '["إثارة", "رعب"]'::jsonb, '[{"name": "Stephen Lang", "character": "The Blind Man", "profile_path": "/gnO5VfkDgA2fsHweD0622LUY3Hu.jpg"}, {"name": "Madelyn Grace", "character": "Phoenix", "profile_path": "/pzK2HNgDSBat6estnAvm2Dj68L9.jpg"}, {"name": "بريندان سكستون الثالث", "character": "Raylan", "profile_path": "/kfvO3Mdk5yqzuaN8aIeaFfVl4T5.jpg"}, {"name": "Adam Young", "character": "Jim-Bob", "profile_path": "/dMp9t3CnylsSL1lLniCjZUhqblx.jpg"}, {"name": "Rocci Williams", "character": "Duke", "profile_path": "/e5GWh54fUmbupb5DKsSNU5axEx2.jpg"}]'::jsonb, 98) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (510, 'movie', 'في السراء والضراء', 'कभी ख़ुशी कभी ग़म', 'कभी ख़ुशी कभी ग़म', 'kabhi khushi kabhie gham', 2001, 10757, 'movie', '/22FzymqB2hojCn99qqjEXUBZuuX.jpg', '/sPMBiyjTco4JdKojlfGIz5Wd0jC.jpg', '(رايتشند) رجل متشدد، يرغب في أن يعيش ابناه معه هو وزوجته، وأن يتزوجا بفتاتين من اختياره، واحد من الابنين ويدعى (راهول) ابنه بالتبني، بينما (روهان) هو الابن الحقيقي، ولكن تسير الأمور على عكس ما يتوقع (رايتشند)، وذلك عندما يقع (راهول) في حب فتاة فقيرة تدعى (أنجالي)؛ مما يثير غضب (رايتشند) بشدة، ويتجادل معه لفترة طويلة، ويتشاجران، ونتيجة لهذا يغادر (راهول) المنزل ويسافر إلى بريطانيا، ويستقر هناك، حتى ينصب تركيز (رايتشند) على ابنه الحقيقي (روهان)، الذي يصمم على أن يعيد (راهول) و(أنجالي) إلى وطنهما.', '(رايتشند) رجل متشدد، يرغب في أن يعيش ابناه معه هو وزوجته، وأن يتزوجا بفتاتين من اختياره، واحد من الابنين ويدعى (راهول) ابنه بالتبني، بينما (روهان) هو الابن الحقيقي، ولكن تسير الأمور على عكس ما يتوقع (رايتشند)، وذلك عندما يقع (راهول) في حب فتاة فقيرة تدعى (أنجالي)؛ مما يثير غضب (رايتشند) بشدة، ويتجادل معه لفترة طويلة، ويتشاجران، ونتيجة لهذا يغادر (راهول) المنزل ويسافر إلى بريطانيا، ويستقر هناك، حتى ينصب تركيز (رايتشند) على ابنه الحقيقي (روهان)، الذي يصمم على أن يعيد (راهول) و(أنجالي) إلى وطنهما.', 7.7, '["كوميديا", "دراما"]'::jsonb, '[{"name": "Amitabh Bachchan", "character": "Yashvardhan “Yash” Raichand", "profile_path": "/u69PvpWqGkywSm0YjFiw77j9eqS.jpg"}, {"name": "شاه رخ خان", "character": "Rahul Raichand", "profile_path": "/tCEppfUu0g2Luu0rS5VKMoL4eSw.jpg"}, {"name": "هريثيك روشان", "character": "Rohan Raichand", "profile_path": "/d7XGTvyYgmrsA05XOn1YtxYcuY1.jpg"}, {"name": "काजोल", "character": "Anjali Sharma Raichand", "profile_path": "/h4m0TkDuEMCUNaPrQxMRyFb2AQ7.jpg"}, {"name": "Jaya Bachchan", "character": "Nandini Chandran Raichand", "profile_path": "/gXmIdkOhJN7pa8XDR7KQJXgtXni.jpg"}]'::jsonb, 209) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
