INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (513, 'series', 'حبيبتي من تكون', 'घुम है किसिकी प्यार में', 'घुम है किसिकी प्यार में', 'مسلسل حبيبتي من تكون', 2020, 111453, 'tv', '/ApjQvGVoqANC2KLRMKZUIoQViwT.jpg', '/d1ujVe5yWPJ6mtepghxidUYIJa5.jpg', 'يضحي فيرات بحبه للوفاء بالوعد الذي قطعه لرجل يحتضر. محاصرًا بين الماضي والحاضر ، هل سيجد حبًا يتجاوز قيود الواجب؟', 'يضحي فيرات بحبه للوفاء بالوعد الذي قطعه لرجل يحتضر. محاصرًا بين الماضي والحاضر ، هل سيجد حبًا يتجاوز قيود الواجب؟', 5.7, '["دراما", "أوبرا صابونية", "عائلي"]'::jsonb, '[]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (514, 'series', 'أمنية وإن تحققت', 'ये रिश्ता क्या कहलाता है', 'ये रिश्ता क्या कहलाता है', 'مسلسل امنيه وان تحققت', 2009, 16413, 'tv', '/njKFVDwOGrRUyhpn3lPGE2AzcDR.jpg', '/5M4kx2WuO3iRuAWhk5SYKus6RMd.jpg', 'تنقلب حياة طبيب يكره الزواج رأسا على عقب عندما يجد نفسه منجذبا لسيدة شابة تزامنا مع وقوع أختها غير الشقيقة في غرامه.', 'تنقلب حياة طبيب يكره الزواج رأسا على عقب عندما يجد نفسه منجذبا لسيدة شابة تزامنا مع وقوع أختها غير الشقيقة في غرامه.', 3.9, '["دراما", "عائلي", "أوبرا صابونية"]'::jsonb, '[{"name": "Samriddhi Shukla", "character": "Adv. Abhira Sharma-Poddar", "profile_path": null}, {"name": "Rohit Purohit", "character": "Adv. Armaan Poddar", "profile_path": "/z7MUpfP0qJsMlmxgJ3oxYxfwNRf.jpg"}, {"name": "Arshiya Sharma", "character": "Maira Poddar", "profile_path": "/n9VkSuddLH80nKTiQ5TCtSsq6li.jpg"}, {"name": "Sarah Killedar", "character": "Vaani Gupta/ Mukti Poddar", "profile_path": "/cEYGRsi98Bs42wPEKe14cjxqw1k.jpg"}, {"name": "Anita Raj", "character": "Kaveri Poddar", "profile_path": "/ny2EEe6T0hP37X9b92iOZxm3GsC.jpg"}]'::jsonb, NULL) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (515, 'movie', 'قطار تشيناي السريع', 'Chennai Express', 'Chennai Express', 'chennai express', 2013, 205022, 'movie', '/9j7XfhBJKNfidMCa8JsNbqU1waV.jpg', '/8u7dfVGGBcGrk1nCu55X5RqImwv.jpg', 'تدور قصة الفلم حول راهول (شاروخان) الذي يعيش في (مومباي) شمال (الهند) ، ويقوم برحلة إلى (رامبشوارام) في جنوب (الهند) ليحقق آخر أمنية لجده ، وهي أن يكون رماده مغمورا في المياه المقدسة في (رامبشوارام) ، وأثناء رحلته يقع في حب ابنة أحد رجال العصابات الخطيرة ، ويتعرض للعديد من المواقف والمشاكل قبل اكتشافه حقيقة حبيبته .', 'تدور قصة الفلم حول راهول (شاروخان) الذي يعيش في (مومباي) شمال (الهند) ، ويقوم برحلة إلى (رامبشوارام) في جنوب (الهند) ليحقق آخر أمنية لجده ، وهي أن يكون رماده مغمورا في المياه المقدسة في (رامبشوارام) ، وأثناء رحلته يقع في حب ابنة أحد رجال العصابات الخطيرة ، ويتعرض للعديد من المواقف والمشاكل قبل اكتشافه حقيقة حبيبته .', 6.5, '["رومنسية", "كوميديا", "حركة"]'::jsonb, '[{"name": "شاه رخ خان", "character": "Rahul Mithaiwala", "profile_path": "/tCEppfUu0g2Luu0rS5VKMoL4eSw.jpg"}, {"name": "Deepika Padukone", "character": "Meenamma Lochini Azhagusundaram", "profile_path": "/rzvvBQ0r6oiqDdzcsdTRB7jN4Rx.jpg"}, {"name": "Nikitin Dheer", "character": "Tangaballi", "profile_path": "/gAHNWVtStTGsqf2uxCegxvn6ILe.jpg"}, {"name": "Sathyaraj", "character": "Durgeshwara Azhagusundaram", "profile_path": "/lnlBZ7V3K3Z3OIsjCd0zkKx26L3.jpg"}, {"name": "Mukesh Tiwari", "character": "Inspector Shamsher", "profile_path": "/37GTjltEJHpi1lQmLmHKJYTpxjj.jpg"}]'::jsonb, 141) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path =