INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (518, 'movie', 'كريش 3', 'कृष ३', 'कृष ३', 'krrish 3', 2013, 204435, 'movie', '/tpCrYKO0S6jIc4qf2rif4J4U4lh.jpg', '/rG2pFglPrNS1H0UmFu5z5KTTPtJ.jpg', 'بعد أن قام كريش مهرا (هريثيك روشان) بهزيمة دكتور سيدهانت أريا وإنقاذ والده من الموت ،يقرر الاستمرار في محاربة الشر من أجل إنقاذ حياة الأبرياء والضعفاء. يعيش كريش حياةً سعيدةً مع زوجته بريا ميهرا (بريانكا شوبرا) ،يقوم والده روهيت بالاستمرار في أبحاثه العلمية من أجل إفادة المجتمع. ولكن سُرعان ما يتحول كل ذلك إلى جحيم، عندما تحاول قوى ظلامٍ عظيمةٌ السيطرة على العالم ونشر شرها متمثلةً في كال (فيفيك أوبروي) ،الذي يستخدم قوته من أجل نشر الموت والدمار ،ويساعده في ذلك جيشٌ من التابعين الذين قام باختراعهم. حينها يقرر كريش وروهيت التصدي لهذا المعتوه من أجل إنقاذ الناس الأبرياء من كارثةٍ حتميةٍ.', 'بعد أن قام كريش مهرا (هريثيك روشان) بهزيمة دكتور سيدهانت أريا وإنقاذ والده من الموت ،يقرر الاستمرار في محاربة الشر من أجل إنقاذ حياة الأبرياء والضعفاء. يعيش كريش حياةً سعيدةً مع زوجته بريا ميهرا (بريانكا شوبرا) ،يقوم والده روهيت بالاستمرار في أبحاثه العلمية من أجل إفادة المجتمع. ولكن سُرعان ما يتحول كل ذلك إلى جحيم، عندما تحاول قوى ظلامٍ عظيمةٌ السيطرة على العالم ونشر شرها متمثلةً في كال (فيفيك أوبروي) ،الذي يستخدم قوته من أجل نشر الموت والدمار ،ويساعده في ذلك جيشٌ من التابعين الذين قام باختراعهم. حينها يقرر كريش وروهيت التصدي لهذا المعتوه من أجل إنقاذ الناس الأبرياء من كارثةٍ حتميةٍ.', 5.6, '["حركة", "خيال علمي"]'::jsonb, '[{"name": "هريثيك روشان", "character": "Krishna Mehra / Krrish / Rohit Mehra", "profile_path": "/d7XGTvyYgmrsA05XOn1YtxYcuY1.jpg"}, {"name": "Priyanka Chopra Jonas", "character": "Priya Mehra", "profile_path": "/hh48u9scic0nITGtzi9b6rJeAtT.jpg"}, {"name": "Vivek Oberoi", "character": "Kaal", "profile_path": "/60T3Q8CsxF4kF6RIHZ1yis2Q0wA.jpg"}, {"name": "Kangana Ranaut", "character": "Kaya", "profile_path": "/GmIRKLKP3xEx1mgF7VrFurIEbz.jpg"}, {"name": "Arif Zakaria", "character": "Dr. Varun Shetty", "profile_path": "/fQx14DwQV2Z2p25t4bogVn9A2c.jpg"}]'::jsonb, 152) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (519, 'movie', 'صاحب القلب الشجاع سيحوز على العروسة', 'दिलवाले दुल्हनिया ले जायेंगे', 'दिलवाले दुल्हनिया ले जायेंगे', 'dilwale dulhania le jayenge', 1995, 19404, 'movie', '/2CAL2433ZeIihfX1Hb2139CX0pW.jpg', '/84beTJf26mfhoasUlKSOiNSutyS.jpg', 'الفيلم يدور حول أسرتين هنديتين تعيشان في لندن، تذهب ابنة إحدى الأسرتين (سيمران) في رحلة قبل أن تتزوج برجل لا تعرفه، ويذهب ابن الأسرة الأخرى (راج) في نفس الرحلة، ليلتقيا ببعضهما البعض، ويقع بينهما الحب الحقيقي، ويجد كل منهما حب حياته في الطرف الآخر، ولكن عليهم التغلب على المصاعب الشديدة والقوية التي تحول دون ارتباطهم بعضهما البعض.', 'الفيلم يدور حول أسرتين هنديتين تعيشان في لندن، تذهب ابنة إحدى الأسرتين (سيمران) في رحلة قبل أن تتزوج برجل لا تعرفه، ويذهب ابن الأسرة الأخرى (راج) في نفس الرحلة، ليلتقيا ببعضهما البعض، ويقع بينهما الحب الحقيقي، ويجد كل منهما حب حياته في الطرف الآخر، ولكن عليهم التغلب على المصاعب الشديدة والقوية التي تحول دون ارتباطهم بعضهما البعض.', 8.5, '["كوميديا", "دراما", "رومنسية"]'::jsonb, '[{"name": "काजोल", "character": "Simran Singh", "profile_path": "/h4m0TkDuEMCUNaPrQxMRyFb2AQ7.jpg"}, {"name": "شاه رخ خان", "character": "Raj Malhotra", "profile_path": "/tCEppfUu0g2Luu0rS5VKMoL4eSw.jpg"}, {"name": "Amrish Puri", "character": "Chaudhry Baldev Singh", "profile_path": "/uhMGFS7tuG71LDv2wk9LfZZ4EG6.jpg"}, {"name": "Farida Jalal", "character": "Lajwanti ''Lajjo'' Singh", "profile_path": "/tJdqL4BRSAWVFX1W6cmwxFs9IFh.jpg"}, {"name": "Anupam Kher", "character": "Dharamvir Malhotra", "profile_path": "/kgU5Ap1Kf9RnicB5DMcXEZqed2f.jpg"}]'::jsonb, 190) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmd