INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (522, 'movie', 'المنتقمون: الحرب الأبدية', 'Avengers: Infinity War', 'Avengers: Infinity War', 'war', 2018, 299536, 'movie', '/pig5cJjP08d9OUgBXNjiqbU6RjH.jpg', '/mDfJG3LC3Dqb67AZ52x3Z0jU0uB.jpg', 'مع استمرار المنتقمون وحلفائهم في حماية العالم من التهديدات التي لا يمكن لأي بطل لوحده التعامل معها، ظهر خطر جديد من الظلال الكوني - ثانوس -  مستبد من العار المجحف، هدفه هو جمع كل حجارة اللانهاية الستة، التي تحمل قوة لا يمكن تصورها، واستخدامها لإلحاق إرادته الملتوية على كل الواقع. لقد قادت كل الأمور التي كافحها المنتقمون حتى هذه اللحظة  - لم يكن مصير الأرض ووجودها أكثر غموضاً من ذي قبل.', 'مع استمرار المنتقمون وحلفائهم في حماية العالم من التهديدات التي لا يمكن لأي بطل لوحده التعامل معها، ظهر خطر جديد من الظلال الكوني - ثانوس -  مستبد من العار المجحف، هدفه هو جمع كل حجارة اللانهاية الستة، التي تحمل قوة لا يمكن تصورها، واستخدامها لإلحاق إرادته الملتوية على كل الواقع. لقد قادت كل الأمور التي كافحها المنتقمون حتى هذه اللحظة  - لم يكن مصير الأرض ووجودها أكثر غموضاً من ذي قبل.', 8.2, '["مغامرة", "حركة", "خيال علمي"]'::jsonb, '[{"name": "روبرت داوني جونيور", "character": "Tony Stark / Iron Man", "profile_path": "/5qHNjhtjMD4YWH3UP0rm4tKwxCL.jpg"}, {"name": "كريس إيفانز", "character": "Steve Rogers / Captain America", "profile_path": "/3bOGNsHlrswhyW79uvIHH1V43JI.jpg"}, {"name": "كريس هيمسوورث", "character": "Thor", "profile_path": "/piQGdoIQOF3C1EI5cbYZLAW1gfj.jpg"}, {"name": "جوش برولين", "character": "Thanos", "profile_path": "/sX2etBbIkxRaCsATyw5ZpOVMPTD.jpg"}, {"name": "مارك رافالو", "character": "Bruce Banner / Hulk", "profile_path": "/5GilHMOt5PAQh6rlUKZzGmaKEI7.jpg"}]'::jsonb, 149) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (523, 'movie', 'انفجار 3', 'धूम ३', 'धूम ३', 'dhoom 3', 2013, 44977, 'movie', '/pBIfUu87XeS3NHjt0XBQJCwD0Sg.jpg', '/m715Fj5VVCXfwzqbCZFhmJBH8S9.jpg', 'في جو الحركة والتشويق يرصد الفيلم قصة ساهر (أمير خان) رجل السيرك المتمكن. ساهر لديه رابطةٌ قويةٌ بوالده حيث إنه الذي قام بتدريبه. عليا (كاترينا كيف) امرأة جميلة وجذابة وزميلة ساهر في السيرك، لدى ساهر دافعٌ قويٌ للمضي قدمًا والانتقام لوفاة والده، لكن عن طريق سرقة مالك السيرك ظنًا منه أنه وراء مقتل والده.', 'في جو الحركة والتشويق يرصد الفيلم قصة ساهر (أمير خان) رجل السيرك المتمكن. ساهر لديه رابطةٌ قويةٌ بوالده حيث إنه الذي قام بتدريبه. عليا (كاترينا كيف) امرأة جميلة وجذابة وزميلة ساهر في السيرك، لدى ساهر دافعٌ قويٌ للمضي قدمًا والانتقام لوفاة والده، لكن عن طريق سرقة مالك السيرك ظنًا منه أنه وراء مقتل والده.', 6.0, '["حركة", "جريمة"]'::jsonb, '[{"name": "عامر خان", "character": "Sahir/Samar", "profile_path": "/6uiZSwi2kvd1jZ7X7Xz9W9VGuV4.jpg"}, {"name": "أبهيشيك باتشان", "character": "A.C.P. Jai Dixit", "profile_path": "/o2hWC004VnRyGLOgg8OjiP1Ch5A.jpg"}, {"name": "Katrina Kaif", "character": "Aaliya", "profile_path": "/gSNaBg8Q7Nh0u4HhW6pR5B0ujlL.jpg"}, {"name": "Uday Chopra", "character": "Ali", "profile_path": "/bHmH00vJNavpf5BgSuBeUSPB9bj.jpg"}, {"name": "جاكي شروف", "character": "Iqbal Khan", "profile_path": "/1UNJypgEyuihUW2avLLVYj76jie.jpg"}]'::jsonb, 171) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cas