INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (525, 'movie', 'را.وان', 'Ra.One', 'Ra.One', 'ra one', 2011, 41517, 'movie', '/i72RJRlrjfZp53JF6yBxkRHlJ3u.jpg', '/lXI2fhjeoah5d5pxoR9GMogb6Q3.jpg', 'عندما يتخذ الخصم الرئيسي في لعبة الحركة شكلاً مادياً، يصبح الأمر متروكاً لبطل اللعبة الأقل قوة لإنقاذ العالم', 'عندما يتخذ الخصم الرئيسي في لعبة الحركة شكلاً مادياً، يصبح الأمر متروكاً لبطل اللعبة الأقل قوة لإنقاذ العالم', 5.7, '["مغامرة", "حركة", "خيال علمي"]'::jsonb, '[{"name": "شاه رخ خان", "character": "Shekhar Subramaniam / G.One", "profile_path": "/tCEppfUu0g2Luu0rS5VKMoL4eSw.jpg"}, {"name": "अर्जुन रामपाल", "character": "Ra.One", "profile_path": "/1F81WNcVV5cW9O4D5Otk1Y2WHV9.jpg"}, {"name": "करीना कपूर खान", "character": "Sonia S. Subramanium", "profile_path": "/kp9xnwDALUt6nuPBGuJHlvnxGnM.jpg"}, {"name": "Armaan Verma", "character": "Prateek", "profile_path": "/v2xVNHtpUJ9RZ7zf0IVaBuZqZe3.jpg"}, {"name": "Tom Wu", "character": "Akaashi", "profile_path": "/qBQAerjLCCglXIyMURUj3hPpiCM.jpg"}]'::jsonb, 156) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
