INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (527, 'movie', 'عودة سينجام', 'सिंघम रिटर्न्स', 'सिंघम रिटर्न्स', 'singham returns', 2014, 285803, 'movie', '/k8CDjZLYG8bCIuXWAg4gukxf0BE.jpg', '/rvG9irR3D0HrxAA0Jh577Rik2Ck.jpg', 'في إطار دراما الجريمة الممزوجة بالإثارة والتشويق وفي هذا الجزء الجديد، يعود الشرطي الشرس باجيرو سنجام (آجاي دفجن) مجددًا بعد أن ترقى، وصار نائب مفوض الشرطة في مدينة مومباي، الذي يضطلع بمهمة جديدة هادفًا إلى محاربة الجريمة المنظمة في المدينة.', 'في إطار دراما الجريمة الممزوجة بالإثارة والتشويق وفي هذا الجزء الجديد، يعود الشرطي الشرس باجيرو سنجام (آجاي دفجن) مجددًا بعد أن ترقى، وصار نائب مفوض الشرطة في مدينة مومباي، الذي يضطلع بمهمة جديدة هادفًا إلى محاربة الجريمة المنظمة في المدينة.', 6.1, '["حركة"]'::jsonb, '[{"name": "Ajay Devgan", "character": "Bajirao Singham", "profile_path": "/vnHQQFzTjJ0sv14DGMIoKa3qTxN.jpg"}, {"name": "करीना कपूर खान", "character": "Avni Kamat", "profile_path": "/kp9xnwDALUt6nuPBGuJHlvnxGnM.jpg"}, {"name": "Amole Gupte", "character": "Swami Ji", "profile_path": "/wBGlaN2N16y3Hoco2piGRwhNTX5.jpg"}, {"name": "Anupam Kher", "character": "Guruji", "profile_path": "/kgU5Ap1Kf9RnicB5DMcXEZqed2f.jpg"}, {"name": "Vineet Sharma", "character": "Sub-Inspector Dev Phadnis", "profile_path": "/6S9cNAfvUd03YV1Ehixp95orP0.jpg"}]'::jsonb, 142) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
INSERT INTO public.content (id, content_type, title_ar, title_en, original_title, normalized_title, release_year, tmdb_id, tmdb_type, poster_path, backdrop_path, overview_ar, overview_en, rating, genres, cast_members, runtime_minutes) VALUES (528, 'movie', '3 بلهاء', '3 Idiots', '3 Idiots', '3 idiots', 2009, 20453, 'movie', '/9FhGenQJbIYZ7OPeUysi49i2IjH.jpg', '/8gT3UKtglLVpu0YfccwbmXZ5Eis.jpg', 'في تقليد "يوم عطلة فيريس بيولر" ، تأتي هذه الكوميديا المنعشة حول مخادع متمرد بعقل ماكر وقلب من الذهب. الوغد. مهرج. حالم. عبقري ... لم تقابل طالبًا جامعيًا مثل "رانشو". منذ لحظة وصوله إلى أكثر الجامعات المرموقة في الهند ، تقلب مخططات رانشو الغريبة الحرم الجامعي رأسًا على عقب - جنبًا إلى جنب مع حياة اثنين من أصدقائه الجدد. معًا ، يجعلون الحياة بائسة لـ "الفيروسات" ، عميد المدرسة المتوتر والقلوب. ولكن عندما لفت رانشو أنظار ابنة العميد المثيرة ، فإن Virus يضع نصب عينيه إخفاق "الحمقى الثلاثة" مرة واحدة وإلى الأبد.', 'في تقليد "يوم عطلة فيريس بيولر" ، تأتي هذه الكوميديا المنعشة حول مخادع متمرد بعقل ماكر وقلب من الذهب. الوغد. مهرج. حالم. عبقري ... لم تقابل طالبًا جامعيًا مثل "رانشو". منذ لحظة وصوله إلى أكثر الجامعات المرموقة في الهند ، تقلب مخططات رانشو الغريبة الحرم الجامعي رأسًا على عقب - جنبًا إلى جنب مع حياة اثنين من أصدقائه الجدد. معًا ، يجعلون الحياة بائسة لـ "الفيروسات" ، عميد المدرسة المتوتر والقلوب. ولكن عندما لفت رانشو أنظار ابنة العميد المثيرة ، فإن Virus يضع نصب عينيه إخفاق "الحمقى الثلاثة" مرة واحدة وإلى الأبد.', 8.0, '["دراما", "كوميديا"]'::jsonb, '[{"name": "عامر خان", "character": "Ranchoddas \"Rancho\" Chanchad", "profile_path": "/6uiZSwi2kvd1jZ7X7Xz9W9VGuV4.jpg"}, {"name": "R. Madhavan", "character": "Farhan Qureshi", "profile_path": "/gaDrAdXxIrbBRCd9cX8YvJDEuLb.jpg"}, {"name": "Sharman Joshi", "character": "Raju Rastogi", "profile_path": "/mQr8ynFFVq08qgQ4aSNl5B0ko8v.jpg"}, {"name": "करीना कपूर खान", "character": "Pia Sahastrabudhhe", "profile_path": "/kp9xnwDALUt6nuPBGuJHlvnxGnM.jpg"}, {"name": "Boman Irani", "character": "Viru \"Virus\" Sahastrabudhhe", "profile_path": "/5J7GiiNar9bg9rGYeA2L30JXE2W.jpg"}]'::jsonb, 171) ON CONFLICT (id) DO UPDATE SET content_type = EXCLUDED.content_type, title_ar = EXCLUDED.title_ar, title_en = EXCLUDED.title_en, original_title = EXCLUDED.original_title, release_year = EXCLUDED.release_year, tmdb_id = EXCLUDED.tmdb_id, poster_path = EXCLUDED.poster_path, backdrop_path = EXCLUDED.backdrop_path, overview_ar = EXCLUDED.overview_ar, rating = EXCLUDED.rating, genres = EXCLUDED.genres, cast_members = EXCLUDED.cast_members, runtime_minutes = EXCLUDED.runtime_minutes;
